    // element behind a user gesture — even after the WebAudio context is unlocked.
    // So a track first heard in a LATER scene would stay silent until the next tap.
    // Warm EVERY track up during the very first gesture: a muted play()+pause()
    // "unlocks" each element so later programmatic startMusic() just works.
    var musicWarmed = false;
    function unlockAllMusic() {
        if (musicWarmed) return;
        musicWarmed = true;
        // Unlock each element by CALLING play() during the gesture, then pausing it
        // SYNCHRONOUSLY (with volume 0) so nothing is ever actually audible — that's
        // the Howler-style idiom. An async pause (in a .then) lets them all blare at
        // once before the pause lands; the synchronous pause + zero volume can't.
        function warm(el) {
            if (!el) return;
            try {
                el.volume = 0;
                var p = el.play();
                if (p && p.catch) p.catch(function () {});   // the immediate pause aborts play() — ignore
                el.pause();
                el.currentTime = 0;
                el.volume = MUSIC_VOLUME;
            } catch (e) { try { el.volume = MUSIC_VOLUME; } catch (e2) {} }
        }
        var tracks = Object.keys(MUSIC_FILES || {});
        for (var i = 0; i < tracks.length; i++) warm(getMusicEl(tracks[i]));
        var plKeys = Object.keys(MUSIC_PLAYLISTS || {});
        for (var k = 0; k < plKeys.length; k++) {
            buildPlaylist(plKeys[k]);
            var els = playlistEls[plKeys[k]] || [];
            for (var j = 0; j < els.length; j++) warm(els[j]);
        }
    }

    function playHonkPitched(pitch) {
        if (audioMuted) return;
        var ac = getAudio(); if (!ac) return;
        for (var b = 0; b < 2; b++) {
            var osc = ac.createOscillator(); var gain = ac.createGain();
            osc.type = "square"; osc.frequency.value = pitch + b * 30;
            var t = ac.currentTime + b * 0.12;
            gain.gain.setValueAtTime(0.18, t);
            gain.gain.setValueAtTime(0.18, t + 0.06);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
            osc.connect(gain).connect(ac.destination); osc.start(t); osc.stop(t + 0.13);
        }
    }

    // ── Canvas Setup ─────────────────────────────────────────
    var canvas = document.getElementById("gameCanvas");
    var ctx = canvas.getContext("2d");
    var dpr = Math.max(1, window.devicePixelRatio || 1);
    var viewW = W, viewH = H;           // last-measured viewport size (CSS px)
    var SAFE_TOP = 0, SAFE_BOTTOM = 0;   // safe-area insets in LOGICAL units

    function measureViewport() {
        var vv = window.visualViewport;
        var vw = vv && vv.width ? vv.width : (document.documentElement.clientWidth || window.innerWidth || W);
        var vh = vv && vv.height ? vv.height : (document.documentElement.clientHeight || window.innerHeight || H);
        return { w: Math.max(1, Math.round(vw)), h: Math.max(1, Math.round(vh)) };
    }
    function readSafeInsets() {
        try {
            var p = document.createElement("div");
            p.style.cssText = "position:fixed;top:0;left:0;width:0;height:0;visibility:hidden;pointer-events:none;" +
                "padding-top:env(safe-area-inset-top);padding-bottom:env(safe-area-inset-bottom);";
            document.body.appendChild(p);
            var cs = getComputedStyle(p);
            var t = parseFloat(cs.paddingTop) || 0, b = parseFloat(cs.paddingBottom) || 0;
            document.body.removeChild(p);
            return { top: t, bottom: b };
        } catch (e) { return { top: 0, bottom: 0 }; }
    }
    // Recompute everything that depends on the (variable) play-field height.
    function recomputeLayout() {
        PLAYER_Y = H - 170;
        var bot = H - SAFE_BOTTOM;
        PAUSE_RECT        = { x: 8,       y: SAFE_TOP + 12, w: 48, h: 48 };
        MOBILE_BOOST_RECT = { x: 14,      y: bot - 168, w: 64, h: 64 };
        MOBILE_BRAKE_RECT = { x: 14,      y: bot - 96,  w: 64, h: 64 };
        MISSILE_RECT      = { x: W - 78,  y: bot - 96,  w: 64, h: 64 };
        HONK_RECT         = { x: W - 78,  y: bot - 168, w: 64, h: 64 };
        PEPPER_RECT       = { x: W - 78,  y: bot - 240, w: 64, h: 64 };
        COP_RECT          = { x: 14,      y: bot - 240, w: 64, h: 64 };  // siren / pull-over (cop car only)
        EXIT_RECT         = { x: W / 2 - 74, y: bot - 58, w: 148, h: 44 }; // ditch the car → on foot (when slowed)
        PARK_LEFT_RECT    = { x: 12,      y: bot - 96,  w: 64, h: 64 };
        PARK_RIGHT_RECT   = { x: 88,      y: bot - 96,  w: 64, h: 64 };
        PARK_FWD_RECT     = { x: W - 152, y: bot - 96,  w: 64, h: 64 };
        PARK_REV_RECT     = { x: W - 76,  y: bot - 96,  w: 64, h: 64 };

        // ── MOVABLE CONTROLS: apply the player's saved custom layout ──────
        // save.ctrlLayout maps a control key → {fx,fy} = the button CENTER as
        // a fraction of W,H. Any missing key keeps its default slot above.
        // Fractions (not pixels) so a layout built on a phone lands
        // proportionally on an iPad (H 700 vs 1043). Each override is clamped
        // fully on-screen inside the safe-area insets. With ctrlLayout === null
        // this whole block no-ops, so the output stays byte-identical to stock.
        if (save.ctrlLayout) {
            var ctrlRects = {
                pause: PAUSE_RECT, boost: MOBILE_BOOST_RECT, brake: MOBILE_BRAKE_RECT,
                missile: MISSILE_RECT, honk: HONK_RECT, pepper: PEPPER_RECT, cop: COP_RECT
            };
            for (var ck in ctrlRects) {
                var cl = save.ctrlLayout[ck], cr = ctrlRects[ck];
                if (!cl || !cr) continue;
                cr.x = clamp(cl.fx * W - cr.w / 2, 6, W - cr.w - 6);
                cr.y = clamp(cl.fy * H - cr.h / 2, SAFE_TOP + 6, H - SAFE_BOTTOM - cr.h - 6);
            }
        }
    }
    // Full-bleed responsive sizing — re-measured whenever iOS changes the
    // viewport (which it does late and repeatedly on launch / rotation).
    function relayout() {
        // Cap DPR at 2 — native 3× on big iPhones can blow the 256 MB canvas limit.
        dpr = Math.min(2, Math.max(1, window.devicePixelRatio || 1));
        var m = measureViewport();
        viewW = m.w; viewH = m.h;
        // Logical play-field height.
        //  • PORTRAIT viewport (phones): match the canvas aspect to the screen so
        //    it fills edge-to-edge with no distortion.
        //  • LANDSCAPE viewport (desktop browsers): a wide aspect can't be matched
        //    without squashing the portrait game flat, so lock to a tall-phone
        //    aspect and LETTERBOX (centered, background bars on the sides) instead
        //    of stretching the canvas across the whole window.
        if (viewH >= viewW) {
            H = clamp(Math.round(W * viewH / viewW), 700, 1600);
        } else {
            H = 960;   // ~0.5 aspect: a comfortable modern-phone portrait
        }
        // Contain-fit the W×H canvas inside the viewport (preserve aspect), then
        // center it. When the aspect already matches (phones) this is full-bleed.
        var cAspect = W / H;
        var dispW, dispH;
        if (viewW / viewH > cAspect) { dispH = viewH; dispW = Math.round(viewH * cAspect); }
        else { dispW = viewW; dispH = Math.round(viewW / cAspect); }
        var ins = readSafeInsets();
        var perCss = H / dispH;             // logical px per CSS px (in display space)
        SAFE_TOP = ins.top * perCss;
        SAFE_BOTTOM = ins.bottom * perCss;
        canvas.width = Math.round(W * dpr);
        canvas.height = Math.round(H * dpr);
        canvas.style.width = dispW + "px";
        canvas.style.height = dispH + "px";
        canvas.style.left = Math.round((viewW - dispW) / 2) + "px";   // center the letterbox
        canvas.style.top = Math.round((viewH - dispH) / 2) + "px";
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        recomputeLayout();
    }

    // ── Input ────────────────────────────────────────────────
    var keys = { left: false, right: false, up: false, down: false };
    var actionQueued = false;
    var clickQueue = null; // {x, y} in canvas coords
    var tapFx = [];        // touch-feedback ripples (drawn in interiors, where buttons lack press fx)
    var EXIT_RECT = null;           // ditch-the-car button (only while slowed)
    var exitQueued = false;         // tapped the EXIT button / pressed Q
    var exitBtnShown = false;       // set each frame by updatePlaying when eligible
    var pauseQueued = false;
    var missileQueued = false;
    var honkQueued = false;
    var pepperQueued = false;
    var sirenQueued = false;
    var footActQueued = false; // on-foot "interact" (enter building / steal car)
    var laneQueued = 0; // -1 = step left, +1 = step right (set on tap, drained per frame)
    var touchX = null;
    var touchY = null;  // held-finger position (drag-to-move scenes); null when not dragging
    var steerTouchId = null;
    var boostTouchId = null;
    var brakeTouchId = null;
    // "Cruise control" — double-tap the run/slow button to LOCK it on (for big
    // screens / pros who don't want to hold). boost*Lock keeps keys.up/down set
    // after release; *DblT is the short double-tap window.
    var boostLock = false, brakeLock = false, boostDblT = 0, brakeDblT = 0;
    var parkLeftTouchId = null;
    var parkRightTouchId = null;
    var parkFwdTouchId = null;
    var parkRevTouchId = null;
    var isTouchDevice = ("ontouchstart" in window) || (navigator.maxTouchPoints > 0);

    function queueAction() { actionQueued = true; }
    function consumeAction() { if (actionQueued) { actionQueued = false; return true; } return false; }
    function consumeClick() { var c = clickQueue; clickQueue = null; return c; }
    // A single tap queues BOTH a click and an action (see touchstart/mousedown).
    // `consumeClick() || consumeAction()` short-circuits and leaves the action
    // queued, which then leaks into the next frame and double-advances dialogue.
    // consumeTap() drains both unconditionally and reports whether either fired —
    // use it anywhere you just want "did the user tap?" (position unused).
    function consumeTap() { var c = consumeClick(); var a = consumeAction(); return !!(c || a); }
    function consumePause() { if (pauseQueued) { pauseQueued = false; return true; } return false; }
    function consumeMissile() { if (missileQueued) { missileQueued = false; return true; } return false; }
    function consumeHonk() { if (honkQueued) { honkQueued = false; return true; } return false; }
    function consumePepper() { if (pepperQueued) { pepperQueued = false; return true; } return false; }
    function consumeSiren() { if (sirenQueued) { sirenQueued = false; return true; } return false; }

    function playHonk() {
        if (audioMuted) return;
        var ac = getAudio(); if (!ac) return;
        // Classic "BEEP BEEP" - two short tones
        for (var b = 0; b < 2; b++) {
            var osc = ac.createOscillator();
            var gain = ac.createGain();
            osc.type = "square";
            osc.frequency.value = 440 + b * 30;
            var t = ac.currentTime + b * 0.16;
            gain.gain.setValueAtTime(0.18, t);
            gain.gain.setValueAtTime(0.18, t + 0.08);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.13);
            osc.connect(gain).connect(ac.destination);
            osc.start(t);
            osc.stop(t + 0.14);
        }
    }

    // Mobile control button rects — 64×64, kept clear of the home indicator via
    // SAFE_BOTTOM. Actual positions are (re)computed in recomputeLayout(); these
    // are just declarations.
    var PAUSE_RECT, MOBILE_BOOST_RECT, MOBILE_BRAKE_RECT, MISSILE_RECT, HONK_RECT, PEPPER_RECT, COP_RECT;
    var PARK_LEFT_RECT, PARK_RIGHT_RECT, PARK_FWD_RECT, PARK_REV_RECT;

    // Now that the rect vars exist, lay everything out and keep it in sync with
    // the live viewport. iOS reports the final viewport late and repeatedly on
    // launch, so we re-measure on every relevant event AND a few times after.
    relayout();
    window.addEventListener("resize", relayout);
    window.addEventListener("orientationchange", function () { setTimeout(relayout, 120); });
    if (window.visualViewport) {
        window.visualViewport.addEventListener("resize", relayout);
        window.visualViewport.addEventListener("scroll", relayout);
    }
    [60, 150, 300, 600, 1000, 1500].forEach(function (ms) { setTimeout(relayout, ms); });

    function hitGameButton(pos) {
        if (state === "playing") {
            if (pointInRect(pos.x, pos.y, PAUSE_RECT.x, PAUSE_RECT.y, PAUSE_RECT.w, PAUSE_RECT.h)) return "pause";
            if (save.missiles > 0 && pointInRect(pos.x, pos.y, MISSILE_RECT.x, MISSILE_RECT.y, MISSILE_RECT.w, MISSILE_RECT.h)) return "missile";
            if (save.pepperSpray > 0 && pointInRect(pos.x, pos.y, PEPPER_RECT.x, PEPPER_RECT.y, PEPPER_RECT.w, PEPPER_RECT.h)) return "pepper";
            if ((playerVehicle === "cop" || playerVehicle === "ambulance" || playerVehicle === "bus") &&
                pointInRect(pos.x, pos.y, COP_RECT.x, COP_RECT.y, COP_RECT.w, COP_RECT.h)) return "siren";
            if (pointInRect(pos.x, pos.y, HONK_RECT.x, HONK_RECT.y, HONK_RECT.w, HONK_RECT.h)) return "honk";
            if (exitBtnShown && EXIT_RECT && pointInRect(pos.x, pos.y, EXIT_RECT.x, EXIT_RECT.y, EXIT_RECT.w, EXIT_RECT.h)) return "exit";
            if (pointInRect(pos.x, pos.y, MOBILE_BOOST_RECT.x, MOBILE_BOOST_RECT.y, MOBILE_BOOST_RECT.w, MOBILE_BOOST_RECT.h)) return "boost";
            if (pointInRect(pos.x, pos.y, MOBILE_BRAKE_RECT.x, MOBILE_BRAKE_RECT.y, MOBILE_BRAKE_RECT.w, MOBILE_BRAKE_RECT.h)) return "brake";
            return null;
        }
        if (state === "parking") {
            if (pointInRect(pos.x, pos.y, PAUSE_RECT.x, PAUSE_RECT.y, PAUSE_RECT.w, PAUSE_RECT.h)) return "pause";
            if (pointInRect(pos.x, pos.y, PARK_LEFT_RECT.x, PARK_LEFT_RECT.y, PARK_LEFT_RECT.w, PARK_LEFT_RECT.h)) return "parkLeft";
            if (pointInRect(pos.x, pos.y, PARK_RIGHT_RECT.x, PARK_RIGHT_RECT.y, PARK_RIGHT_RECT.w, PARK_RIGHT_RECT.h)) return "parkRight";
            if (pointInRect(pos.x, pos.y, PARK_FWD_RECT.x, PARK_FWD_RECT.y, PARK_FWD_RECT.w, PARK_FWD_RECT.h)) return "parkFwd";
            if (pointInRect(pos.x, pos.y, PARK_REV_RECT.x, PARK_REV_RECT.y, PARK_REV_RECT.w, PARK_REV_RECT.h)) return "parkRev";
            return null;
        }
        // Dina's run + Cookie Catch reuse the parking D-pad rects for their
        // on-screen buttons. Without this, taps fell through to a generic click
        // and the buttons did nothing on mobile.
        // Dina's run uses finger-drag for left/right (like Lulu's car); only the
        // sprint (⚡) and slow (🐢) buttons remain so they can be held with a
        // second finger while dragging.
        if (state === "dinaRun") {
            if (pointInRect(pos.x, pos.y, PARK_FWD_RECT.x, PARK_FWD_RECT.y, PARK_FWD_RECT.w, PARK_FWD_RECT.h)) return "parkFwd";
            if (pointInRect(pos.x, pos.y, PARK_REV_RECT.x, PARK_REV_RECT.y, PARK_REV_RECT.w, PARK_REV_RECT.h)) return "parkRev";
            return null;
        }
        // Lulu on foot: pause (top-left), pepper (top-right stack), run/slow on the
        // LEFT (boost/brake slots), interact on the RIGHT (honk slot).
        if (state === "footRun") {
            if (pointInRect(pos.x, pos.y, PAUSE_RECT.x, PAUSE_RECT.y, PAUSE_RECT.w, PAUSE_RECT.h)) return "pause";
            if (save.pepperSpray > 0 && pointInRect(pos.x, pos.y, PEPPER_RECT.x, PEPPER_RECT.y, PEPPER_RECT.w, PEPPER_RECT.h)) return "pepper";
            if (pointInRect(pos.x, pos.y, MOBILE_BOOST_RECT.x, MOBILE_BOOST_RECT.y, MOBILE_BOOST_RECT.w, MOBILE_BOOST_RECT.h)) return "boost";
            if (pointInRect(pos.x, pos.y, MOBILE_BRAKE_RECT.x, MOBILE_BRAKE_RECT.y, MOBILE_BRAKE_RECT.w, MOBILE_BRAKE_RECT.h)) return "brake";
            if (pointInRect(pos.x, pos.y, HONK_RECT.x, HONK_RECT.y, HONK_RECT.w, HONK_RECT.h)) return "footAct";
            return null;
        }
        // Cookie Catch slides the plate by dragging; only Pause stays a button.
        if (state === "cookieCatch") {
            if (pointInRect(pos.x, pos.y, PAUSE_RECT.x, PAUSE_RECT.y, PAUSE_RECT.w, PAUSE_RECT.h)) return "pause";
            return null;
        }
        // Dina's bedroom is now drag-to-walk + tap-to-interact (no D-pad).
        return null;
    }

    function screenToCanvas(clientX, clientY) {
        // Re-read the rect every touch (never cache — stale on iOS rotate/settle).
        var rect = canvas.getBoundingClientRect();
        // If a touch lands before layout settled the rect can be 0 → NaN coords
        // → random hit-tests. Re-measure once and retry.
        if (!rect.width || !rect.height) { relayout(); rect = canvas.getBoundingClientRect(); }
        if (!rect.width || !rect.height) return { x: clientX, y: clientY };
        return {
            x: (clientX - rect.left) / rect.width * W,
            y: (clientY - rect.top) / rect.height * H
        };
    }

    // Block iOS pinch-zoom / double-tap-zoom so the visual viewport can't shift
    // out from under our touch→canvas mapping.
    document.addEventListener("gesturestart", function (e) { e.preventDefault(); }, { passive: false });
    document.addEventListener("dblclick", function (e) { e.preventDefault(); }, { passive: false });

    document.addEventListener("keydown", function (e) {
        getAudio(); audioUnlocked = true; unlockAllMusic();   // keyboard counts as a gesture too
        if (e.key === "ArrowLeft" || e.key === "a" || e.key === "A") keys.left = true;
        if (e.key === "ArrowRight" || e.key === "d" || e.key === "D") keys.right = true;
        if (e.key === "ArrowUp" || e.key === "w" || e.key === "W") { keys.up = true; e.preventDefault(); }
        if (e.key === "ArrowDown" || e.key === "s" || e.key === "S") { keys.down = true; e.preventDefault(); }
        if (e.key === " " || e.key === "Enter") { queueAction(); e.preventDefault(); }
        if (e.key === "p" || e.key === "P" || e.key === "Escape") { pauseQueued = true; e.preventDefault(); }
        if (e.key === "m" || e.key === "M") { missileQueued = true; e.preventDefault(); }
        if (e.key === "h" || e.key === "H") { honkQueued = true; e.preventDefault(); }
        if (e.key === "x" || e.key === "X") { pepperQueued = true; e.preventDefault(); }
        if (e.key === "z" || e.key === "Z") { sirenQueued = true; e.preventDefault(); }
        if (e.key === "e" || e.key === "E") { footActQueued = true; e.preventDefault(); } // on-foot interact
        if (e.key === "q" || e.key === "Q") { exitQueued = true; e.preventDefault(); }     // ditch the car
    });
    document.addEventListener("keyup", function (e) {
        if (e.key === "ArrowLeft" || e.key === "a" || e.key === "A") keys.left = false;
        if (e.key === "ArrowRight" || e.key === "d" || e.key === "D") keys.right = false;
        if (e.key === "ArrowUp" || e.key === "w" || e.key === "W") keys.up = false;
        if (e.key === "ArrowDown" || e.key === "s" || e.key === "S") keys.down = false;
    });

    canvas.addEventListener("touchstart", function (e) {
        e.preventDefault();
        getAudio(); // unlock audio on first touch
        audioUnlocked = true;
        unlockAllMusic(); // warm up every track so later scenes don't wait for a tap
        for (var i = 0; i < e.changedTouches.length; i++) {
            var t = e.changedTouches[i];
            var pos = screenToCanvas(t.clientX, t.clientY);
            var btn = hitGameButton(pos);

            if (btn) flashButton(btn);
            if (btn === "pause") {
                pauseQueued = true;
            } else if (btn === "missile") {
                missileQueued = true;
            } else if (btn === "pepper") {
                pepperQueued = true;
            } else if (btn === "siren") {
                sirenQueued = true;
            } else if (btn === "honk") {
                honkQueued = true;
            } else if (btn === "exit") {
                exitQueued = true;
            } else if (btn === "boost") {
                if (boostDblT > 0) { boostLock = !boostLock; boostDblT = 0; } else boostDblT = 0.3;
                if (boostLock) { brakeLock = false; keys.down = false; }
                keys.up = true;
                boostTouchId = t.identifier;
            } else if (btn === "brake") {
                if (brakeDblT > 0) { brakeLock = !brakeLock; brakeDblT = 0; } else brakeDblT = 0.3;
                if (brakeLock) { boostLock = false; keys.up = false; }
                keys.down = true;
                brakeTouchId = t.identifier;
            } else if (btn === "parkLeft") {
                keys.left = true;
                laneQueued = -1; // ensures a fast tap still registers a lane step
                parkLeftTouchId = t.identifier;
            } else if (btn === "parkRight") {
                keys.right = true;
                laneQueued = 1;
                parkRightTouchId = t.identifier;
            } else if (btn === "parkFwd") {
                keys.up = true;
                parkFwdTouchId = t.identifier;
            } else if (btn === "parkRev") {
                keys.down = true;
                parkRevTouchId = t.identifier;
            } else if (btn === "footAct") {
                footActQueued = true;
            } else {
                // Not a button — register click (for menu/shop/game-over) and
                // start finger-drag steering. Drag-to-move scenes (Dina's run,
                // Cookie Catch, Dina's room) use the same single-finger follow as
                // Lulu's driving, so no on-screen arrows are needed.
                clickQueue = pos;
                queueAction();
                tapFx.push({ x: pos.x, y: pos.y, t: 0 }); if (tapFx.length > 6) tapFx.shift();
                if (steerTouchId === null &&
                    (state === "playing" || state === "dinaRun" || state === "footRun" ||
                     state === "footInterior" || state === "cookieCatch" || state === "dinaHome" ||
                     state === "editControls")) {
                    steerTouchId = t.identifier;
                    touchX = pos.x;
                    touchY = pos.y;
                }
            }
        }
    }, { passive: false });

    canvas.addEventListener("touchmove", function (e) {
        e.preventDefault();
        for (var i = 0; i < e.changedTouches.length; i++) {
            var t = e.changedTouches[i];
            if (t.identifier === steerTouchId) {
                var pos = screenToCanvas(t.clientX, t.clientY);
                touchX = pos.x;
                touchY = pos.y;
            }
        }
    }, { passive: false });

    function releaseTouchId(id) {
        if (id === steerTouchId) { steerTouchId = null; touchX = null; touchY = null; }
        if (id === boostTouchId) { keys.up = boostLock; boostTouchId = null; } // stays on if locked
        if (id === brakeTouchId) { keys.down = brakeLock; brakeTouchId = null; }
        if (id === parkLeftTouchId)  { keys.left = false;  parkLeftTouchId = null; }
        if (id === parkRightTouchId) { keys.right = false; parkRightTouchId = null; }
        if (id === parkFwdTouchId)   { keys.up = false;    parkFwdTouchId = null; }
        if (id === parkRevTouchId)   { keys.down = false;  parkRevTouchId = null; }
    }

    canvas.addEventListener("touchend", function (e) {
        e.preventDefault();
        for (var i = 0; i < e.changedTouches.length; i++) {
            releaseTouchId(e.changedTouches[i].identifier);
        }
    }, { passive: false });

    canvas.addEventListener("touchcancel", function (e) {
        for (var i = 0; i < e.changedTouches.length; i++) {
            releaseTouchId(e.changedTouches[i].identifier);
        }
    }, { passive: false });

    // Desktop drag support for the Movable-Controls editor. Touch already drives
    // touchX/touchY via the steer-tracking path (editControls is in the state
    // list); the mouse never did, so a held-mouse drag needs these three hooks.
    // Scoped to state === "editControls" so ordinary gameplay clicks are untouched.
    var editMouseDown = false;
    canvas.addEventListener("mousedown", function (e) {
        getAudio();
        audioUnlocked = true;
        unlockAllMusic();
        var pos = screenToCanvas(e.clientX, e.clientY);
        clickQueue = pos;
        queueAction();
        tapFx.push({ x: pos.x, y: pos.y, t: 0 }); if (tapFx.length > 6) tapFx.shift();
        if (state === "editControls") { editMouseDown = true; touchX = pos.x; touchY = pos.y; }
    });
    canvas.addEventListener("mousemove", function (e) {
        if (editMouseDown && state === "editControls") {
            var pos = screenToCanvas(e.clientX, e.clientY);
            touchX = pos.x; touchY = pos.y;
        }
    });
    window.addEventListener("mouseup", function () {
        if (editMouseDown) { editMouseDown = false; touchX = null; touchY = null; }
    });

    // Tap-feedback ripple: a quick expanding ring where the finger landed. The
    // driving HUD's buttons have their own press fx — this is for the interiors
    // (bar/school/hospital/precinct/beach), whose tap targets gave no feedback.
    function updateTapFx(dt) {
        for (var i = tapFx.length - 1; i >= 0; i--) { tapFx[i].t += dt; if (tapFx[i].t > 0.32) tapFx.splice(i, 1); }
    }
    function drawTapFx() {
        for (var i = 0; i < tapFx.length; i++) {
            var f = tapFx[i], p = f.t / 0.32;
            ctx.save();
            ctx.strokeStyle = "rgba(255,255,255," + (0.55 * (1 - p)) + ")"; ctx.lineWidth = 2.5;
            ctx.beginPath(); ctx.arc(f.x, f.y, 8 + p * 26, 0, Math.PI * 2); ctx.stroke();
            ctx.fillStyle = "rgba(255,255,255," + (0.16 * (1 - p)) + ")"; ctx.fill();
            ctx.restore();
        }
    }

    // Prevent the context menu on long-press (mobile)
    canvas.addEventListener("contextmenu", function (e) { e.preventDefault(); });

    // ── Background / foreground: silence music when the app is backgrounded ──
    // On iOS the HTML5 <audio> music keeps playing after you swipe the app away
    // unless we explicitly pause it. Pause on hide, resume on return.
    function onAppHidden() {
        pauseMusic();
        if (audioCtx && audioCtx.state === "running") { try { audioCtx.suspend(); } catch (e) {} }
    }
    function onAppVisible() {
        if (audioCtx && audioCtx.state === "suspended") { try { audioCtx.resume(); } catch (e) {} }
        resumeMusic();
    }
    document.addEventListener("visibilitychange", function () {
        if (document.hidden) onAppHidden(); else onAppVisible();
    });
    window.addEventListener("pagehide", onAppHidden);
    // Capacitor App.appStateChange is the authoritative iOS background signal
    // (maps to applicationWillResignActive / DidBecomeActive). We keep
    // visibilitychange + pagehide as the web fallback and DROP blur/focus
    // (they false-fire on iOS for keyboards / alerts).
    if (window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.App) {
        try {
            window.Capacitor.Plugins.App.addListener("appStateChange", function (s) {
                if (s && s.isActive) onAppVisible(); else onAppHidden();
            });
        } catch (e) {}
    }

    function getSteer(playerX) {
        var s = 0;
        if (keys.left) s -= 1;
        if (keys.right) s += 1;
        // Mobile: finger-follow steering (continuous) — also when on foot
        if (touchX !== null && (state === "playing" || state === "footRun")) {
            var diff = touchX - playerX;
            s = clamp(diff / 35, -1.4, 1.4);
        }
        return s;
    }

    // ── Utilities ────────────────────────────────────────────
    function lerp(a, b, t) { return a + (b - a) * t; }
    function easeOutBack(t) { var c1 = 1.70158, c3 = c1 + 1; return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2); }
    function easeOutQuad(t) { return 1 - (1 - t) * (1 - t); }
    function easeInOutQuad(t) { return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2; }
    function easeOutElastic(t) { if (t === 0 || t === 1) return t; var c4 = (2 * Math.PI) / 3; return Math.pow(2, -10 * t) * Math.sin((t * 10 - 0.75) * c4) + 1; }

    // Floating particles for +1 text bursts on pickup
    var floaters = [];
    function spawnFloater(x, y, txt, color) {
        floaters.push({ kind: "text", x: x, y: y, t: 0, dur: 0.8, txt: txt, color: color || "#FFD700" });
    }
    function updateFloaters(dt) {
        for (var i = floaters.length - 1; i >= 0; i--) {
            floaters[i].t += dt;
            if (floaters[i].t >= floaters[i].dur) floaters.splice(i, 1);
        }
    }
    function drawFloaters() {
        for (var i = 0; i < floaters.length; i++) {
            var f = floaters[i];
            var p = f.t / f.dur;
            ctx.globalAlpha = 1 - easeOutQuad(p);
            drawText(f.txt, f.x, f.y - 40 * easeOutQuad(p),
                "bold 20px 'Segoe UI', Arial, sans-serif", f.color, "#000", 4);
            ctx.globalAlpha = 1;
        }
    }

    // Scene fade transition — fade-to-dark-then-out on state changes
    var sceneFade = { t: 1, dur: 0.35, next: null, fired: true, onMid: null };
    // Returns true if a transition actually started (false if one is already running).
    // onMid (optional) runs once at the fade midpoint — use it to init the next scene.
    function gotoState(newState, onMid) {
        if (sceneFade.t < sceneFade.dur) return false; // already transitioning
        sceneFade = { t: 0, dur: 0.35, next: newState, fired: false, onMid: onMid || null };
        return true;
    }
    function updateSceneFade(dt) {
        if (sceneFade.t >= sceneFade.dur) return;
        sceneFade.t += dt;
        if (!sceneFade.fired && sceneFade.t >= sceneFade.dur / 2) {
            state = sceneFade.next;
            if (sceneFade.onMid) sceneFade.onMid();
            sceneFade.fired = true;
        }
    }
    function drawSceneFade() {
        if (sceneFade.t >= sceneFade.dur) return;
        var p = sceneFade.t / sceneFade.dur;
        var a = p < 0.5 ? easeInOutQuad(p * 2) : easeInOutQuad((1 - p) * 2);
        ctx.fillStyle = "rgba(15,10,30," + (a * 0.85) + ")";
        ctx.fillRect(0, 0, W, H);
    }

    // Lightweight "iris-in" wipe played on every scene change (the new scene is
    // revealed through a growing circular hole). Triggered from the game loop
    // when `state` changes, so it polishes hard cuts everywhere at once without
    // touching each transition site.
    var stateTrans = { t: 999, dur: 0.34 };
    function startStateTransition() { stateTrans = { t: 0, dur: 0.34 }; }
    function updateStateTransition(dt) { if (stateTrans.t < stateTrans.dur) stateTrans.t += dt; }
    function drawStateTransition() {
        if (stateTrans.t >= stateTrans.dur) return;
        var p = clamp(stateTrans.t / stateTrans.dur, 0, 1);
        var e = easeInOutQuad(p);
        var maxR = Math.sqrt(W * W + H * H) / 2;
        var r = e * maxR;
        ctx.save();
        ctx.fillStyle = "rgba(8,6,20,0.94)";
        ctx.beginPath();
        ctx.rect(0, 0, W, H);
        ctx.arc(W / 2, H / 2, r, 0, Math.PI * 2);
        ctx.fill("evenodd");
        // a soft bright rim on the iris edge for a touch of polish
        if (r > 4 && r < maxR) {
            ctx.globalAlpha = (1 - e) * 0.5;
            ctx.strokeStyle = "#FFE9B0";
            ctx.lineWidth = 3;
            ctx.beginPath(); ctx.arc(W / 2, H / 2, r, 0, Math.PI * 2); ctx.stroke();
        }
        ctx.restore();
    }

    // Button press visual feedback — register hit, draw a brief overlay
    var btnPressFx = {};
    function flashButton(id) { btnPressFx[id] = { t: 0, dur: 0.22 }; }
    function getBtnPressScale(id) {
        var fx = btnPressFx[id];
        if (!fx) return 1;
        var p = clamp(fx.t / fx.dur, 0, 1);
        if (p < 0.5) return 1 - 0.10 * Math.sin(p * Math.PI);
        return 1 + 0.05 * easeOutBack((p - 0.5) * 2) * (1 - p);
    }
    function updateBtnPressFx(dt) {
        if (boostDblT > 0) boostDblT -= dt;
        if (brakeDblT > 0) brakeDblT -= dt;
        for (var k in btnPressFx) {
            btnPressFx[k].t += dt;
            if (btnPressFx[k].t >= btnPressFx[k].dur) delete btnPressFx[k];
        }
    }
    function clamp(v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; }
    function rand(lo, hi) { return lo + Math.random() * (hi - lo); }
    function randInt(lo, hi) { return Math.floor(rand(lo, hi + 1)); }
    function randPick(arr) { return arr[randInt(0, arr.length - 1)]; }

    function roundRect(x, y, w, h, r) {
        r = Math.min(r, w / 2, h / 2);
        ctx.beginPath();
        ctx.moveTo(x + r, y);
        ctx.lineTo(x + w - r, y);
        ctx.arcTo(x + w, y, x + w, y + r, r);
        ctx.lineTo(x + w, y + h - r);
        ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
        ctx.lineTo(x + r, y + h);
        ctx.arcTo(x, y + h, x, y + h - r, r);
        ctx.lineTo(x, y + r);
        ctx.arcTo(x, y, x + r, y, r);
        ctx.closePath();
    }

    function drawText(text, x, y, font, fill, outline, outW, align) {
        ctx.font = font;
        ctx.textAlign = align || "center";
        ctx.textBaseline = "middle";
        ctx.lineJoin = "round";
        ctx.miterLimit = 2;
        if (outline) {
            ctx.strokeStyle = outline;
            ctx.lineWidth = outW || 4;
            ctx.strokeText(text, x, y);
        }
        ctx.fillStyle = fill;
        ctx.fillText(text, x, y);
    }

    function aabb(ax, ay, aw, ah, bx, by, bw, bh) {
        return Math.abs(ax - bx) < (aw + bw) / 2 &&
               Math.abs(ay - by) < (ah + bh) / 2;
    }

    function shadeColor(hex, amount) {
        var col = hexToRgb(hex);
        return rgbToHex(clamp(col.r + amount, 0, 255), clamp(col.g + amount, 0, 255), clamp(col.b + amount, 0, 255));
    }

    function hexToRgb(hex) {
        return {
            r: parseInt(hex.slice(1, 3), 16),
            g: parseInt(hex.slice(3, 5), 16),
            b: parseInt(hex.slice(5, 7), 16)
        };
    }

    function rgbToHex(r, g, b) {
        return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
    }

    function formatNum(n) {
        return n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    }

    function pointInRect(px, py, x, y, w, h) {
        return px >= x && px <= x + w && py >= y && py <= y + h;
    }

    // ── Particle System ──────────────────────────────────────
    var particles = [];

    function spawnCoinSparkle(x, y) {
        for (var i = 0; i < 8; i++) {
            var angle = (Math.PI * 2 / 8) * i;
            particles.push({
                x: x, y: y,
                vx: Math.cos(angle) * rand(60, 120),
                vy: Math.sin(angle) * rand(60, 120),
                life: 0.45, maxLife: 0.45,
                size: rand(2, 5),
                color: Math.random() > 0.5 ? C.coin : C.coinShine,
                gravity: 0
            });
        }
    }

    function spawnCrashBurst(x, y, big) {
        var cols = ["#FF5722", "#FF9800", "#F44336", "#9E9E9E", "#FFD700", "#FFC107"];
        var count = big ? 40 : 16;
        for (var i = 0; i < count; i++) {
            var angle = rand(0, Math.PI * 2);
            var spd = rand(big ? 120 : 80, big ? 380 : 250);
            particles.push({
                x: x, y: y,
                vx: Math.cos(angle) * spd,
                vy: Math.sin(angle) * spd,
                life: rand(0.6, big ? 1.4 : 1.0), maxLife: big ? 1.2 : 0.8,
                size: rand(big ? 4 : 3, big ? 12 : 8),
                color: randPick(cols),
                gravity: 350
            });
        }
        // Smoke particles
        if (big) {
            for (var j = 0; j < 15; j++) {
                var ang = rand(0, Math.PI * 2);
                particles.push({
                    x: x + rand(-10, 10), y: y + rand(-10, 10),
                    vx: Math.cos(ang) * rand(20, 60),
                    vy: Math.sin(ang) * rand(-80, -20),
                    life: rand(1.0, 2.0), maxLife: 1.5,
                    size: rand(8, 16),
                    color: randPick(["#424242", "#616161", "#9E9E9E"]),
                    gravity: -30,
                    smoke: true
                });
            }
        }
    }

    // Celebratory confetti — fluttering rotating rectangles that drift down.
    // Used on big wins (new high score) for a satisfying payoff.
    function spawnConfetti(x, y, count) {
        var cols = ["#FF5252", "#FFD54F", "#69F0AE", "#40C4FF", "#E040FB", "#FF80AB", "#FFFFFF"];
        count = count || 60;
        for (var i = 0; i < count; i++) {
            var ang = rand(-Math.PI * 0.85, -Math.PI * 0.15);
            var spd = rand(160, 460);
            particles.push({
                x: x + rand(-30, 30), y: y,
                vx: Math.cos(ang) * spd,
                vy: Math.sin(ang) * spd,
                life: rand(1.4, 2.6), maxLife: 2.2,
                size: rand(4, 8),
                color: randPick(cols),
                gravity: 320,
                confetti: true,
                rot: rand(0, Math.PI * 2),
                spin: rand(-9, 9),
                wob: rand(0, Math.PI * 2)
            });
        }
    }

    function updateParticles(dt) {
        for (var i = particles.length - 1; i >= 0; i--) {
            var p = particles[i];
            p.x += p.vx * dt;
            p.y += p.vy * dt;
            p.vy += p.gravity * dt;
            if (p.confetti) {
                p.rot += p.spin * dt;
                p.wob += dt * 6;
                p.x += Math.sin(p.wob) * 28 * dt;   // gentle side-to-side flutter
                p.vx *= 0.97;                         // air drag so they settle
            }
            p.life -= dt;
            if (p.smoke) p.size += dt * 8;
            if (p.life <= 0) particles.splice(i, 1);
        }
    }

    function drawParticles() {
        for (var i = 0; i < particles.length; i++) {
            var p = particles[i];
            var alpha = clamp(p.life / p.maxLife, 0, 1);
            if (p.confetti) {
                ctx.save();
                ctx.globalAlpha = alpha;
                ctx.translate(p.x, p.y);
                ctx.rotate(p.rot);
                ctx.fillStyle = p.color;
                // flip width by the flutter so it looks like a spinning flake
                var w = p.size * (0.4 + Math.abs(Math.cos(p.wob)) * 0.9);
                ctx.fillRect(-w / 2, -p.size / 2, w, p.size);
                ctx.restore();
                continue;
            }
            ctx.globalAlpha = p.smoke ? alpha * 0.6 : alpha;
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size * (p.smoke ? 1 : alpha), 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.globalAlpha = 1;
    }

    // ── Decorations ──────────────────────────────────────────
    var decorations = [];
    var decoTimer = 0;

    function initDecorations() {
        decorations = [];
        for (var y = -100; y < H + 100; y += 70) pushDeco(y, true);
    }

    function pushDeco(y, both) {
        if (both) {
            pushDecoSide(y, -1);
            pushDecoSide(y + rand(-30, 30), 1);
        } else {
            pushDecoSide(y, Math.random() > 0.5 ? -1 : 1);
        }
    }

    function pushDecoSide(y, side) {
        var type = Math.random();
        var x = side < 0 ? rand(10, ROAD_L - 15) : rand(ROAD_R + 15, W - 10);
        var d = { x: x, y: y, side: side, parallax: rand(0.55, 0.85) };
        var cfg = SEASONS[season];
        // Bridge railings are drawn as part of the road — no shoulder clutter.
        if (zone === "bridge") return;
        // Beach: the seaward (left) side is open water; the sandy (right) side
        // gets palms, umbrellas and the odd beach ball.
        if (zone === "beach") {
            if (side < 0) return;
            var br = Math.random();
            if (br < 0.45) { d.type = "palm"; d.scale = rand(0.85, 1.2); d.swayOffset = rand(0, Math.PI * 2); }
            else if (br < 0.78) { d.type = "umbrella"; d.scale = rand(0.7, 1.0); d.color = randPick(["#E53935", "#1E88E5", "#FB8C00", "#8E24AA"]); }
            else { d.type = "beachball"; d.scale = rand(0.5, 0.8); }
            decorations.push(d);
            return;
        }
        // In city zones the shoulder is sidewalk railings, not forest, so the
        // themed buildings read clearly behind them.
        if (zone !== "rural") {
            d.type = "fence"; d.width = rand(28, 50);
            decorations.push(d);
            return;
        }
        // Winter sprinkles snow piles along the shoulder.
        if (cfg.bare && type < 0.16) {
            d.type = "snowpile"; d.scale = rand(0.7, 1.2);
        } else if (type < 0.50) {
            d.type = "tree"; d.scale = rand(0.7, 1.1); d.swayOffset = rand(0, Math.PI * 2);
        } else if (type < 0.72) {
            d.type = "bush"; d.scale = rand(0.6, 1.0); d.bounceOffset = rand(0, Math.PI * 2);
        } else if (type < 0.72 + cfg.flower) {
            // Flower frequency follows the season (lush in spring, none in winter).
            d.type = "flower"; d.color = randPick(C.flower); d.scale = rand(0.5, 0.8);
        } else {
            d.type = "fence"; d.width = rand(30, 55);
        }
        decorations.push(d);
    }

    function updateDecorations(dt, speed) {
        for (var i = decorations.length - 1; i >= 0; i--) {
            decorations[i].y += speed * decorations[i].parallax * dt;
            if (decorations[i].y > H + 80) decorations.splice(i, 1);
        }
        decoTimer -= dt;
        if (decoTimer <= 0) {
            decoTimer = rand(0.15, 0.4);
            pushDeco(-rand(40, 100), false);
        }
    }

    // ── Seasons / weather ────────────────────────────────────
    // The world cycles through seasons every ~SEASON_DISTANCE of travel. Each
    // season retints the sky/grass/foliage, sets a weather effect, a darkness
    // level, and a puddle-frequency multiplier. Easy to tweak below.
    var SEASONS = {
        summer: { name: "Summer ☀️", sky: ["#A8E6CF", "#7CCB7E", "#5BA85D"], grass: "#66BB6A",
                  trees: ["#2E7D32", "#388E3C", "#43A047"], bushes: ["#66BB6A", "#4CAF50", "#388E3C"],
                  dark: 0, weather: null, puddleMul: 1, flower: 0.15, bare: false },
        spring: { name: "Spring 🌸", sky: ["#BFE9FF", "#CDEFC4", "#9CD98C"], grass: "#7CC36A",
                  trees: ["#7CB342", "#9CCC65", "#AED581"], bushes: ["#9CCC65", "#7CB342", "#689F38"],
                  dark: 0, weather: "petals", puddleMul: 1, flower: 0.34, bare: false },
        fall:   { name: "Fall 🍂", sky: ["#FFE0B2", "#F6C98E", "#D9A05B"], grass: "#C2A14B",
                  trees: ["#E65100", "#EF6C00", "#F9A825"], bushes: ["#C0691E", "#A0522D", "#8D4E1E"],
                  dark: 0.05, weather: "leaves", puddleMul: 1, flower: 0.05, bare: false },
        winter: { name: "Winter ❄️", sky: ["#D4E6F1", "#C2D8E8", "#AEC9DC"], grass: "#E8EEF2",
                  trees: ["#9DB1B8", "#8D9499", "#B0BEC5"], bushes: ["#E0E8EC", "#C5D2D8", "#A7B8C0"],
                  dark: 0.12, weather: "snow", puddleMul: 1.5, flower: 0, bare: true },
        rain:   { name: "Rainy 🌧️", sky: ["#9AABB5", "#80949F", "#65808C"], grass: "#4E7A52",
                  trees: ["#2E5E32", "#356B39", "#3E7A42"], bushes: ["#3E7A42", "#356B39", "#2E5E32"],
                  dark: 0.22, weather: "rain", puddleMul: 2.4, flower: 0.08, bare: false },
        storm:  { name: "Thunderstorm ⛈️", sky: ["#5C6670", "#474F57", "#363C42"], grass: "#3E5E44",
                  trees: ["#23421F", "#2A4D26", "#33592E"], bushes: ["#33592E", "#2A4D26", "#23421F"],
                  dark: 0.38, weather: "rain", puddleMul: 2.6, flower: 0.05, bare: false, lightning: true },
        night:  { name: "Night 🌙", sky: ["#1A2238", "#222A45", "#2A3350"], grass: "#2E4A36",
                  trees: ["#1B3A22", "#234A2A", "#2A5530"], bushes: ["#234A2A", "#1B3A22", "#163018"],
                  dark: 0.5, weather: null, puddleMul: 1, flower: 0.05, bare: false, night: true },
        fog:    { name: "Foggy 🌫️", sky: ["#C8CDD0", "#BFC4C7", "#B4B9BC"], grass: "#6E8270",
                  trees: ["#4A6B4E", "#557056", "#5E7A5F"], bushes: ["#5E7A5F", "#557056", "#4A6B4E"],
                  dark: 0.06, weather: null, puddleMul: 1.1, flower: 0.08, bare: false, fog: true },
        heatwave: { name: "Heat Wave 🥵", sky: ["#FFE08A", "#FFC85E", "#FBA94C"], grass: "#B8A24E",
                  trees: ["#9C8A3C", "#A8923F", "#B89C44"], bushes: ["#B89C44", "#A8923F", "#9C8A3C"],
                  dark: 0, weather: "dust", puddleMul: 0.3, flower: 0.04, bare: false, heat: true },
        // Story-exclusive golden hour (Avigail's boutique aesthetic). NOT in
        // SEASON_ORDER — cruise never rolls it; only setSeason("dusk") reaches it.
        dusk:   { name: "Dusk 🌆", sky: ["#F6A5C0", "#C97BA4", "#8E5D9F"], grass: "#5E7A52",
                  trees: ["#3E5E3A", "#4A6B44", "#57784E"], bushes: ["#57784E", "#4A6B44", "#3E5E3A"],
                  dark: 0.16, weather: null, puddleMul: 1, flower: 0.12, bare: false }
    };
    var SEASON_ORDER = ["spring", "fall", "winter", "rain", "storm", "night", "fog", "heatwave"];
    var SEASON_DISTANCE = 24000;  // px of travel between season changes (longer = rarer)

    var season = "summer", prevSeason = "summer", seasonBlend = 1;
    var seasonNextAt = SEASON_DISTANCE, seasonBannerT = 0;
    var weatherBits = [], weatherAccum = 0;
    var lightningFlash = 0, lightningTimer = 4, lightningStrike = null;

    function initSeason() {
        season = "summer"; prevSeason = "summer"; seasonBlend = 1;
        seasonNextAt = SEASON_DISTANCE + rand(-5000, 6000);
        seasonBannerT = 0; weatherBits = []; weatherAccum = 0;
        lightningFlash = 0; lightningTimer = rand(2, 5); lightningStrike = null;
    }
    function changeSeason() {
        prevSeason = season;
        // Spend most of the time in plain Summer; specials are occasional. If
        // we're in a special season, usually return to Summer; from Summer, pick
        // a random special one.
        var pick;
        if (season !== "summer" && Math.random() < 0.55) {
            pick = "summer";
        } else {
            var tries = 0; pick = season;
            while (pick === season && tries < 12) { pick = randPick(SEASON_ORDER); tries++; }
        }
        season = pick;
        seasonBlend = 0;
        seasonNextAt = scrollOffset + SEASON_DISTANCE + rand(-5000, 6000);
        seasonBannerT = 0;
        lightningTimer = rand(1.5, 4);
    }
    // Transition to a SPECIFIC season (used for atmospheric zone pairings).
    function setSeason(target) {
        if (!SEASONS[target] || target === season) return;
        prevSeason = season;
        season = target;
        seasonBlend = 0;
        lightningTimer = rand(1.5, 4);
    }
    function curSeason() { return SEASONS[season]; }
    function lerpColor(a, b, t) {
        var ca = hexToRgb(a), cb = hexToRgb(b);
        return rgbToHex(Math.round(lerp(ca.r, cb.r, t)), Math.round(lerp(ca.g, cb.g, t)), Math.round(lerp(ca.b, cb.b, t)));
    }
    function seasonSky(i) { return lerpColor(SEASONS[prevSeason].sky[i], SEASONS[season].sky[i], seasonBlend); }
    function seasonGrass() { return lerpColor(SEASONS[prevSeason].grass, SEASONS[season].grass, seasonBlend); }
    function seasonDark() { return lerp(SEASONS[prevSeason].dark, SEASONS[season].dark, seasonBlend); }

    function updateSeason(dt, speed) {
        if (seasonBlend < 1) seasonBlend = Math.min(1, seasonBlend + dt / 1.8);
        if (seasonBannerT > 0) seasonBannerT -= dt;
        // Hold the forced bright sky steady through scenic biomes — no random
        // flip to rain/snow/night mid-bridge or mid-beach. The deferred change
        // simply fires once the crossing ends (back on the rural road).
        // STORY chapter sets HOLD their directed season — cruise rotates as usual.
        if (scrollOffset >= seasonNextAt && zone !== "bridge" && zone !== "beach" &&
            !(typeof storySeasonHold === "function" && storySeasonHold())) changeSeason();
        var cfg = SEASONS[season];
        // spawn weather
        var rate = cfg.weather === "rain" ? 95 : cfg.weather === "snow" ? 30
                 : cfg.weather === "leaves" ? 11 : cfg.weather === "petals" ? 9
                 : cfg.weather === "dust" ? 24 : 0;
        if (rate > 0 && seasonBlend > 0.25) {
            weatherAccum += rate * dt;
            while (weatherAccum >= 1) { weatherAccum -= 1; pushWeatherBit(cfg.weather, speed); }
            // spring also gets the occasional butterfly fluttering across
            if (cfg.weather === "petals" && Math.random() < dt * 0.4) pushButterfly();
        }
        for (var i = weatherBits.length - 1; i >= 0; i--) {
            var w = weatherBits[i];
            w.x += w.vx * dt; w.y += w.vy * dt;
            if (w.spin !== undefined) w.rot += w.spin * dt;
            if (w.flap !== undefined) w.flap += dt * 14;
            w.life -= dt;
            if (w.y > H + 24 || w.life <= 0 || w.x < -40 || w.x > W + 40) weatherBits.splice(i, 1);
        }
        // lightning
        if (lightningFlash > 0) lightningFlash = Math.max(0, lightningFlash - dt * 3);
        if (lightningStrike) { lightningStrike.t += dt; if (lightningStrike.t > 0.28) lightningStrike = null; }
        if (cfg.lightning && seasonBlend > 0.5) {
            lightningTimer -= dt;
            if (lightningTimer <= 0) { lightningTimer = rand(3, 8); triggerLightning(); }
        }
    }

    function pushWeatherBit(kind, speed) {
        if (kind === "rain") {
            weatherBits.push({ kind: "rain", x: rand(-20, W + 30), y: -20, vx: -120,
                vy: 900 + speed * 0.4, len: rand(10, 18), life: 2 });
        } else if (kind === "snow") {
            weatherBits.push({ kind: "snow", x: rand(0, W), y: -10, vx: rand(-15, 15),
                vy: rand(55, 105) + speed * 0.12, r: rand(1.5, 3.5), sway: rand(0, 6.28), life: 14 });
        } else if (kind === "leaves") {
            weatherBits.push({ kind: "leaf", x: rand(0, W), y: -15, vx: rand(-45, 45),
                vy: rand(70, 130) + speed * 0.2, rot: rand(0, 6.28), spin: rand(-4, 4),
                r: rand(4, 7), color: randPick(["#E65100", "#F57F17", "#FF8F00", "#BF360C"]), life: 12 });
        } else if (kind === "petals") {
            weatherBits.push({ kind: "petal", x: rand(0, W), y: -15, vx: rand(-30, 30),
                vy: rand(50, 90) + speed * 0.15, rot: rand(0, 6.28), spin: rand(-3, 3),
                r: rand(3, 5), color: randPick(["#FF80AB", "#F8BBD0", "#FFCDD2", "#F48FB1"]), life: 12 });
        } else if (kind === "dust") {
            var d2 = Math.random() < 0.5 ? 1 : -1;
            weatherBits.push({ kind: "dust", x: d2 > 0 ? -20 : W + 20, y: rand(H * 0.25, H - 50),
                vx: d2 * rand(180, 340), vy: rand(-12, 12), r: rand(2, 5),
                color: randPick(["#D2B48C", "#C9A66B", "#E0C28A"]), life: 4 });
        }
    }
    function pushButterfly() {
        var dir = Math.random() < 0.5 ? 1 : -1;
        weatherBits.push({ kind: "butterfly", x: dir > 0 ? -20 : W + 20, y: rand(60, H * 0.55),
            vx: dir * rand(60, 100), vy: rand(-10, 10), flap: rand(0, 6.28),
            color: randPick(["#FF7043", "#AB47BC", "#42A5F5", "#FFCA28"]), life: 9, dir: dir });
    }

    function triggerLightning() {
        lightningFlash = 1;
        playThunder();
        if (Math.random() < 0.45 && typeof obstacles !== "undefined" && obstacles && obstacles.length) {
            var cand = [];
            for (var i = 0; i < obstacles.length; i++) {
                var o = obstacles[i];
                if (o.y > 30 && o.y < H - 130 && (o.type === "car" || o.type === "cone" || o.type === "ped")) cand.push(i);
            }
            if (cand.length) {
                var idx = randPick(cand);
                var ob = obstacles[idx];
                lightningStrike = { x: ob.x, y: ob.y, t: 0 };
                spawnCrashBurst(ob.x, ob.y, true);
                obstacles.splice(idx, 1);
            }
        }
    }

    function drawWeather() {
        for (var i = 0; i < weatherBits.length; i++) {
            var w = weatherBits[i];
            if (w.kind === "rain") {
                ctx.strokeStyle = "rgba(185,212,235,0.55)"; ctx.lineWidth = 1.5;
                ctx.beginPath(); ctx.moveTo(w.x, w.y); ctx.lineTo(w.x - 3, w.y - w.len); ctx.stroke();
            } else if (w.kind === "snow") {
                ctx.fillStyle = "rgba(255,255,255,0.9)";
                ctx.beginPath(); ctx.arc(w.x + Math.sin(w.sway + w.y * 0.04) * 8, w.y, w.r, 0, Math.PI * 2); ctx.fill();
            } else if (w.kind === "butterfly") {
                ctx.save(); ctx.translate(w.x, w.y);
                var flap = Math.abs(Math.sin(w.flap)) * 0.8 + 0.2;
                ctx.fillStyle = w.color;
                ctx.beginPath(); ctx.ellipse(-3, 0, 3 * flap, 4, -0.4, 0, Math.PI * 2); ctx.fill();
                ctx.beginPath(); ctx.ellipse(3, 0, 3 * flap, 4, 0.4, 0, Math.PI * 2); ctx.fill();
                ctx.fillStyle = "#3E2723";
                ctx.fillRect(-0.6, -3, 1.2, 6);
                ctx.restore();
            } else if (w.kind === "dust") {
                ctx.globalAlpha = 0.5;
                ctx.fillStyle = w.color;
                ctx.beginPath(); ctx.ellipse(w.x, w.y, w.r * 2.2, w.r, 0, 0, Math.PI * 2); ctx.fill();
                ctx.globalAlpha = 1;
            } else { // leaf / petal
                ctx.save(); ctx.translate(w.x, w.y); ctx.rotate(w.rot);
                ctx.fillStyle = w.color;
                ctx.beginPath(); ctx.ellipse(0, 0, w.r, w.r * 0.55, 0, 0, Math.PI * 2); ctx.fill();
                ctx.restore();
            }
        }
    }

    // Darkness tint + weather + lightning + season banner. Drawn over the world
    // (call after the scene, before the HUD).
    function drawSeasonFx() {
        var cfg = curSeason();
        var dk = seasonDark();
        if (dk > 0.001) { ctx.fillStyle = "rgba(12,16,38," + dk + ")"; ctx.fillRect(0, 0, W, H); }
        if (cfg.night && seasonBlend > 0.35) drawNightFx();
        if (cfg.fog) drawFogFx();
        if (cfg.heat) drawHeatFx();
        drawWeather();
        if (lightningStrike && lightningStrike.t < 0.18) {
            ctx.strokeStyle = "#FFFDE7"; ctx.lineWidth = 3; ctx.lineCap = "round";
            ctx.beginPath();
            var lx = lightningStrike.x, ly = 0;
            ctx.moveTo(lx, 0);
            while (ly < lightningStrike.y) { ly += rand(20, 42); lx += rand(-18, 18); ctx.lineTo(lx, ly); }
            ctx.stroke(); ctx.lineCap = "butt";
        }
        if (lightningFlash > 0) { ctx.fillStyle = "rgba(255,255,255," + (lightningFlash * 0.5) + ")"; ctx.fillRect(0, 0, W, H); }
    }

    function drawNightFx() {
        // Headlight beams from Lulu's car lighting the road ahead — but NOT when
        // she's on foot (she has no car, so floating headlights looked silly).
        if (typeof player !== "undefined" && player && state !== "footRun") {
            var hx = player.x, hy = player.y - 34;
            var g = ctx.createLinearGradient(0, hy, 0, hy - 200);
            g.addColorStop(0, "rgba(255,248,200,0.20)");
            g.addColorStop(1, "rgba(255,248,200,0)");
            ctx.fillStyle = g;
            ctx.beginPath();
            ctx.moveTo(hx - 13, hy); ctx.lineTo(hx - 62, hy - 200);
            ctx.lineTo(hx + 62, hy - 200); ctx.lineTo(hx + 13, hy);
            ctx.closePath(); ctx.fill();
        }
    }
    function drawFogFx() {
        var g = ctx.createLinearGradient(0, 0, 0, H);
        g.addColorStop(0, "rgba(222,226,229,0.62)");
        g.addColorStop(0.5, "rgba(222,226,229,0.36)");
        g.addColorStop(1, "rgba(222,226,229,0.16)");
        ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
        for (var i = 0; i < 4; i++) {
            var fy = ((gameTime * 16 + i * 130) % (H + 120)) - 60;
            ctx.fillStyle = "rgba(238,240,242,0.12)";
            ctx.beginPath(); ctx.ellipse(W / 2, fy, W * 0.72, 42, 0, 0, Math.PI * 2); ctx.fill();
        }
    }
    function drawHeatFx() {
        ctx.fillStyle = "rgba(255,176,72,0.10)"; ctx.fillRect(0, 0, W, H);
        // wavering heat-shimmer bands near the horizon
        for (var i = 0; i < 7; i++) {
            var yy = H * 0.12 + i * 16 + Math.sin(gameTime * 3 + i) * 3;
            ctx.fillStyle = "rgba(255,255,255,0.05)";
            ctx.fillRect(0, yy, W, 4);
        }
    }

    // ── City zones (themed scenery stretches) ────────────────
    // Most of the drive is rural. Occasionally you pass through a CITY zone with
    // themed roadside buildings and matching traffic: a bar district (drunk
    // drivers), police HQ (lots of cops), a school zone (kids crossing), or
    // downtown (texting drivers). Zones last a good stretch so they don't flash by.
    var ZONE_CITY = ["bars", "police", "school", "downtown", "hospital", "construction", "gas", "market", "salon", "parking"];
    // Weighted city picker: the bar district is a signature set-piece (drunks
    // catcalling Lulu), so it's a touch more common than the rest — but only
    // slightly, and never forced to be first. Everything else is equal-weight.
    var ZONE_CITY_WEIGHT = { bars: 2 };
    function pickCityZone() {
        var total = 0, i;
        for (i = 0; i < ZONE_CITY.length; i++) total += ZONE_CITY_WEIGHT[ZONE_CITY[i]] || 1;
        var r = Math.random() * total;
        for (i = 0; i < ZONE_CITY.length; i++) {
            r -= ZONE_CITY_WEIGHT[ZONE_CITY[i]] || 1;
            if (r < 0) return ZONE_CITY[i];
        }
        return ZONE_CITY[0];
    }
    var ZONE_SCENIC = ["bridge", "beach"]; // open-water / coast biomes (no buildings)
    var ZONE_NAMES = {
        bars: "Bar District 🍸", police: "Police HQ 🚓", school: "School Zone 🏫", downtown: "Downtown 🏙️",
        hospital: "Hospital 🏥", construction: "Construction 🚧", gas: "Gas Station ⛽", market: "Farmers Market 🧺",
        salon: "Salon Row 💇", parking: "Parking District 🅿️",
        bridge: "Bridge Crossing 🌉", beach: "Coast Road 🏖️"
    };
    // Each city often arrives with a fitting sky (atmospheric combos).
    var ZONE_SEASON = {
        bars: ["night", "night", "rain"], downtown: ["night", "fog", "rain"],
        police: ["night", "rain"], school: ["summer", "spring"],
        market: ["summer", "spring"], construction: ["summer", "heatwave"],
        hospital: ["summer", "fog"], gas: ["summer", "night"],
        salon: ["spring", "summer"], parking: ["night", "fog"]
    };
    var ZONE_RURAL_GAP = 11000;   // px of rural driving between city visits
    var zone = "rural";
    var zoneEndsAt = 0, zoneNextAt = ZONE_RURAL_GAP;
    var cityBuildings = [], cityBuildTimer = 0;
    var policeLotCount = 0;   // # of roadside police lots spawned this police zone (cap ~2)
    var citiesSeen = 0; // used to fast-track the bar district on the first city visit

    function initZone() {
        zone = "rural";
        zoneNextAt = ZONE_RURAL_GAP + rand(-3000, 5000);
        zoneEndsAt = 0; cityBuildings = []; cityBuildTimer = 0;
        citiesSeen = 0;
        if (typeof sidewalkFolk !== "undefined") { sidewalkFolk = []; folkTimer = 0; }
    }
    function updateZone(dt, speed) {
        if (zone === "rural") {
            if (scrollOffset >= zoneNextAt) {
                // STORY chapter DIRECTION (null in cruise): may bias scenic odds /
                // force a scenic or city kind for the leg's set. Cruise = unchanged.
                var zb = (typeof storyZoneBias === "function") ? storyZoneBias() : null;
                var scenicProb = 0.2, scenicKind = null, cityKind = null;
                if (zb) {
                    if (typeof zb.scenic === "number") scenicProb = zb.scenic;
                    if (zb.scenicKind) scenicKind = zb.scenicKind;
                    if (zb.cityKind) cityKind = zb.cityKind;
                }
                var held = (typeof storySeasonHold === "function" && storySeasonHold());
                // ~1-in-5 visits is a scenic crossing instead of a city. The first
                // visit is never scenic so a fresh session reaches a city promptly
                // (a forced scenic kind skips that requirement — the leg WANTS it).
                if ((scenicKind || citiesSeen > 0) && Math.random() < scenicProb) {
                    zone = scenicKind || randPick(ZONE_SCENIC);
                    zoneEndsAt = scrollOffset + rand(5500, 8000);
                    if (!held) setSeason("summer"); // bright skies over the water & sand
                } else {
                    // Every city is a fresh weighted random roll — no zone is ever
                    // forced (the bar district just has a slightly higher weight);
                    // a story leg may PREFER a district (70%) to dress its set.
                    zone = (cityKind && Math.random() < 0.7) ? cityKind : pickCityZone();
                    citiesSeen++;
                    zoneEndsAt = scrollOffset + rand(7000, 11000); // long enough to feel it
                    // Atmospheric pairing: a city often brings a fitting sky.
                    if (ZONE_SEASON[zone] && Math.random() < 0.6 && !held) setSeason(randPick(ZONE_SEASON[zone]));
                }
                cityBuildTimer = 0;
                policeLotCount = 0;   // fresh zone → it can grow a lot or two again
            }
        } else {
            if (scrollOffset >= zoneEndsAt) {
                zone = "rural";
                // STORY: a leg's set can stretch the quiet rural gap (bubbe = +30%).
                var zb2 = (typeof storyZoneBias === "function") ? storyZoneBias() : null;
                var gapMul = (zb2 && typeof zb2.ruralGapMul === "number") ? zb2.ruralGapMul : 1;
                zoneNextAt = scrollOffset + (ZONE_RURAL_GAP + rand(-3000, 5000)) * gapMul;
            }
            // Only city zones grow buildings; scenic biomes use shoulder deco.
            if (zone !== "bridge" && zone !== "beach") {
                cityBuildTimer -= dt;
                if (cityBuildTimer <= 0) {
                    // Spaced out + sides chosen independently so it's a streetscape,
                    // not a solid wall of identical boxes.
                    cityBuildTimer = rand(1.0, 1.8);
                    // The police zone grows a roadside motor-pool once or twice.
                    if (zone === "police" && policeLotCount < 2 && Math.random() < 0.45) {
                        spawnPoliceLot(Math.random() < 0.5 ? -1 : 1); policeLotCount++;
                    } else {
                        if (Math.random() < 0.85) spawnCityBuilding(-1);
                        if (Math.random() < 0.7) spawnCityBuilding(1);
                    }
                }
            }
        }
        for (var i = cityBuildings.length - 1; i >= 0; i--) {
            cityBuildings[i].y += speed * dt;
            if (cityBuildings[i].y > H + 160) cityBuildings.splice(i, 1);
        }
        updateSidewalkFolk(dt, speed);
    }

    // ── Sidewalk folk: ambient city pedestrians ─────────────────────────────
    // Purely decorative people strolling the sidewalks of city stretches — some
    // emerge FROM a storefront, some walk along and duck INTO one. No collision,
    // no interaction: they're what makes a street read as a living city.
    var sidewalkFolk = [], folkTimer = 0;
    function updateSidewalkFolk(dt, speed) {
        var cityish = zone !== "rural" && zone !== "bridge" && zone !== "beach";
        folkTimer -= dt;
        if (cityish && folkTimer <= 0 && sidewalkFolk.length < 5) {
            // STORY: a leg's set can thicken foot traffic (bubbe erev-Shabbos = ×0.5).
            folkTimer = rand(1.6, 3.2) * ((typeof storyFolkMul === "function") ? storyFolkMul() : 1);
            var side = Math.random() < 0.5 ? -1 : 1;
            var sx = side < 0 ? rand(Math.max(20, ROAD_L - 34), Math.max(24, ROAD_L - 14)) : rand(ROAD_R + 14, ROAD_R + 34);
            var f = { x: sx, y: -26, side: side, dir: Math.random() < 0.6 ? 1 : -1,
                      spd: rand(26, 52), walkTime: rand(0, 5), pedType: randInt(0, 2),
                      mode: "stroll", fade: 0 };
            // A third of them step OUT of a storefront on their side instead.
            if (Math.random() < 0.34) {
                for (var b = 0; b < cityBuildings.length; b++) {
                    var cb = cityBuildings[b];
                    if (cb.side === side && cb.y > -60 && cb.y + cb.h < H * 0.45) {
                        f.y = cb.y + cb.h + 6; f.x = cb.x; f.mode = "exiting"; f.fade = 1; break;
                    }
                }
            }
            sidewalkFolk.push(f);
        }
        for (var i = sidewalkFolk.length - 1; i >= 0; i--) {
            var p = sidewalkFolk[i];
            p.y += speed * dt + p.dir * p.spd * dt * (p.mode === "stroll" ? 1 : 0.5);
            p.walkTime += dt;
            if (p.mode === "exiting") { p.fade -= dt * 1.6; if (p.fade <= 0) { p.fade = 0; p.mode = "stroll"; } }
            // Strollers sometimes spot a shop coming up on their side and go in.
            if (p.mode === "stroll" && !p.target && Math.random() < dt * 0.25) {
                for (var b2 = 0; b2 < cityBuildings.length; b2++) {
                    var tb = cityBuildings[b2];
                    if (tb.side === p.side && tb.y + tb.h > p.y - 140 && tb.y + tb.h < p.y - 30) { p.target = tb; break; }
                }
            }
            if (p.target) {
                var dy = (p.target.y + p.target.h + 6) - p.y;
                p.y += clamp(dy, -40 * dt, 40 * dt);                 // drift to the doorway
                p.x += clamp(p.target.x - p.x, -30 * dt, 30 * dt);
                if (Math.abs(dy) < 5 && Math.abs(p.target.x - p.x) < 6) {
                    p.mode = "entering"; p.fade = (p.fade || 0) + dt * 2.2;
                    if (p.fade >= 1) { sidewalkFolk.splice(i, 1); continue; }   // stepped inside
                }
            }
            if (p.y > H + 40 || p.y < -60 || (!cityish && p.y > H * 0.5)) sidewalkFolk.splice(i, 1);
        }
    }
    function drawSidewalkFolk() {
        for (var i = 0; i < sidewalkFolk.length; i++) {
            var p = sidewalkFolk[i];
            ctx.save();
            if (p.fade > 0) ctx.globalAlpha = clamp(1 - p.fade, 0, 1);   // door fade in/out
            if (typeof drawPedestrian === "function") drawPedestrian(p.x, p.y, p.walkTime, p.pedType);
            ctx.restore();
        }
    }
    function spawnPoliceLot(side) {
        var lw = 92, lh = 150;
        var x = side < 0 ? Math.max(lw / 2 + 2, ROAD_L / 2)
                         : Math.min(W - lw / 2 - 2, (ROAD_R + W) / 2);
        cityBuildings.push({ x: x, y: -lh - 30, side: side, kind: "policeLot", w: lw, h: lh });
    }
    // A real street is a MIX — the zone sets the flavor (about half the
    // buildings), the rest is the usual city jumble of shops and offices.
    // (Before this, a "salon" zone was 100% salons — a monoculture street.)
    var CITY_MIX = ["downtown", "downtown", "market", "gas", "bakery", "pizza", "books", "salon", "bars", "parking"];
    function cityKindFor() {
        var own = zone === "police" || zone === "construction" ? 0.6 : 0.45;
        return Math.random() < own ? zone : randPick(CITY_MIX);
    }
    function spawnCityBuilding(side) {
        var kind = cityKindFor();
        var shortKind = (kind === "market" || kind === "gas" || kind === "salon" ||
                         kind === "bakery" || kind === "pizza" || kind === "books");
        var w = kind === "parking" ? rand(70, 96) : rand(50, 74);
        var h = shortKind ? rand(64, 92) : (kind === "parking" ? rand(96, 138) : rand(74, kind === "downtown" ? 162 : 126));
        var x = side < 0 ? rand(6, Math.max(8, ROAD_L - w - 6)) + w / 2
                         : rand(ROAD_R + 6, W - w - 6) + w / 2;
        // All variety is chosen ONCE here (stable per building → no flicker).
        var label = kind === "bars" ? randPick(BAR_NAMES)
                  : kind === "school" ? randPick(SCHOOL_NAMES)
                  : BUILD_LABEL[kind];
        cityBuildings.push({ x: x, y: -h - 36, side: side, kind: kind, w: w, h: h,
            lit: Math.random() < 0.72, tint: randInt(0, 2), seed: randInt(1, 997),
            style: randInt(0, 2), roof: randInt(0, 2), shade: randInt(-12, 12),
            label: label, glow: kind === "bars" && Math.random() < 0.3,
            signC: kind === "bars" ? randPick(["#FF4FA3", "#4FC3F7", "#FFD54F", "#AED581", "#FF8A65"]) : BUILD_SIGN[kind],
            roofC: randPick(["#5D4037", "#455A64", "#37474F", "#6D4C41", "#4E342E", "#827717"]),
            awn: [randInt(0, 3), randInt(0, 3)], prod: [randInt(0, 4), randInt(0, 4), randInt(0, 4)] });
    }
    function drawCityBuildings() {
        for (var i = 0; i < cityBuildings.length; i++) drawBuilding(cityBuildings[i]);
    }
    // Draw bold text shrunk to fit maxW (stops names spilling out of buildings).
    function drawFitText(text, cx, cy, maxW, basePx, color, outline) {
        var px = basePx;
        ctx.font = "bold " + px + "px 'Segoe UI', Arial, sans-serif";
        while (px > 5 && ctx.measureText(text).width > maxW) {
            px--; ctx.font = "bold " + px + "px 'Segoe UI', Arial, sans-serif";
        }
        ctx.textAlign = "center"; ctx.textBaseline = "middle"; ctx.lineJoin = "round";
        if (outline) { ctx.strokeStyle = outline; ctx.lineWidth = 3; ctx.strokeText(text, cx, cy); }
        ctx.fillStyle = color; ctx.fillText(text, cx, cy);
    }
    var BUILD_BODY = {
        bars: ["#3E2C4F", "#4A3A5C", "#5C2E52"], police: ["#37474F", "#455A64", "#2E3D44"],
        school: ["#9C4A3C", "#A85A48", "#8C4234"], downtown: ["#546E7A", "#607D8B", "#7E8A93"],
        hospital: ["#ECEFF1", "#E0E4E7", "#F5F7F8"], construction: ["#9E8E6E", "#8C7D5E", "#A89A7C"],
        gas: ["#C62828", "#B71C1C", "#D32F2F"], market: ["#6D4C41", "#7B5A4C", "#5D4037"],
        salon: ["#E79BBC", "#EFA9C6", "#DD8BAE"], parking: ["#79858C", "#828E95", "#6E7A81"],
        bakery: ["#EFD9B4", "#E8CFA5", "#F5E3C3"], pizza: ["#C62828", "#B92B2B", "#D13030"],
        books: ["#33574A", "#2E4F43", "#3B6152"]
    };
    var BUILD_LABEL = { bars: "BAR", police: "POLICE", school: "SCHOOL", hospital: "HOSPITAL", gas: "GAS", market: "MARKET", salon: "SALON", parking: "PARKING", bakery: "BAKERY", pizza: "PIZZA", books: "BOOKS" };
    var BAR_NAMES = ["BAR", "PUB", "LOUNGE", "KARAOKE", "TAVERN", "JUICE BAR"];
    var SCHOOL_NAMES = ["SCHOOL", "BAIS YAAKOV", "CHEDER", "ACADEMY", "DAY SCHOOL"];
    var BUILD_SIGN = { bars: "#FF4FA3", police: "#42A5F5", school: "#FFD54F", hospital: "#E53935", gas: "#FFEB3B", market: "#AED581", salon: "#FFC0DD", parking: "#90CAF9", bakery: "#FFB74D", pizza: "#FFF176", books: "#A5D6A7" };
    var AWN_COLS = ["#E53935", "#43A047", "#1E88E5", "#FB8C00"];
    var PRODUCE = ["#FF7043", "#FFCA28", "#8BC34A", "#E53935", "#AB47BC"];
    function drawMarketStall(b) {
        var x = b.x - b.w / 2, w = b.w, baseY = b.y + b.h, stallH = 56, top = baseY - stallH;
        ctx.fillStyle = "rgba(0,0,0,0.16)";
        ctx.beginPath(); ctx.ellipse(x + w / 2, baseY - 2, w / 2, 7, 0, 0, Math.PI * 2); ctx.fill();
        // posts + back board
        ctx.fillStyle = "#8D6E63"; ctx.fillRect(x + 2, top + 10, 5, stallH - 10); ctx.fillRect(x + w - 7, top + 10, 5, stallH - 10);
        ctx.fillStyle = "#BCAAA4"; ctx.fillRect(x + 5, top + 12, w - 10, stallH - 30);
        // produce crates
        var crateY = baseY - 24, cw = (w - 12) / 3;
        for (var c = 0; c < 3; c++) {
            var cx0 = x + 6 + c * cw;
            ctx.fillStyle = "#6D4C41"; ctx.fillRect(cx0, crateY, cw - 2, 16);
            ctx.fillStyle = "#5D4037"; ctx.fillRect(cx0, crateY, cw - 2, 3);
            ctx.fillStyle = PRODUCE[b.prod[c]];
            for (var p = 0; p < 4; p++) {
                ctx.beginPath();
                ctx.arc(cx0 + 4 + (p % 2) * (cw - 12), crateY - 1 - Math.floor(p / 2) * 4, 3, 0, Math.PI * 2);
                ctx.fill();
            }
        }
        ctx.fillStyle = "#8D6E63"; ctx.fillRect(x + 2, baseY - 8, w - 4, 8); // counter front
        // striped scalloped awning
        var a1 = AWN_COLS[b.awn[0]], awY = top - 2, awH = 15, sw0 = 10;
        for (var s = 0; s < w; s += sw0) {
            var sw = Math.min(sw0, w - s);
            ctx.fillStyle = ((s / sw0) % 2) ? "#FAFAFA" : a1;
            ctx.fillRect(x + s, awY, sw, awH);
            ctx.beginPath(); ctx.moveTo(x + s, awY + awH); ctx.lineTo(x + s + sw / 2, awY + awH + 6); ctx.lineTo(x + s + sw, awY + awH); ctx.closePath(); ctx.fill();
        }
        // sign
        ctx.fillStyle = "#3E2723"; roundRect(x + 6, top - 19, w - 12, 14, 3); ctx.fill();
        drawFitText(b.label || "MARKET", x + w / 2, top - 12, w - 16, 9, "#FFF59D");
    }

    function drawSchool(b) {
        var x = b.x - b.w / 2, y = b.y, w = b.w, h = b.h, wi, wy, wx;
        ctx.fillStyle = "rgba(0,0,0,0.18)"; ctx.fillRect(x + 4, y + 8, w, h);
        ctx.fillStyle = shadeColor("#9C4A3C", b.shade); ctx.fillRect(x, y, w, h);
        ctx.strokeStyle = "rgba(0,0,0,0.1)"; ctx.lineWidth = 1;
        for (var br = y + 9; br < y + h; br += 9) { ctx.beginPath(); ctx.moveTo(x, br); ctx.lineTo(x + w, br); ctx.stroke(); }
        ctx.strokeStyle = "rgba(0,0,0,0.4)"; ctx.lineWidth = 2; ctx.strokeRect(x, y, w, h);
        // arched windows (deterministic lit), leaving room for the door banner
        wi = 0;
        for (wy = y + 14; wy < y + h - 34; wy += 19) {
            for (wx = x + 9; wx < x + w - 11; wx += 17) {
                wi++;
                ctx.fillStyle = (b.lit && ((wi * 37 + b.seed) % 10 < 6)) ? "#FFE082" : "#BBDEFB";
                ctx.beginPath();
                ctx.moveTo(wx, wy + 9); ctx.lineTo(wx, wy + 3); ctx.arc(wx + 5, wy + 3, 5, Math.PI, 0); ctx.lineTo(wx + 10, wy + 9); ctx.closePath();
                ctx.fill(); ctx.strokeStyle = "#FFF"; ctx.lineWidth = 1; ctx.stroke();
            }
        }
        // peaked roof + bell cupola
        ctx.fillStyle = b.roofC; ctx.beginPath();
        ctx.moveTo(x - 4, y); ctx.lineTo(x + w / 2, y - 18); ctx.lineTo(x + w + 4, y); ctx.closePath(); ctx.fill();
        ctx.fillStyle = "#FAFAFA"; ctx.fillRect(x + w / 2 - 5, y - 28, 10, 12);
        ctx.fillStyle = b.roofC; ctx.beginPath();
        ctx.moveTo(x + w / 2 - 6, y - 28); ctx.lineTo(x + w / 2, y - 36); ctx.lineTo(x + w / 2 + 6, y - 28); ctx.closePath(); ctx.fill();
        ctx.fillStyle = "#FFD54F"; ctx.beginPath(); ctx.arc(x + w / 2, y - 22, 2.5, 0, Math.PI * 2); ctx.fill();
        // double doors
        ctx.fillStyle = "#4E342E"; ctx.fillRect(x + w / 2 - 9, y + h - 18, 18, 18);
        ctx.strokeStyle = "rgba(255,255,255,0.4)"; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(x + w / 2, y + h - 18); ctx.lineTo(x + w / 2, y + h); ctx.stroke();
        // fitted name banner over the door
        ctx.fillStyle = "#FFFFFF"; roundRect(x + 4, y + h - 33, w - 8, 13, 2); ctx.fill();
        ctx.strokeStyle = "#5D4037"; ctx.lineWidth = 1; roundRect(x + 4, y + h - 33, w - 8, 13, 2); ctx.stroke();
        drawFitText(b.label || "SCHOOL", x + w / 2, y + h - 26, w - 12, 9, "#5D4037");
    }

    // A proper PRECINCT: stone facade, a columned portico with a pediment, a big
    // illuminated POLICE / PRECINCT 18½ sign, lit windows, a rotating blue beacon,
    // a flag, entrance steps and the classic blue lamp globes. Scales to b.w/b.h
    // so it reads well both as a roadside police-zone landmark and as the bigger
    // booking destination during an arrest.
    function drawPoliceStation(b) {
        var x = b.x - b.w / 2, y = b.y, w = b.w, h = b.h, t = gameTime;
        // drop shadow
        ctx.fillStyle = "rgba(0,0,0,0.22)"; ctx.fillRect(x + 5, y + 9, w, h);
        // stone facade (cool blue-grey, lighter at top)
        var fg = ctx.createLinearGradient(0, y, 0, y + h);
        fg.addColorStop(0, "#637182"); fg.addColorStop(1, "#46525F");
        ctx.fillStyle = fg; ctx.fillRect(x, y, w, h);
        // corner pilasters + ashlar coursing
        ctx.fillStyle = "#71808F"; ctx.fillRect(x, y, 6, h); ctx.fillRect(x + w - 6, y, 6, h);
        ctx.strokeStyle = "rgba(0,0,0,0.10)"; ctx.lineWidth = 1;
        for (var cy2 = y + 18; cy2 < y + h - 4; cy2 += 18) { ctx.beginPath(); ctx.moveTo(x + 6, cy2); ctx.lineTo(x + w - 6, cy2); ctx.stroke(); }
        // cornice / parapet
        ctx.fillStyle = "#39444F"; ctx.fillRect(x - 3, y - 5, w + 6, 9);
        ctx.fillStyle = "#2B343D"; ctx.fillRect(x - 3, y - 5, w + 6, 2.5);
        // lit window columns flanking the central bay
        var bayW = Math.max(26, w * 0.42), bx0 = x + w / 2 - bayW / 2, bx1 = x + w / 2 + bayW / 2;
        var wi = 0;
        for (var wy = y + 12; wy < y + h - 12; wy += 17) {
            for (var side = 0; side < 2; side++) {
                var wx = side === 0 ? x + 11 : bx1 + 5;
                var wEnd = side === 0 ? bx0 - 5 : x + w - 11;
                for (; wx + 9 <= wEnd; wx += 14) {
                    wi++;
                    var lit = b.lit !== false && (((wi * 41 + (b.seed || 7)) % 10) < 6);
                    ctx.fillStyle = lit ? "#FFE082" : "#2A3742";
                    roundRect(wx, wy, 9, 11, 1.5); ctx.fill();
                    ctx.fillStyle = "rgba(255,255,255,0.10)"; ctx.fillRect(wx, wy, 9, 2);
                }
            }
        }
        // ── central PORTICO: pediment + entablature + columns ──
        var px = x + w / 2, pw = bayW + 8, colTop = y + 20, colBot = y + h - 16;
        ctx.fillStyle = "#8493A2";                                   // pediment
        ctx.beginPath(); ctx.moveTo(px - pw / 2 - 3, colTop); ctx.lineTo(px, y + 2); ctx.lineTo(px + pw / 2 + 3, colTop); ctx.closePath(); ctx.fill();
        ctx.fillStyle = "#6E7D8C"; ctx.beginPath(); ctx.moveTo(px - pw / 2 - 3, colTop); ctx.lineTo(px, y + 6); ctx.lineTo(px + pw / 2 + 3, colTop); ctx.closePath(); ctx.fill();
        ctx.fillStyle = "#9AA8B6"; ctx.fillRect(px - pw / 2 - 3, colTop, pw + 6, 7);   // entablature
        ctx.fillStyle = "#39444F"; ctx.fillRect(px - pw / 2 - 3, colTop + 7, pw + 6, 2);
        // recessed entrance bay (dark) behind the columns
        ctx.fillStyle = "#2A333C"; ctx.fillRect(px - pw / 2 + 2, colTop + 9, pw - 4, colBot - (colTop + 9));
        // columns
        var ncol = w > 90 ? 4 : 3;
        for (var c = 0; c < ncol; c++) {
            var cx2 = px - pw / 2 + 4 + c * (pw - 8) / (ncol - 1);
            var cg = ctx.createLinearGradient(cx2 - 3, 0, cx2 + 3, 0);
            cg.addColorStop(0, "#AEBAC6"); cg.addColorStop(0.5, "#E7ECF1"); cg.addColorStop(1, "#AEBAC6");
            ctx.fillStyle = cg; ctx.fillRect(cx2 - 2.6, colTop + 9, 5.2, colBot - (colTop + 9));
            ctx.fillStyle = "#C9D2DA"; ctx.fillRect(cx2 - 3.4, colTop + 8, 6.8, 2.5);     // capital
            ctx.fillRect(cx2 - 3.4, colBot - 2, 6.8, 2.5);                                  // base
        }
        // glass entrance doors at the base of the bay
        ctx.fillStyle = "#11181E"; roundRect(px - pw * 0.26, colBot - 16, pw * 0.52, 16, 2); ctx.fill();
        ctx.fillStyle = "#2E4A63"; roundRect(px - pw * 0.24, colBot - 14, pw * 0.22, 13, 1); ctx.fill();
        ctx.fillStyle = "#2E4A63"; roundRect(px + pw * 0.02, colBot - 14, pw * 0.22, 13, 1); ctx.fill();
        // entrance steps spilling toward the road
        for (var s = 0; s < 3; s++) { ctx.fillStyle = s % 2 ? "#7E8C9A" : "#909DAB"; ctx.fillRect(px - pw * 0.34 - s * 3, y + h - 2 + s * 2.4, pw * 0.68 + s * 6, 3); }
        // ── blue precinct lamp globes flanking the doors (glowing) ──
        var glow = 0.5 + 0.5 * Math.sin(t * 4);
        for (var lg = 0; lg < 2; lg++) {
            var lgx = lg === 0 ? px - pw * 0.42 : px + pw * 0.42, lgy = colBot - 6;
            ctx.fillStyle = "#2B343D"; ctx.fillRect(lgx - 1, lgy, 2, 8);
            ctx.fillStyle = "rgba(41,121,255," + (0.25 + 0.25 * glow) + ")"; ctx.beginPath(); ctx.arc(lgx, lgy - 1, 6, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#2979FF"; ctx.beginPath(); ctx.arc(lgx, lgy - 1, 3, 0, Math.PI * 2); ctx.fill();
        }
        // ── illuminated POLICE sign band across the facade ──
        var sy0 = y + 8;
        ctx.fillStyle = "#0D1B3E"; roundRect(x + 6, sy0, w - 12, 15, 3); ctx.fill();
        ctx.shadowColor = "#42A5F5"; ctx.shadowBlur = 7;
        drawFitText("POLICE", x + w / 2, sy0 + 8, w - 16, 11, "#90CAF9");
        ctx.shadowBlur = 0;
        // small precinct number plaque
        drawText("PRECINCT 18½", x + w / 2, sy0 + 24, "bold 7px 'Segoe UI', Arial, sans-serif", "#CFD8DC", "#0A1018", 2);
        // ── rooftop rotating blue beacon ──
        var beac = Math.sin(t * 8) > 0;
        ctx.fillStyle = "#2B343D"; ctx.fillRect(px - 5, y - 11, 10, 7);
        if (beac) { ctx.fillStyle = "rgba(41,121,255,0.35)"; ctx.beginPath(); ctx.arc(px, y - 12, 11, 0, Math.PI * 2); ctx.fill(); }
        ctx.fillStyle = beac ? "#2979FF" : "#1A3A6B"; ctx.beginPath(); ctx.arc(px, y - 12, 3.4, 0, Math.PI * 2); ctx.fill();
        // ── flagpole + flag on the corner ──
        var fpx = x + 10;
        ctx.strokeStyle = "#CFD8DC"; ctx.lineWidth = 1.6; ctx.beginPath(); ctx.moveTo(fpx, y - 4); ctx.lineTo(fpx, y - 26); ctx.stroke();
        ctx.fillStyle = "#1E88E5"; var fw = Math.sin(t * 3) * 1.5;
        ctx.beginPath(); ctx.moveTo(fpx, y - 26); ctx.lineTo(fpx + 14, y - 24 + fw); ctx.lineTo(fpx, y - 19); ctx.closePath(); ctx.fill();
        ctx.fillStyle = "#FFD700"; ctx.beginPath(); ctx.arc(fpx, y - 26, 1.4, 0, Math.PI * 2); ctx.fill();
    }

    // A chic HAIR SALON: blush-pink stucco facade, a scalloped pink/white awning,
    // a big plate-glass window with a styling chair + mannequin-head silhouette,
    // a candy-stripe barber pole by the door, and a glowing neon "💇 SALON" sign.
    // Reads instantly as a hair salon at the roadside building scale.
    function drawSalonStore(b) {
        var x = b.x - b.w / 2, y = b.y, w = b.w, h = b.h, t = gameTime;
        // drop shadow
        ctx.fillStyle = "rgba(0,0,0,0.18)"; ctx.fillRect(x + 4, y + 8, w, h);
        // blush stucco facade (lighter at top)
        var fg = ctx.createLinearGradient(0, y, 0, y + h);
        fg.addColorStop(0, "#FAD3E2"); fg.addColorStop(1, "#E79BBC");
        ctx.fillStyle = fg; ctx.fillRect(x, y, w, h);
        ctx.strokeStyle = "rgba(120,40,80,0.35)"; ctx.lineWidth = 2; ctx.strokeRect(x, y, w, h);
        // soft pilasters
        ctx.fillStyle = "rgba(255,255,255,0.22)"; ctx.fillRect(x, y, 4, h); ctx.fillRect(x + w - 4, y, 4, h);
        // gold trim band under the sign
        ctx.fillStyle = "#E6B84F"; ctx.fillRect(x, y + 2, w, 3);

        // ── big plate-glass window (most of the lower facade) ──
        var gx = x + 6, gy = y + h * 0.42, gw = w - 12, gh = h - (gy - y) - 22;
        ctx.fillStyle = "#5B7C86"; roundRect(gx, gy, gw, gh, 3); ctx.fill();           // glass (teal-grey)
        var glass = ctx.createLinearGradient(gx, gy, gx + gw, gy + gh);
        glass.addColorStop(0, "rgba(255,255,255,0.45)"); glass.addColorStop(0.5, "rgba(255,255,255,0.05)");
        glass.addColorStop(1, "rgba(255,255,255,0.30)");
        ctx.fillStyle = glass; roundRect(gx, gy, gw, gh, 3); ctx.fill();
        ctx.strokeStyle = "#C98AAA"; ctx.lineWidth = 2; roundRect(gx, gy, gw, gh, 3); ctx.stroke();
        var gbot = gy + gh;
        // mannequin-head silhouette on a stand (left of window)
        var mhx = gx + gw * 0.30;
        ctx.fillStyle = "rgba(40,20,40,0.55)";
        ctx.fillRect(mhx - 1, gbot - gh * 0.34, 2, gh * 0.34);                          // stand
        ctx.beginPath(); ctx.arc(mhx, gbot - gh * 0.40, gh * 0.11, 0, Math.PI * 2); ctx.fill(); // head
        // big swoosh of styled hair on the head
        ctx.fillStyle = "rgba(90,55,30,0.6)";
        ctx.beginPath();
        ctx.moveTo(mhx - gh * 0.11, gbot - gh * 0.42);
        ctx.quadraticCurveTo(mhx - gh * 0.22, gbot - gh * 0.18, mhx - gh * 0.05, gbot - gh * 0.14);
        ctx.quadraticCurveTo(mhx + gh * 0.02, gbot - gh * 0.34, mhx + gh * 0.10, gbot - gh * 0.40);
        ctx.closePath(); ctx.fill();
        // styling chair silhouette (right of window)
        var chx = gx + gw * 0.70;
        ctx.fillStyle = "rgba(40,20,40,0.5)";
        ctx.fillRect(chx - 1.5, gbot - gh * 0.30, 3, gh * 0.30);                        // pedestal
        roundRect(chx - gh * 0.10, gbot - gh * 0.44, gh * 0.20, gh * 0.18, 3); ctx.fill(); // seat back
        ctx.fillRect(chx - gh * 0.10, gbot - gh * 0.30, gh * 0.20, gh * 0.06);          // seat
        // a couple of pink bottles on a counter shelf
        ctx.fillStyle = "rgba(255,255,255,0.4)"; ctx.fillRect(gx + 3, gbot - 7, gw - 6, 3);
        ctx.fillStyle = "#FF7AB3"; ctx.fillRect(gx + 6, gbot - 12, 3, 5);
        ctx.fillStyle = "#FFD24F"; ctx.fillRect(gx + 12, gbot - 11, 3, 4);
        ctx.fillStyle = "#7AD0FF"; ctx.fillRect(gx + gw - 12, gbot - 12, 3, 5);

        // ── door + barber pole ──
        var dw = Math.min(16, w * 0.26), dx = (b.side < 0) ? x + w - dw - 5 : x + 5, dyTop = y + h - 18;
        ctx.fillStyle = "#7A4A60"; roundRect(dx, dyTop, dw, 18, 2); ctx.fill();
        ctx.fillStyle = "rgba(255,255,255,0.25)"; ctx.fillRect(dx + 2, dyTop + 2, dw - 4, 7);
        ctx.fillStyle = "#FFD54F"; ctx.beginPath(); ctx.arc(b.side < 0 ? dx + 3 : dx + dw - 3, dyTop + 11, 1.4, 0, Math.PI * 2); ctx.fill();
        // barber pole on the far side of the door from the window flow
        var bpx = (b.side < 0) ? x + 7 : x + w - 7, bpY = y + h - 26, bpH = 22;
        ctx.fillStyle = "#FFFFFF"; roundRect(bpx - 2.5, bpY, 5, bpH, 2.5); ctx.fill();
        for (var sp = 0; sp < bpH; sp += 4) {
            var off = (sp + (t * 9) % 4);
            ctx.fillStyle = ((Math.floor((sp) / 4) % 2)) ? "#E53935" : "#1E88E5";
            ctx.fillRect(bpx - 2.5, bpY + ((off) % bpH), 5, 2);
        }
        ctx.fillStyle = "#C0A050"; ctx.fillRect(bpx - 3, bpY - 2, 6, 2.5); ctx.fillRect(bpx - 3, bpY + bpH - 0.5, 6, 2.5);

        // ── scalloped pink/white awning above the window ──
        var awY = gy - 13, awH = 11, sw0 = 10;
        for (var s = 0; s < w; s += sw0) {
            var sw = Math.min(sw0, w - s);
            ctx.fillStyle = ((s / sw0) % 2) ? "#FFFFFF" : "#F06AA6";
            ctx.fillRect(x + s, awY, sw, awH);
            ctx.beginPath(); ctx.moveTo(x + s, awY + awH); ctx.lineTo(x + s + sw / 2, awY + awH + 5); ctx.lineTo(x + s + sw, awY + awH); ctx.closePath(); ctx.fill();
        }
        ctx.fillStyle = "rgba(0,0,0,0.12)"; ctx.fillRect(x, awY, w, 2);

        // ── glowing neon SALON sign poking above the roof ──
        var sy0 = y - 17;
        ctx.fillStyle = "#3A1828"; roundRect(x + 4, sy0, w - 8, 15, 4); ctx.fill();
        ctx.strokeStyle = "#E6B84F"; ctx.lineWidth = 1; roundRect(x + 4, sy0, w - 8, 15, 4); ctx.stroke();
        ctx.shadowColor = "#FF4FA3"; ctx.shadowBlur = 7;
        drawFitText("💇 " + (b.label || "SALON"), x + w / 2, sy0 + 8, w - 14, 10, "#FFC0DD");
        ctx.shadowBlur = 0;
    }

    // A multi-level PARKING GARAGE: concrete-grey structure with blue trim,
    // horizontal deck slabs (a couple of parked-car silhouettes peeking out of the
    // openings), a roll-up entry door with a ramp arrow, and a bold blue "P" sign
    // on the roof. Reads instantly as a parking structure.
    function drawParkingGarage(b) {
        var x = b.x - b.w / 2, y = b.y, w = b.w, h = b.h;
        // drop shadow
        ctx.fillStyle = "rgba(0,0,0,0.2)"; ctx.fillRect(x + 4, y + 8, w, h);
        // concrete facade
        var fg = ctx.createLinearGradient(0, y, 0, y + h);
        fg.addColorStop(0, "#9AA6AD"); fg.addColorStop(1, "#79858C");
        ctx.fillStyle = fg; ctx.fillRect(x, y, w, h);
        // corner columns
        ctx.fillStyle = "#B3BEC4"; ctx.fillRect(x, y, 6, h); ctx.fillRect(x + w - 6, y, 6, h);
        ctx.strokeStyle = "rgba(0,0,0,0.4)"; ctx.lineWidth = 2; ctx.strokeRect(x, y, w, h);
        // blue cornice band at the top
        ctx.fillStyle = "#1E88E5"; ctx.fillRect(x - 2, y - 4, w + 4, 7);
        ctx.fillStyle = "#1565C0"; ctx.fillRect(x - 2, y - 4, w + 4, 2.5);

        // ── deck levels: each level is a dark open band with a slab beneath it,
        //    and the road-facing openings show a parked-car silhouette or two ──
        var carCols = ["#E57373", "#FFD54F", "#64B5F6", "#FFFFFF", "#81C784", "#FF8A65"];
        var lvlH = 22, leftIn = x + 8, rightIn = x + w - 8, innerW = rightIn - leftIn;
        var doorH = 20, lastLvlBot = y + h - doorH - 2;
        var li = 0;
        for (var ly = y + 9; ly + lvlH <= lastLvlBot; ly += lvlH) {
            // open (dark) deck cavity
            ctx.fillStyle = "#34404A"; ctx.fillRect(leftIn, ly, innerW, lvlH - 6);
            // a couple of parked-car silhouettes peeking out (deterministic per level)
            var slots = Math.max(2, Math.floor(innerW / 17));
            var slotW = innerW / slots;
            for (var c = 0; c < slots; c++) {
                var key = ((li * 31 + c * 17 + (b.seed || 1)) % 10);
                if (key < 5) continue;                                  // empty stall
                var cx0 = leftIn + c * slotW + 2, cwid = slotW - 4, carTop = ly + lvlH - 6 - 9;
                ctx.fillStyle = carCols[(li * 3 + c + (b.seed || 0)) % carCols.length];
                roundRect(cx0, carTop, cwid, 9, 2); ctx.fill();          // car body
                ctx.fillStyle = "rgba(180,225,255,0.55)"; ctx.fillRect(cx0 + 1.5, carTop + 1, cwid - 3, 3.5); // windshield
                ctx.fillStyle = "rgba(0,0,0,0.45)"; ctx.fillRect(cx0 + 1, carTop + 8, 2.5, 2); ctx.fillRect(cx0 + cwid - 3.5, carTop + 8, 2.5, 2); // wheels
            }
            // concrete slab under the deck (with blue safety stripe edge)
            ctx.fillStyle = "#C2CBD0"; ctx.fillRect(leftIn - 2, ly + lvlH - 6, innerW + 4, 6);
            ctx.fillStyle = "#FBC02D"; ctx.fillRect(leftIn - 2, ly + lvlH - 6, innerW + 4, 1.5);
            li++;
        }

        // ── ground floor: roll-up entry door with chevron ramp arrows ──
        var dy = y + h - doorH;
        ctx.fillStyle = "#2B343B"; ctx.fillRect(leftIn - 2, dy, innerW + 4, doorH);
        ctx.strokeStyle = "rgba(255,255,255,0.12)"; ctx.lineWidth = 1;
        for (var rr = dy + 3; rr < dy + doorH; rr += 4) { ctx.beginPath(); ctx.moveTo(leftIn - 2, rr); ctx.lineTo(leftIn + innerW + 2, rr); ctx.stroke(); }
        // up-ramp chevrons (entry arrow) pointing in
        var acx = x + w / 2;
        ctx.strokeStyle = "#FFEB3B"; ctx.lineWidth = 2;
        for (var ch = 0; ch < 3; ch++) {
            var ay = dy + doorH - 4 - ch * 5;
            ctx.beginPath(); ctx.moveTo(acx - 6, ay + 3); ctx.lineTo(acx, ay - 1); ctx.lineTo(acx + 6, ay + 3); ctx.stroke();
        }
        // clearance bar above the door
        ctx.fillStyle = "#FBC02D"; ctx.fillRect(leftIn - 2, dy - 3, innerW + 4, 3);

        // ── bold blue "P" sign on a post poking above the roof ──
        var px2 = (b.side < 0) ? x + 12 : x + w - 12, sTop = y - 30;
        ctx.fillStyle = "#90A4AE"; ctx.fillRect(px2 - 1.5, y - 6, 3, 6);                // post
        ctx.fillStyle = "#1565C0"; roundRect(px2 - 9, sTop, 18, 18, 3); ctx.fill();
        ctx.strokeStyle = "#FFFFFF"; ctx.lineWidth = 1.5; roundRect(px2 - 9, sTop, 18, 18, 3); ctx.stroke();
        drawText("P", px2, sTop + 9, "bold 15px 'Segoe UI', Arial, sans-serif", "#FFFFFF", null, 0);
        // PARKING label band across the cornice
        var ly0 = y - 18;
        ctx.fillStyle = "#0D2A47"; roundRect(x + 4, ly0, w - 8, 14, 3); ctx.fill();
        drawFitText(b.label || "PARKING", x + w / 2, ly0 + 7, w - 14, 9, "#90CAF9");
    }

    // A warm little BAKERY: cream stucco with chocolate-brown trim, a brown/cream
    // scalloped awning, a glowing display window stacked with braided challahs,
    // round loaves and a frosted layer cake, a "🥐 BAKERY" sign board, and faint
    // steam wisps curling out of a rooftop vent pipe. Reads instantly as a bakery.
    function drawBakeryStore(b) {
        var x = b.x - b.w / 2, y = b.y, w = b.w, h = b.h, t = gameTime, sd = b.seed || 3;
        // drop shadow
        ctx.fillStyle = "rgba(0,0,0,0.18)"; ctx.fillRect(x + 4, y + 8, w, h);
        // cream stucco facade (lighter at top)
        var fg = ctx.createLinearGradient(0, y, 0, y + h);
        fg.addColorStop(0, "#FBEED3"); fg.addColorStop(1, "#E9CF9C");
        ctx.fillStyle = fg; ctx.fillRect(x, y, w, h);
        ctx.strokeStyle = "rgba(93,58,32,0.5)"; ctx.lineWidth = 2; ctx.strokeRect(x, y, w, h);
        // soft pilasters + chocolate trim band under the roofline
        ctx.fillStyle = "rgba(255,255,255,0.28)"; ctx.fillRect(x, y, 4, h); ctx.fillRect(x + w - 4, y, 4, h);
        ctx.fillStyle = "#8D5A33"; ctx.fillRect(x, y + 2, w, 3);

        // ── rooftop vent pipe + faint steam wisps (subtle, gameTime-animated) ──
        var vx = x + w - 9;
        ctx.fillStyle = "#8D6E63"; ctx.fillRect(vx - 2, y - 20, 4, 20);
        ctx.fillStyle = "#6D4C41"; ctx.fillRect(vx - 3.5, y - 22, 7, 2.5);
        for (var st = 0; st < 3; st++) {
            var ph = (t * 0.5 + st * 0.33 + (sd % 5) * 0.13) % 1;        // 0..1 rise cycle
            var sy2 = y - 24 - ph * 15;
            var sx2 = vx + Math.sin(ph * 5 + st * 2.1) * 3;
            ctx.fillStyle = "rgba(255,255,255," + (0.28 * (1 - ph)).toFixed(3) + ")";
            ctx.beginPath(); ctx.arc(sx2, sy2, 2.2 + ph * 2.6, 0, Math.PI * 2); ctx.fill();
        }

        // ── big display window full of baked goods ──
        var gx = x + 6, gy = y + h * 0.34, gw = w - 12, gh = h - (gy - y) - 21, gbot = gy + gh;
        ctx.fillStyle = "#4E342E"; roundRect(gx, gy, gw, gh, 3); ctx.fill();
        var warm = ctx.createLinearGradient(0, gy, 0, gbot);
        warm.addColorStop(0, "rgba(255,196,110,0.38)"); warm.addColorStop(1, "rgba(255,170,70,0.12)");
        ctx.fillStyle = warm; roundRect(gx, gy, gw, gh, 3); ctx.fill();
        // upper shelf: frosted layer cake (left) + braided challah (right)
        var shY = gy + gh * 0.50;
        ctx.fillStyle = "rgba(255,235,200,0.5)"; ctx.fillRect(gx + 2, shY, gw - 4, 2);
        var ckx = gx + gw * 0.26;
        ctx.fillStyle = "#F48FB1"; ctx.fillRect(ckx - 7, shY - 7, 14, 7);          // bottom tier
        ctx.fillStyle = "#FFF3E0"; ctx.fillRect(ckx - 5, shY - 12, 10, 5);         // top tier
        ctx.beginPath(); ctx.arc(ckx - 4, shY - 7, 1.5, 0, Math.PI);               // frosting drips
        ctx.arc(ckx, shY - 7, 1.5, 0, Math.PI); ctx.arc(ckx + 4, shY - 7, 1.5, 0, Math.PI); ctx.fill();
        ctx.fillStyle = "#E53935"; ctx.beginPath(); ctx.arc(ckx, shY - 13.5, 1.7, 0, Math.PI * 2); ctx.fill(); // cherry
        var chX = gx + gw * 0.70, chW = Math.min(22, gw * 0.4);
        ctx.fillStyle = "#B5722A"; roundRect(chX - chW / 2, shY - 6, chW, 6, 3); ctx.fill();  // challah base
        ctx.fillStyle = "#D99A45";                                                   // braid humps
        for (var bp = 0; bp < 4; bp++) { ctx.beginPath(); ctx.arc(chX - chW / 2 + 4 + bp * (chW - 8) / 3, shY - 6, 2.6, Math.PI, 0); ctx.fill(); }
        ctx.fillStyle = "#FFF3E0";                                                   // sesame
        ctx.fillRect(chX - 4, shY - 8, 1, 1); ctx.fillRect(chX + 2, shY - 7.5, 1, 1); ctx.fillRect(chX - 1, shY - 9, 1, 1);
        // lower counter: round sourdough loaves
        ctx.fillStyle = "rgba(255,235,200,0.45)"; ctx.fillRect(gx + 3, gbot - 6, gw - 6, 3);
        var lfx = gx + gw * 0.28;
        ctx.fillStyle = "#C07E33";
        ctx.beginPath(); ctx.arc(lfx, gbot - 10, 4.4, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(gx + gw * 0.52, gbot - 9.5, 3.6, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(gx + gw * 0.74, gbot - 10, 4, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = "#8A5620"; ctx.lineWidth = 1;                              // score lines
        ctx.beginPath(); ctx.moveTo(lfx - 3, gbot - 11.5); ctx.lineTo(lfx + 3, gbot - 8.5); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(gx + gw * 0.74 - 2.6, gbot - 8.6); ctx.lineTo(gx + gw * 0.74 + 2.6, gbot - 11.4); ctx.stroke();
        ctx.strokeStyle = "#8D5A33"; ctx.lineWidth = 2; roundRect(gx, gy, gw, gh, 3); ctx.stroke(); // frame

        // ── wooden door with glass panel (on the road side) ──
        var dw = Math.min(16, w * 0.26), dx = (b.side < 0) ? x + w - dw - 5 : x + 5, dyTop = y + h - 18;
        ctx.fillStyle = "#5D4037"; roundRect(dx, dyTop, dw, 18, 2); ctx.fill();
        ctx.fillStyle = "rgba(255,220,150,0.4)"; ctx.fillRect(dx + 2, dyTop + 2, dw - 4, 7);
        ctx.fillStyle = "#E6B84F"; ctx.beginPath(); ctx.arc(b.side < 0 ? dx + 3 : dx + dw - 3, dyTop + 11, 1.4, 0, Math.PI * 2); ctx.fill();

        // ── brown/cream scalloped awning above the window ──
        var awY = gy - 13, awH = 11, sw0 = 10;
        for (var s = 0; s < w; s += sw0) {
            var sw = Math.min(sw0, w - s);
            ctx.fillStyle = ((s / sw0) % 2) ? "#FFF3DC" : "#8D5A33";
            ctx.fillRect(x + s, awY, sw, awH);
            ctx.beginPath(); ctx.moveTo(x + s, awY + awH); ctx.lineTo(x + s + sw / 2, awY + awH + 5); ctx.lineTo(x + s + sw, awY + awH); ctx.closePath(); ctx.fill();
        }
        ctx.fillStyle = "rgba(0,0,0,0.12)"; ctx.fillRect(x, awY, w, 2);

        // ── warm BAKERY sign board above the roof ──
        var sy0 = y - 17;
        ctx.fillStyle = "#4E2A14"; roundRect(x + 4, sy0, w - 8, 15, 4); ctx.fill();
        ctx.strokeStyle = "#E6B84F"; ctx.lineWidth = 1; roundRect(x + 4, sy0, w - 8, 15, 4); ctx.stroke();
        ctx.shadowColor = "#FFB300"; ctx.shadowBlur = 6;
        drawFitText("🥐 " + (b.label || "BAKERY"), x + w / 2, sy0 + 8, w - 14, 10, "#FFE0A3");
        ctx.shadowBlur = 0;
    }

    // A classic corner PIZZERIA: white/cream facade with tricolore green cornice
    // and red base course, a red/white scalloped awning, a glowing red "🍕 PIZZA"
    // sign, a round pepperoni-pizza emblem on a post, and a warm oven-lit window
    // with the pizzaiolo's silhouette (chef hat!) behind the counter.
    function drawPizzaStore(b) {
        var x = b.x - b.w / 2, y = b.y, w = b.w, h = b.h, t = gameTime, sd = b.seed || 5;
        // drop shadow
        ctx.fillStyle = "rgba(0,0,0,0.18)"; ctx.fillRect(x + 4, y + 8, w, h);
        // cream facade
        var fg = ctx.createLinearGradient(0, y, 0, y + h);
        fg.addColorStop(0, "#FDF6EA"); fg.addColorStop(1, "#EFDFC4");
        ctx.fillStyle = fg; ctx.fillRect(x, y, w, h);
        ctx.strokeStyle = "rgba(80,40,20,0.4)"; ctx.lineWidth = 2; ctx.strokeRect(x, y, w, h);
        ctx.fillStyle = "rgba(255,255,255,0.3)"; ctx.fillRect(x, y, 4, h); ctx.fillRect(x + w - 4, y, 4, h);
        // Italian tricolore trim: green cornice band + red base course
        ctx.fillStyle = "#2E7D32"; ctx.fillRect(x, y + 2, w, 4);
        ctx.fillStyle = "#C62828"; ctx.fillRect(x, y + h - 3, w, 3);

        // ── warm window with counter + pizzaiolo silhouette ──
        var gx = x + 6, gy = y + h * 0.42, gw = w - 12, gh = h - (gy - y) - 21, gbot = gy + gh;
        ctx.fillStyle = "#301B10"; roundRect(gx, gy, gw, gh, 3); ctx.fill();
        var oa = 0.30 + 0.05 * Math.sin(t * 2.2);                       // gentle oven-glow breathing
        var og = ctx.createRadialGradient(gx + gw * 0.5, gbot - 4, 2, gx + gw * 0.5, gbot - 4, gw * 0.62);
        og.addColorStop(0, "rgba(255,167,70," + oa.toFixed(3) + ")"); og.addColorStop(1, "rgba(255,120,40,0)");
        ctx.fillStyle = og; roundRect(gx, gy, gw, gh, 3); ctx.fill();
        var pzx = gx + gw * 0.36;                                        // pizzaiolo (dark against glow)
        ctx.fillStyle = "rgba(20,10,6,0.8)";
        ctx.beginPath(); ctx.arc(pzx, gy + gh * 0.40, gh * 0.12, 0, Math.PI * 2); ctx.fill();      // head
        roundRect(pzx - gh * 0.16, gy + gh * 0.50, gh * 0.32, gh * 0.30, 3); ctx.fill();           // torso
        ctx.fillStyle = "rgba(255,248,235,0.85)";                                                   // chef hat
        roundRect(pzx - gh * 0.09, gy + gh * 0.40 - gh * 0.27, gh * 0.18, gh * 0.15, 2); ctx.fill();
        ctx.fillStyle = "#4E342E"; ctx.fillRect(gx + 2, gbot - gh * 0.26, gw - 4, 4);              // counter top
        var cpx = gx + gw * 0.74, cpy = gbot - gh * 0.26 - 3;                                       // pizza on the counter
        ctx.fillStyle = "#E0A040"; ctx.beginPath(); ctx.arc(cpx, cpy, 5, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#FFCB4D"; ctx.beginPath(); ctx.arc(cpx, cpy, 3.6, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#C62828";
        ctx.beginPath(); ctx.arc(cpx - 1.5, cpy - 1, 1, 0, Math.PI * 2); ctx.arc(cpx + 1.6, cpy + 0.3, 1, 0, Math.PI * 2); ctx.arc(cpx - 0.4, cpy + 1.8, 1, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = "#1B5E20"; ctx.lineWidth = 2; roundRect(gx, gy, gw, gh, 3); ctx.stroke(); // green frame

        // ── green door (road side) ──
        var dw = Math.min(16, w * 0.26), dx = (b.side < 0) ? x + w - dw - 5 : x + 5, dyTop = y + h - 18;
        ctx.fillStyle = "#1B5E20"; roundRect(dx, dyTop, dw, 18, 2); ctx.fill();
        ctx.fillStyle = "rgba(255,214,130,0.4)"; ctx.fillRect(dx + 2, dyTop + 2, dw - 4, 7);
        ctx.fillStyle = "#FFD54F"; ctx.beginPath(); ctx.arc(b.side < 0 ? dx + 3 : dx + dw - 3, dyTop + 11, 1.4, 0, Math.PI * 2); ctx.fill();

        // ── red/white scalloped awning above the window ──
        var awY = gy - 13, awH = 11, sw0 = 10;
        for (var s = 0; s < w; s += sw0) {
            var sw = Math.min(sw0, w - s);
            ctx.fillStyle = ((s / sw0) % 2) ? "#FFFFFF" : "#D32F2F";
            ctx.fillRect(x + s, awY, sw, awH);
            ctx.beginPath(); ctx.moveTo(x + s, awY + awH); ctx.lineTo(x + s + sw / 2, awY + awH + 5); ctx.lineTo(x + s + sw, awY + awH); ctx.closePath(); ctx.fill();
        }
        ctx.fillStyle = "rgba(0,0,0,0.12)"; ctx.fillRect(x, awY, w, 2);

        // ── glowing neon PIZZA sign above the roof ──
        var sy0 = y - 16;
        ctx.fillStyle = "#23120C"; roundRect(x + 4, sy0, w - 8, 14, 4); ctx.fill();
        ctx.strokeStyle = "#2E7D32"; ctx.lineWidth = 1; roundRect(x + 4, sy0, w - 8, 14, 4); ctx.stroke();
        ctx.shadowColor = "#FF3D00"; ctx.shadowBlur = 6 + Math.sin(t * 3) * 1.5;
        drawFitText("🍕 " + (b.label || "PIZZA"), x + w / 2, sy0 + 7, w - 14, 10, "#FFAB91");
        ctx.shadowBlur = 0;

        // ── round pepperoni-pizza emblem on a post (road side, pokes above roof) ──
        var px2 = (b.side < 0) ? x + 13 : x + w - 13, ecy = y - 27;
        ctx.fillStyle = "#8D6E63"; ctx.fillRect(px2 - 1.5, y - 18, 3, 18);          // post
        ctx.fillStyle = "#D9903C"; ctx.beginPath(); ctx.arc(px2, ecy, 10, 0, Math.PI * 2); ctx.fill();   // crust
        ctx.fillStyle = "#FFC94D"; ctx.beginPath(); ctx.arc(px2, ecy, 7.6, 0, Math.PI * 2); ctx.fill();  // cheese
        ctx.strokeStyle = "rgba(160,90,20,0.45)"; ctx.lineWidth = 1;                 // slice cuts
        for (var cl = 0; cl < 3; cl++) {
            var ca = cl * Math.PI / 3 + 0.4;
            ctx.beginPath(); ctx.moveTo(px2 - Math.cos(ca) * 7.4, ecy - Math.sin(ca) * 7.4);
            ctx.lineTo(px2 + Math.cos(ca) * 7.4, ecy + Math.sin(ca) * 7.4); ctx.stroke();
        }
        ctx.fillStyle = "#C62828";                                                   // pepperoni (deterministic)
        for (var pp = 0; pp < 5; pp++) {
            var pa = pp * 2.4 + sd, pr = 2.2 + ((pp * 37 + sd) % 3) * 1.5;
            ctx.beginPath(); ctx.arc(px2 + Math.cos(pa) * pr, ecy + Math.sin(pa) * pr, 1.5, 0, Math.PI * 2); ctx.fill();
        }
        ctx.strokeStyle = "#FFFFFF"; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.arc(px2, ecy, 10, 0, Math.PI * 2); ctx.stroke();
    }

    // A cozy BOOKSHOP: deep bottle-green painted timber facade with a wood
    // cornice and gold pinstripe, a warm window stacked with colourful book
    // spines, a gently swinging "📚 BOOKS" sign hanging on chains from the
    // cornice, and a little wooden bargain-book cart parked out front.
    function drawBookStore(b) {
        var x = b.x - b.w / 2, y = b.y, w = b.w, h = b.h, t = gameTime, sd = b.seed || 9;
        var SPINES = ["#C62828", "#F9A825", "#1565C0", "#6A1B9A", "#2E7D32", "#EF6C00", "#AD1457", "#00838F"];
        // drop shadow
        ctx.fillStyle = "rgba(0,0,0,0.18)"; ctx.fillRect(x + 4, y + 8, w, h);
        // bottle-green painted facade
        var fg = ctx.createLinearGradient(0, y, 0, y + h);
        fg.addColorStop(0, "#3E6B50"); fg.addColorStop(1, "#26503A");
        ctx.fillStyle = fg; ctx.fillRect(x, y, w, h);
        ctx.strokeStyle = "rgba(0,0,0,0.45)"; ctx.lineWidth = 2; ctx.strokeRect(x, y, w, h);
        // wood pilasters + carved cornice with gold pinstripe
        ctx.fillStyle = "#5D4037"; ctx.fillRect(x, y, 5, h); ctx.fillRect(x + w - 5, y, 5, h);
        ctx.fillStyle = "#6D4C41"; ctx.fillRect(x - 2, y - 5, w + 4, 9);
        ctx.fillStyle = "#4E342E"; ctx.fillRect(x - 2, y - 5, w + 4, 2.5);
        ctx.fillStyle = "#E6B84F"; ctx.fillRect(x, y + 5, w, 1.5);

        // ── warm shop window stacked with book spines ──
        var gx = x + 7, gy = y + 27, gw = w - 14, gh = h - 27 - 20, gbot = gy + gh;
        ctx.fillStyle = "#2B1D12"; roundRect(gx, gy, gw, gh, 2); ctx.fill();
        var warm = ctx.createLinearGradient(0, gy, 0, gbot);
        warm.addColorStop(0, "rgba(255,205,130,0.30)"); warm.addColorStop(1, "rgba(255,180,100,0.06)");
        ctx.fillStyle = warm; roundRect(gx, gy, gw, gh, 2); ctx.fill();
        // shelves of colourful spines (deterministic widths/heights via seed);
        // short windows get one shelf, tall ones two
        var nrows = gh > 30 ? 2 : 1;
        for (var row = 0; row < nrows; row++) {
            var shelfY = gbot - 3 - row * (gh * 0.46);
            ctx.fillStyle = "#5D4037"; ctx.fillRect(gx + 1, shelfY, gw - 2, 2.5);
            var bx2 = gx + 3, k = 0;
            while (bx2 < gx + gw - 5) {
                var key2 = k * 29 + row * 13 + sd * 3;
                var bw2 = 2.5 + (key2 % 3), bh2 = Math.min(7 + ((key2 * 7) % 5), shelfY - gy - 2);
                if ((key2 % 9) === 4) { bx2 += bw2 + 2.5; k++; continue; }    // the odd gap
                ctx.fillStyle = SPINES[key2 % SPINES.length];
                ctx.fillRect(bx2, shelfY - bh2, bw2, bh2);
                bx2 += bw2 + 1; k++;
            }
        }
        ctx.strokeStyle = "#8D6E63"; ctx.lineWidth = 2; roundRect(gx, gy, gw, gh, 2); ctx.stroke();

        // ── wooden door with 4-pane glass (road side) ──
        var dw = Math.min(16, w * 0.26), dx = (b.side < 0) ? x + w - dw - 6 : x + 6, dyTop = y + h - 19;
        ctx.fillStyle = "#4E342E"; roundRect(dx, dyTop, dw, 19, 2); ctx.fill();
        ctx.fillStyle = "rgba(255,214,140,0.45)";
        ctx.fillRect(dx + 2, dyTop + 2, dw / 2 - 3, 5); ctx.fillRect(dx + dw / 2 + 1, dyTop + 2, dw / 2 - 3, 5);
        ctx.fillRect(dx + 2, dyTop + 9, dw / 2 - 3, 5); ctx.fillRect(dx + dw / 2 + 1, dyTop + 9, dw / 2 - 3, 5);
        ctx.fillStyle = "#E6B84F"; ctx.beginPath(); ctx.arc(b.side < 0 ? dx + 3 : dx + dw - 3, dyTop + 11, 1.4, 0, Math.PI * 2); ctx.fill();

        // ── hanging "📚 BOOKS" sign on chains under the cornice (subtle sway) ──
        var sw2 = Math.min(w - 14, 58), sh2 = 13;
        ctx.save();
        ctx.translate(x + w / 2, y + 6);
        ctx.rotate(Math.sin(t * 1.3 + sd) * 0.045);
        ctx.strokeStyle = "#B08D57"; ctx.lineWidth = 1;                              // chains
        ctx.beginPath(); ctx.moveTo(-sw2 / 2 + 8, 0); ctx.lineTo(-sw2 / 2 + 6, 5); ctx.moveTo(sw2 / 2 - 8, 0); ctx.lineTo(sw2 / 2 - 6, 5); ctx.stroke();
        ctx.fillStyle = "#4E342E"; roundRect(-sw2 / 2, 5, sw2, sh2, 3); ctx.fill();
        ctx.strokeStyle = "#E6B84F"; roundRect(-sw2 / 2, 5, sw2, sh2, 3); ctx.stroke();
        drawFitText("📚 " + (b.label || "BOOKS"), 0, 5 + sh2 / 2 + 0.5, sw2 - 8, 9, "#F5E6C0");
        ctx.restore();

        // ── little bargain-book cart out front (road side) ──
        var cx3 = (b.side < 0) ? x + w + 10 : x - 10, cby = y + h;
        ctx.fillStyle = "rgba(0,0,0,0.15)"; ctx.beginPath(); ctx.ellipse(cx3, cby - 1, 10, 3, 0, 0, Math.PI * 2); ctx.fill();
        for (var bk = 0; bk < 5; bk++) {                                             // books poking out
            var kk = bk * 31 + sd * 7;
            ctx.fillStyle = SPINES[kk % SPINES.length];
            ctx.fillRect(cx3 - 7 + bk * 3, cby - 13 - (5 + (kk % 4)), 2.6, 8 + (kk % 4));
        }
        ctx.fillStyle = "#795548"; ctx.fillRect(cx3 - 9, cby - 13, 18, 8);           // cart box
        ctx.fillStyle = "#5D4037"; ctx.fillRect(cx3 - 9, cby - 13, 18, 2);
        ctx.strokeStyle = "#5D4037"; ctx.lineWidth = 1.5;                            // handle toward the shop
        ctx.beginPath(); ctx.moveTo(cx3 + (b.side < 0 ? -9 : 9), cby - 11); ctx.lineTo(cx3 + (b.side < 0 ? -14 : 14), cby - 14); ctx.stroke();
        ctx.fillStyle = "#33251C";                                                    // wheels
        ctx.beginPath(); ctx.arc(cx3 - 5, cby - 4, 2.6, 0, Math.PI * 2); ctx.arc(cx3 + 5, cby - 4, 2.6, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#B08D57";
        ctx.beginPath(); ctx.arc(cx3 - 5, cby - 4, 0.9, 0, Math.PI * 2); ctx.arc(cx3 + 5, cby - 4, 0.9, 0, Math.PI * 2); ctx.fill();
    }

    function drawBuilding(b) {
        var x = b.x - b.w / 2, y = b.y, w = b.w, h = b.h;
        if (b.kind === "policeLot" && typeof drawPoliceLot === "function") { drawPoliceLot(b); return; }
        if ((b.kind === "police" || b.kind === "policeStation")) { drawPoliceStation(b); return; }
        if (b.kind === "salon") { drawSalonStore(b); return; }
        if (b.kind === "parking") { drawParkingGarage(b); return; }
        if (b.kind === "market") { drawMarketStall(b); return; }
        if (b.kind === "bakery") { drawBakeryStore(b); return; }
        if (b.kind === "pizza") { drawPizzaStore(b); return; }
        if (b.kind === "books") { drawBookStore(b); return; }
        if (b.kind === "school") { drawSchool(b); return; }
        ctx.fillStyle = "rgba(0,0,0,0.18)";
        ctx.fillRect(x + 4, y + 8, w, h);
        ctx.fillStyle = shadeColor((BUILD_BODY[b.kind] || BUILD_BODY.downtown)[b.tint], b.shade || 0);
        ctx.fillRect(x, y, w, h);
        ctx.strokeStyle = "rgba(0,0,0,0.45)"; ctx.lineWidth = 2;
        ctx.strokeRect(x, y, w, h);

        if (b.kind === "construction") {
            // concrete shell: floor slabs + columns
            ctx.strokeStyle = "rgba(0,0,0,0.28)"; ctx.lineWidth = 1;
            for (var cf = y + 14; cf < y + h; cf += 15) { ctx.beginPath(); ctx.moveTo(x, cf); ctx.lineTo(x + w, cf); ctx.stroke(); }
            for (var cc = x + 9; cc < x + w; cc += 16) { ctx.beginPath(); ctx.moveTo(cc, y); ctx.lineTo(cc, y + h); ctx.stroke(); }
            // dark unfinished floor openings (deterministic per building)
            ctx.fillStyle = "rgba(15,12,8,0.5)";
            var oi = 0;
            for (var oy = y + 17; oy < y + h - 16; oy += 15) {
                for (var ox = x + 6; ox < x + w - 10; ox += 16) {
                    oi++; if (((oi * 53 + (b.seed || 0)) % 10) < 5) ctx.fillRect(ox, oy, 11, 9);
                }
            }
            // green safety netting on the road-facing half (semi-transparent)
            var netx = b.side < 0 ? x + w / 2 : x;
            ctx.fillStyle = "rgba(76,175,80,0.18)"; ctx.fillRect(netx, y + 6, w / 2, h - 10);
            ctx.strokeStyle = "rgba(46,125,50,0.4)"; ctx.lineWidth = 0.5;
            for (var ny = y + 8; ny < y + h - 6; ny += 5) { ctx.beginPath(); ctx.moveTo(netx, ny); ctx.lineTo(netx + w / 2, ny); ctx.stroke(); }
            // exposed rebar poking out of the top
            ctx.strokeStyle = "#B0BEC5"; ctx.lineWidth = 1.5;
            for (var rb = x + 6; rb < x + w; rb += 8) { ctx.beginPath(); ctx.moveTo(rb, y); ctx.lineTo(rb + (rb % 3 - 1) * 2, y - 7); ctx.stroke(); }
            // scaffolding on the road-facing edge (poles + diagonals)
            var sfx = b.side < 0 ? x + w - 7 : x + 1;
            ctx.strokeStyle = "#90A4AE"; ctx.lineWidth = 1.5;
            ctx.strokeRect(sfx, y + 6, 6, h - 10);
            for (var sy = y + 6; sy < y + h - 12; sy += 14) { ctx.beginPath(); ctx.moveTo(sfx, sy); ctx.lineTo(sfx + 6, sy + 14); ctx.stroke(); }
            // hazard stripes at the base
            for (var sc = 0; sc < w; sc += 8) { ctx.fillStyle = (sc / 8) % 2 ? "#1A1A1A" : "#FFC107"; ctx.fillRect(x + sc, y + h - 7, 8, 7); }
            // dirt + rubble mound at the base on the road side
            var dmx = b.side < 0 ? x + w + 2 : x - 16;
            ctx.fillStyle = "#8D6E63";
            ctx.beginPath(); ctx.moveTo(dmx, y + h); ctx.quadraticCurveTo(dmx + 7, y + h - 12, dmx + 14, y + h); ctx.closePath(); ctx.fill();
            ctx.fillStyle = "#A1887F"; ctx.beginPath(); ctx.arc(dmx + 5, y + h - 3, 2, 0, Math.PI * 2); ctx.arc(dmx + 10, y + h - 2, 1.6, 0, Math.PI * 2); ctx.fill();
            // tower crane rising beside the shell
            var crX = b.side < 0 ? x + w + 5 : x - 5, jib = b.side < 0 ? 1 : -1;
            ctx.fillStyle = "#FB8C00"; ctx.fillRect(crX - 4, y + h - 10, 8, 10); // crane base
            ctx.strokeStyle = "#FB8C00"; ctx.lineWidth = 3; ctx.lineCap = "round";
            ctx.beginPath(); ctx.moveTo(crX, y + 12); ctx.lineTo(crX, y - 52); ctx.stroke();             // mast
            // lattice rungs on the mast
            ctx.lineWidth = 1;
            for (var mr = y + 8; mr > y - 50; mr -= 8) { ctx.beginPath(); ctx.moveTo(crX - 3, mr); ctx.lineTo(crX + 3, mr - 4); ctx.stroke(); }
            ctx.lineWidth = 3;
            ctx.beginPath(); ctx.moveTo(crX - jib * 12, y - 50); ctx.lineTo(crX + jib * 38, y - 50); ctx.stroke(); // jib + counter-jib
            ctx.lineCap = "butt";
            ctx.fillStyle = "#FB8C00"; ctx.fillRect(crX - 4, y - 56, 8, 7);                                // operator cab
            ctx.fillStyle = "#37474F"; ctx.fillRect(crX - jib * 16, y - 53, jib * 5, 6);                   // counterweight
            var lx = crX + jib * 30, lyb = y - 50 + 14 + Math.sin(gameTime * 1.6) * 4;                     // hanging load (bobs)
            ctx.strokeStyle = "#546E7A"; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(lx, y - 50); ctx.lineTo(lx, lyb); ctx.stroke();
            ctx.fillStyle = "#78909C"; ctx.fillRect(lx - 5, lyb, 10, 8); // concrete block
            return;
        }
        if (b.kind === "gas") {
            // bright canopy + a pump out front
            ctx.fillStyle = "#FAFAFA"; ctx.fillRect(x - 2, y - 10, w + 4, 12);
            ctx.fillStyle = "#C62828"; ctx.fillRect(x - 2, y - 10, w + 4, 4);
            ctx.fillStyle = "#1A1A1A"; roundRect(x + w / 2 - 18, y - 30, 36, 18, 3); ctx.fill();
            drawText("⛽GAS", x + w / 2, y - 21, "bold 10px 'Segoe UI', Arial, sans-serif", "#FFEB3B", null, 0);
            ctx.fillStyle = "#37474F"; ctx.fillRect(x + w / 2 - 4, y + h - 22, 8, 22); // pump
            ctx.fillStyle = "#FF5252"; ctx.fillRect(x + w / 2 - 3, y + h - 20, 6, 6);
            return;
        }
        if (b.kind === "market") {
            // striped awning over the storefront + crates
            for (var aw = 0; aw < w; aw += 10) { ctx.fillStyle = (aw / 10) % 2 ? "#E53935" : "#FAFAFA"; ctx.fillRect(x + aw, y - 12, 10, 12); }
            ctx.fillStyle = "#1A1A1A"; roundRect(x + 3, y - 30, w - 6, 16, 3); ctx.fill();
            drawText("MARKET", x + w / 2, y - 22, "bold 9px 'Segoe UI', Arial, sans-serif", "#AED581", null, 0);
            ctx.fillStyle = "#A1887F"; ctx.fillRect(x + 6, y + h - 14, 12, 12); ctx.fillRect(x + w - 18, y + h - 14, 12, 12);
            ctx.fillStyle = "#FF7043"; ctx.beginPath(); ctx.arc(x + 12, y + h - 16, 3, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#8BC34A"; ctx.beginPath(); ctx.arc(x + w - 12, y + h - 16, 3, 0, Math.PI * 2); ctx.fill();
            return;
        }

        // Tall buildings (bars/police/school/downtown/hospital): lit window grid.
        // Lit pattern is DETERMINISTIC per building (seed) — re-rolling each
        // frame made every window strobe, which read as 'too flashy'.
        var wi = 0;
        for (var wy = y + 10; wy < y + h - 8; wy += 16) {
            for (var wx = x + 7; wx < x + w - 8; wx += 14) {
                wi++;
                var litWin = b.lit && (((wi * 37 + (b.seed || 0)) % 10) < 6);
                ctx.fillStyle = litWin ? "#FFE082" : "rgba(20,20,30,0.5)";
                ctx.fillRect(wx, wy, 8, 9);
            }
        }
        // Roofline variety (parapet / stepped / peaked) so towers aren't clones.
        var roofC = shadeColor((BUILD_BODY[b.kind] || BUILD_BODY.downtown)[b.tint], (b.shade || 0) - 22);
        ctx.fillStyle = roofC;
        if (b.roof === 0) {
            ctx.fillRect(x - 2, y - 4, w + 4, 6);                          // flat parapet
        } else if (b.roof === 1) {
            ctx.fillRect(x - 2, y - 4, w + 4, 5);
            ctx.fillRect(x + w * 0.18, y - 9, w * 0.64, 6);               // stepped
            ctx.fillRect(x + w * 0.36, y - 13, w * 0.28, 5);
        } else {
            ctx.beginPath(); ctx.moveTo(x - 2, y); ctx.lineTo(x + w / 2, y - 13); ctx.lineTo(x + w + 2, y); ctx.closePath(); ctx.fill(); // low peak
        }
        var label = b.label || BUILD_LABEL[b.kind];
        if (label) {
            var signC = b.signC || BUILD_SIGN[b.kind];
            var sy0 = y - 16 - (b.roof === 1 ? 8 : b.roof === 2 ? 6 : 0);
            ctx.fillStyle = "#1A1A1A";
            roundRect(x + 3, sy0, w - 6, 15, 3); ctx.fill();
            if (b.glow && b.lit) { ctx.shadowColor = signC; ctx.shadowBlur = 6; }
            drawFitText(label, x + w / 2, sy0 + 8, w - 12, 9, signC);
            ctx.shadowBlur = 0;
        }
        if (b.kind === "bars") {
            if (b.style === 1) {
                // striped fabric awning over the entrance
                for (var awb = 0; awb < w - 8; awb += 9) {
                    ctx.fillStyle = (awb / 9) % 2 ? "#FAFAFA" : (b.signC || "#FF4FA3");
                    ctx.fillRect(x + 4 + awb, y + 2, Math.min(9, w - 12 - awb), 8);
                }
            } else if (b.style === 2) {
                // a string of warm cafe lights along the facade (static)
                ctx.strokeStyle = "rgba(0,0,0,0.35)"; ctx.lineWidth = 1;
                ctx.beginPath(); ctx.moveTo(x + 4, y + 6); ctx.quadraticCurveTo(x + w / 2, y + 12, x + w - 4, y + 6); ctx.stroke();
                for (var lt = 0; lt < 5; lt++) {
                    var ltx = x + 6 + (w - 12) * lt / 4;
                    ctx.fillStyle = "#FFD54F";
                    ctx.beginPath(); ctx.arc(ltx, y + 8 + Math.sin(lt * 2.1) * 2, 1.8, 0, Math.PI * 2); ctx.fill();
                }
            }
        } else if (b.kind === "school") {
            if (b.style === 0) {
                // flagpole beside the door
                var fpx = x + 6;
                ctx.strokeStyle = "#90A4AE"; ctx.lineWidth = 2;
                ctx.beginPath(); ctx.moveTo(fpx, y + h); ctx.lineTo(fpx, y - 14); ctx.stroke();
                ctx.fillStyle = "#42A5F5"; ctx.fillRect(fpx + 1, y - 13, 11, 7);
            } else {
                // wide double doors at the base
                ctx.fillStyle = "#4E342E";
                ctx.fillRect(x + w / 2 - 9, y + h - 18, 18, 18);
                ctx.strokeStyle = "rgba(255,255,255,0.5)"; ctx.lineWidth = 1;
                ctx.beginPath(); ctx.moveTo(x + w / 2, y + h - 18); ctx.lineTo(x + w / 2, y + h); ctx.stroke();
            }
        }
        if (b.kind === "police") {
            ctx.fillStyle = "#E53935"; ctx.fillRect(x + 2, y - 22, (w - 4) / 2, 4);
            ctx.fillStyle = "#1E88E5"; ctx.fillRect(x + 2 + (w - 4) / 2, y - 22, (w - 4) / 2, 4);
        } else if (b.kind === "downtown") {
            if (b.style === 0) {
                // rooftop water tower
                var wtx = x + w / 2;
                ctx.strokeStyle = "#6D4C41"; ctx.lineWidth = 2;
                ctx.beginPath(); ctx.moveTo(wtx - 6, y); ctx.lineTo(wtx - 6, y - 8); ctx.moveTo(wtx + 6, y); ctx.lineTo(wtx + 6, y - 8); ctx.stroke();
                ctx.fillStyle = "#8D6E63"; roundRect(wtx - 9, y - 22, 18, 14, 3); ctx.fill();
                ctx.fillStyle = "#6D4C41"; ctx.beginPath();
                ctx.moveTo(wtx - 10, y - 22); ctx.lineTo(wtx, y - 30); ctx.lineTo(wtx + 10, y - 22); ctx.closePath(); ctx.fill();
            } else {
                ctx.strokeStyle = "#90A4AE"; ctx.lineWidth = 2;
                ctx.beginPath(); ctx.moveTo(x + w / 2, y); ctx.lineTo(x + w / 2, y - 18); ctx.stroke();
                ctx.fillStyle = "#FF5252"; ctx.beginPath(); ctx.arc(x + w / 2, y - 18, 2, 0, Math.PI * 2); ctx.fill();
            }
        } else if (b.kind === "hospital") {
            // big red cross on the facade
            ctx.fillStyle = "#E53935";
            ctx.fillRect(x + w / 2 - 4, y + 12, 8, 26); ctx.fillRect(x + w / 2 - 13, y + 21, 26, 8);
        }
    }

    // ── Drawing: Environment ─────────────────────────────────
    function drawTree(x, y, scale, time, swayOff) {
        var s = scale || 1;
        var sway = Math.sin(time * 1.5 + (swayOff || 0)) * 2;
        var cfg = SEASONS[season];
        ctx.save();
        ctx.translate(x + sway, y);
        ctx.scale(s, s);
        ctx.fillStyle = C.trunkDark;
        roundRect(-7, -8, 14, 30, 3); ctx.fill();
        ctx.fillStyle = C.trunk;
        roundRect(-5, -6, 10, 26, 2); ctx.fill();
        if (cfg.bare) {
            // Winter: bare branches with little snow caps
            ctx.strokeStyle = C.trunkDark; ctx.lineWidth = 2; ctx.lineCap = "round";
            ctx.beginPath();
            ctx.moveTo(0, -6); ctx.lineTo(-9, -20); ctx.moveTo(0, -10); ctx.lineTo(9, -22);
            ctx.moveTo(0, -14); ctx.lineTo(0, -28); ctx.moveTo(0, -16); ctx.lineTo(-7, -26);
            ctx.stroke(); ctx.lineCap = "butt";
            ctx.fillStyle = "#FFFFFF";
            ctx.beginPath();
            ctx.ellipse(-9, -21, 3, 1.6, 0, 0, Math.PI * 2);
            ctx.ellipse(9, -23, 3, 1.6, 0, 0, Math.PI * 2);
            ctx.ellipse(0, -29, 3.2, 1.7, 0, 0, Math.PI * 2);
            ctx.fill();
        } else {
            for (var i = 0; i < 3; i++) {
                var cx = [-10, 10, 0][i], cy = [-26, -24, -34][i], r = [14, 13, 16][i];
                ctx.fillStyle = shadeColor(cfg.trees[i], -34);
                ctx.beginPath(); ctx.arc(cx, cy, r + 2, 0, Math.PI * 2); ctx.fill();
                ctx.fillStyle = cfg.trees[i];
                ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.fill();
            }
        }
        ctx.restore();
    }

    function drawBush(x, y, scale, time, bounceOff) {
        var s = (scale || 1) * (1 + Math.sin(time * 2 + (bounceOff || 0)) * 0.03);
        var pal = SEASONS[season].bushes;
        ctx.save();
        ctx.translate(x, y); ctx.scale(s, s);
        for (var i = 0; i < 3; i++) {
            var bx = [-9, 9, 0][i], by = [-2, -1, -8][i];
            var rx = [13, 12, 14][i], ry = [9, 8, 11][i];
            ctx.fillStyle = shadeColor(pal[i], -34);
            ctx.beginPath(); ctx.ellipse(bx, by, rx + 2, ry + 2, 0, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = pal[i];
            ctx.beginPath(); ctx.ellipse(bx, by, rx, ry, 0, 0, Math.PI * 2); ctx.fill();
        }
        ctx.restore();
    }

    function drawFlower(x, y, color, scale) {
        var s = scale || 1;
        ctx.save();
        ctx.translate(x, y); ctx.scale(s, s);
        ctx.fillStyle = "#388E3C"; ctx.fillRect(-1, 0, 2, 10);
        for (var i = 0; i < 5; i++) {
            ctx.fillStyle = color;
            ctx.save();
            ctx.rotate((Math.PI * 2 / 5) * i);
            ctx.beginPath(); ctx.ellipse(0, -5, 3, 5, 0, 0, Math.PI * 2); ctx.fill();
            ctx.restore();
        }
        ctx.fillStyle = "#FFF176";
        ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
    }

    function drawFence(x, y, w) {
        ctx.fillStyle = "#795548";
        roundRect(x - w / 2, y - 4, w, 6, 2); ctx.fill();
        ctx.fillStyle = "#8D6E63";
        roundRect(x - w / 2, y - 3, w, 4, 1); ctx.fill();
        for (var i = 0; i < w; i += 14) {
            ctx.fillStyle = "#795548";
            roundRect(x - w / 2 + i + 2, y - 12, 5, 16, 1); ctx.fill();
            ctx.fillStyle = "#8D6E63";
            roundRect(x - w / 2 + i + 3, y - 11, 3, 14, 1); ctx.fill();
        }
    }

    function drawSnowPile(x, y, scale) {
        var s = scale || 1;
        ctx.save();
        ctx.translate(x, y); ctx.scale(s, s);
        ctx.fillStyle = "rgba(0,0,0,0.10)";
        ctx.beginPath(); ctx.ellipse(0, 4, 20, 7, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#E8EEF2";
        ctx.beginPath(); ctx.ellipse(-7, 0, 12, 9, 0, 0, Math.PI * 2);
        ctx.ellipse(7, 1, 11, 8, 0, 0, Math.PI * 2);
        ctx.ellipse(0, -4, 13, 10, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#FFFFFF";
        ctx.beginPath(); ctx.ellipse(-3, -6, 7, 4, 0, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
    }

    // ── Scenic biome art: palm, umbrella, beach ball ─────────
    function drawPalm(x, y, scale, time, swayOff) {
        var s = scale || 1;
        var sway = Math.sin(time * 1.4 + (swayOff || 0)) * 0.12;
        ctx.save();
        ctx.translate(x, y); ctx.scale(s, s);
        // shadow on the sand
        ctx.fillStyle = "rgba(0,0,0,0.12)";
        ctx.beginPath(); ctx.ellipse(0, 2, 16, 5, 0, 0, Math.PI * 2); ctx.fill();
        ctx.rotate(sway);
        // trunk (gently curved, banded)
        ctx.strokeStyle = "#9C6B3F"; ctx.lineCap = "round"; ctx.lineWidth = 7;
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.quadraticCurveTo(5, -22, 1, -44); ctx.stroke();
        ctx.strokeStyle = "#B07D4C"; ctx.lineWidth = 4;
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.quadraticCurveTo(5, -22, 1, -44); ctx.stroke();
        // crown of fronds
        ctx.translate(1, -44);
        ctx.fillStyle = "#2E9E5B";
        for (var f = 0; f < 7; f++) {
            ctx.save();
            ctx.rotate((f / 7) * Math.PI * 2 + Math.sin(time * 1.4 + f) * 0.06);
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.quadraticCurveTo(14, -5, 26, 2);
            ctx.quadraticCurveTo(14, 1, 0, 4);
            ctx.closePath(); ctx.fill();
            ctx.restore();
        }
        ctx.fillStyle = "#1F7E45";
        for (var f2 = 0; f2 < 7; f2++) {
            ctx.save();
            ctx.rotate((f2 / 7) * Math.PI * 2 + 0.4);
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.quadraticCurveTo(10, -3, 20, 1);
            ctx.quadraticCurveTo(10, 0, 0, 3);
            ctx.closePath(); ctx.fill();
            ctx.restore();
        }
        // coconuts
        ctx.fillStyle = "#5D4037";
        ctx.beginPath(); ctx.arc(-3, 3, 3, 0, Math.PI * 2); ctx.arc(3, 4, 3, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
    }

    function drawBeachUmbrella(x, y, scale, color) {
        var s = scale || 1;
        var col = color || "#E53935";
        ctx.save();
        ctx.translate(x, y); ctx.scale(s, s);
        ctx.fillStyle = "rgba(0,0,0,0.12)";
        ctx.beginPath(); ctx.ellipse(0, 2, 12, 4, 0, 0, Math.PI * 2); ctx.fill();
        // pole
        ctx.strokeStyle = "#9E9E9E"; ctx.lineWidth = 2.5; ctx.lineCap = "round";
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-2, -30); ctx.stroke();
        // canopy — alternating colour / white wedges
        ctx.translate(-2, -30);
        var R = 22;
        for (var w = 0; w < 8; w++) {
            ctx.fillStyle = (w % 2 === 0) ? col : "#FAFAFA";
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.arc(0, 0, R, Math.PI + (w / 8) * Math.PI, Math.PI + ((w + 1) / 8) * Math.PI);
            ctx.closePath(); ctx.fill();
        }
        ctx.strokeStyle = "rgba(0,0,0,0.15)"; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.arc(0, 0, R, Math.PI, Math.PI * 2); ctx.stroke();
        ctx.fillStyle = col;
        ctx.beginPath(); ctx.arc(0, 0, 2.5, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
    }

    function drawBeachBall(x, y, scale, color) {
        var s = scale || 1;
        ctx.save();
        ctx.translate(x, y); ctx.scale(s, s);
        ctx.fillStyle = "rgba(0,0,0,0.12)";
        ctx.beginPath(); ctx.ellipse(0, 9, 9, 3, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#FAFAFA";
        ctx.beginPath(); ctx.arc(0, 0, 9, 0, Math.PI * 2); ctx.fill();
        var cols = ["#E53935", "#FDD835", "#1E88E5"];
        for (var seg = 0; seg < 3; seg++) {
            ctx.fillStyle = cols[seg % cols.length];
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.arc(0, 0, 9, (seg / 3) * Math.PI * 2 - 0.4, (seg / 3) * Math.PI * 2 + 0.4);
            ctx.closePath(); ctx.fill();
        }
        ctx.fillStyle = "rgba(255,255,255,0.7)";
        ctx.beginPath(); ctx.arc(-3, -3, 2.5, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
    }

    // Animated water for bridge/beach biomes — gentle shimmer bands that
    // drift with travel so it reads as flowing, not a flat fill.
    function drawWaterField(scrollOff, x0, x1, base) {
        ctx.fillStyle = base;
        ctx.fillRect(x0, 0, x1 - x0, H);
        ctx.save();
        ctx.beginPath(); ctx.rect(x0, 0, x1 - x0, H); ctx.clip();
        ctx.strokeStyle = "rgba(255,255,255,0.16)"; ctx.lineWidth = 2;
        var off = (scrollOff * 0.5) % 30;
        for (var wy = -30 + off; wy < H + 30; wy += 30) {
            ctx.beginPath();
            for (var wx = x0 - 4; wx <= x1 + 4; wx += 16) {
                var yy = wy + Math.sin((wx + scrollOff * 0.6) * 0.06) * 3;
                if (wx <= x0 - 4) ctx.moveTo(wx, yy); else ctx.lineTo(wx, yy);
            }
            ctx.stroke();
        }
        ctx.restore();
    }

    // A run of bridge railing along one road edge, posts scrolling past.
    function drawBridgeRail(ex, scrollOff) {
        ctx.fillStyle = "#B0BEC5";
        ctx.fillRect(ex - 2, 0, 5, H);          // top rail
        ctx.fillStyle = "#78909C";
        ctx.fillRect(ex - 2, 2, 5, 2);
        var off = (scrollOff * 0.85) % 34;
        ctx.fillStyle = "#90A4AE";
        for (var py = -34 + off; py < H; py += 34) {
            ctx.fillRect(ex - 1, py, 3, 18);    // posts
        }
        ctx.fillStyle = "#CFD8DC";
        ctx.fillRect(ex - 2, 9, 5, 2);          // lower rail highlight
    }

    function drawDecorations(time) {
        for (var i = 0; i < decorations.length; i++) {
            var d = decorations[i];
            if (d.type === "tree") drawTree(d.x, d.y, d.scale, time, d.swayOffset);
            else if (d.type === "bush") drawBush(d.x, d.y, d.scale, time, d.bounceOffset);
            else if (d.type === "flower") drawFlower(d.x, d.y, d.color, d.scale);
            else if (d.type === "snowpile") drawSnowPile(d.x, d.y, d.scale);
            else if (d.type === "fence") drawFence(d.x, d.y, d.width);
            else if (d.type === "palm") drawPalm(d.x, d.y, d.scale, time, d.swayOffset);
            else if (d.type === "umbrella") drawBeachUmbrella(d.x, d.y, d.scale, d.color);
            else if (d.type === "beachball") drawBeachBall(d.x, d.y, d.scale, d.color);
        }
    }

    function drawRoad(scrollOff) {
        // Sky-to-grass gradient for depth (season-tinted)
        var skyGrad = ctx.createLinearGradient(0, 0, 0, H);
        skyGrad.addColorStop(0, seasonSky(0));
        skyGrad.addColorStop(0.35, seasonSky(1));
        skyGrad.addColorStop(1, seasonSky(2));
        ctx.fillStyle = skyGrad;
        ctx.fillRect(0, 0, W, H);
        if (zone === "bridge") {
            // Driving out over open water.
            drawWaterField(scrollOff, 0, W, "#3C7CA6");
        } else if (zone === "beach") {
            // Ocean on the left, golden sand on the right (road hugs the coast).
            drawWaterField(scrollOff, 0, ROAD_L - 4, "#1FA7C2");
            var sandGrad = ctx.createLinearGradient(ROAD_R, 0, W, 0);
            sandGrad.addColorStop(0, "#E4CF93");
            sandGrad.addColorStop(1, "#EFDDAA");
            ctx.fillStyle = sandGrad;
            ctx.fillRect(ROAD_R - 4, 0, W - (ROAD_R - 4), H);
            // a few speckles of darker, damp sand for texture
            ctx.fillStyle = "rgba(150,120,70,0.18)";
            for (var sx = ROAD_R + 8; sx < W - 4; sx += 22) {
                var sdy = ((sx * 7 + scrollOff * 0.3) % H);
                ctx.fillRect(sx, sdy, 4, 3);
                ctx.fillRect(sx + 9, (sdy + 130) % H, 3, 3);
            }
        } else {
            ctx.fillStyle = shadeColor(seasonGrass(), 10);
            for (var gy = ((scrollOff * 0.3) % 40) - 40; gy < H; gy += 40) {
                ctx.fillRect(0, gy, W, 18);
            }
        }
        // Drop shadow + chunky outline on road for depth (Sneaky-Sasquatch style)
        ctx.fillStyle = "rgba(0,0,0,0.22)";
        ctx.fillRect(ROAD_L - 14, 0, 4, H);
        ctx.fillRect(ROAD_R + 10, 0, 4, H);
        ctx.fillStyle = C.shoulder;
        roundRect(ROAD_L - 8, 0, ROAD_W + 16, H, 0); ctx.fill();
        ctx.fillStyle = C.road;
        ctx.fillRect(ROAD_L, 0, ROAD_W, H);
        ctx.strokeStyle = "#1A1A1A";
        ctx.lineWidth = 3;
        ctx.strokeRect(ROAD_L - 8, 0, ROAD_W + 16, H);

        ctx.strokeStyle = C.roadLine;
        ctx.lineWidth = 3;
        ctx.setLineDash([]);
        ctx.beginPath();
        ctx.moveTo(ROAD_L + 2, 0); ctx.lineTo(ROAD_L + 2, H);
        ctx.moveTo(ROAD_R - 2, 0); ctx.lineTo(ROAD_R - 2, H);
        ctx.stroke();

        ctx.strokeStyle = C.roadLine;
        ctx.lineWidth = 2;
        ctx.setLineDash([28, 22]);
        ctx.lineDashOffset = -(scrollOff % 50);
        for (var lane = 1; lane < 3; lane++) {
            var lx = ROAD_L + lane * LANE_W;
            ctx.beginPath();
            ctx.moveTo(lx, 0); ctx.lineTo(lx, H);
            ctx.stroke();
        }
        ctx.setLineDash([]);

        // Scenic edge trim, drawn over the road's shoulder.
        if (zone === "bridge") {
            drawBridgeRail(ROAD_L - 11, scrollOff);
            drawBridgeRail(ROAD_R + 11, scrollOff);
        } else if (zone === "beach") {
            // Wavy foam line where the surf laps the road's seaward shoulder.
            ctx.strokeStyle = "rgba(255,255,255,0.8)"; ctx.lineWidth = 3; ctx.lineCap = "round";
            ctx.beginPath();
            for (var fy = -6; fy < H + 6; fy += 12) {
                var fx = ROAD_L - 9 + Math.sin((fy + scrollOff) * 0.08) * 4;
                if (fy <= -6) ctx.moveTo(fx, fy); else ctx.lineTo(fx, fy);
            }
            ctx.stroke();
            ctx.lineCap = "butt"; // don't leak the round cap into later strokes
        }
    }

    // ── Drawing: Lulu's car (with skin & feminine face) ──────
    // ── Spawn tuning (EDIT ME) ───────────────────────────────
    // Rarity/timing for the random "encounter" events in Lulu's driving game.
    // Everything here is safe to tweak — just edit the numbers and rebuild
    // (`node build.js`). Core obstacles (cars/cones/coins) are NOT here; they
    // stay frequent. These are the special, occasional events.
    //
    //   first:  [min,max] seconds before the event can FIRST appear in a run.
    //           Randomized per run, so the ORDER of events differs every time.
    //   every:  [min,max] seconds between attempts after that.
    //   chance: 0..1 probability an attempt actually spawns (lower = rarer).
    //
    // Want something rarer?  → raise `every` and/or lower `chance`.
    // Want it more common?   → lower `every` and/or raise `chance`.
    var SPAWN_CONFIG = {
        pedestrian:  { first: [12, 30], every: [20, 38],  chance: 0.70 }, // 🚶 walkers → passenger coin bonus
        parkingSign: { first: [25, 75],  every: [55, 100], chance: 0.00 }, // 🅿 DISABLED — parking now entered via the pull-over; sign path kept intact
        iceCream:    { first: [30, 85],  every: [65, 115], chance: 0.50 }, // 🍦 ice-cream bonus
        avigail:     { first: [40, 110], every: [110, 190], chance: 0.4 }, // Avigail porch visit — RARE, so it's an EVENT
        avigailCar:  { first: [30, 70],  every: [55, 110],  chance: 0.5 }, // 💅 Avigail out DRIVING (taunts; sometimes pulled over)
        salon:       { first: [30, 85],  every: [65, 115], chance: 0.45 }, // 💇 salon scene
        sasquatch:   { first: [40, 100], every: [75, 150], chance: 0.35 }, // 🦶 sasquatch easter egg
        copHide:     { first: [22, 60],  every: [35, 75],  chance: 0.55 }, // 🚓 hidden roadside speed-trap cop
        heshyPool:   { first: [25, 70],  every: [40, 80],  chance: 0.50 }, // 🏊 Heshy-in-the-pool easter egg
        heart:       { first: [15, 35],  every: [20, 40],  chance: 0.60 }, // ❤️ extra-life pickup
        toll:        { first: [45, 90],  every: [60, 120], chance: 0.55 }, // 🎫 toll-booth gauntlet
        train:       { first: [55, 110], every: [70, 140], chance: 0.55 }, // 🚂 railroad crossing
        driveThru:   { first: [35, 80],  every: [55, 110], chance: 0.55 }, // 🍔 drive-thru bonus
        parade:      { first: [60, 120], every: [90, 170], chance: 0.45 }, // 🎉 parade / marathon crowd
        uncle:       { first: [35, 90],  every: [80, 150], chance: 0.4 }   // 👨 Uncle sighting
    };

    // Per-event countdown timers, (re)initialized at the start of each run.
    var spawnTimers = {};
    function initSpawnTimers() {
        for (var key in SPAWN_CONFIG) {
            var c = SPAWN_CONFIG[key];
            spawnTimers[key] = rand(c.first[0], c.first[1]);
        }
    }
    // Counts down `name`'s timer; when it elapses, resets it and rolls `chance`.
    // Returns true only on the frames the event should actually spawn.
    function tickSpawn(name, dt) {
        var c = SPAWN_CONFIG[name];
        if (!c) return false;
        if (spawnTimers[name] === undefined) spawnTimers[name] = rand(c.first[0], c.first[1]);
        spawnTimers[name] -= dt;
        if (spawnTimers[name] > 0) return false;
        spawnTimers[name] = rand(c.every[0], c.every[1]);
        // STORY mode nudges a few leg-themed events more common (cruise = ×1).
        var eff = c.chance * (typeof storySpawnBias === "function" ? storySpawnBias(name) : 1);
        if (eff > 0.95) eff = 0.95;
        return Math.random() < eff;
    }

    // Shared cute face for Lulu's car — used by both the driving game and the
    // parking minigame so she looks identical in both. Drawn centered at (0, fy)
    // in the car's local space. `crying` swaps in the sad/teary parking face.
    function drawLuluFace(fy, crying) {
        var hairC = save.luluHair;
        var hairDark = shadeColor(hairC, -28);
        var hairLite = shadeColor(hairC, 22);
        var hairStyle = save.luluHairStyle || "sheitel";

        // BIG & BOUNCY / AVIGAIL get extra volume drawn BEHIND the head first
        if (hairStyle === "bouncy") {
            ctx.fillStyle = hairC;
            ctx.beginPath(); ctx.arc(-9, fy - 3, 5, 0, Math.PI * 2); ctx.arc(9, fy - 3, 5, 0, Math.PI * 2); ctx.fill();
        } else if (hairStyle === "avigail") {
            ctx.fillStyle = hairC;
            ctx.beginPath();
            ctx.arc(-5, fy - 11, 3.4, 0, Math.PI * 2); ctx.arc(0, fy - 13, 3.8, 0, Math.PI * 2);
            ctx.arc(5, fy - 11, 3.4, 0, Math.PI * 2); ctx.arc(0, fy - 16, 3, 0, Math.PI * 2); ctx.fill();
        }

        // Long hair flowing down BOTH SIDES of the face
        ctx.fillStyle = hairC;
        ctx.beginPath();
        ctx.moveTo(-7.5, fy - 4);
        ctx.quadraticCurveTo(-12, fy + 2, -10.5, fy + 14);
        ctx.quadraticCurveTo(-9, fy + 20, -6, fy + 18);
        ctx.quadraticCurveTo(-6.5, fy + 8, -5, fy + 2);
        ctx.closePath();
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(7.5, fy - 4);
        ctx.quadraticCurveTo(12, fy + 2, 10.5, fy + 14);
        ctx.quadraticCurveTo(9, fy + 20, 6, fy + 18);
        ctx.quadraticCurveTo(6.5, fy + 8, 5, fy + 2);
        ctx.closePath();
        ctx.fill();
        ctx.fillStyle = hairLite;
        ctx.beginPath();
        ctx.ellipse(-9, fy + 7, 1.3, 5, 0.1, 0, Math.PI * 2);
        ctx.ellipse(9, fy + 7, 1.3, 5, -0.1, 0, Math.PI * 2);
        ctx.fill();

        // Face — soft round, bright peachy skin
        ctx.fillStyle = "#FFD9C0";
        ctx.beginPath();
        ctx.ellipse(0, fy, 8, 8.5, 0, 0, Math.PI * 2);
        ctx.fill();

        // Center-parted bangs
        ctx.fillStyle = hairC;
        ctx.beginPath();
        ctx.moveTo(-8, fy + 1);
        ctx.quadraticCurveTo(-10, fy - 8, 0, fy - 9);
        ctx.quadraticCurveTo(10, fy - 8, 8, fy + 1);
        ctx.quadraticCurveTo(6, fy - 3, 4, fy - 2.5);
        ctx.quadraticCurveTo(2, fy - 5.5, 0, fy - 5);
        ctx.quadraticCurveTo(-2, fy - 5.5, -4, fy - 2.5);
        ctx.quadraticCurveTo(-6, fy - 3, -8, fy + 1);
        ctx.closePath();
        ctx.fill();
        ctx.fillStyle = hairLite;
        ctx.beginPath();
        ctx.ellipse(-4, fy - 5, 2.2, 1.1, -0.3, 0, Math.PI * 2);
        ctx.fill();

        // Eyebrows
        ctx.strokeStyle = hairDark;
        ctx.lineWidth = 0.7;
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(-4.6, fy - 2.6); ctx.quadraticCurveTo(-2.8, fy - 3.4, -1, fy - 2.7);
        ctx.moveTo(1, fy - 2.7); ctx.quadraticCurveTo(2.8, fy - 3.4, 4.6, fy - 2.6);
        ctx.stroke();
        ctx.lineCap = "butt";

        if (crying) {
            // Squeezed-shut sad eyes
            ctx.strokeStyle = "#5D4037";
            ctx.lineWidth = 1.1;
            ctx.lineCap = "round";
            ctx.beginPath();
            ctx.arc(-2.9, fy + 0.4, 2.3, 0.1 * Math.PI, 0.9 * Math.PI);
            ctx.arc(2.9, fy + 0.4, 2.3, 0.1 * Math.PI, 0.9 * Math.PI);
            ctx.stroke();
            ctx.lineCap = "butt";
            // Tear drops
            ctx.fillStyle = "#4FC3F7";
            ctx.beginPath();
            ctx.moveTo(-2.9, fy + 2.4); ctx.quadraticCurveTo(-4.6, fy + 6, -3.6, fy + 8.4);
            ctx.quadraticCurveTo(-1.9, fy + 6, -2.9, fy + 2.4); ctx.fill();
            ctx.beginPath();
            ctx.moveTo(2.9, fy + 2.4); ctx.quadraticCurveTo(4.6, fy + 6, 3.6, fy + 8.4);
            ctx.quadraticCurveTo(1.9, fy + 6, 2.9, fy + 2.4); ctx.fill();
            // Wailing frown
            ctx.fillStyle = "#5D4037";
            ctx.beginPath();
            ctx.ellipse(0, fy + 5, 1.8, 1.2, 0, 0, Math.PI * 2);
            ctx.fill();
            return;
        }

        // Eyes — big, round, sparkly
        ctx.fillStyle = "#FFFFFF";
        ctx.beginPath();
        ctx.ellipse(-2.9, fy, 2.4, 2.6, 0, 0, Math.PI * 2);
        ctx.ellipse(2.9, fy, 2.4, 2.6, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#7A4A24";
        ctx.beginPath();
        ctx.arc(-2.9, fy + 0.2, 1.7, 0, Math.PI * 2);
        ctx.arc(2.9, fy + 0.2, 1.7, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#241208";
        ctx.beginPath();
        ctx.arc(-2.9, fy + 0.2, 0.85, 0, Math.PI * 2);
        ctx.arc(2.9, fy + 0.2, 0.85, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#FFFFFF";
        ctx.beginPath();
        ctx.arc(-2.1, fy - 0.6, 0.8, 0, Math.PI * 2);
        ctx.arc(3.7, fy - 0.6, 0.8, 0, Math.PI * 2);
        ctx.fill();

        // Upper lash line + outer lashes
        ctx.strokeStyle = "#2E1A10";
        ctx.lineWidth = 0.9;
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.arc(-2.9, fy, 2.5, Math.PI * 1.05, Math.PI * 1.85);
        ctx.arc(2.9, fy, 2.5, Math.PI * 1.15, Math.PI * 1.95);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(-5.2, fy - 0.6); ctx.lineTo(-6.1, fy - 1.4);
        ctx.moveTo(5.2, fy - 0.6); ctx.lineTo(6.1, fy - 1.4);
        ctx.stroke();
        ctx.lineCap = "butt";

        // Blush
        ctx.fillStyle = "rgba(255, 135, 160, 0.5)";
        ctx.beginPath();
        ctx.ellipse(-4.6, fy + 3.2, 1.8, 1.2, 0, 0, Math.PI * 2);
        ctx.ellipse(4.6, fy + 3.2, 1.8, 1.2, 0, 0, Math.PI * 2);
        ctx.fill();

        // Button nose
        ctx.strokeStyle = "rgba(190,120,90,0.5)";
        ctx.lineWidth = 0.7;
        ctx.beginPath();
        ctx.arc(0, fy + 2.4, 0.9, Math.PI * 0.15, Math.PI * 0.85);
        ctx.stroke();

        // Glossy pink smile
        ctx.fillStyle = "#E84A7F";
        ctx.beginPath();
        ctx.moveTo(-2.4, fy + 4.6);
        ctx.quadraticCurveTo(0, fy + 6.6, 2.4, fy + 4.6);
        ctx.quadraticCurveTo(0, fy + 5.4, -2.4, fy + 4.6);
        ctx.closePath();
        ctx.fill();
        ctx.fillStyle = "#FFFFFF";
        ctx.fillRect(-1.2, fy + 4.8, 2.4, 0.6);
    }

    function drawLuluCar(x, y, tilt, blinking, time, distracted, skinKey, scale, empty) {
        var skin = SKINS[skinKey || save.selectedSkin] || SKINS.pink;
        var sc = scale || 1;
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(tilt || 0);
        ctx.scale(sc, sc);

        if (blinking && Math.sin(time * 18) > 0) ctx.globalAlpha = 0.35;

        var hw = CAR_W / 2, hh = CAR_H / 2;

        // Shadow
        ctx.fillStyle = "rgba(0,0,0,0.2)";
        ctx.beginPath();
        ctx.ellipse(3, 6, hw + 4, hh - 6, 0, 0, Math.PI * 2);
        ctx.fill();

        // Wheels — deeper tire contrast (dark tire + a lighter tread inset)
        var wheelSpots = [[-hw - 4, -hh + 10], [hw - 4, -hh + 10], [-hw - 4, hh - 28], [hw - 4, hh - 28]];
        for (var wi = 0; wi < 4; wi++) {
            var wx0 = wheelSpots[wi][0], wy0 = wheelSpots[wi][1];
            ctx.fillStyle = "#181818";
            roundRect(wx0, wy0, 8, 18, 3); ctx.fill();
            ctx.fillStyle = "#3a3a3a";
            roundRect(wx0 + 1.5, wy0 + 3, 5, 12, 2); ctx.fill();
        }

        // Body outline
        ctx.fillStyle = skin.dark;
        roundRect(-hw - 2, -hh - 2, CAR_W + 4, CAR_H + 4, 14); ctx.fill();

        // Body — diagonal gradient, light source top-left
        var grad = ctx.createLinearGradient(-hw, -hh, hw, hh);
        grad.addColorStop(0, skin.light);
        grad.addColorStop(0.42, skin.body);
        grad.addColorStop(1, skin.dark);
        ctx.fillStyle = grad;
        roundRect(-hw, -hh, CAR_W, CAR_H, 12); ctx.fill();
        // top-left sheen band along the hood
        var sheen = ctx.createLinearGradient(-hw, -hh, -hw + 14, -hh + 20);
        sheen.addColorStop(0, "rgba(255,255,255,0.28)");
        sheen.addColorStop(1, "rgba(255,255,255,0)");
        ctx.fillStyle = sheen;
        roundRect(-hw, -hh, CAR_W, CAR_H, 12); ctx.fill();

        // Optional racing stripe
        if (skin.stripe) {
            ctx.fillStyle = skin.stripe;
            roundRect(-4, -hh + 4, 8, CAR_H - 8, 2); ctx.fill();
        }

        // Thin bumper highlights (front + rear lip)
        ctx.fillStyle = "rgba(255,255,255,0.3)";
        roundRect(-hw + 5, -hh + 1, CAR_W - 10, 2, 1); ctx.fill();
        ctx.fillStyle = "rgba(255,255,255,0.15)";
        roundRect(-hw + 5, hh - 3, CAR_W - 10, 2, 1); ctx.fill();

        // Windshield — glass gradient + diagonal glare stripe
        ctx.fillStyle = C.windshieldDark;
        roundRect(-hw + 7, -hh + 8, CAR_W - 14, 26, 6); ctx.fill();
        var wsg = ctx.createLinearGradient(-hw + 8, -hh + 9, -hw + 8, -hh + 33);
        wsg.addColorStop(0, "#A6E1FB"); wsg.addColorStop(1, C.windshield);
        ctx.fillStyle = wsg;
        roundRect(-hw + 8, -hh + 9, CAR_W - 16, 24, 5); ctx.fill();
        ctx.save();
        roundRect(-hw + 8, -hh + 9, CAR_W - 16, 24, 5); ctx.clip();
        ctx.fillStyle = "rgba(255,255,255,0.35)";
        ctx.beginPath();
        ctx.moveTo(-hw + 10, -hh + 9); ctx.lineTo(-hw + 20, -hh + 9);
        ctx.lineTo(-hw + 8, -hh + 33); ctx.lineTo(-hw + 4, -hh + 33); ctx.closePath(); ctx.fill();
        ctx.restore();

        // ── Lulu's face (skipped for an EMPTY car — she's out of it) ──
      if (empty) {
        // two empty seat-backs showing through the windshield
        ctx.fillStyle = "rgba(0,0,0,0.18)";
        roundRect(-hw + 11, -hh + 12, (CAR_W - 22) / 2 - 1, 18, 3); ctx.fill();
        roundRect(2, -hh + 12, (CAR_W - 22) / 2 - 1, 18, 3); ctx.fill();
      } else {
        var fy = -hh + 23;                 // face center y
        var hairC = save.luluHair;
        var hairDark = shadeColor(hairC, -28);
        var hairLite = shadeColor(hairC, 22);

        // Long hair flowing down BOTH SIDES of the face (frames it — clearly feminine)
        ctx.fillStyle = hairC;
        // left lock
        ctx.beginPath();
        ctx.moveTo(-7.5, fy - 4);
        ctx.quadraticCurveTo(-12, fy + 2, -10.5, fy + 14);  // sweeps out then down
        ctx.quadraticCurveTo(-9, fy + 20, -6, fy + 18);     // rounded tip
        ctx.quadraticCurveTo(-6.5, fy + 8, -5, fy + 2);     // inner edge back up to cheek
        ctx.closePath();
        ctx.fill();
        // right lock (mirror)
        ctx.beginPath();
        ctx.moveTo(7.5, fy - 4);
        ctx.quadraticCurveTo(12, fy + 2, 10.5, fy + 14);
        ctx.quadraticCurveTo(9, fy + 20, 6, fy + 18);
        ctx.quadraticCurveTo(6.5, fy + 8, 5, fy + 2);
        ctx.closePath();
        ctx.fill();
        // hair sheen down each lock
        ctx.fillStyle = hairLite;
        ctx.beginPath();
        ctx.ellipse(-9, fy + 7, 1.3, 5, 0.1, 0, Math.PI * 2);
        ctx.ellipse(9, fy + 7, 1.3, 5, -0.1, 0, Math.PI * 2);
        ctx.fill();

        // Face — soft round, bright peachy skin
        ctx.fillStyle = "#FFD9C0";
        ctx.beginPath();
        ctx.ellipse(0, fy, 8, 8.5, 0, 0, Math.PI * 2);
        ctx.fill();

        // Hair: center-parted bangs framing just the top of the face
        ctx.fillStyle = hairC;
        ctx.beginPath();
        ctx.moveTo(-8, fy + 1);
        ctx.quadraticCurveTo(-10, fy - 8, 0, fy - 9);
        ctx.quadraticCurveTo(10, fy - 8, 8, fy + 1);
        ctx.quadraticCurveTo(6, fy - 3, 4, fy - 2.5);     // right bang sweep
        ctx.quadraticCurveTo(2, fy - 5.5, 0, fy - 5);     // center part dip
        ctx.quadraticCurveTo(-2, fy - 5.5, -4, fy - 2.5); // left bang sweep
        ctx.quadraticCurveTo(-6, fy - 3, -8, fy + 1);
        ctx.closePath();
        ctx.fill();
        // Hair highlight sheen on bangs
        ctx.fillStyle = hairLite;
        ctx.beginPath();
        ctx.ellipse(-4, fy - 5, 2.2, 1.1, -0.3, 0, Math.PI * 2);
        ctx.fill();

        // Eyebrows — soft thin arcs
        ctx.strokeStyle = hairDark;
        ctx.lineWidth = 0.7;
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(-4.6, fy - 2.6); ctx.quadraticCurveTo(-2.8, fy - 3.4, -1, fy - 2.7);
        ctx.moveTo(1, fy - 2.7); ctx.quadraticCurveTo(2.8, fy - 3.4, 4.6, fy - 2.6);
        ctx.stroke();

        // Eyes — big, round, sparkly (the key to reading as a cute girl)
        ctx.fillStyle = "#FFFFFF";
        ctx.beginPath();
        ctx.ellipse(-2.9, fy, 2.4, 2.6, 0, 0, Math.PI * 2);
        ctx.ellipse(2.9, fy, 2.4, 2.6, 0, 0, Math.PI * 2);
        ctx.fill();
        // Iris — large warm brown
        ctx.fillStyle = "#7A4A24";
        ctx.beginPath();
        ctx.arc(-2.9, fy + 0.2, 1.7, 0, Math.PI * 2);
        ctx.arc(2.9, fy + 0.2, 1.7, 0, Math.PI * 2);
        ctx.fill();
        // Pupil
        ctx.fillStyle = "#241208";
        ctx.beginPath();
        ctx.arc(-2.9, fy + 0.2, 0.85, 0, Math.PI * 2);
        ctx.arc(2.9, fy + 0.2, 0.85, 0, Math.PI * 2);
        ctx.fill();
        // Big eye sparkle
        ctx.fillStyle = "#FFFFFF";
        ctx.beginPath();
        ctx.arc(-2.1, fy - 0.6, 0.8, 0, Math.PI * 2);
        ctx.arc(3.7, fy - 0.6, 0.8, 0, Math.PI * 2);
        ctx.fill();

        // Upper lash line + outer-corner lashes (defines feminine eyes)
        ctx.strokeStyle = "#2E1A10";
        ctx.lineWidth = 0.9;
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.arc(-2.9, fy, 2.5, Math.PI * 1.05, Math.PI * 1.85);
        ctx.arc(2.9, fy, 2.5, Math.PI * 1.15, Math.PI * 1.95);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(-5.2, fy - 0.6); ctx.lineTo(-6.1, fy - 1.4);
        ctx.moveTo(5.2, fy - 0.6); ctx.lineTo(6.1, fy - 1.4);
        ctx.stroke();
        ctx.lineCap = "butt";

        // Soft pink blush on cheeks
        ctx.fillStyle = "rgba(255, 135, 160, 0.5)";
        ctx.beginPath();
        ctx.ellipse(-4.6, fy + 3.2, 1.8, 1.2, 0, 0, Math.PI * 2);
        ctx.ellipse(4.6, fy + 3.2, 1.8, 1.2, 0, 0, Math.PI * 2);
        ctx.fill();

        // Tiny button nose
        ctx.strokeStyle = "rgba(190,120,90,0.5)";
        ctx.lineWidth = 0.7;
        ctx.beginPath();
        ctx.arc(0, fy + 2.4, 0.9, Math.PI * 0.15, Math.PI * 0.85);
        ctx.stroke();

        // Glossy pink smile
        ctx.fillStyle = "#E84A7F";
        ctx.beginPath();
        ctx.moveTo(-2.4, fy + 4.6);
        ctx.quadraticCurveTo(0, fy + 6.6, 2.4, fy + 4.6);
        ctx.quadraticCurveTo(0, fy + 5.4, -2.4, fy + 4.6);
        ctx.closePath();
        ctx.fill();
        ctx.fillStyle = "#FFFFFF";
        ctx.fillRect(-1.2, fy + 4.8, 2.4, 0.6);   // teeth glint
      }

        // Phone (distracted mode)
        if (distracted) {
            ctx.fillStyle = "#212121";
            roundRect(6, -hh + 24, 8, 13, 2); ctx.fill();
            ctx.fillStyle = "#4FC3F7";
            roundRect(7, -hh + 25, 6, 11, 1); ctx.fill();
            // little screen content
            ctx.fillStyle = "#FFF";
            ctx.fillRect(8, -hh + 27, 4, 1);
            ctx.fillRect(8, -hh + 30, 4, 1);
            ctx.fillRect(8, -hh + 33, 4, 1);
            // hand on phone
            ctx.fillStyle = C.skin;
            ctx.beginPath();
            ctx.arc(7, -hh + 24, 3, 0, Math.PI * 2);
            ctx.fill();
        }

        // Rear window
        ctx.fillStyle = C.windshieldDark;
        roundRect(-hw + 10, hh - 22, CAR_W - 20, 12, 4); ctx.fill();

        // Sasquatch hitchhiker — big furry head sticking out top
        if (sasquatchPassenger > 0) {
            ctx.save();
            // Body lump squished in the car
            ctx.fillStyle = "#4E342E";
            roundRect(-hw + 6, hh - 30, CAR_W - 12, 18, 6); ctx.fill();
            // Head poking up through roof
            ctx.fillStyle = "#1A1410";
            ctx.beginPath(); ctx.arc(8, hh - 36, 13, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#4E342E";
            ctx.beginPath(); ctx.arc(8, hh - 36, 11, 0, Math.PI * 2); ctx.fill();
            // Fur tufts
            ctx.fillStyle = "#3E2723";
            ctx.beginPath();
            ctx.arc(2, hh - 44, 3.5, 0, Math.PI * 2);
            ctx.arc(8, hh - 46, 4, 0, Math.PI * 2);
            ctx.arc(14, hh - 44, 3.5, 0, Math.PI * 2);
            ctx.fill();
            // Eyes
            ctx.fillStyle = "#FFF9C4";
            ctx.beginPath();
            ctx.arc(4, hh - 37, 2.5, 0, Math.PI * 2);
            ctx.arc(12, hh - 37, 2.5, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = "#000";
            ctx.beginPath();
            ctx.arc(4, hh - 37, 1.4, 0, Math.PI * 2);
            ctx.arc(12, hh - 37, 1.4, 0, Math.PI * 2);
            ctx.fill();
            // Big chill smile
            ctx.strokeStyle = "#1A1410";
            ctx.lineWidth = 1.5;
            ctx.lineCap = "round";
            ctx.beginPath();
            ctx.arc(8, hh - 32, 3.5, 0.1 * Math.PI, 0.9 * Math.PI);
            ctx.stroke();
            ctx.lineCap = "butt";
            // Arm hanging out window
            ctx.fillStyle = "#4E342E";
            roundRect(hw - 4, hh - 26, 8, 16, 3); ctx.fill();
            ctx.restore();
        }

        // Passengers (peeking out the rear window)
        if (passengers && passengers.length > 0) {
            var slots = [[-8, hh - 16], [8, hh - 16], [-4, hh - 12], [4, hh - 12]];
            for (var pi = 0; pi < passengers.length && pi < 4; pi++) {
                var ps = passengers[pi];
                var bob = Math.sin(time * 4 + ps.bobOffset) * 0.5;
                var px = slots[pi][0], py = slots[pi][1] + bob;
                // hair
                ctx.fillStyle = ps.hairColor;
                ctx.beginPath(); ctx.arc(px, py, 3.2, 0, Math.PI * 2); ctx.fill();
                // face
                ctx.fillStyle = C.skin;
                ctx.beginPath(); ctx.arc(px, py + 0.6, 2.5, 0, Math.PI * 2); ctx.fill();
                // eyes
                ctx.fillStyle = "#222";
                ctx.beginPath();
                ctx.arc(px - 0.9, py + 0.5, 0.4, 0, Math.PI * 2);
                ctx.arc(px + 0.9, py + 0.5, 0.4, 0, Math.PI * 2);
                ctx.fill();
                // happy mouth
                ctx.strokeStyle = "#222";
                ctx.lineWidth = 0.5;
                ctx.beginPath();
                ctx.arc(px, py + 1.2, 0.8, 0.1 * Math.PI, 0.9 * Math.PI);
                ctx.stroke();
            }
        }

        // Avigail riding shotgun (after she joins) — curly black hair, gold hoops
        if (avigailInCar) {
            var ax = 7, ay = -hh + 22;
            // Curly black hair
            ctx.fillStyle = "#1A1A1A";
            ctx.beginPath();
            ctx.arc(ax - 3, ay - 2, 3, 0, Math.PI * 2);
            ctx.arc(ax, ay - 4, 3.2, 0, Math.PI * 2);
            ctx.arc(ax + 3, ay - 2, 3, 0, Math.PI * 2);
            ctx.fill();
            // Face
            ctx.fillStyle = "#C68642";
            ctx.beginPath(); ctx.arc(ax, ay, 3.4, 0, Math.PI * 2); ctx.fill();
            // Hoop earrings
            ctx.strokeStyle = "#FFD700"; ctx.lineWidth = 0.5;
            ctx.beginPath(); ctx.arc(ax - 3.5, ay + 1, 1, 0, Math.PI * 2); ctx.stroke();
            ctx.beginPath(); ctx.arc(ax + 3.5, ay + 1, 1, 0, Math.PI * 2); ctx.stroke();
            // Eyes
            ctx.fillStyle = "#000";
            ctx.beginPath();
            ctx.arc(ax - 1, ay, 0.5, 0, Math.PI * 2);
            ctx.arc(ax + 1, ay, 0.5, 0, Math.PI * 2);
            ctx.fill();
        }

        // Kids in back seat (after successful parking)
        if (kidsInCar) {
            // Pigtail kid
            ctx.fillStyle = "#FFC107";
            ctx.beginPath(); ctx.arc(-6, hh - 14, 4, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = C.skin;
            ctx.beginPath(); ctx.arc(-6, hh - 13.5, 3, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#FFC107";
            ctx.beginPath();
            ctx.ellipse(-9, -hh + (hh - 14), 1.8, 2.5, -0.4, 0, Math.PI * 2);
            ctx.ellipse(-3, -hh + (hh - 14), 1.8, 2.5, 0.4, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = "#000";
            ctx.beginPath();
            ctx.arc(-7, hh - 14, 0.6, 0, Math.PI * 2);
            ctx.arc(-5, hh - 14, 0.6, 0, Math.PI * 2);
            ctx.fill();
            // Cap kid
            ctx.fillStyle = C.skin;
            ctx.beginPath(); ctx.arc(6, hh - 13.5, 3, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#1976D2";
            ctx.beginPath();
            ctx.arc(6, hh - 15, 3.3, Math.PI, Math.PI * 2);
            ctx.fill();
            ctx.fillRect(7, hh - 15, 3.5, 1.2);
            ctx.fillStyle = "#000";
            ctx.beginPath();
            ctx.arc(5, hh - 13, 0.6, 0, Math.PI * 2);
            ctx.arc(7, hh - 13, 0.6, 0, Math.PI * 2);
            ctx.fill();
        }

        // Live driving cues: only the active player car, while actually driving
        var driving = (typeof state !== "undefined" && state === "playing" && !blinking) || false;
        var boosting = driving && keys.up;
        var braking = driving && keys.down;

        // Boost: warm headlight beam glowing forward
        if (boosting) {
            var beam = ctx.createLinearGradient(0, -hh - 30, 0, -hh);
            beam.addColorStop(0, "rgba(255,249,196,0)");
            beam.addColorStop(1, "rgba(255,249,196,0.35)");
            ctx.fillStyle = beam;
            ctx.beginPath();
            ctx.moveTo(-hw + 6, -hh + 2);
            ctx.lineTo(-hw - 4, -hh - 26);
            ctx.lineTo(hw + 4, -hh - 26);
            ctx.lineTo(hw - 6, -hh + 2);
            ctx.closePath();
            ctx.fill();
        }

        // Headlights
        ctx.fillStyle = "#FFF9C4";
        ctx.beginPath();
        ctx.ellipse(-hw + 10, -hh + 2, 5, 3, 0, 0, Math.PI * 2);
        ctx.ellipse(hw - 10, -hh + 2, 5, 3, 0, 0, Math.PI * 2);
        ctx.fill();

        // Brake-light glow halo when slowing
        if (braking) {
            ctx.fillStyle = "rgba(244,67,54,0.35)";
            ctx.beginPath();
            ctx.ellipse(-hw + 10, hh - 4, 9, 7, 0, 0, Math.PI * 2);
            ctx.ellipse(hw - 10, hh - 4, 9, 7, 0, 0, Math.PI * 2);
            ctx.fill();
        }

        // Taillights (brighter red when braking)
        ctx.fillStyle = braking ? "#FF5252" : "#F44336";
        ctx.beginPath();
        ctx.ellipse(-hw + 10, hh - 4, 4, 3, 0, 0, Math.PI * 2);
        ctx.ellipse(hw - 10, hh - 4, 4, 3, 0, 0, Math.PI * 2);
        ctx.fill();
        if (braking) {
            // hot white core
            ctx.fillStyle = "#FFCDD2";
            ctx.beginPath();
            ctx.ellipse(-hw + 10, hh - 4, 1.8, 1.4, 0, 0, Math.PI * 2);
            ctx.ellipse(hw - 10, hh - 4, 1.8, 1.4, 0, 0, Math.PI * 2);
            ctx.fill();
        }

        // Boost exhaust puffs out the back
        if (boosting && Math.random() > 0.4) {
            particles.push({
                x: x + rand(-hw + 8, -hw + 14), y: y + hh + 4,
                vx: rand(-12, 12), vy: rand(40, 90),
                life: 0.35, maxLife: 0.35, smoke: true,
                size: rand(2, 4), color: "rgba(200,200,200,0.7)", gravity: 0
            });
            particles.push({
                x: x + rand(hw - 14, hw - 8), y: y + hh + 4,
                vx: rand(-12, 12), vy: rand(40, 90),
                life: 0.35, maxLife: 0.35, smoke: true,
                size: rand(2, 4), color: "rgba(200,200,200,0.7)", gravity: 0
            });
        }

        ctx.globalAlpha = 1;
        ctx.restore();
    }

    // ── Showroom "fake-3D" car ────────────────────────────────
    // A pretty SIDE-PROFILE cartoon car (facing +x) used by the garage detail
    // turntable and the card previews. The turntable illusion (see
    // drawShowroomCar) is the classic sprite trick: horizontally squash the
    // profile by cos(angle) and swap to a narrow FRONT/REAR sliver when the car
    // turns edge-on, so it never collapses to a flat line.

    // Trace the body silhouette (facing right, centered near origin). No fill —
    // callers fill / clip / darken with it so the shape can't drift.
    function showroomBodyPath() {
        ctx.beginPath();
        ctx.moveTo(-72, 16);
        ctx.quadraticCurveTo(-75, 4, -70, -6);        // rear bumper + trunk lip
        ctx.lineTo(-58, -9);
        ctx.quadraticCurveTo(-50, -11, -45, -30);     // C-pillar up to roof
        ctx.quadraticCurveTo(-43, -35, -35, -35);     // rear roof corner
        ctx.lineTo(8, -35);                           // roofline
        ctx.quadraticCurveTo(20, -35, 27, -19);       // A-pillar / windshield
        ctx.lineTo(41, -12);                          // cowl → hood base
        ctx.lineTo(64, -11);                          // hood
        ctx.quadraticCurveTo(73, -10, 74, -1);        // nose
        ctx.quadraticCurveTo(75, 8, 71, 16);          // front bumper
        ctx.lineTo(-72, 16);                          // rocker (bottom)
        ctx.closePath();
    }

    // One wheel of the side profile: tire depth, hubcap, spokes.
    function showroomWheel(wx) {
        var wr = 17;
        // wheel-well shadow
        ctx.fillStyle = "rgba(0,0,0,0.35)";
        ctx.beginPath(); ctx.arc(wx, 17, wr + 3, Math.PI, 0); ctx.fill();
        // tire
        ctx.fillStyle = "#1b1b1f";
        ctx.beginPath(); ctx.arc(wx, 18, wr, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#2c2c30";
        ctx.beginPath(); ctx.arc(wx, 18, wr - 2.5, 0, Math.PI * 2); ctx.fill();
        // hubcap
        var hg = ctx.createRadialGradient(wx - 3, 15, 1, wx, 18, wr - 5);
        hg.addColorStop(0, "#f2f4f6"); hg.addColorStop(1, "#9aa4ac");
        ctx.fillStyle = hg;
        ctx.beginPath(); ctx.arc(wx, 18, wr - 6, 0, Math.PI * 2); ctx.fill();
        // spokes
        ctx.strokeStyle = "rgba(80,90,98,0.7)"; ctx.lineWidth = 1.4;
        for (var k = 0; k < 5; k++) {
            var a = k * (Math.PI * 2 / 5) + 0.4;
            ctx.beginPath(); ctx.moveTo(wx, 18);
            ctx.lineTo(wx + Math.cos(a) * (wr - 7), 18 + Math.sin(a) * (wr - 7)); ctx.stroke();
        }
        ctx.fillStyle = "#5a646c";
        ctx.beginPath(); ctx.arc(wx, 18, 2.4, 0, Math.PI * 2); ctx.fill();
    }

    // The full side illustration, facing +x, drawn already-squashed by caller.
    function showroomProfileArt(skin) {
        var wheelFront = 45, wheelRear = -44;
        // wheels first (body overlaps their tops → seated look)
        showroomWheel(wheelRear);
        showroomWheel(wheelFront);

        // body outline (dark keyline)
        ctx.fillStyle = skin.dark;
        ctx.save(); ctx.translate(0, 0); ctx.lineJoin = "round";
        showroomBodyPath();
        ctx.lineWidth = 5; ctx.strokeStyle = skin.dark; ctx.stroke();
        ctx.fill();
        ctx.restore();

        // body fill — vertical gradient, light source top
        var bg = ctx.createLinearGradient(0, -35, 0, 16);
        bg.addColorStop(0, skin.light);
        bg.addColorStop(0.45, skin.body);
        bg.addColorStop(1, skin.dark);
        showroomBodyPath();
        ctx.save(); ctx.clip();
        ctx.fillStyle = bg;
        ctx.fillRect(-80, -40, 160, 60);

        // rocker-panel shading (bottom strip in shadow)
        var rg = ctx.createLinearGradient(0, 4, 0, 16);
        rg.addColorStop(0, "rgba(0,0,0,0)"); rg.addColorStop(1, "rgba(0,0,0,0.4)");
        ctx.fillStyle = rg; ctx.fillRect(-80, 2, 160, 16);

        // racing stripe along the side (stripe skins)
        if (skin.stripe) {
            ctx.fillStyle = skin.stripe;
            ctx.globalAlpha = 0.9;
            ctx.fillRect(-72, -3, 146, 6);
            ctx.globalAlpha = 1;
        }

        // horizontal specular band along the body
        var spec = ctx.createLinearGradient(0, -10, 0, -2);
        spec.addColorStop(0, "rgba(255,255,255,0)");
        spec.addColorStop(0.5, "rgba(255,255,255,0.45)");
        spec.addColorStop(1, "rgba(255,255,255,0)");
        ctx.fillStyle = spec; ctx.fillRect(-72, -11, 146, 9);
        ctx.restore();  // end body clip

        // greenhouse / windows with sky reflection
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(-42, -31);
        ctx.lineTo(6, -31);
        ctx.quadraticCurveTo(15, -31, 20, -19);
        ctx.lineTo(-42, -14);
        ctx.closePath();
        ctx.clip();
        var sky = ctx.createLinearGradient(0, -33, 0, -13);
        sky.addColorStop(0, "#cdeafd"); sky.addColorStop(0.55, "#8fc6f0"); sky.addColorStop(1, "#5b93c4");
        ctx.fillStyle = sky; ctx.fillRect(-44, -33, 66, 22);
        // reflection streak
        ctx.fillStyle = "rgba(255,255,255,0.4)";
        ctx.beginPath();
        ctx.moveTo(-30, -31); ctx.lineTo(-22, -31); ctx.lineTo(-34, -13); ctx.lineTo(-42, -13); ctx.closePath(); ctx.fill();
        // Lulu head silhouette behind the glass
        var hairC = save.luluHair || "#8B5A2B";
        ctx.fillStyle = hairC;
        ctx.beginPath(); ctx.arc(-8, -20, 7.5, 0, Math.PI * 2); ctx.fill();      // hair
        ctx.fillStyle = "#FFD9C0";
        ctx.beginPath(); ctx.arc(-6, -19, 5, 0, Math.PI * 2); ctx.fill();        // face
        ctx.fillStyle = hairC;
        ctx.beginPath(); ctx.arc(-11, -18, 3.4, 0, Math.PI * 2); ctx.fill();     // hair sweep
        ctx.restore();
        // window pillar + frame
        ctx.strokeStyle = skin.dark; ctx.lineWidth = 2.4;
        ctx.beginPath();
        ctx.moveTo(-42, -31); ctx.lineTo(6, -31);
        ctx.quadraticCurveTo(15, -31, 20, -19);
        ctx.stroke();
        // B-pillar
        ctx.lineWidth = 2.2;
        ctx.beginPath(); ctx.moveTo(-16, -31); ctx.lineTo(-16, -14); ctx.stroke();

        // door seam + handle
        ctx.strokeStyle = "rgba(0,0,0,0.35)"; ctx.lineWidth = 1.6;
        ctx.beginPath(); ctx.moveTo(-16, -12); ctx.lineTo(-16, 8); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(-40, -9); ctx.lineTo(-40, 6); ctx.stroke();
        ctx.fillStyle = "rgba(0,0,0,0.4)";
        roundRect(-30, -8, 9, 3, 1.5); ctx.fill();

        // headlight (front) + taillight (rear)
        ctx.fillStyle = "#FFF7C0";
        ctx.beginPath(); ctx.ellipse(69, -4, 4, 5, 0, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = "rgba(255,255,255,0.6)"; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.ellipse(69, -4, 4, 5, 0, 0, Math.PI * 2); ctx.stroke();
        ctx.fillStyle = "#E53935";
        roundRect(-73, -5, 5, 9, 2); ctx.fill();

        // thin bumper highlights
        ctx.strokeStyle = "rgba(255,255,255,0.35)"; ctx.lineWidth = 1.4;
        ctx.beginPath(); ctx.moveTo(66, 10); ctx.lineTo(72, 6); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(-71, 8); ctx.lineTo(-66, 11); ctx.stroke();
    }

    // Narrow FRONT (or REAR) sliver, so the car never collapses edge-on.
    function showroomEndArt(skin, isFront) {
        // ground shadow
        ctx.fillStyle = "rgba(0,0,0,0.25)";
        ctx.beginPath(); ctx.ellipse(0, 40, 30, 10, 0, 0, Math.PI * 2); ctx.fill();
        // wheels peeking at the sides
        ctx.fillStyle = "#1b1b1f";
        roundRect(-26, 8, 8, 22, 4); ctx.fill();
        roundRect(18, 8, 8, 22, 4); ctx.fill();
        // narrow body
        showroomEndBodyPath();
        ctx.fillStyle = skin.dark; ctx.lineWidth = 5; ctx.strokeStyle = skin.dark;
        ctx.stroke(); ctx.fill();
        showroomEndBodyPath();
        ctx.save(); ctx.clip();
        var bg = ctx.createLinearGradient(-22, 0, 22, 0);
        bg.addColorStop(0, skin.dark); bg.addColorStop(0.5, skin.light); bg.addColorStop(1, skin.dark);
        ctx.fillStyle = bg; ctx.fillRect(-24, -40, 48, 60);
        if (skin.stripe) { ctx.fillStyle = skin.stripe; ctx.globalAlpha = 0.9; ctx.fillRect(-4, -36, 8, 52); ctx.globalAlpha = 1; }
        ctx.restore();
        // windshield / rear window
        var wg = ctx.createLinearGradient(0, -32, 0, -12);
        wg.addColorStop(0, "#cdeafd"); wg.addColorStop(1, "#5b93c4");
        ctx.fillStyle = wg;
        roundRect(-17, -31, 34, 20, 6); ctx.fill();
        ctx.strokeStyle = skin.dark; ctx.lineWidth = 2;
        roundRect(-17, -31, 34, 20, 6); ctx.stroke();
        if (isFront) {
            // Lulu behind the windshield
            var hairC = save.luluHair || "#8B5A2B";
            ctx.fillStyle = hairC; ctx.beginPath(); ctx.arc(0, -22, 7, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#FFD9C0"; ctx.beginPath(); ctx.arc(0, -20, 4.5, 0, Math.PI * 2); ctx.fill();
            // headlights
            ctx.fillStyle = "#FFF7C0";
            ctx.beginPath(); ctx.ellipse(-15, 2, 4, 5, 0, 0, Math.PI * 2); ctx.ellipse(15, 2, 4, 5, 0, 0, Math.PI * 2); ctx.fill();
            // grille
            ctx.fillStyle = "rgba(0,0,0,0.4)"; roundRect(-8, 4, 16, 5, 2); ctx.fill();
        } else {
            // taillights
            ctx.fillStyle = "#E53935";
            roundRect(-18, 0, 6, 8, 2); ctx.fill();
            roundRect(12, 0, 6, 8, 2); ctx.fill();
        }
        // roof specular
        ctx.fillStyle = "rgba(255,255,255,0.3)";
        roundRect(-14, -33, 28, 3, 1.5); ctx.fill();
    }

    function showroomEndBodyPath() {
        ctx.beginPath();
        ctx.moveTo(-22, 14);
        ctx.quadraticCurveTo(-24, -8, -18, -12);
        ctx.quadraticCurveTo(-18, -34, 0, -34);
        ctx.quadraticCurveTo(18, -34, 18, -12);
        ctx.quadraticCurveTo(24, -8, 22, 14);
        ctx.closePath();
    }

    // Public: draw the showroom car centered at the current origin.
    // angle spins the turntable; scale sizes it.
    function drawShowroomCar(skinKey, angle, scale) {
        var skin = SKINS[skinKey || save.selectedSkin] || SKINS.pink;
        var s = scale || 1;
        var f = Math.cos(angle);
        ctx.save();
        ctx.scale(s, s);

        if (Math.abs(f) < 0.18) {
            // edge-on → front/rear sliver (sin sign picks which end faces us)
            showroomEndArt(skin, Math.sin(angle) >= 0);
        } else {
            var squash = Math.abs(f);
            // ground shadow (barely squashes → stays grounded)
            ctx.fillStyle = "rgba(0,0,0,0.28)";
            ctx.beginPath();
            ctx.ellipse(0, 40, 74 * (0.5 + 0.5 * squash), 12, 0, 0, Math.PI * 2); ctx.fill();
            // squashed + sign-flipped profile
            ctx.save();
            ctx.scale(f, 1);
            showroomProfileArt(skin);
            // darken the side turning away
            if (squash < 1) {
                showroomBodyPath();
                ctx.fillStyle = "rgba(0,0,0," + ((1 - squash) * 0.4) + ")";
                ctx.fill();
            }
            ctx.restore();
        }
        ctx.restore();
    }

    // ── Drawing: Enemy cars ──────────────────────────────────
    // Pick a traffic body type — ordinary sedans (0-2) stay common; the fun rides
    // (pickup / sports / electric / box truck) sprinkle in for variety. Used by
    // traffic, roadside decoration, and the parked cars Lulu can borrow on foot.
    function randCarType() {
        var r = Math.random();
        if (r < 0.50) return randInt(0, 2);   // sedans — still the bulk of traffic
        if (r < 0.62) return 7;                // taxi — common around town
        if (r < 0.73) return 3;                // pickup truck
        if (r < 0.83) return 6;                // sports car
        if (r < 0.91) return 5;                // electric car
        if (r < 0.97) return 4;                // box truck
        return 8;                              // city bus (rarest — the longest)
    }
    // Collision box sized to each body — big rides (truck / bus) are proper big
    // targets instead of a car-sized box floating in a huge silhouette.
    function carHitbox(type) {
        if (type === 3) return { hw: 40, hh: 80 };    // pickup
        if (type === 4) return { hw: 46, hh: 94 };    // box truck
        if (type === 5) return { hw: 36, hh: 62 };    // electric
        if (type === 6) return { hw: 44, hh: 66 };    // sports
        if (type === 7) return { hw: 38, hh: 68 };    // taxi
        if (type === 8) return { hw: 48, hh: 112 };   // city bus
        return { hw: 36, hh: 64 };                     // sedans
    }
    // How each borrowed ride handles: a sports car is quick, a truck/bus is a slug.
    function vehicleSpeedFactor(type) {
        if (type === 6) return 1.18;   // sports — zippy
        if (type === 5) return 1.06;   // electric — peppy
        if (type === 3) return 0.90;   // pickup — a bit heavy
        if (type === 4) return 0.80;   // box truck — slug
        if (type === 8) return 0.74;   // city bus — big slug
        return 1;                      // sedans / taxi — normal
    }
    function drawEnemyCar(x, y, color, type) {
        ctx.save();
        ctx.translate(x, y);
        var ew, eh, rad;
        if (type === 0) { ew = 42; eh = 74; rad = 10; }
        else if (type === 1) { ew = 48; eh = 82; rad = 8; }
        else if (type === 2) { ew = 44; eh = 68; rad = 12; }
        else if (type === 3) { ew = 46; eh = 88; rad = 8; }   // pickup truck — longer
        else if (type === 4) { ew = 52; eh = 100; rad = 6; }  // box truck — biggest
        else if (type === 5) { ew = 42; eh = 72; rad = 16; }  // electric car — rounded/compact
        else if (type === 6) { ew = 50; eh = 76; rad = 9; }   // sports car — low & wide
        else if (type === 7) { ew = 44; eh = 76; rad = 9; }   // taxi — sedan-ish
        else if (type === 8) { ew = 50; eh = 118; rad = 7; }  // city bus — longest vehicle
        else { ew = 44; eh = 68; rad = 12; }
        var hw2 = ew / 2, hh2 = eh / 2;

        // soft drop shadow
        ctx.fillStyle = "rgba(0,0,0,0.18)";
        ctx.beginPath();
        ctx.ellipse(3, 5, hw2 + 3, hh2 - 8, 0, 0, Math.PI * 2);
        ctx.fill();

        // wheels (four dark roundRects at the corners)
        ctx.fillStyle = C.wheel;
        roundRect(-hw2 - 3, -hh2 + 8, 7, 16, 3); ctx.fill();
        roundRect(hw2 - 4, -hh2 + 8, 7, 16, 3); ctx.fill();
        roundRect(-hw2 - 3, hh2 - 24, 7, 16, 3); ctx.fill();
        roundRect(hw2 - 4, hh2 - 24, 7, 16, 3); ctx.fill();

        // darker body outline
        ctx.fillStyle = shadeColor(color, -40);
        roundRect(-hw2 - 2, -hh2 - 2, ew + 4, eh + 4, rad + 2); ctx.fill();

        // vertical body gradient
        var g2 = ctx.createLinearGradient(0, -hh2, 0, hh2);
        g2.addColorStop(0, shadeColor(color, 30));
        g2.addColorStop(1, color);
        ctx.fillStyle = g2;
        roundRect(-hw2, -hh2, ew, eh, rad); ctx.fill();

        if (type === 3) {
            // ── PICKUP TRUCK ── cab at front (top) + open cargo bed at rear (bottom)
            var cabTop = -hh2 + 4, cabH = eh * 0.42;
            // cab roof panel
            ctx.fillStyle = shadeColor(color, 12);
            roundRect(-hw2 + 3, cabTop, ew - 6, cabH, rad - 2); ctx.fill();
            // windshield (front of cab)
            ctx.fillStyle = "#78909C";
            roundRect(-hw2 + 8, cabTop + 5, ew - 16, 11, 3); ctx.fill();
            // cab rear window
            roundRect(-hw2 + 8, cabTop + cabH - 12, ew - 16, 9, 3); ctx.fill();
            // ── open cargo bed (recessed rectangle with visible walls) ──
            var bedTop = cabTop + cabH + 4, bedBot = hh2 - 6;
            ctx.fillStyle = shadeColor(color, -22);     // bed walls
            roundRect(-hw2 + 4, bedTop, ew - 8, bedBot - bedTop, 4); ctx.fill();
            ctx.fillStyle = shadeColor(color, -48);     // recessed bed floor
            roundRect(-hw2 + 8, bedTop + 4, ew - 16, bedBot - bedTop - 8, 3); ctx.fill();
            // spare tire in the bed
            ctx.fillStyle = C.wheel;
            ctx.beginPath(); ctx.ellipse(-hw2 + 15, (bedTop + bedBot) / 2, 6, 6, 0, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = shadeColor(C.wheel, 40);
            ctx.beginPath(); ctx.ellipse(-hw2 + 15, (bedTop + bedBot) / 2, 2.5, 2.5, 0, 0, Math.PI * 2); ctx.fill();
            // wooden crate in the bed
            ctx.fillStyle = "#A1887F";
            roundRect(hw2 - 22, (bedTop + bedBot) / 2 - 6, 13, 13, 2); ctx.fill();
            ctx.strokeStyle = "#6D4C41"; ctx.lineWidth = 1.5;
            roundRect(hw2 - 22, (bedTop + bedBot) / 2 - 6, 13, 13, 2); ctx.stroke();
            // cab windshield gloss
            ctx.fillStyle = "rgba(255,255,255,0.18)";
            roundRect(-hw2 + 8, cabTop + 5, (ew - 16) * 0.42, 11, 3); ctx.fill();
        } else if (type === 4) {
            // ── BOX TRUCK ── small cab at front + tall box cargo body behind it
            var bcabH = eh * 0.24, bcabTop = -hh2 + 3;
            // cab (uses body color, slightly darker roof)
            ctx.fillStyle = shadeColor(color, -8);
            roundRect(-hw2 + 3, bcabTop, ew - 6, bcabH, rad); ctx.fill();
            // cab windshield
            ctx.fillStyle = "#78909C";
            roundRect(-hw2 + 8, bcabTop + 4, ew - 16, bcabH - 8, 3); ctx.fill();
            ctx.fillStyle = "rgba(255,255,255,0.18)";
            roundRect(-hw2 + 8, bcabTop + 4, (ew - 16) * 0.42, bcabH - 8, 3); ctx.fill();
            // ── tall box cargo body (lighter than cab) ──
            var boxTop = bcabTop + bcabH + 2, boxBot = hh2 - 3;
            var boxCol = shadeColor(color, 55);
            var bg = ctx.createLinearGradient(0, boxTop, 0, boxBot);
            bg.addColorStop(0, shadeColor(boxCol, 20));
            bg.addColorStop(1, boxCol);
            ctx.fillStyle = shadeColor(color, -40);     // box edge
            roundRect(-hw2 + 1, boxTop, ew - 2, boxBot - boxTop, 5); ctx.fill();
            ctx.fillStyle = bg;
            roundRect(-hw2 + 3, boxTop + 1, ew - 6, boxBot - boxTop - 2, 4); ctx.fill();
            // roll-up door panel on the back with horizontal slat lines
            ctx.fillStyle = shadeColor(boxCol, -14);
            roundRect(-hw2 + 6, boxBot - 22, ew - 12, 18, 3); ctx.fill();
            ctx.strokeStyle = shadeColor(boxCol, -34); ctx.lineWidth = 1;
            for (var si = 1; si <= 3; si++) {
                var sy = boxBot - 22 + si * 4.5;
                ctx.beginPath(); ctx.moveTo(-hw2 + 8, sy); ctx.lineTo(hw2 - 8, sy); ctx.stroke();
            }
            // door handle
            ctx.fillStyle = shadeColor(boxCol, -40);
            roundRect(-3, boxBot - 15, 6, 3, 1.5); ctx.fill();
            // box top sheen
            ctx.fillStyle = "rgba(255,255,255,0.10)";
            roundRect(-hw2 + 5, boxTop + 2, ew - 10, 5, 2); ctx.fill();
        } else if (type === 5) {
            // ── ELECTRIC CAR ── sleek/rounded, smooth closed nose, teal eco accent
            var evTeal = "#26C6DA";
            // smooth nose (no grille) — a bright full-width LED light bar across the front
            ctx.fillStyle = evTeal;
            roundRect(-hw2 + 6, -hh2 + 3, ew - 12, 4, 2); ctx.fill();
            ctx.fillStyle = "rgba(255,255,255,0.7)";
            roundRect(-hw2 + 8, -hh2 + 4, ew - 16, 2, 1); ctx.fill();
            // large curved windshield + rear cabin glass
            ctx.fillStyle = "#78909C";
            roundRect(-hw2 + 7, -hh2 + 11, ew - 14, 13, 5); ctx.fill();
            roundRect(-hw2 + 7, hh2 - 26, ew - 14, 13, 5); ctx.fill();
            // eco/teal accent stripe down each side
            ctx.fillStyle = evTeal;
            roundRect(-hw2 + 2, -hh2 + 12, 3, eh - 24, 1.5); ctx.fill();
            roundRect(hw2 - 5, -hh2 + 12, 3, eh - 24, 1.5); ctx.fill();
            // charge-port dot with a tiny glow
            ctx.fillStyle = evTeal;
            ctx.beginPath(); ctx.ellipse(hw2 - 9, -hh2 + 20, 3, 3, 0, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#E0F7FA";
            ctx.beginPath(); ctx.ellipse(hw2 - 9, -hh2 + 20, 1.3, 1.3, 0, 0, Math.PI * 2); ctx.fill();
            // glossy windshield sheen + body top sheen
            ctx.fillStyle = "rgba(255,255,255,0.20)";
            roundRect(-hw2 + 7, -hh2 + 11, (ew - 14) * 0.42, 13, 4); ctx.fill();
            ctx.fillStyle = "rgba(255,255,255,0.14)";
            roundRect(-hw2 + 6, -hh2 + 7, ew - 12, 4, 3); ctx.fill();
            // taillights
            ctx.fillStyle = "#EF5350";
            ctx.beginPath();
            ctx.ellipse(-hw2 + 8, hh2 - 3, 3, 2, 0, 0, Math.PI * 2);
            ctx.ellipse(hw2 - 8, hh2 - 3, 3, 2, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
            return;
        } else if (type === 6) {
            // ── SPORTS CAR ── low & wide, tapered nose, twin racing stripes, rear wing
            // aggressive tapered nose (dark wedge at the front)
            ctx.fillStyle = shadeColor(color, -28);
            ctx.beginPath();
            ctx.moveTo(-hw2 + 6, -hh2 + 3);
            ctx.lineTo(hw2 - 6, -hh2 + 3);
            ctx.lineTo(hw2 - 12, -hh2 + 16);
            ctx.lineTo(-hw2 + 12, -hh2 + 16);
            ctx.closePath(); ctx.fill();
            // twin racing stripes down the middle
            ctx.fillStyle = "rgba(255,255,255,0.85)";
            roundRect(-6, -hh2 + 2, 4, eh - 4, 1.5); ctx.fill();
            roundRect(2, -hh2 + 2, 4, eh - 4, 1.5); ctx.fill();
            // low wide cockpit glass (single canopy)
            ctx.fillStyle = "#78909C";
            roundRect(-hw2 + 8, -hh2 + 18, ew - 16, 24, 5); ctx.fill();
            // windshield gloss
            ctx.fillStyle = "rgba(255,255,255,0.20)";
            roundRect(-hw2 + 8, -hh2 + 18, (ew - 16) * 0.4, 24, 4); ctx.fill();
            // ── rear spoiler / wing across the tail ──
            ctx.fillStyle = shadeColor(color, -50);
            roundRect(-hw2 - 1, hh2 - 12, 5, 12, 2); ctx.fill();   // left strut
            roundRect(hw2 - 4, hh2 - 12, 5, 12, 2); ctx.fill();    // right strut
            ctx.fillStyle = shadeColor(color, -30);
            roundRect(-hw2 - 3, hh2 - 6, ew + 6, 6, 3); ctx.fill(); // wing blade
            ctx.fillStyle = "rgba(255,255,255,0.16)";
            roundRect(-hw2 - 1, hh2 - 6, ew + 2, 2, 1); ctx.fill();
            // taillights
            ctx.fillStyle = "#EF5350";
            ctx.beginPath();
            ctx.ellipse(-hw2 + 9, hh2 - 9, 3, 2, 0, 0, Math.PI * 2);
            ctx.ellipse(hw2 - 9, hh2 - 9, 3, 2, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
            return;
        } else if (type === 7) {
            // ── TAXI ── classic yellow cab: checker band, TAXI roof light, red taillights
            var taxiY = "#FDD835", taxiYd = "#FBC02D";
            // repaint the body in iconic taxi yellow (a taxi is defined by its color)
            ctx.fillStyle = shadeColor(taxiY, -40);
            roundRect(-hw2 - 2, -hh2 - 2, ew + 4, eh + 4, rad + 2); ctx.fill();
            var tg = ctx.createLinearGradient(0, -hh2, 0, hh2);
            tg.addColorStop(0, shadeColor(taxiY, 25));
            tg.addColorStop(1, taxiYd);
            ctx.fillStyle = tg;
            roundRect(-hw2, -hh2, ew, eh, rad); ctx.fill();
            // windshield (front) + rear window
            ctx.fillStyle = "#78909C";
            roundRect(-hw2 + 8, -hh2 + 8, ew - 16, 11, 3); ctx.fill();
            roundRect(-hw2 + 6, hh2 - 22, ew - 12, 14, 4); ctx.fill();
            // ── black-and-white CHECKER stripe band across the middle side ──
            var bandTop = -2, bandH = 8, sq = bandH / 2, nsq = Math.ceil(ew / sq) + 1;
            ctx.fillStyle = "#ECEFF1";
            ctx.fillRect(-hw2, bandTop, ew, bandH);
            ctx.fillStyle = "#212121";
            for (var cr = 0; cr < 2; cr++) {
                for (var cc = 0; cc < nsq; cc++) {
                    if ((cr + cc) % 2 === 0) ctx.fillRect(-hw2 + cc * sq, bandTop + cr * sq, sq, sq);
                }
            }
            ctx.strokeStyle = shadeColor(taxiY, -40); ctx.lineWidth = 1;
            ctx.strokeRect(-hw2, bandTop, ew, bandH);
            // ── small "TAXI" roof-light box on top (front) ──
            var lbW = 20, lbH = 9, lbTop = -hh2 + 22;
            ctx.fillStyle = "#212121";
            roundRect(-lbW / 2 - 1, lbTop - 1, lbW + 2, lbH + 2, 2); ctx.fill();
            ctx.fillStyle = "#FFF59D";                  // lit sign
            roundRect(-lbW / 2, lbTop, lbW, lbH, 2); ctx.fill();
            ctx.fillStyle = "#5D4037";
            ctx.font = "bold 6px sans-serif";
            ctx.textAlign = "center"; ctx.textBaseline = "middle";
            ctx.fillText("TAXI", 0, lbTop + lbH / 2 + 0.5);
            ctx.textAlign = "left"; ctx.textBaseline = "alphabetic";
            // windshield gloss + body top sheen
            ctx.fillStyle = "rgba(255,255,255,0.20)";
            roundRect(-hw2 + 8, -hh2 + 8, (ew - 16) * 0.42, 11, 3); ctx.fill();
            ctx.fillStyle = "rgba(255,255,255,0.12)";
            roundRect(-hw2 + 4, -hh2 + 3, ew - 8, 5, 3); ctx.fill();
            // taillights
            ctx.fillStyle = "#EF5350";
            ctx.beginPath();
            ctx.ellipse(-hw2 + 8, hh2 - 3, 3, 2, 0, 0, Math.PI * 2);
            ctx.ellipse(hw2 - 8, hh2 - 3, 3, 2, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
            return;
        } else if (type === 8) {
            // ── CITY BUS ── longest vehicle: side-window rows, dest sign, livery stripe
            // big front windshield
            ctx.fillStyle = "#78909C";
            roundRect(-hw2 + 6, -hh2 + 12, ew - 12, 14, 4); ctx.fill();
            ctx.fillStyle = "rgba(255,255,255,0.20)";
            roundRect(-hw2 + 6, -hh2 + 12, (ew - 12) * 0.4, 14, 4); ctx.fill();
            // ── lit destination sign strip near the front ──
            ctx.fillStyle = "#212121";
            roundRect(-hw2 + 6, -hh2 + 4, ew - 12, 6, 2); ctx.fill();
            ctx.fillStyle = "#FFF176";
            roundRect(-hw2 + 8, -hh2 + 5, ew - 16, 4, 1.5); ctx.fill();
            ctx.fillStyle = "#4E342E";
            ctx.font = "bold 4.5px sans-serif";
            ctx.textAlign = "center"; ctx.textBaseline = "middle";
            ctx.fillText("42 DOWNTOWN", 0, -hh2 + 7.2);
            ctx.textAlign = "left"; ctx.textBaseline = "alphabetic";
            // ── horizontal livery accent stripe down the length ──
            ctx.fillStyle = shadeColor(color, 45);
            ctx.fillRect(-hw2, -1, ew, 6);
            ctx.fillStyle = shadeColor(color, -30);
            ctx.fillRect(-hw2, -2, ew, 1.5);
            // ── rows of side windows down BOTH sides (evenly spaced) ──
            var winTop = -hh2 + 30, winBot = hh2 - 12, winH = 12;
            var gap = 5, nWin = Math.floor((winBot - winTop + gap) / (winH + gap));
            var winW = 8;
            for (var wi = 0; wi < nWin; wi++) {
                var wy = winTop + wi * (winH + gap);
                if (wy + winH > winBot) break;
                ctx.fillStyle = "#78909C";
                roundRect(-hw2 + 3, wy, winW, winH, 2); ctx.fill();     // left column
                roundRect(hw2 - 3 - winW, wy, winW, winH, 2); ctx.fill(); // right column
                ctx.fillStyle = "rgba(255,255,255,0.16)";
                roundRect(-hw2 + 3, wy, winW * 0.4, winH, 2); ctx.fill();
                roundRect(hw2 - 3 - winW, wy, winW * 0.4, winH, 2); ctx.fill();
            }
            // body top sheen
            ctx.fillStyle = "rgba(255,255,255,0.10)";
            roundRect(-hw2 + 5, -hh2 + 3, ew - 10, 4, 2); ctx.fill();
            // taillights
            ctx.fillStyle = "#EF5350";
            ctx.beginPath();
            ctx.ellipse(-hw2 + 8, hh2 - 3, 3, 2, 0, 0, Math.PI * 2);
            ctx.ellipse(hw2 - 8, hh2 - 3, 3, 2, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
            return;
        } else {
            // ── SEDANS (types 0,1,2) — unchanged ──
            ctx.fillStyle = "#78909C";
            roundRect(-hw2 + 6, hh2 - 22, ew - 12, 14, 4); ctx.fill();
            roundRect(-hw2 + 8, -hh2 + 8, ew - 16, 11, 3); ctx.fill();
            // glass gloss highlight (diagonal sheen) — cleaner, less flat look
            ctx.fillStyle = "rgba(255,255,255,0.18)";
            roundRect(-hw2 + 8, hh2 - 21, (ew - 12) * 0.42, 12, 3); ctx.fill();
            // body top sheen
            ctx.fillStyle = "rgba(255,255,255,0.12)";
            roundRect(-hw2 + 4, -hh2 + 3, ew - 8, 5, 3); ctx.fill();
        }

        // facing taillights (enemy cars drive toward us — red lights at their rear/bottom)
        ctx.fillStyle = "#EF5350";
        ctx.beginPath();
        ctx.ellipse(-hw2 + 8, hh2 - 3, 3, 2, 0, 0, Math.PI * 2);
        ctx.ellipse(hw2 - 8, hh2 - 3, 3, 2, 0, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();
    }

    // ── Drawing: Obstacles ───────────────────────────────────
    function drawCone(x, y) {
        ctx.save();
        ctx.translate(x, y);
        ctx.fillStyle = "#444";
        ctx.beginPath(); ctx.ellipse(0, 6, 10, 4, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = C.cone;
        ctx.beginPath();
        ctx.moveTo(-9, 6); ctx.lineTo(-3, -14); ctx.lineTo(3, -14); ctx.lineTo(9, 6);
        ctx.closePath(); ctx.fill();
        ctx.fillStyle = C.coneStripe;
        ctx.fillRect(-6, -4, 12, 4);
        ctx.fillRect(-4, -12, 8, 3);
        ctx.strokeStyle = "#BF360C";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-9, 6); ctx.lineTo(-3, -14); ctx.lineTo(3, -14); ctx.lineTo(9, 6);
        ctx.closePath(); ctx.stroke();
        ctx.restore();
    }

    function drawPuddle(x, y) {
        ctx.save();
        ctx.translate(x, y);
        ctx.globalAlpha = 0.4;
        ctx.fillStyle = C.puddle;
        ctx.beginPath(); ctx.ellipse(0, 0, 24, 10, 0, 0, Math.PI * 2); ctx.fill();
        ctx.globalAlpha = 0.6;
        ctx.fillStyle = "#BBDEFB";
        ctx.beginPath(); ctx.ellipse(-6, -2, 6, 3, -0.3, 0, Math.PI * 2); ctx.fill();
        ctx.globalAlpha = 1;
        ctx.restore();
    }

    function drawCoin(x, y, time) {
        ctx.save();
        ctx.translate(x, y + Math.sin(time * 4) * 3);
        var squeeze = Math.abs(Math.cos(time * 3));
        var rx = 10 * Math.max(squeeze, 0.3);
        ctx.fillStyle = C.coinDark;
        ctx.beginPath(); ctx.ellipse(0, 0, rx + 2, 12, 0, 0, Math.PI * 2); ctx.fill();
        var cg = ctx.createRadialGradient(-2, -2, 1, 0, 0, 10);
        cg.addColorStop(0, C.coinShine);
        cg.addColorStop(0.6, C.coin);
        cg.addColorStop(1, C.coinDark);
        ctx.fillStyle = cg;
        ctx.beginPath(); ctx.ellipse(0, 0, rx, 10, 0, 0, Math.PI * 2); ctx.fill();
        if (squeeze > 0.5) {
            ctx.fillStyle = C.coinDark;
            ctx.font = "bold 11px Arial";
            ctx.textAlign = "center";
            ctx.textBaseline = "middle";
            ctx.fillText("★", 0, 0);
        }
        ctx.restore();
    }

    // A compact "bank balance" chip (💰 N) for scenes where Lulu spends coins —
    // court, the ER, jail — so she can watch fines/fees come out of her stash.
    function drawCoinHud(x, y) {
        var bw = 102, bh = 30;
        var bx = (typeof x === "number") ? x : W - 116, by = (typeof y === "number") ? y : 14;
        ctx.fillStyle = "rgba(0,0,0,0.45)"; roundRect(bx, by, bw, bh, 15); ctx.fill();
        ctx.strokeStyle = "rgba(255,215,0,0.5)"; ctx.lineWidth = 1.5; roundRect(bx, by, bw, bh, 15); ctx.stroke();
        drawCoin(bx + 18, by + 15, gameTime);
        drawText(formatNum(save.totalCoins), bx + 34, by + 16, "bold 16px 'Segoe UI', Arial, sans-serif", C.coin, "#000", 3, "left");
    }

    // ── Drawing: Pedestrians (people obstacles) ──────────────
    function drawPedestrian(x, y, walkTime, type, worker, drunk, cop, kid) {
        ctx.save();
        ctx.translate(x, y);
        if (drunk) {
            // Tipsy bar patron: a woozy green aura and a big drunken sway so it
            // reads as "drunk" at a glance even when zipping past.
            var ag = ctx.createRadialGradient(0, -4, 4, 0, -4, 30);
            ag.addColorStop(0, "rgba(124,179,66,0.42)");
            ag.addColorStop(0.6, "rgba(124,179,66,0.22)");
            ag.addColorStop(1, "rgba(124,179,66,0)");
            ctx.fillStyle = ag;
            ctx.beginPath(); ctx.arc(0, -4, 28, 0, Math.PI * 2); ctx.fill();
            // Floating "tipsy" bubbles drifting up off the patron.
            ctx.fillStyle = "rgba(174,213,129,0.85)";
            var bphase = walkTime * 1.6;
            for (var db = 0; db < 3; db++) {
                var bb = (bphase + db * 0.66) % 1;
                ctx.globalAlpha = (1 - bb) * 0.8;
                ctx.beginPath();
                ctx.arc(7 + db * 2 - Math.sin(bphase + db) * 2, -20 - bb * 16, 1.6 + db * 0.4, 0, Math.PI * 2);
                ctx.fill();
            }
            ctx.globalAlpha = 1;
            // Pronounced wobble (bigger than a normal walk lean).
            ctx.rotate(Math.sin(walkTime * 3) * 0.26);
        }
        var legSwing = Math.sin(walkTime * (drunk ? 6 : 10)) * (drunk ? 6 : 4);
        // Shadow
        ctx.fillStyle = "rgba(0,0,0,0.2)";
        ctx.beginPath(); ctx.ellipse(0, 16, 12, 4, 0, 0, Math.PI * 2); ctx.fill();

        // Legs
        var pantColor = type === 0 ? "#1976D2" : (type === 1 ? "#37474F" : "#6D4C41");
        ctx.fillStyle = pantColor;
        roundRect(-5, 4 - legSwing, 4, 14 + legSwing, 2); ctx.fill();
        roundRect(1, 4 + legSwing, 4, 14 - legSwing, 2); ctx.fill();
        // Shoes
        ctx.fillStyle = "#212121";
        roundRect(-6, 16 - legSwing, 6, 4, 2); ctx.fill();
        roundRect(0, 16 + legSwing, 6, 4, 2); ctx.fill();

        // Body / shirt
        var shirtColor = type === 0 ? "#E91E63" : (type === 1 ? "#FFC107" : "#43A047");
        ctx.fillStyle = shadeColor(shirtColor, -40);
        roundRect(-9, -8, 18, 16, 5); ctx.fill();
        ctx.fillStyle = shirtColor;
        roundRect(-8, -7, 16, 14, 4); ctx.fill();

        // Arms
        ctx.fillStyle = shirtColor;
        roundRect(-11, -6, 4, 12, 2); ctx.fill();
        roundRect(7, -6, 4, 12, 2); ctx.fill();
        // Hands
        ctx.fillStyle = C.skin;
        ctx.beginPath(); ctx.arc(-9, 7, 2.5, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(9, 7, 2.5, 0, Math.PI * 2); ctx.fill();

        // Head with chunky outline
        ctx.fillStyle = "#1A1A1A";
        ctx.beginPath(); ctx.arc(0, -14, 8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = C.skin;
        ctx.beginPath(); ctx.arc(0, -14, 6.8, 0, Math.PI * 2); ctx.fill();

        // Hair
        var hairCol = type === 0 ? "#FFC107" : (type === 1 ? "#3E2723" : "#6D4C41");
        ctx.fillStyle = hairCol;
        ctx.beginPath();
        ctx.arc(0, -16, 7, Math.PI, Math.PI * 2);
        ctx.fill();
        if (type === 0) {
            // ponytail
            ctx.beginPath();
            ctx.ellipse(-7, -12, 3, 5, -0.3, 0, Math.PI * 2);
            ctx.fill();
        }

        // Sasquatch-style big sparkly eyes
        ctx.fillStyle = "#FFFFFF";
        ctx.beginPath();
        ctx.arc(-2.2, -13, 1.6, 0, Math.PI * 2);
        ctx.arc(2.2, -13, 1.6, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#1A1A1A";
        ctx.beginPath();
        ctx.arc(-2.2, -12.8, 1.1, 0, Math.PI * 2);
        ctx.arc(2.2, -12.8, 1.1, 0, Math.PI * 2);
        ctx.fill();
        // Eye highlights
        ctx.fillStyle = "#FFFFFF";
        ctx.beginPath();
        ctx.arc(-1.8, -13.2, 0.4, 0, Math.PI * 2);
        ctx.arc(2.6, -13.2, 0.4, 0, Math.PI * 2);
        ctx.fill();
        // Rosy cheek dots
        ctx.fillStyle = "rgba(255,140,140,0.55)";
        ctx.beginPath();
        ctx.arc(-4, -11, 1.4, 0, Math.PI * 2);
        ctx.arc(4, -11, 1.4, 0, Math.PI * 2);
        ctx.fill();
        // Tiny "oh!" mouth (still surprised)
        ctx.fillStyle = "#5D2A2A";
        ctx.beginPath();
        ctx.ellipse(0, -10, 0.9, 1.3, 0, 0, Math.PI * 2);
        ctx.fill();

        if (worker) {
            // Road worker: hi-vis vest over the shirt + a yellow hard hat.
            ctx.fillStyle = "#FF7043";
            roundRect(-8, -7, 16, 14, 4); ctx.fill();
            roundRect(-11, -6, 4, 8, 2); ctx.fill(); roundRect(7, -6, 4, 8, 2); ctx.fill();
            ctx.fillStyle = "#FDD835";
            ctx.fillRect(-8, -2, 16, 2.5); ctx.fillRect(-1.5, -7, 3, 14);
            ctx.fillStyle = "#FBC02D";
            ctx.beginPath(); ctx.arc(0, -16, 8, Math.PI, 0); ctx.fill();
            ctx.fillRect(-8.5, -16, 17, 2.5);
            ctx.fillStyle = "#F9A825"; ctx.fillRect(-1.5, -23, 3, 7);
        }

        if (drunk) {
            // A chunky bottle clutched in one hand, raised a little for "cheers".
            ctx.fillStyle = "#2E7D32";
            roundRect(7.5, -2, 4.5, 12, 2); ctx.fill();
            ctx.fillStyle = "#1B5E20";
            ctx.fillRect(8.8, -6, 2, 4); // neck
            ctx.fillStyle = "#A5D6A7"; // glassy highlight
            ctx.fillRect(8.4, 0, 1, 7);
            ctx.fillStyle = "#FFF8E1"; // little label
            ctx.fillRect(8.2, 3, 3.2, 3);
        }

        if (cop) {
            // Navy police uniform over the shirt + a peaked cap + gold badge.
            ctx.fillStyle = "#1A237E";
            roundRect(-9, -8, 18, 16, 5); ctx.fill();
            roundRect(-11, -6, 4, 12, 2); ctx.fill(); roundRect(7, -6, 4, 12, 2); ctx.fill();
            ctx.fillStyle = "#FFD54F";
            ctx.beginPath(); ctx.arc(-4, -2, 1.8, 0, Math.PI * 2); ctx.fill();   // badge
            ctx.strokeStyle = "rgba(0,0,0,0.35)"; ctx.lineWidth = 1;
            ctx.beginPath(); ctx.moveTo(0, -7); ctx.lineTo(0, 7); ctx.stroke();  // placket
            // peaked cap over the hair
            ctx.fillStyle = "#0D1B5E";
            ctx.beginPath(); ctx.ellipse(0, -18, 8, 2.6, 0, 0, Math.PI * 2); ctx.fill();   // band
            ctx.fillStyle = "#1A237E";
            ctx.beginPath(); ctx.ellipse(0, -20.5, 7.5, 3.6, 0, Math.PI, 0); ctx.fill();   // crown
            ctx.fillStyle = "#0A0A0A";
            ctx.beginPath(); ctx.ellipse(0, -16.6, 8.5, 1.8, 0, 0, Math.PI); ctx.fill();   // brim
            ctx.fillStyle = "#FFD54F";
            ctx.beginPath(); ctx.arc(0, -19.5, 1.4, 0, Math.PI * 2); ctx.fill();           // emblem
        }

        if (kid) {
            // A little school backpack on the back.
            ctx.fillStyle = "#EF5350";
            roundRect(-12, -6, 5, 12, 2); ctx.fill();
            ctx.fillStyle = "#C62828";
            ctx.fillRect(-12, -1, 5, 2);
            ctx.strokeStyle = "#C62828"; ctx.lineWidth = 1.4;
            ctx.beginPath(); ctx.moveTo(-7, -6); ctx.lineTo(-4, -5); ctx.stroke(); // strap
        }

        ctx.restore();
    }

    // ── The Uncles: rare rotating roadside cameo ─────────────
    // Three recurring uncle characters that Lulu waves to on the shoulder.
    // Personality lives BOTH in the art (below) and these quip lists. Rotation
    // + spawn/greet logic is in 05-driving-loop.js; state in 03-art-parking-hud.js.
    var UNCLES = [
        { id: "yedidya", name: "Uncle Yedidya", color: "#FFF3E0", quips: [
            "Fresh from the cow — no pasteurizing!",
            "Vaccines? I don't DO shots.",
            "Forty-two and fabulous... still looking though.",
            "Swig of raw milk? It's ORGANIC."
        ] },
        { id: "burry", name: "Uncle Burry", color: "#A5D6A7", quips: [
            "Lakewood to Vegas, baby! 🎲",
            "Mindy packed the kids, I packed... the vibes.",
            "So chill. So blessed.",
            "Desert's callin', cousin."
        ] },
        { id: "shuey", name: "Uncle Shuey", color: "#B3E5FC", quips: [
            "Rough year... the divorce, then the cat.",
            "Just me and Avraham now.",
            "I'm a doctor, but I couldn't save Fluffy. 😿",
            "Say hi to your uncle, Avraham."
        ] }
    ];

    // Dispatch a roadside uncle by id.
    function drawUncle(u) {
        if (u.id === "yedidya") drawUncleYedidya(u.x, u.y, u.walkTime);
        else if (u.id === "burry") drawUncleBurry(u.x, u.y, u.walkTime);
        else if (u.id === "shuey") drawUncleShuey(u.x, u.y, u.walkTime);
    }

    // Shared: a plain little standing "companion" figure (kids / wife) at (dx,dy)
    // scaled down. skin/hair/shirt customizable so groups read clearly.
    function drawUncleBuddy(dx, dy, scale, shirt, hair, walkTime, isGirl) {
        ctx.save();
        ctx.translate(dx, dy);
        ctx.scale(scale, scale);
        var sw = Math.sin(walkTime * 9 + dx) * 3;
        ctx.fillStyle = "rgba(0,0,0,0.18)";
        ctx.beginPath(); ctx.ellipse(0, 15, 9, 3, 0, 0, Math.PI * 2); ctx.fill();
        // legs
        ctx.fillStyle = "#3E4A54";
        roundRect(-4, 3 - sw, 3.4, 12 + sw, 2); ctx.fill();
        roundRect(0.6, 3 + sw, 3.4, 12 - sw, 2); ctx.fill();
        ctx.fillStyle = "#212121";
        roundRect(-5, 14 - sw, 5, 3.5, 1.5); ctx.fill();
        roundRect(0, 14 + sw, 5, 3.5, 1.5); ctx.fill();
        // body
        ctx.fillStyle = shadeColor(shirt, -35); roundRect(-7, -6, 14, 13, 4); ctx.fill();
        ctx.fillStyle = shirt; roundRect(-6, -5, 12, 11, 3); ctx.fill();
        // arms
        ctx.fillStyle = shirt;
        roundRect(-8.5, -4, 3, 9, 1.5); ctx.fill();
        roundRect(5.5, -4, 3, 9, 1.5); ctx.fill();
        ctx.fillStyle = C.skin;
        ctx.beginPath(); ctx.arc(-7, 5, 2, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(7, 5, 2, 0, Math.PI * 2); ctx.fill();
        // head
        ctx.fillStyle = "#1A1A1A"; ctx.beginPath(); ctx.arc(0, -11, 6.6, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = C.skin; ctx.beginPath(); ctx.arc(0, -11, 5.4, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = hair;
        ctx.beginPath(); ctx.arc(0, -13, 5.6, Math.PI, Math.PI * 2); ctx.fill();
        if (isGirl) { ctx.beginPath(); ctx.arc(-6, -9, 2.6, 0, Math.PI * 2); ctx.arc(6, -9, 2.6, 0, Math.PI * 2); ctx.fill(); }
        // eyes
        ctx.fillStyle = "#FFF";
        ctx.beginPath(); ctx.arc(-1.9, -11, 1.2, 0, Math.PI * 2); ctx.arc(1.9, -11, 1.2, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#1A1A1A";
        ctx.beginPath(); ctx.arc(-1.9, -11, 0.6, 0, Math.PI * 2); ctx.arc(1.9, -11, 0.6, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
    }

    // Uncle Yedidya — scruffy black beard, glass jug of RAW milk, "NO 💉" pin,
    // bare ring finger. The single-over-40 raw-milk anti-vaxxer uncle.
    function drawUncleYedidya(x, y, walkTime) {
        ctx.save();
        ctx.translate(x, y);
        var legSwing = Math.sin(walkTime * 9) * 3;
        ctx.fillStyle = "rgba(0,0,0,0.22)";
        ctx.beginPath(); ctx.ellipse(0, 17, 12, 4, 0, 0, Math.PI * 2); ctx.fill();
        // legs (black slacks)
        ctx.fillStyle = "#263238";
        roundRect(-5, 5 - legSwing, 4.4, 14 + legSwing, 2); ctx.fill();
        roundRect(0.6, 5 + legSwing, 4.4, 14 - legSwing, 2); ctx.fill();
        ctx.fillStyle = "#111"; roundRect(-6, 17 - legSwing, 6, 4, 2); ctx.fill(); roundRect(0, 17 + legSwing, 6, 4, 2); ctx.fill();
        // long dark coat body
        ctx.fillStyle = "#1C2733"; roundRect(-10, -8, 20, 20, 6); ctx.fill();
        ctx.fillStyle = "#2C3A48"; roundRect(-9, -7, 18, 18, 5); ctx.fill();
        // white shirt collar V
        ctx.fillStyle = "#ECEFF1";
        ctx.beginPath(); ctx.moveTo(-3, -7); ctx.lineTo(0, -1); ctx.lineTo(3, -7); ctx.closePath(); ctx.fill();
        // "NO shots" pin on lapel (red circle + syringe + slash)
        ctx.fillStyle = "#E53935"; ctx.beginPath(); ctx.arc(-5.5, -3, 3.2, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = "#FFF"; ctx.lineWidth = 0.9;
        ctx.beginPath(); ctx.moveTo(-7, -4.4); ctx.lineTo(-4, -1.6); ctx.stroke(); // syringe
        ctx.strokeStyle = "#B71C1C"; ctx.lineWidth = 1.3;
        ctx.beginPath(); ctx.moveTo(-7.6, -1); ctx.lineTo(-3.4, -5); ctx.stroke(); // NO slash
        // right arm holding a milk jug
        ctx.fillStyle = "#2C3A48"; roundRect(6, -6, 4.4, 12, 2); ctx.fill();
        ctx.fillStyle = "#4E5D6B"; roundRect(-11, -6, 4.4, 13, 2); ctx.fill(); // left arm (bare hand shown low)
        // LEFT hand — bare ring finger (single!)
        ctx.fillStyle = C.skin; ctx.beginPath(); ctx.arc(-9, 8, 2.6, 0, Math.PI * 2); ctx.fill();
        // the RAW milk jug in right hand
        ctx.save();
        ctx.translate(11, 6);
        ctx.fillStyle = "rgba(255,255,255,0.55)"; roundRect(-3.5, -9, 8, 12, 2.5); ctx.fill();   // glass
        ctx.fillStyle = "#FFFDF7"; roundRect(-3, -4, 7, 6.5, 2); ctx.fill();                       // milk fill
        ctx.fillStyle = "rgba(255,255,255,0.75)"; ctx.fillRect(-3, -10, 6, 2.5);                   // cap
        ctx.strokeStyle = "rgba(255,255,255,0.8)"; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.arc(4, -6, 2.6, -Math.PI * 0.5, Math.PI * 0.5); ctx.stroke();         // handle
        ctx.fillStyle = "#C62828"; ctx.font = "bold 4px Arial"; ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillText("RAW", 0.5, -1);
        ctx.restore();
        // hand on jug
        ctx.fillStyle = C.skin; ctx.beginPath(); ctx.arc(9, 8, 2.6, 0, Math.PI * 2); ctx.fill();
        // head
        ctx.fillStyle = "#1A1A1A"; ctx.beginPath(); ctx.arc(0, -14, 8.4, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = C.skin; ctx.beginPath(); ctx.arc(0, -14, 7, 0, Math.PI * 2); ctx.fill();
        // black hat (yeshivish)
        ctx.fillStyle = "#0A0A0A";
        ctx.beginPath(); ctx.ellipse(0, -19, 10.5, 2.6, 0, 0, Math.PI * 2); ctx.fill();     // brim
        roundRect(-7, -26, 14, 8, 3); ctx.fill();                                            // crown
        ctx.fillStyle = "#1A1A1A"; ctx.fillRect(-7, -20.5, 14, 2);
        // eyes
        ctx.fillStyle = "#FFF"; ctx.beginPath(); ctx.arc(-2.6, -14.5, 1.4, 0, Math.PI * 2); ctx.arc(2.6, -14.5, 1.4, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#1A1A1A"; ctx.beginPath(); ctx.arc(-2.6, -14.5, 0.8, 0, Math.PI * 2); ctx.arc(2.6, -14.5, 0.8, 0, Math.PI * 2); ctx.fill();
        // scruffy half-messy black beard (uneven clumps)
        ctx.fillStyle = "#141414";
        var bd = [[-6, -9], [-3, -7], [0, -6], [3, -7], [6, -9], [-5, -6], [5, -6], [-1.5, -4.5], [2, -4.5], [0, -3]];
        for (var bi = 0; bi < bd.length; bi++) {
            ctx.beginPath(); ctx.arc(bd[bi][0], bd[bi][1], 2.6 + (bi % 3) * 0.5, 0, Math.PI * 2); ctx.fill();
        }
        ctx.restore();
    }

    // Uncle Burry — clean-shaven, shades, chill droopy smile, green haze,
    // wife Mindy + little kids + a stack of "VEGAS" moving boxes.
    function drawUncleBurry(x, y, walkTime) {
        ctx.save();
        ctx.translate(x, y);
        // green mellow haze around him
        var hz = ctx.createRadialGradient(0, -6, 4, 0, -6, 34);
        hz.addColorStop(0, "rgba(120,200,120,0.34)");
        hz.addColorStop(0.6, "rgba(120,200,120,0.16)");
        hz.addColorStop(1, "rgba(120,200,120,0)");
        ctx.fillStyle = hz; ctx.beginPath(); ctx.arc(0, -6, 32, 0, Math.PI * 2); ctx.fill();
        // drifting smoke wisps
        ctx.strokeStyle = "rgba(200,230,200,0.55)"; ctx.lineWidth = 1.4;
        for (var sm = 0; sm < 2; sm++) {
            var ph = walkTime * 1.3 + sm * 1.5;
            ctx.beginPath();
            ctx.moveTo(9 + sm * 3, -16);
            ctx.quadraticCurveTo(13 + Math.sin(ph) * 4, -24, 9 + sm * 3 + Math.sin(ph + 1) * 3, -32);
            ctx.stroke();
        }
        // Mindy (pretty wife) to his left + kids clustered, boxes to the right
        drawUncleBuddy(-19, 2, 0.78, "#E91E63", "#4E342E", walkTime, true);   // Mindy
        drawUncleBuddy(-11, 8, 0.5, "#42A5F5", "#3E2723", walkTime + 0.5, false); // kid
        drawUncleBuddy(-24, 9, 0.46, "#FFB300", "#5D4037", walkTime + 1.1, false); // kid
        drawUncleBuddy(-15, 11, 0.42, "#66BB6A", "#3E2723", walkTime + 1.7, true); // kid
        // VEGAS moving boxes stacked to his right
        ctx.save();
        ctx.translate(20, 8);
        ctx.fillStyle = "#C89B6C"; roundRect(-9, -2, 18, 12, 1.5); ctx.fill();
        ctx.fillStyle = "#B5875A"; roundRect(-7, -12, 14, 11, 1.5); ctx.fill();
        ctx.strokeStyle = "rgba(90,60,30,0.5)"; ctx.lineWidth = 0.8;
        ctx.beginPath(); ctx.moveTo(-9, 3); ctx.lineTo(9, 3); ctx.moveTo(-7, -6.5); ctx.lineTo(7, -6.5); ctx.stroke();
        ctx.fillStyle = "#7B4B1E"; ctx.font = "bold 5px Arial"; ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillText("VEGAS", 0, 4); ctx.fillText("VEGAS", 0, -6);
        // a couple of dice on top
        ctx.fillStyle = "#FFF"; roundRect(-6, -16, 5, 5, 1); ctx.fill(); roundRect(1, -16, 5, 5, 1); ctx.fill();
        ctx.fillStyle = "#333";
        ctx.beginPath(); ctx.arc(-3.5, -13.5, 0.7, 0, Math.PI * 2); ctx.arc(3.5, -14.5, 0.7, 0, Math.PI * 2); ctx.arc(3.5, -12.5, 0.7, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
        // Burry himself
        var legSwing = Math.sin(walkTime * 8) * 2.5;
        ctx.fillStyle = "rgba(0,0,0,0.22)";
        ctx.beginPath(); ctx.ellipse(0, 17, 11, 4, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#455A64";
        roundRect(-5, 5 - legSwing, 4.4, 14 + legSwing, 2); ctx.fill();
        roundRect(0.6, 5 + legSwing, 4.4, 14 - legSwing, 2); ctx.fill();
        ctx.fillStyle = "#212121"; roundRect(-6, 17 - legSwing, 6, 4, 2); ctx.fill(); roundRect(0, 17 + legSwing, 6, 4, 2); ctx.fill();
        // loose tropical shirt
        ctx.fillStyle = shadeColor("#26A69A", -35); roundRect(-10, -8, 20, 19, 6); ctx.fill();
        ctx.fillStyle = "#26A69A"; roundRect(-9, -7, 18, 17, 5); ctx.fill();
        // palm-leaf pattern dabs
        ctx.fillStyle = "rgba(255,241,118,0.7)";
        ctx.beginPath(); ctx.arc(-4, -2, 1.3, 0, Math.PI * 2); ctx.arc(3, 2, 1.3, 0, Math.PI * 2); ctx.arc(5, -4, 1.3, 0, Math.PI * 2); ctx.fill();
        // relaxed arms
        ctx.fillStyle = "#26A69A"; roundRect(-11.5, -6, 4.2, 12, 2); ctx.fill(); roundRect(7.3, -6, 4.2, 12, 2); ctx.fill();
        ctx.fillStyle = C.skin;
        ctx.beginPath(); ctx.arc(-9.5, 7, 2.6, 0, Math.PI * 2); ctx.arc(9.5, 7, 2.6, 0, Math.PI * 2); ctx.fill();
        // head
        ctx.fillStyle = "#1A1A1A"; ctx.beginPath(); ctx.arc(0, -14, 8.4, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = C.skin; ctx.beginPath(); ctx.arc(0, -14, 7, 0, Math.PI * 2); ctx.fill();
        // short hair + kippah
        ctx.fillStyle = "#3E2723"; ctx.beginPath(); ctx.arc(0, -16, 7, Math.PI, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#5D4037"; ctx.beginPath(); ctx.ellipse(0, -20.5, 4.2, 2, 0, Math.PI, 0); ctx.fill();
        // sunglasses
        ctx.fillStyle = "#111";
        roundRect(-6.5, -15.5, 5, 3.6, 1.4); ctx.fill();
        roundRect(1.5, -15.5, 5, 3.6, 1.4); ctx.fill();
        ctx.fillRect(-1.5, -14.4, 3, 1.2);
        ctx.fillStyle = "rgba(120,220,160,0.5)"; ctx.fillRect(-5.6, -15, 3.2, 1.2); ctx.fillRect(2.4, -15, 3.2, 1.2);
        // droopy chill smile
        ctx.strokeStyle = "#5D2A2A"; ctx.lineWidth = 1.3; ctx.lineCap = "round";
        ctx.beginPath(); ctx.arc(0, -11, 3, 0.15 * Math.PI, 0.85 * Math.PI); ctx.stroke();
        ctx.restore();
    }

    // Uncle Shuey — like Burry but older/greyer, a DOCTOR (scrubs + stethoscope
    // + head mirror), melancholy. Son Avraham holds his hand; a translucent cat
    // angel (halo + wings) floats above.
    function drawUncleShuey(x, y, walkTime) {
        ctx.save();
        ctx.translate(x, y);
        // floating translucent cat angel above him
        ctx.save();
        ctx.globalAlpha = 0.5;
        ctx.translate(6, -34 + Math.sin(walkTime * 2) * 3);
        // halo
        ctx.strokeStyle = "#FFF59D"; ctx.lineWidth = 1.4;
        ctx.beginPath(); ctx.ellipse(0, -7, 4.5, 1.8, 0, 0, Math.PI * 2); ctx.stroke();
        // wings
        ctx.fillStyle = "rgba(255,255,255,0.85)";
        ctx.beginPath(); ctx.ellipse(-6, -1, 3.5, 2, -0.5, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.ellipse(6, -1, 3.5, 2, 0.5, 0, Math.PI * 2); ctx.fill();
        // cat body/head
        ctx.fillStyle = "rgba(176,190,197,0.9)";
        ctx.beginPath(); ctx.ellipse(0, 2, 5, 4, 0, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(0, -2, 4, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "rgba(150,165,175,0.95)";
        ctx.beginPath(); ctx.moveTo(-3.5, -4.5); ctx.lineTo(-2, -1.5); ctx.lineTo(-4.8, -1.8); ctx.closePath(); ctx.fill(); // ear
        ctx.beginPath(); ctx.moveTo(3.5, -4.5); ctx.lineTo(2, -1.5); ctx.lineTo(4.8, -1.8); ctx.closePath(); ctx.fill();   // ear
        // sad closed eyes 😿
        ctx.strokeStyle = "#37474F"; ctx.lineWidth = 0.8; ctx.lineCap = "round";
        ctx.beginPath(); ctx.moveTo(-2.4, -2.6); ctx.lineTo(-0.8, -1.8); ctx.moveTo(2.4, -2.6); ctx.lineTo(0.8, -1.8); ctx.stroke();
        // tear
        ctx.fillStyle = "rgba(129,212,250,0.9)"; ctx.beginPath(); ctx.arc(-1.6, -0.6, 0.9, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
        // little Avraham holding his (left) hand
        drawUncleBuddy(-14, 5, 0.62, "#5C6BC0", "#3E2723", walkTime + 0.7, false);
        // Shuey himself
        var legSwing = Math.sin(walkTime * 7) * 2;
        ctx.fillStyle = "rgba(0,0,0,0.22)";
        ctx.beginPath(); ctx.ellipse(0, 17, 11, 4, 0, 0, Math.PI * 2); ctx.fill();
        // scrub pants
        ctx.fillStyle = "#2E7D8A";
        roundRect(-5, 5 - legSwing, 4.4, 14 + legSwing, 2); ctx.fill();
        roundRect(0.6, 5 + legSwing, 4.4, 14 - legSwing, 2); ctx.fill();
        ctx.fillStyle = "#ECEFF1"; roundRect(-6, 17 - legSwing, 6, 4, 2); ctx.fill(); roundRect(0, 17 + legSwing, 6, 4, 2); ctx.fill(); // white clogs
        // teal scrub top
        ctx.fillStyle = shadeColor("#26A69A", -50); roundRect(-10, -8, 20, 19, 6); ctx.fill();
        ctx.fillStyle = "#3AAFA9"; roundRect(-9, -7, 18, 17, 5); ctx.fill();
        // scrub V-neck
        ctx.strokeStyle = "#2E7D8A"; ctx.lineWidth = 1.2;
        ctx.beginPath(); ctx.moveTo(-3.5, -7); ctx.lineTo(0, -2); ctx.lineTo(3.5, -7); ctx.stroke();
        // chest pocket
        ctx.strokeStyle = "rgba(0,0,0,0.2)"; ctx.lineWidth = 0.8; ctx.strokeRect(2, 1, 5, 5);
        // arms
        ctx.fillStyle = "#3AAFA9"; roundRect(-11.5, -6, 4.2, 12, 2); ctx.fill(); roundRect(7.3, -6, 4.2, 12, 2); ctx.fill();
        ctx.fillStyle = C.skin;
        ctx.beginPath(); ctx.arc(-9.5, 7, 2.6, 0, Math.PI * 2); ctx.arc(9.5, 7, 2.6, 0, Math.PI * 2); ctx.fill();
        // stethoscope around neck
        ctx.strokeStyle = "#263238"; ctx.lineWidth = 1.4;
        ctx.beginPath(); ctx.moveTo(-4, -6); ctx.quadraticCurveTo(0, 3, 5, 5); ctx.moveTo(4, -6); ctx.quadraticCurveTo(6, 2, 5, 5); ctx.stroke();
        ctx.fillStyle = "#90A4AE"; ctx.beginPath(); ctx.arc(5, 6, 1.8, 0, Math.PI * 2); ctx.fill();
        // head
        ctx.fillStyle = "#1A1A1A"; ctx.beginPath(); ctx.arc(0, -14, 8.4, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = C.skin; ctx.beginPath(); ctx.arc(0, -14, 7, 0, Math.PI * 2); ctx.fill();
        // greying hair + light stubble
        ctx.fillStyle = "#8D9499"; ctx.beginPath(); ctx.arc(0, -16, 7, Math.PI, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "rgba(120,130,135,0.5)";
        ctx.beginPath(); ctx.arc(-4, -9.5, 3.2, 0, Math.PI * 2); ctx.arc(4, -9.5, 3.2, 0, Math.PI * 2); ctx.arc(0, -8, 3.2, 0, Math.PI * 2); ctx.fill();
        // head mirror (doctor) on forehead
        ctx.fillStyle = "#CFD8DC"; ctx.beginPath(); ctx.arc(0, -19, 2.6, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#607D8B"; ctx.beginPath(); ctx.arc(0, -19, 1.2, 0, Math.PI * 2); ctx.fill();
        // sad eyes + downturned mouth
        ctx.fillStyle = "#FFF"; ctx.beginPath(); ctx.arc(-2.6, -14, 1.4, 0, Math.PI * 2); ctx.arc(2.6, -14, 1.4, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#1A1A1A"; ctx.beginPath(); ctx.arc(-2.6, -13.4, 0.8, 0, Math.PI * 2); ctx.arc(2.6, -13.4, 0.8, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = "#5D2A2A"; ctx.lineWidth = 1.2; ctx.lineCap = "round";
        ctx.beginPath(); ctx.arc(0, -8.5, 3, 1.15 * Math.PI, 1.85 * Math.PI); ctx.stroke(); // frown
        ctx.restore();
    }

    // ── Drawing: Animals ─────────────────────────────────────
    function drawDuck(x, y, walkFrame) {
        ctx.save();
        ctx.translate(x, y);
        ctx.fillStyle = "#333";
        ctx.beginPath(); ctx.ellipse(0, 0, 11, 9, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#FDD835";
        ctx.beginPath(); ctx.ellipse(0, 0, 9, 7, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#333";
        ctx.beginPath(); ctx.arc(-10, -6, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#FDD835";
        ctx.beginPath(); ctx.arc(-10, -6, 5.5, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#FF8F00";
        ctx.beginPath();
        ctx.moveTo(-15, -6); ctx.lineTo(-20, -5); ctx.lineTo(-15, -4);
        ctx.closePath(); ctx.fill();
        ctx.fillStyle = "#333";
        ctx.beginPath(); ctx.arc(-11, -7, 1.5, 0, Math.PI * 2); ctx.fill();
        var legOff = Math.sin(walkFrame * 8) * 3;
        ctx.fillStyle = "#FF8F00";
        ctx.fillRect(-3, 6, 3, 4 + legOff);
        ctx.fillRect(3, 6, 3, 4 - legOff);
        ctx.restore();
    }

    function drawRaccoon(x, y, walkFrame) {
        ctx.save();
        ctx.translate(x, y);
        ctx.fillStyle = "#333";
        ctx.beginPath(); ctx.ellipse(0, 0, 12, 10, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#78909C";
        ctx.beginPath(); ctx.ellipse(0, 0, 10, 8, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#333";
        ctx.beginPath(); ctx.arc(-10, -5, 8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#78909C";
        ctx.beginPath(); ctx.arc(-10, -5, 6.5, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#333";
        ctx.beginPath(); ctx.ellipse(-10, -5, 6, 2.5, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#FFF";
        ctx.beginPath();
        ctx.arc(-12, -5, 2, 0, Math.PI * 2);
        ctx.arc(-8, -5, 2, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#333";
        ctx.beginPath();
        ctx.arc(-12, -5, 1, 0, Math.PI * 2);
        ctx.arc(-8, -5, 1, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#333";
        ctx.beginPath(); ctx.arc(-14, -3, 1.5, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = "#78909C";
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.moveTo(10, 0); ctx.quadraticCurveTo(16, -8, 12, -14); ctx.stroke();
        ctx.strokeStyle = "#333";
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.moveTo(12, -10); ctx.quadraticCurveTo(14, -14, 12, -16); ctx.stroke();
        var legOff2 = Math.sin(walkFrame * 8) * 3;
        ctx.fillStyle = "#555";
        ctx.fillRect(-5, 7, 4, 4 + legOff2);
        ctx.fillRect(3, 7, 4, 4 - legOff2);
        ctx.restore();
    }

    function drawOstrich(x, y, walkFrame) {
        ctx.save();
        ctx.translate(x, y);
        var legOff = Math.sin(walkFrame * 7) * 8;

        // Shadow
        ctx.fillStyle = "rgba(0,0,0,0.2)";
        ctx.beginPath(); ctx.ellipse(0, 18, 14, 4, 0, 0, Math.PI * 2); ctx.fill();

        // Legs (long pink/orange)
        ctx.strokeStyle = "#F4A582";
        ctx.lineWidth = 3;
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(-4, 6); ctx.lineTo(-5, 16 + legOff); ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(4, 6); ctx.lineTo(5, 16 - legOff); ctx.stroke();
        // Feet (3-toed)
        ctx.fillStyle = "#FFB74D";
        ctx.beginPath();
        ctx.moveTo(-5, 16 + legOff);
        ctx.lineTo(-8, 18 + legOff);
        ctx.lineTo(-2, 18 + legOff);
        ctx.closePath(); ctx.fill();
        ctx.beginPath();
        ctx.moveTo(5, 16 - legOff);
        ctx.lineTo(2, 18 - legOff);
        ctx.lineTo(8, 18 - legOff);
        ctx.closePath(); ctx.fill();

        // Body (big fluffy black/grey oval)
        ctx.fillStyle = "#212121";
        ctx.beginPath(); ctx.ellipse(0, 0, 14, 11, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#424242";
        ctx.beginPath(); ctx.ellipse(0, 0, 12, 9, 0, 0, Math.PI * 2); ctx.fill();
        // White tail feathers
        ctx.fillStyle = "#FAFAFA";
        ctx.beginPath();
        ctx.ellipse(11, 2, 5, 4, 0.4, 0, Math.PI * 2);
        ctx.fill();

        // Long neck (curves up and left)
        ctx.strokeStyle = "#F4A582";
        ctx.lineWidth = 5;
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(-8, -3);
        ctx.quadraticCurveTo(-14, -12, -10, -22);
        ctx.stroke();

        // Head
        ctx.fillStyle = "#F4A582";
        ctx.beginPath();
        ctx.arc(-10, -23, 5, 0, Math.PI * 2); ctx.fill();
        // Beak
        ctx.fillStyle = "#FFB74D";
        ctx.beginPath();
        ctx.moveTo(-14, -23);
        ctx.lineTo(-19, -22);
        ctx.lineTo(-14, -21);
        ctx.closePath(); ctx.fill();
        // Eye
        ctx.fillStyle = "#FFF";
        ctx.beginPath(); ctx.arc(-11, -24, 1.8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#222";
        ctx.beginPath(); ctx.arc(-11, -24, 1, 0, Math.PI * 2); ctx.fill();
        // Eyelash
        ctx.strokeStyle = "#222";
        ctx.lineWidth = 0.8;
        ctx.beginPath();
        ctx.moveTo(-12, -26); ctx.lineTo(-12.5, -27.5);
        ctx.stroke();

        ctx.restore();
    }

    // Dispatch helper: draw whichever critter species is swarming Lulu.
    function drawCrashAnimal(x, y, type, frame) {
        if (type === "raccoon") drawRaccoon(x, y, frame);
        else if (type === "ostrich") drawOstrich(x, y, frame);
        else drawDuck(x, y, frame);
    }

    // A comically-deceased critter (belly-up, X-ed-out eyes, lolling tongue)
    // for the "you hit an animal" crash. Species only changes the body colour.
    function drawDeadAnimal(x, y, type) {
        var col = type === "raccoon" ? "#78909C" : type === "ostrich" ? "#424242" : "#FDD835";
        ctx.save();
        ctx.translate(x, y);
        // Shadow
        ctx.fillStyle = "rgba(0,0,0,0.2)";
        ctx.beginPath(); ctx.ellipse(0, 6, 16, 5, 0, 0, Math.PI * 2); ctx.fill();
        // Flattened body
        ctx.fillStyle = col;
        ctx.beginPath(); ctx.ellipse(0, 0, 14, 7, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "rgba(0,0,0,0.12)";
        ctx.beginPath(); ctx.ellipse(0, 1.5, 14, 5.5, 0, 0, Math.PI * 2); ctx.fill();
        // Stiff little legs sticking straight up
        ctx.strokeStyle = "#5D4037";
        ctx.lineWidth = 2; ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(-6, -4); ctx.lineTo(-8, -12);
        ctx.moveTo(-2, -5); ctx.lineTo(-2, -13);
        ctx.moveTo(2, -5); ctx.lineTo(3, -13);
        ctx.moveTo(6, -4); ctx.lineTo(8, -12);
        ctx.stroke();
        // Head lolling to the side
        ctx.fillStyle = col;
        ctx.beginPath(); ctx.arc(-15, 1, 6, 0, Math.PI * 2); ctx.fill();
        // X-ed-out eyes
        ctx.strokeStyle = "#222"; ctx.lineWidth = 1.3;
        ctx.beginPath();
        ctx.moveTo(-18, -2); ctx.lineTo(-15, 1);
        ctx.moveTo(-15, -2); ctx.lineTo(-18, 1);
        ctx.stroke();
        // Tongue
        ctx.fillStyle = "#E53935";
        ctx.beginPath(); ctx.ellipse(-20, 3.5, 2, 3, 0.4, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
    }

    // ── Drawing: Missile ─────────────────────────────────────
    function drawMissile(x, y, time) {
        ctx.save();
        ctx.translate(x, y);
        // exhaust trail
        var flicker = 1 + Math.sin(time * 30) * 0.3;
        ctx.fillStyle = "rgba(255,200,0,0.6)";
        ctx.beginPath();
        ctx.ellipse(0, 18, 6, 12 * flicker, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "rgba(255,87,34,0.8)";
        ctx.beginPath();
        ctx.ellipse(0, 14, 4, 8 * flicker, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "rgba(255,255,255,0.8)";
        ctx.beginPath();
        ctx.ellipse(0, 12, 2, 5 * flicker, 0, 0, Math.PI * 2); ctx.fill();

        // missile body
        ctx.fillStyle = "#37474F";
        roundRect(-5, -12, 10, 24, 3); ctx.fill();
        ctx.fillStyle = "#B0BEC5";
        roundRect(-4, -11, 8, 22, 2); ctx.fill();
        // nose cone
        ctx.fillStyle = "#F44336";
        ctx.beginPath();
        ctx.moveTo(-5, -10);
        ctx.lineTo(0, -18);
        ctx.lineTo(5, -10);
        ctx.closePath(); ctx.fill();
        // fins
        ctx.fillStyle = "#37474F";
        ctx.beginPath();
        ctx.moveTo(-5, 8); ctx.lineTo(-9, 12); ctx.lineTo(-5, 12);
        ctx.closePath(); ctx.fill();
        ctx.beginPath();
        ctx.moveTo(5, 8); ctx.lineTo(9, 12); ctx.lineTo(5, 12);
        ctx.closePath(); ctx.fill();

        ctx.restore();

        // smoke trail particles
        if (Math.random() > 0.5) {
            particles.push({
                x: x + rand(-4, 4), y: y + 18,
                vx: rand(-10, 10), vy: rand(40, 80),
                life: 0.4, maxLife: 0.4,
                size: rand(3, 6),
                color: randPick(["#FFA000", "#FF5722", "#9E9E9E"]),
                gravity: 0
            });
        }
    }

    // ── Drawing: Angry Man + Speech Bubble ───────────────────
    function drawAngryMan(x, y, time, state, runDir, cop, mood, hair, type) {
        ctx.save();
        ctx.translate(x, y);
        // The driver who climbs out isn't always a grumpy grandpa: `mood` is
        // "angry" (default), "scared", or "sad", and `hair` varies the person
        // ("grandpa" = the classic wild white; otherwise a combed cap of that
        // color). Cops are always by-the-book angry.
        mood = mood || "angry";
        if (cop) { mood = "angry"; hair = null; }
        var grandpa = !hair || hair === "grandpa";
        var hairCol = grandpa ? "#FAFAFA" : hair;

        // A cop variant (when the wreck was a police cruiser): navy uniform,
        // peaked cap + badge instead of grandpa plaid + wild white hair.
        var shirtDark = cop ? "#0D1B5E" : (type && type.shirtDark) || "#8B0000";
        var shirtMain = cop ? "#1A237E" : (type && type.shirt) || "#B71C1C";

        // Shadow
        ctx.fillStyle = "rgba(0,0,0,0.25)";
        ctx.beginPath(); ctx.ellipse(0, 22, 14, 4, 0, 0, Math.PI * 2); ctx.fill();

        var legSwing = state === "running" ? Math.sin(time * 18) * 6 : Math.sin(time * 4) * 1;
        var armRaise = state === "yelling" ? Math.sin(time * 12) * 10 : 0;

        // Legs (brown pants — navy for the cop)
        ctx.fillStyle = cop ? "#1A237E" : "#3E2723";
        roundRect(-6, 8 - legSwing, 5, 16 + legSwing, 2); ctx.fill();
        roundRect(1, 8 + legSwing, 5, 16 - legSwing, 2); ctx.fill();
        // Shoes
        ctx.fillStyle = "#212121";
        roundRect(-7, 22 - legSwing, 7, 4, 2); ctx.fill();
        roundRect(0, 22 + legSwing, 7, 4, 2); ctx.fill();

        // Body (plaid red shirt for grumpy-grandpa vibe / navy police shirt)
        ctx.fillStyle = shirtDark;
        roundRect(-11, -8, 22, 18, 5); ctx.fill();
        ctx.fillStyle = shirtMain;
        roundRect(-10, -7, 20, 16, 4); ctx.fill();
        if (cop) {
            // Police shirt details: button placket, badge, tie.
            ctx.strokeStyle = "rgba(0,0,0,0.35)"; ctx.lineWidth = 1;
            ctx.beginPath(); ctx.moveTo(0, -7); ctx.lineTo(0, 9); ctx.stroke();
            // gold badge (left chest)
            ctx.fillStyle = "#FFD54F";
            ctx.beginPath();
            for (var bs = 0; bs < 5; bs++) {
                var ba = -Math.PI / 2 + bs * (Math.PI * 2 / 5);
                ctx.lineTo(-6 + Math.cos(ba) * 3, -2 + Math.sin(ba) * 3);
                ctx.lineTo(-6 + Math.cos(ba + Math.PI / 5) * 1.4, -2 + Math.sin(ba + Math.PI / 5) * 1.4);
            }
            ctx.closePath(); ctx.fill();
            // collar tabs
            ctx.fillStyle = shirtDark;
            ctx.beginPath(); ctx.moveTo(-3, -7); ctx.lineTo(0, -4); ctx.lineTo(-1, -7); ctx.fill();
            ctx.beginPath(); ctx.moveTo(3, -7); ctx.lineTo(0, -4); ctx.lineTo(1, -7); ctx.fill();
        } else if (!type || type.hair === "grandpa") {
            // shirt lines (plaid) — the classic grumpy-grandpa flannel
            ctx.strokeStyle = "rgba(0,0,0,0.3)";
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(-4, -7); ctx.lineTo(-4, 9);
            ctx.moveTo(4, -7); ctx.lineTo(4, 9);
            ctx.moveTo(-10, -2); ctx.lineTo(10, -2);
            ctx.moveTo(-10, 4); ctx.lineTo(10, 4);
            ctx.stroke();
        } else {
            // collared shirt with a button placket; a tie for the suit types
            ctx.fillStyle = "rgba(255,255,255,0.85)"; roundRect(-3, -7, 6, 5, 1); ctx.fill();   // open collar
            if (type.tie) { ctx.fillStyle = type.tie; ctx.beginPath(); ctx.moveTo(-1.6, -5); ctx.lineTo(1.6, -5); ctx.lineTo(1, 8); ctx.lineTo(-1, 8); ctx.closePath(); ctx.fill(); }
            else { ctx.strokeStyle = "rgba(0,0,0,0.22)"; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(0, -6); ctx.lineTo(0, 9); ctx.stroke(); }
        }

        // Arms (one raised when yelling)
        ctx.fillStyle = shirtMain;
        if (state === "yelling") {
            // both arms up (shaking fist)
            ctx.save();
            ctx.translate(-10, -5);
            ctx.rotate(-0.8 + armRaise * 0.03);
            roundRect(-3, -12, 6, 14, 2); ctx.fill();
            // fist
            ctx.fillStyle = C.skin;
            ctx.beginPath(); ctx.arc(0, -13, 3, 0, Math.PI * 2); ctx.fill();
            ctx.restore();
            ctx.fillStyle = shirtMain;
            ctx.save();
            ctx.translate(10, -5);
            ctx.rotate(0.8 - armRaise * 0.03);
            roundRect(-3, -12, 6, 14, 2); ctx.fill();
            ctx.fillStyle = C.skin;
            ctx.beginPath(); ctx.arc(0, -13, 3, 0, Math.PI * 2); ctx.fill();
            ctx.restore();
        } else if (state === "running") {
            var armSwing = -legSwing;
            ctx.fillStyle = shirtMain;
            roundRect(-13, -5 - armSwing * 0.3, 5, 14, 2); ctx.fill();
            roundRect(8, -5 + armSwing * 0.3, 5, 14, 2); ctx.fill();
            ctx.fillStyle = C.skin;
            ctx.beginPath(); ctx.arc(-10, 9 - armSwing * 0.3, 2.5, 0, Math.PI * 2); ctx.fill();
            ctx.beginPath(); ctx.arc(11, 9 + armSwing * 0.3, 2.5, 0, Math.PI * 2); ctx.fill();
        } else if (state === "talk" || state === "listen") {
            // calm chatting pose — arms at rest with a small gesture bob
            var gb = (state === "talk" ? Math.sin(time * 5) * 2 : 0);
            ctx.fillStyle = shirtMain;
            roundRect(-13, -5, 5, 13, 2); ctx.fill();
            roundRect(8, -5 + gb * 0.4, 5, 13, 2); ctx.fill();
            ctx.fillStyle = C.skin;
            ctx.beginPath(); ctx.arc(-10, 8, 2.5, 0, Math.PI * 2); ctx.fill();
            ctx.beginPath(); ctx.arc(11, 8 + gb * 0.4, 2.5, 0, Math.PI * 2); ctx.fill();
        }

        // Head — flushed red when angry, pale when scared, wan when sad.
        ctx.fillStyle = "#222";
        ctx.beginPath(); ctx.arc(0, -16, 9, 0, Math.PI * 2); ctx.fill();
        var faceCol = mood === "scared" ? "#FFE3D2" : mood === "sad" ? "#EDB29A"
                    : (state === "yelling" ? "#FF7043" : "#FFAB91");
        ctx.fillStyle = faceCol;
        ctx.beginPath(); ctx.arc(0, -16, 8, 0, Math.PI * 2); ctx.fill();

        if (cop) {
            // Short dark hair under the cap
            ctx.fillStyle = "#3E2723";
            ctx.beginPath(); ctx.arc(0, -18, 8, Math.PI, 0); ctx.fill();
            // Peaked police cap: band, crown, glossy black peak, gold emblem.
            ctx.fillStyle = "#0D1B5E";
            ctx.beginPath(); ctx.ellipse(0, -22, 9, 3.2, 0, 0, Math.PI * 2); ctx.fill(); // band
            ctx.fillStyle = "#1A237E";
            ctx.beginPath(); ctx.ellipse(0, -25, 8.5, 4.5, 0, Math.PI, 0); ctx.fill();   // crown
            ctx.fillStyle = "#0A0A0A";
            ctx.beginPath(); ctx.ellipse(0, -20.5, 9.5, 2.2, 0, 0, Math.PI); ctx.fill(); // peak/brim
            // gold cap emblem
            ctx.fillStyle = "#FFD54F";
            ctx.beginPath(); ctx.arc(0, -24, 1.8, 0, Math.PI * 2); ctx.fill();
        } else if (grandpa) {
        // White hair (wild messy clumps with darker base for depth)
        ctx.fillStyle = "#9E9E9E";
        ctx.beginPath();
        ctx.arc(-7, -20, 6, 0, Math.PI * 2);
        ctx.arc(0, -23, 7, 0, Math.PI * 2);
        ctx.arc(7, -20, 6, 0, Math.PI * 2);
        ctx.arc(-10, -17, 5, 0, Math.PI * 2);
        ctx.arc(10, -17, 5, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#FAFAFA";
        ctx.beginPath();
        ctx.arc(-6, -21, 5, 0, Math.PI * 2);
        ctx.arc(1, -24, 5.8, 0, Math.PI * 2);
        ctx.arc(7, -21, 5, 0, Math.PI * 2);
        ctx.arc(-9, -18, 4, 0, Math.PI * 2);
        ctx.arc(9, -18, 4, 0, Math.PI * 2);
        ctx.fill();
        // Sticky-up tufts (Sasquatch-grandpa cue)
        ctx.beginPath();
        ctx.ellipse(-4, -26, 1.5, 3, -0.3, 0, Math.PI * 2);
        ctx.ellipse(4, -26, 1.5, 3, 0.3, 0, Math.PI * 2);
        ctx.fill();
        } else {
        // A combed cap of hair in the driver's colour (a younger, varied person)
        ctx.fillStyle = hairCol;
        ctx.beginPath(); ctx.arc(0, -19, 8.6, Math.PI, 0); ctx.fill();
        ctx.beginPath();
        ctx.ellipse(-7, -15, 2.6, 6, -0.3, 0, Math.PI * 2);
        ctx.ellipse(7, -15, 2.6, 6, 0.3, 0, Math.PI * 2);
        ctx.fill();
        }
        // ── type headwear (over the hair) ──
        if (!cop && type) {
            if (type.cap) {                                  // baseball cap, brim forward
                ctx.fillStyle = type.cap; ctx.beginPath(); ctx.ellipse(0, -21, 8.4, 5, 0, Math.PI, 0); ctx.fill();
                ctx.fillRect(-8.4, -21, 16.8, 2.5);
                ctx.fillStyle = shadeColor(type.cap, -18); roundRect(runDir >= 0 ? 4 : -16, -21.5, 12, 3.5, 2); ctx.fill();
                ctx.fillStyle = "rgba(255,255,255,0.5)"; ctx.beginPath(); ctx.arc(0, -22, 1.4, 0, Math.PI * 2); ctx.fill();
            } else if (type.beanie) {                        // knit beanie with a fold
                ctx.fillStyle = type.beanie; ctx.beginPath(); ctx.arc(0, -18, 8.8, Math.PI, 0); ctx.fill();
                ctx.fillStyle = shadeColor(type.beanie, 18); ctx.fillRect(-8.8, -19.5, 17.6, 3.5);
                ctx.fillStyle = shadeColor(type.beanie, -12); ctx.beginPath(); ctx.arc(0, -26, 2, 0, Math.PI * 2); ctx.fill();
            } else if (type.sunhat) {                        // wide straw sun hat
                ctx.fillStyle = "#FFE082"; ctx.beginPath(); ctx.ellipse(0, -19, 13, 4.2, 0, 0, Math.PI * 2); ctx.fill();
                ctx.fillStyle = "#FFD54F"; ctx.beginPath(); ctx.ellipse(0, -22, 7, 4.5, 0, Math.PI, 0); ctx.fill();
                ctx.strokeStyle = "#26A69A"; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(-7, -20); ctx.lineTo(7, -20); ctx.stroke();
            }
        }
        // ── Brows / eyes / mouth all read the mood ──
        var browCol = cop ? "#3E2723" : (grandpa ? "#FAFAFA" : hairCol);
        ctx.fillStyle = browCol;
        if (mood === "scared") {                       // high, flat, worried
            roundRect(-6, -22, 5, 2, 1); ctx.fill();
            roundRect(1, -22, 5, 2, 1); ctx.fill();
        } else if (mood === "sad") {                   // inner-up "frown" brows
            ctx.save(); ctx.translate(-3, -19); ctx.rotate(-0.4); roundRect(-3, 0, 6, 2, 1); ctx.fill(); ctx.restore();
            ctx.save(); ctx.translate(3, -19); ctx.rotate(0.4); roundRect(-3, 0, 6, 2, 1); ctx.fill(); ctx.restore();
        } else {                                       // angry V
            ctx.save(); ctx.translate(-3, -18); ctx.rotate(0.4); roundRect(-3, 0, 6, 2, 1); ctx.fill(); ctx.restore();
            ctx.save(); ctx.translate(3, -18); ctx.rotate(-0.4); roundRect(-3, 0, 6, 2, 1); ctx.fill(); ctx.restore();
        }

        if (state === "faint") {                       // X_X knocked out cold
            ctx.strokeStyle = "#000"; ctx.lineWidth = 1.4;
            ctx.beginPath();
            ctx.moveTo(-4.6, -16.6); ctx.lineTo(-1.4, -13.4); ctx.moveTo(-1.4, -16.6); ctx.lineTo(-4.6, -13.4);
            ctx.moveTo(1.4, -16.6); ctx.lineTo(4.6, -13.4); ctx.moveTo(4.6, -16.6); ctx.lineTo(1.4, -13.4);
            ctx.stroke();
        } else if (mood === "scared") {                // wide frightened eyes + sweat
            ctx.fillStyle = "#FFF"; ctx.beginPath(); ctx.arc(-3, -15.5, 2.2, 0, Math.PI * 2); ctx.arc(3, -15.5, 2.2, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#000"; ctx.beginPath(); ctx.arc(-3, -15, 1.1, 0, Math.PI * 2); ctx.arc(3, -15, 1.1, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "rgba(130,200,240,0.9)"; ctx.beginPath(); ctx.arc(6.5, -14 + Math.abs(Math.sin(time * 6)) * 2, 1.3, 0, Math.PI * 2); ctx.fill();
        } else if (mood === "sad") {                   // droopy eyes + a welling tear
            ctx.strokeStyle = "#000"; ctx.lineWidth = 1.3;
            ctx.beginPath(); ctx.arc(-3, -14, 1.8, 1.05 * Math.PI, 1.95 * Math.PI); ctx.arc(3, -14, 1.8, 1.05 * Math.PI, 1.95 * Math.PI); ctx.stroke();
            ctx.fillStyle = "#000"; ctx.beginPath(); ctx.arc(-3, -15, 0.9, 0, Math.PI * 2); ctx.arc(3, -15, 0.9, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "rgba(120,190,235,0.95)"; ctx.beginPath(); ctx.arc(-4, -11 + ((time * 10) % 5), 1.3, 0, Math.PI * 2); ctx.fill();
        } else {                                       // angry slits + dot pupils
            ctx.strokeStyle = "#000"; ctx.lineWidth = 1.5;
            ctx.beginPath(); ctx.moveTo(-5, -16); ctx.lineTo(-2, -15); ctx.moveTo(2, -15); ctx.lineTo(5, -16); ctx.stroke();
            ctx.fillStyle = "#000"; ctx.beginPath(); ctx.arc(-3, -15, 0.9, 0, Math.PI * 2); ctx.arc(3, -15, 0.9, 0, Math.PI * 2); ctx.fill();
        }

        // Big mustache — only on the classic grandpa or the cop
        if (grandpa || cop) {
            ctx.fillStyle = cop ? "#3E2723" : "#FAFAFA";
            ctx.beginPath();
            ctx.ellipse(-3, -12, 4, 1.8, 0.2, 0, Math.PI * 2);
            ctx.ellipse(3, -12, 4, 1.8, -0.2, 0, Math.PI * 2);
            ctx.fill();
        }

        // Mouth by mood
        if (state === "faint") {                        // slack, knocked-out mouth
            ctx.fillStyle = "#3A1A1A"; ctx.beginPath(); ctx.ellipse(0, -9, 1.6, 2, 0, 0, Math.PI * 2); ctx.fill();
        } else if (mood === "scared") {                // trembling little "o"
            ctx.fillStyle = "#3A1A1A"; ctx.beginPath();
            ctx.ellipse(Math.sin(time * 30) * 0.6, -9, 1.8, 2.2, 0, 0, Math.PI * 2); ctx.fill();
        } else if (mood === "sad") {                   // wobbly frown / open sob
            if (state === "yelling" || state === "talk") {
                ctx.fillStyle = "#3A1A1A"; ctx.beginPath();
                ctx.ellipse(0, -8, 2.4, 1.6 + Math.abs(Math.sin(time * 10)) * 1.2, 0, 0, Math.PI * 2); ctx.fill();
            } else {
                ctx.strokeStyle = "#000"; ctx.lineWidth = 1.3; ctx.beginPath();
                ctx.arc(0, -5, 3.4, 1.15 * Math.PI, 1.85 * Math.PI); ctx.stroke();
            }
        } else if (state === "yelling" || state === "talk") {
            var talk = state === "talk";
            ctx.fillStyle = "#000"; ctx.beginPath();
            var mouthW = (talk ? 2 : 3) + Math.abs(Math.sin(time * (talk ? 14 : 25))) * (talk ? 1.4 : 1.2);
            ctx.ellipse(0, -9, mouthW, talk ? 1.8 : 2.5, 0, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#F44336"; ctx.beginPath(); ctx.ellipse(0, -8.5, mouthW * 0.6, 1, 0, 0, Math.PI * 2); ctx.fill();
        } else {
            ctx.strokeStyle = "#000"; ctx.lineWidth = 1.2; ctx.beginPath();
            ctx.arc(0, -8, 3, 1.2 * Math.PI, 1.8 * Math.PI); ctx.stroke();
        }

        ctx.restore();
    }

    function drawSpeechBubble(x, y, text, time) {
        ctx.save();
        var lines = text.split("\n");
        var fontSize = 14;
        ctx.font = "bold " + fontSize + "px 'Segoe UI', Arial, sans-serif";
        var maxW = 0;
        for (var li = 0; li < lines.length; li++) {
            var w = ctx.measureText(lines[li]).width;
            if (w > maxW) maxW = w;
        }
        var bw = maxW + 24, bh = lines.length * (fontSize + 4) + 16;
        var bx = x - bw / 2, by = y - bh - 14;
        // wobble for energy
        var wob = Math.sin(time * 20) * 1.5;
        bx += wob;

        // bubble bg
        ctx.fillStyle = "#FFFFFF";
        ctx.strokeStyle = "#000";
        ctx.lineWidth = 3;
        roundRect(bx, by, bw, bh, 10);
        ctx.fill(); ctx.stroke();

        // pointer
        ctx.beginPath();
        ctx.moveTo(x - 6, by + bh);
        ctx.lineTo(x + 4, by + bh + 10);
        ctx.lineTo(x + 6, by + bh);
        ctx.closePath();
        ctx.fillStyle = "#FFFFFF";
        ctx.fill();
        ctx.stroke();

        // text
        ctx.fillStyle = "#D32F2F";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        for (var i = 0; i < lines.length; i++) {
            ctx.fillText(lines[i], bx + bw / 2, by + 12 + i * (fontSize + 4) + fontSize / 2);
        }
        ctx.restore();
    }

    // ── Drawing: Parking sign + ice cream + billboards ────────
    function drawParkingSign(x, y, bob) {
        ctx.save();
        ctx.translate(x, y + Math.sin(bob * 3) * 3);
        // Glow halo
        ctx.fillStyle = "rgba(33,150,243,0.25)";
        ctx.beginPath(); ctx.arc(0, 0, 22, 0, Math.PI * 2); ctx.fill();
        // Pole
        ctx.fillStyle = "#90A4AE";
        ctx.fillRect(-1.5, 14, 3, 8);
        // Sign body
        ctx.fillStyle = "#0D47A1";
        roundRect(-14, -14, 28, 28, 4); ctx.fill();
        ctx.fillStyle = "#1976D2";
        roundRect(-12, -12, 24, 24, 3); ctx.fill();
        // White P
        ctx.fillStyle = "#FFF";
        ctx.font = "bold 22px 'Segoe UI', Arial, sans-serif";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText("P", 0, 1);
        // shimmer
        if (Math.sin(bob * 4) > 0) {
            ctx.fillStyle = "rgba(255,255,255,0.4)";
            roundRect(-10, -10, 8, 4, 2); ctx.fill();
        }
        ctx.restore();
    }

    function drawIceCreamSign(x, y, bob) {
        ctx.save();
        ctx.translate(x, y + Math.sin(bob * 3) * 3);
        // Pole
        ctx.fillStyle = "#5D4037";
        ctx.fillRect(-1.5, 10, 3, 14);
        // Cone (upside-down triangle)
        ctx.fillStyle = "#FFB74D";
        ctx.beginPath();
        ctx.moveTo(-10, -2);
        ctx.lineTo(10, -2);
        ctx.lineTo(0, 14);
        ctx.closePath();
        ctx.fill();
        // Waffle lines
        ctx.strokeStyle = "#E65100";
        ctx.lineWidth = 1;
        for (var i = 0; i < 3; i++) {
            ctx.beginPath();
            ctx.moveTo(-8 + i * 4, 2);
            ctx.lineTo(8 - i * 4, 2);
            ctx.stroke();
        }
        // Pink scoop
        ctx.fillStyle = "#F48FB1";
        ctx.beginPath(); ctx.arc(0, -6, 8, 0, Math.PI * 2); ctx.fill();
        // White scoop on top
        ctx.fillStyle = "#FFFFFF";
        ctx.beginPath(); ctx.arc(-3, -12, 5, 0, Math.PI * 2); ctx.fill();
        // Cherry
        ctx.fillStyle = "#D32F2F";
        ctx.beginPath(); ctx.arc(-3, -16, 2.5, 0, Math.PI * 2); ctx.fill();
        // Stem
        ctx.strokeStyle = "#388E3C";
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(-3, -18); ctx.lineTo(-1, -20);
        ctx.stroke();
        ctx.restore();
    }

    // ── Procedural wanted-poster mugshot: it's ALWAYS LULU IN A DISGUISE ──
    // In-universe every "player" is Lulu, so every fugitive on the wanted board
    // is the SAME pink-car woman working through a stack of cheap aliases. So
    // drawMugshot renders ONE fixed canonical Lulu face (fair peachy skin, rosy
    // blush, big brown sparkly eyes, a can't-help-it little smile) and then
    // layers 1–3 name-derived DISGUISE props on top: obviously-fake wigs in
    // wrong colours (blue beehive / green bob / giant afro / askew blonde
    // sheitel / pigtails), dollar-store / groucho / monocle / novelty eyewear, a
    // peeling stick-on 'stache or drawn-on beauty mark, and headwear (cap pulled
    // low, babushka, inexplicable party hat, floppy sun hat). Everything stays a
    // deterministic function of the name string (mugHash + salted mugPick) so
    // the SAME alias always wears the SAME disguise forever. The tell that it's
    // her every single time: identical face, blush, eyes and that unrepentant
    // smile. It must NOT read the local player's salon choices
    // (save.luluHair / save.luluHairStyle) — those aliases are OTHER players, so
    // only Lulu's stock look is used. Flat cartoon look (drawLuluPortrait in
    // src/06 is the quality bar). ES5, single shared scope.
    var LULU_MUG_SKIN = "#FFD9C0";                                        // her canonical peachy skin
    var LULU_MUG_HAIR = "#3E2723";                                        // her canonical dark-brown hair
    // Wig colours by index: 0 natural dark · 1 blue beehive · 2 green bob ·
    // 3 orange afro · 4 cheap blonde sheitel · 5 magenta pigtails.
    var MUG_WIGC = ["#3E2723", "#2E7DF6", "#3FB65B", "#FB8C00", "#E7CB63", "#C24DBE"];
    function mugHash(str) {
        var h = 2166136261;
        str = "" + (str || "LULU");
        for (var i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = (h * 16777619) >>> 0; }
        return h >>> 0;
    }
    // Each feature draws from an INDEPENDENT, well-mixed slice of the hash (a
    // salted xorshift) so choices don't correlate — plain `h % n` on FNV low
    // bits clusters badly, and signed `>>` can go negative. Always 0..n-1.
    function mugPick(h, salt, n) {
        var x = (h ^ Math.imul(salt, 0x9E3779B1)) >>> 0;
        x ^= x >>> 15; x = Math.imul(x, 0x85EBCA77) >>> 0; x ^= x >>> 13;
        return (x >>> 0) % n;
    }
    function drawMugshot(name, cx, cy, s) {
        var h = mugHash(name);
        var wig  = mugPick(h, 2, 6);   // 0 natural · 1 beehive · 2 green bob · 3 afro · 4 blonde sheitel askew · 5 pigtails
        var eyew = mugPick(h, 4, 5);   // 0 none · 1 shades · 2 groucho · 3 monocle · 4 novelty specs
        var face = mugPick(h, 6, 4);   // 0 none · 1 peeling 'stache · 2 beauty mark · 3 goatee
        var head = mugPick(h, 8, 5);   // 0 none · 1 cap low · 2 babushka · 3 party hat · 4 sun hat
        var expr = mugPick(h, 5, 4);   // 0 unbothered · 1 wink · 2 mid-laugh · 3 deadpan
        // Groucho brings its own moustache — don't stack a stick-on under it.
        if (eyew === 2 && face === 1) face = 0;
        // Every alias wears at LEAST one prop (else it's just bare-faced Lulu).
        if (wig === 0 && eyew === 0 && face === 0 && head === 0) eyew = 1;
        var hairC = MUG_WIGC[wig];
        var eyeY = -3.5, eyeX = 4.6, my = 5;
        // Lulu's unmistakable eye — big white, warm-brown iris, tiny sparkle.
        function mugEye(ex) {
            ctx.fillStyle = "#FFFFFF"; ctx.beginPath(); ctx.ellipse(ex, eyeY, 2.9, 3.2, 0, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#7A4A2B"; ctx.beginPath(); ctx.arc(ex, eyeY + 0.2, 2, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#241208"; ctx.beginPath(); ctx.arc(ex, eyeY + 0.2, 1, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#FFFFFF"; ctx.beginPath(); ctx.arc(ex - 0.8, eyeY - 0.8, 0.7, 0, Math.PI * 2); ctx.fill();
        }
        function mugArcEye(ex, cyy, a0, a1) {   // a happy closed curve (wink / laugh)
            ctx.strokeStyle = "#5D4037"; ctx.lineWidth = 1.3;
            ctx.beginPath(); ctx.arc(ex, cyy, 2.6, a0, a1); ctx.stroke();
        }

        ctx.save();
        ctx.translate(cx, cy);
        ctx.scale(s / 48, s / 48);
        ctx.lineJoin = "round"; ctx.lineCap = "round";

        // clip everything to a rounded booking card
        roundRect(-24, -24, 48, 48, 4);
        ctx.save();
        ctx.clip();

        // height-chart background
        ctx.fillStyle = "#AEB9C2";
        ctx.fillRect(-24, -24, 48, 48);
        ctx.strokeStyle = "rgba(58,70,82,0.32)"; ctx.lineWidth = 0.8;
        for (var gy = -18; gy <= 22; gy += 8) {
            ctx.beginPath(); ctx.moveTo(-24, gy); ctx.lineTo(24, gy); ctx.stroke();
        }
        ctx.strokeStyle = "rgba(58,70,82,0.5)";
        for (var ty = -20; ty <= 22; ty += 4) {
            ctx.beginPath(); ctx.moveTo(-24, ty); ctx.lineTo(-21, ty); ctx.stroke();
        }

        // shoulders — orange booking jumpsuit
        ctx.fillStyle = "#E67E22";
        roundRect(-17, 13, 34, 18, 7); ctx.fill();
        ctx.fillStyle = shadeColor("#E67E22", -26);        // collar V
        ctx.beginPath(); ctx.moveTo(-6, 13); ctx.lineTo(0, 19); ctx.lineTo(6, 13); ctx.closePath(); ctx.fill();

        // neck
        ctx.fillStyle = shadeColor(LULU_MUG_SKIN, -14);
        roundRect(-5, 6, 10, 9, 3); ctx.fill();

        // ── BACK WIG VOLUME (behind the head) — obvious fake, wrong colour ──
        if (wig === 3) {                                     // giant orange afro cloud
            ctx.fillStyle = hairC;
            var af = [[-11, -6, 8], [11, -6, 8], [-9, -15, 8], [9, -15, 8], [0, -18, 9], [-14, -2, 6], [14, -2, 6], [0, -4, 11]];
            for (var ai = 0; ai < af.length; ai++) { ctx.beginPath(); ctx.arc(af[ai][0], af[ai][1], af[ai][2], 0, Math.PI * 2); ctx.fill(); }
        } else if (wig === 2) {                              // green bob body
            ctx.fillStyle = hairC;
            ctx.beginPath(); ctx.ellipse(0, -1, 15, 14, 0, 0, Math.PI * 2); ctx.fill();
        } else if (wig === 5) {                              // pigtail puffs
            ctx.fillStyle = hairC;
            ctx.beginPath(); ctx.arc(-13, 2, 6, 0, Math.PI * 2); ctx.arc(13, 2, 6, 0, Math.PI * 2); ctx.fill();
        }

        // head + ears — THE fixed canonical Lulu face (identical every poster)
        ctx.fillStyle = LULU_MUG_SKIN;
        ctx.beginPath(); ctx.arc(-11.5, -2, 2.4, 0, Math.PI * 2); ctx.arc(11.5, -2, 2.4, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.ellipse(0, -3, 12, 13.5, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "rgba(244,170,140,0.26)";           // soft warm face-edge shade
        ctx.beginPath(); ctx.ellipse(6.5, 0, 5, 9.5, 0, 0, Math.PI * 2); ctx.fill();

        // ── FRONT WIG / HAIR framing the face ──
        if (wig === 0) {                                     // natural dark centre-part swoop
            ctx.fillStyle = hairC;
            ctx.beginPath();
            ctx.moveTo(-12, -3);
            ctx.quadraticCurveTo(-14, -17, 0, -16.5);
            ctx.quadraticCurveTo(14, -17, 12, -3);
            ctx.quadraticCurveTo(9, -10, 4, -11);
            ctx.quadraticCurveTo(0, -13, -4, -11);
            ctx.quadraticCurveTo(-9, -10, -12, -3);
            ctx.closePath(); ctx.fill();
            ctx.fillStyle = shadeColor(hairC, 30);           // glossy part shine
            ctx.beginPath(); ctx.ellipse(-5, -12, 3, 1.4, -0.4, 0, Math.PI * 2); ctx.fill();
        } else if (wig === 1) {                              // blue beehive tower
            ctx.fillStyle = hairC;
            ctx.beginPath();
            ctx.moveTo(-12, -4);
            ctx.quadraticCurveTo(-16, -22, 0, -25);
            ctx.quadraticCurveTo(16, -22, 12, -4);
            ctx.quadraticCurveTo(8, -11, 0, -11);
            ctx.quadraticCurveTo(-8, -11, -12, -4);
            ctx.closePath(); ctx.fill();
            ctx.strokeStyle = shadeColor(hairC, 36); ctx.lineWidth = 1;   // swirl lines
            ctx.beginPath();
            ctx.moveTo(-8, -8); ctx.quadraticCurveTo(0, -12, 8, -8);
            ctx.moveTo(-7, -15); ctx.quadraticCurveTo(0, -19, 7, -15);
            ctx.stroke();
        } else if (wig === 2) {                              // green bob — curtains + blunt fringe
            ctx.fillStyle = hairC;
            roundRect(-15, -13, 5, 21, 3); ctx.fill();
            roundRect(10, -13, 5, 21, 3); ctx.fill();
            ctx.beginPath();
            ctx.moveTo(-14, -7);
            ctx.quadraticCurveTo(-15, -17, 0, -17);
            ctx.quadraticCurveTo(15, -17, 14, -7);
            ctx.quadraticCurveTo(7, -9, 0, -8.5);
            ctx.quadraticCurveTo(-7, -9, -14, -7);
            ctx.closePath(); ctx.fill();
        } else if (wig === 3) {                              // afro — fuzzy front hairline
            ctx.fillStyle = hairC;
            ctx.beginPath(); ctx.ellipse(0, -11, 12, 6, 0, Math.PI, Math.PI * 2); ctx.fill();
            var afb = [[-9, -13, 3], [-3, -15, 3.4], [3, -15, 3.4], [9, -13, 3]];
            for (var afi = 0; afi < afb.length; afi++) { ctx.beginPath(); ctx.arc(afb[afi][0], afb[afi][1], afb[afi][2], 0, Math.PI * 2); ctx.fill(); }
        } else if (wig === 4) {                              // cheap blonde sheitel, sitting ASKEW
            ctx.save();
            ctx.translate(0.6, -1); ctx.rotate(0.13);        // crooked — that's the tell
            ctx.fillStyle = hairC;
            ctx.beginPath();
            ctx.moveTo(-13, -2);
            ctx.quadraticCurveTo(-15, -18, 0, -18);
            ctx.quadraticCurveTo(15, -18, 13, -2);
            ctx.lineTo(12, 8);
            ctx.quadraticCurveTo(9, 5, 8, -2);
            ctx.quadraticCurveTo(6, -8, 0, -8);
            ctx.quadraticCurveTo(-6, -8, -8, -2);
            ctx.quadraticCurveTo(-9, 5, -12, 8);
            ctx.closePath(); ctx.fill();
            ctx.fillStyle = shadeColor(hairC, 26);           // brassy highlight
            ctx.beginPath(); ctx.ellipse(-5, -12, 4, 1.6, -0.4, 0, Math.PI * 2); ctx.fill();
            ctx.restore();
            ctx.fillStyle = LULU_MUG_HAIR;                   // sliver of her REAL hair peeking out
            ctx.beginPath(); ctx.ellipse(-10, 5, 2.6, 2, 0.3, 0, Math.PI * 2); ctx.fill();
        } else {                                             // wig 5 — pigtails: top hair, centre part, ties
            ctx.fillStyle = hairC;
            ctx.beginPath(); ctx.ellipse(0, -8, 12, 8, 0, Math.PI, Math.PI * 2); ctx.fill();
            ctx.strokeStyle = shadeColor(hairC, -24); ctx.lineWidth = 0.8;
            ctx.beginPath(); ctx.moveTo(0, -15); ctx.lineTo(0, -9); ctx.stroke();
            ctx.fillStyle = "#FF4081";                       // hair ties
            ctx.beginPath(); ctx.arc(-13, -2, 1.8, 0, Math.PI * 2); ctx.arc(13, -2, 1.8, 0, Math.PI * 2); ctx.fill();
        }

        // ── Rosy blush — Lulu's signature, on EVERY alias ──
        ctx.fillStyle = "rgba(255,150,170,0.55)";
        ctx.beginPath();
        ctx.ellipse(-7, 2.2, 3.2, 2.2, 0, 0, Math.PI * 2);
        ctx.ellipse(7, 2.2, 3.2, 2.2, 0, 0, Math.PI * 2);
        ctx.fill();

        // ── Eyebrows (her own warm brown; shaped by expression) ──
        ctx.strokeStyle = "#6B4A32"; ctx.lineWidth = 1.3;
        ctx.beginPath();
        if (expr === 3) {                                    // deadpan — flat
            ctx.moveTo(-eyeX - 2.4, eyeY - 5.4); ctx.lineTo(-eyeX + 2.2, eyeY - 5.4);
            ctx.moveTo(eyeX - 2.2, eyeY - 5.4); ctx.lineTo(eyeX + 2.4, eyeY - 5.4);
        } else {                                             // gentle arches
            ctx.moveTo(-eyeX - 2.4, eyeY - 4.8); ctx.quadraticCurveTo(-eyeX, eyeY - 6.4, -eyeX + 2.2, eyeY - 5);
            ctx.moveTo(eyeX - 2.2, eyeY - 5); ctx.quadraticCurveTo(eyeX, eyeY - 6.4, eyeX + 2.4, eyeY - 4.8);
        }
        ctx.stroke();

        // ── Eyes (big & bright — always hers; expression varies) ──
        if (expr === 1) {                                    // wink at the camera
            mugEye(-eyeX); mugArcEye(eyeX, eyeY - 1, 0.15 * Math.PI, 0.85 * Math.PI);
        } else if (expr === 2) {                             // mid-laugh — scrunched ^^
            mugArcEye(-eyeX, eyeY + 1.6, 1.15 * Math.PI, 1.85 * Math.PI);
            mugArcEye(eyeX, eyeY + 1.6, 1.15 * Math.PI, 1.85 * Math.PI);
        } else {                                             // 0 unbothered / 3 deadpan — both open
            mugEye(-eyeX); mugEye(eyeX);
            if (expr === 3) {                                // heavy half-lids
                ctx.strokeStyle = "#3E2723"; ctx.lineWidth = 1.2;
                ctx.beginPath();
                ctx.moveTo(-eyeX - 2.8, eyeY - 1.2); ctx.lineTo(-eyeX + 2.8, eyeY - 1.2);
                ctx.moveTo(eyeX - 2.8, eyeY - 1.2); ctx.lineTo(eyeX + 2.8, eyeY - 1.2);
                ctx.stroke();
            }
        }

        // ── Tiny nose + freckles (part of HER, always) ──
        ctx.fillStyle = "rgba(214,150,120,0.55)";
        ctx.beginPath(); ctx.ellipse(0, 1.4, 1.2, 1.5, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "rgba(180,110,80,0.5)";
        ctx.beginPath(); ctx.arc(-8.5, 3, 0.5, 0, Math.PI * 2); ctx.arc(8.5, 3, 0.5, 0, Math.PI * 2); ctx.fill();

        // ── Mouth — she is ALWAYS a little bit smiling (she'll do it again) ──
        ctx.strokeStyle = "#C44E63"; ctx.lineWidth = 1.5;
        if (expr === 2) {                                    // open laugh
            ctx.fillStyle = "#8E3B4A";
            ctx.beginPath(); ctx.moveTo(-3.6, my - 0.4); ctx.quadraticCurveTo(0, my + 4.6, 3.6, my - 0.4); ctx.quadraticCurveTo(0, my + 1.2, -3.6, my - 0.4); ctx.closePath(); ctx.fill();
            ctx.fillStyle = "#FFFFFF";
            ctx.beginPath(); ctx.moveTo(-2.8, my - 0.2); ctx.quadraticCurveTo(0, my + 1, 2.8, my - 0.2); ctx.quadraticCurveTo(0, my + 0.2, -2.8, my - 0.2); ctx.closePath(); ctx.fill();
        } else if (expr === 3) {                             // deadpan — one corner still curls up
            ctx.beginPath(); ctx.moveTo(-3.4, my + 0.9); ctx.quadraticCurveTo(1, my + 0.3, 3.8, my - 1.2); ctx.stroke();
        } else {                                             // gentle knowing smile
            ctx.beginPath(); ctx.moveTo(-3.6, my); ctx.quadraticCurveTo(0, my + 3, 3.6, my); ctx.stroke();
        }
        ctx.fillStyle = "rgba(255,140,160,0.4)";             // lower-lip blush
        ctx.beginPath(); ctx.ellipse(0, my + 3.2, 2.6, 1, 0, 0, Math.PI * 2); ctx.fill();

        // ── FACIAL disguise ──
        if (face === 1) {                                    // peeling stick-on moustache
            ctx.fillStyle = "#3A2A1A";
            ctx.beginPath();
            ctx.moveTo(-4.6, my - 1.4);
            ctx.quadraticCurveTo(-2.2, my - 3.2, 0, my - 1.4);
            ctx.quadraticCurveTo(2.2, my - 3.2, 4.6, my - 1.4);
            ctx.quadraticCurveTo(2.4, my - 0.1, 0, my - 1);
            ctx.quadraticCurveTo(-2.4, my - 0.1, -4.6, my - 1.4);
            ctx.closePath(); ctx.fill();
            ctx.strokeStyle = "#3A2A1A"; ctx.lineWidth = 0.8;   // one corner peeling off the skin
            ctx.beginPath(); ctx.moveTo(4.4, my - 1.4); ctx.lineTo(6, my - 3); ctx.stroke();
            ctx.beginPath(); ctx.arc(6.1, my - 3.1, 0.7, 0, Math.PI * 2); ctx.fill();
        } else if (face === 2) {                             // drawn-on beauty mark
            ctx.fillStyle = "#2A1A12";
            ctx.beginPath(); ctx.arc(4.6, 4.6, 0.9, 0, Math.PI * 2); ctx.fill();
        } else if (face === 3) {                             // obviously stuck-on goatee
            ctx.fillStyle = "#3A2A1A";
            ctx.beginPath();
            ctx.moveTo(-2.6, my + 3);
            ctx.quadraticCurveTo(0, my + 7, 2.6, my + 3);
            ctx.quadraticCurveTo(0, my + 4.4, -2.6, my + 3);
            ctx.closePath(); ctx.fill();
        }

        // ── EYEWEAR disguise ──
        if (eyew === 1) {                                    // dollar-store sunglasses
            ctx.fillStyle = "#181818";
            roundRect(-eyeX - 3.3, eyeY - 2.6, 6.6, 5, 2); ctx.fill();
            roundRect(eyeX - 3.3, eyeY - 2.6, 6.6, 5, 2); ctx.fill();
            ctx.strokeStyle = "#181818"; ctx.lineWidth = 1.1;
            ctx.beginPath();
            ctx.moveTo(-eyeX + 3.3, eyeY - 0.4); ctx.lineTo(eyeX - 3.3, eyeY - 0.4);
            ctx.moveTo(-eyeX - 3.3, eyeY - 1); ctx.lineTo(-11, eyeY - 2);
            ctx.moveTo(eyeX + 3.3, eyeY - 1); ctx.lineTo(11, eyeY - 2);
            ctx.stroke();
            ctx.fillStyle = "rgba(255,255,255,0.28)";        // cheap lens glare
            ctx.beginPath(); ctx.ellipse(-eyeX - 1, eyeY - 1, 1.3, 0.7, -0.5, 0, Math.PI * 2); ctx.ellipse(eyeX - 1, eyeY - 1, 1.3, 0.7, -0.5, 0, Math.PI * 2); ctx.fill();
        } else if (eyew === 2) {                             // GROUCHO — brows + rims + big nose + 'stache
            ctx.fillStyle = "#241812";
            roundRect(-eyeX - 3.4, eyeY - 4.2, 6.8, 2.2, 1); ctx.fill();
            roundRect(eyeX - 3.4, eyeY - 4.2, 6.8, 2.2, 1); ctx.fill();
            ctx.strokeStyle = "#241812"; ctx.lineWidth = 1.2;
            ctx.beginPath();
            ctx.arc(-eyeX, eyeY, 3.4, 0, Math.PI * 2);
            ctx.arc(eyeX, eyeY, 3.4, 0, Math.PI * 2);
            ctx.moveTo(-eyeX + 3.4, eyeY); ctx.lineTo(eyeX - 3.4, eyeY);
            ctx.moveTo(-eyeX - 3.4, eyeY); ctx.lineTo(-11, eyeY - 1);
            ctx.moveTo(eyeX + 3.4, eyeY); ctx.lineTo(11, eyeY - 1);
            ctx.stroke();
            ctx.fillStyle = "#E8A98A";                        // bulbous fake nose
            ctx.beginPath(); ctx.ellipse(0, 2.4, 3.2, 4, 0, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "rgba(0,0,0,0.10)";
            ctx.beginPath(); ctx.arc(1.2, 3.4, 1, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#241812";                        // bushy 'stache
            ctx.beginPath();
            ctx.moveTo(-5, my - 0.4);
            ctx.quadraticCurveTo(-2.5, my - 3, 0, my - 0.8);
            ctx.quadraticCurveTo(2.5, my - 3, 5, my - 0.4);
            ctx.quadraticCurveTo(2.5, my + 1.8, 0, my + 0.6);
            ctx.quadraticCurveTo(-2.5, my + 1.8, -5, my - 0.4);
            ctx.closePath(); ctx.fill();
        } else if (eyew === 3) {                             // monocle + dangling chain
            ctx.fillStyle = "rgba(230,240,255,0.20)";
            ctx.beginPath(); ctx.arc(eyeX, eyeY, 3.2, 0, Math.PI * 2); ctx.fill();
            ctx.strokeStyle = "#D4AF37"; ctx.lineWidth = 1;
            ctx.beginPath(); ctx.arc(eyeX, eyeY, 3.4, 0, Math.PI * 2); ctx.stroke();
            ctx.strokeStyle = "#B8972E"; ctx.lineWidth = 0.6;
            ctx.beginPath(); ctx.moveTo(eyeX + 3, eyeY + 1.6); ctx.quadraticCurveTo(9, 6, 8, 11); ctx.stroke();
        } else if (eyew === 4) {                             // big round novelty specs
            ctx.strokeStyle = "#20262E"; ctx.lineWidth = 1.1;
            ctx.beginPath();
            ctx.arc(-eyeX, eyeY, 3.6, 0, Math.PI * 2);
            ctx.arc(eyeX, eyeY, 3.6, 0, Math.PI * 2);
            ctx.moveTo(-eyeX + 3.6, eyeY); ctx.lineTo(eyeX - 3.6, eyeY);
            ctx.moveTo(-eyeX - 3.6, eyeY); ctx.lineTo(-11, eyeY - 1.5);
            ctx.moveTo(eyeX + 3.6, eyeY); ctx.lineTo(11, eyeY - 1.5);
            ctx.stroke();
            ctx.fillStyle = "rgba(180,220,255,0.16)";
            ctx.beginPath(); ctx.arc(-eyeX, eyeY, 3.4, 0, Math.PI * 2); ctx.fill();
            ctx.beginPath(); ctx.arc(eyeX, eyeY, 3.4, 0, Math.PI * 2); ctx.fill();
        }

        // ── HEADWEAR disguise (over the hair) ──
        if (head === 1) {                                    // baseball cap pulled LOW
            var capC2 = mugPick(h, 9, 2) ? "#C62828" : "#1565C0";
            ctx.fillStyle = capC2;
            ctx.beginPath(); ctx.ellipse(0, -6, 13, 10, 0, Math.PI, Math.PI * 2); ctx.fill();
            roundRect(-13, -7, 26, 3, 1); ctx.fill();
            ctx.beginPath(); ctx.ellipse(-10, -5.5, 8, 2.6, -0.14, 0, Math.PI); ctx.fill();   // brim over brow
            ctx.fillStyle = shadeColor(capC2, 40);
            ctx.beginPath(); ctx.arc(0, -14, 1.4, 0, Math.PI * 2); ctx.fill();                // button
        } else if (head === 2) {                             // babushka / headscarf
            var scC = mugPick(h, 9, 3);
            var scarfC = scC === 0 ? "#D81B60" : (scC === 1 ? "#00897B" : "#FBC02D");
            ctx.fillStyle = scarfC;
            ctx.beginPath();
            ctx.moveTo(-13, -1);
            ctx.quadraticCurveTo(-15, -18, 0, -18);
            ctx.quadraticCurveTo(15, -18, 13, -1);
            ctx.quadraticCurveTo(8, -8, 0, -7.5);
            ctx.quadraticCurveTo(-8, -8, -13, -1);
            ctx.closePath(); ctx.fill();
            ctx.beginPath(); ctx.arc(12, 0, 2.4, 0, Math.PI * 2); ctx.fill();                 // side knot
            ctx.beginPath(); ctx.moveTo(13, 1); ctx.lineTo(16, 6); ctx.lineTo(12, 4.5); ctx.closePath(); ctx.fill();
            ctx.fillStyle = "rgba(255,255,255,0.7)";         // polka dots
            ctx.beginPath(); ctx.arc(-6, -10, 1, 0, Math.PI * 2); ctx.arc(2, -13, 1, 0, Math.PI * 2); ctx.arc(7, -8, 1, 0, Math.PI * 2); ctx.fill();
        } else if (head === 3) {                             // inexplicable PARTY hat
            ctx.fillStyle = "#7E57C2";
            ctx.beginPath(); ctx.moveTo(-8, -12); ctx.lineTo(0, -27); ctx.lineTo(8, -12); ctx.closePath(); ctx.fill();
            ctx.strokeStyle = "#FFD54F"; ctx.lineWidth = 1;  // zigzag streamer
            ctx.beginPath(); ctx.moveTo(-6, -16); ctx.lineTo(-1, -18); ctx.lineTo(-5, -20.5); ctx.lineTo(0, -22.5); ctx.stroke();
            ctx.fillStyle = "#FF7043";                        // pom-pom
            ctx.beginPath(); ctx.arc(0, -27, 2.2, 0, Math.PI * 2); ctx.fill();
            ctx.strokeStyle = "rgba(0,0,0,0.35)"; ctx.lineWidth = 0.6;   // chin strap (why so serious)
            ctx.beginPath(); ctx.moveTo(-7, -11); ctx.quadraticCurveTo(0, 12, 7, -11); ctx.stroke();
        } else if (head === 4) {                             // big floppy sun hat
            ctx.fillStyle = "#EAD79A";
            ctx.beginPath(); ctx.ellipse(0, -7, 18, 5, 0, 0, Math.PI * 2); ctx.fill();        // wide brim
            ctx.fillStyle = shadeColor("#EAD79A", -16);
            ctx.beginPath(); ctx.ellipse(0, -11, 9, 5.5, 0, Math.PI, Math.PI * 2); ctx.fill(); // crown
            ctx.fillStyle = "#C97BA0";                        // ribbon band
            roundRect(-9, -10, 18, 2, 1); ctx.fill();
        }

        ctx.restore();                                       // drop the clip
        ctx.strokeStyle = "rgba(40,30,20,0.5)"; ctx.lineWidth = 1.2;  // card frame
        roundRect(-24, -24, 48, 48, 4); ctx.stroke();
        ctx.restore();
    }

    function drawBillboard(x, y, side, msg, wanted) {
        ctx.save();
        ctx.translate(x, y);
        // Two posts
        ctx.fillStyle = "#5D4037";
        ctx.fillRect(-30, 0, 5, 50);
        ctx.fillRect(25, 0, 5, 50);
        // Board outline
        ctx.fillStyle = "#3E2723";
        roundRect(-40, -38, 80, 44, 3); ctx.fill();

        if (wanted) {
            // A WANTED poster: aged paper, "WANTED", a Lulu mugshot, "REWARD".
            ctx.fillStyle = "#E8DBB5"; roundRect(-37, -35, 74, 38, 2); ctx.fill();
            ctx.fillStyle = "#3E2723"; ctx.textAlign = "center"; ctx.textBaseline = "middle";
            ctx.font = "bold 9px 'Segoe UI', Arial, sans-serif"; ctx.fillText("WANTED", 0, -31);
            // A REAL online fugitive's name (from the async board) when the poster
            // carries one, else the default reward gag.
            var wName = (msg && msg.indexOf("WANTED: ") === 0) ? msg.substring(8) : "LULU";
            if (wName && wName !== "LULU") {
                // Deterministic booking-photo face for the named fugitive.
                drawMugshot(wName, 0, -17, 21);
            } else {
                // Default poster keeps Lulu's own little mugshot.
                ctx.fillStyle = "#9E9E9E"; roundRect(-11, -27, 22, 20, 2); ctx.fill();
                ctx.fillStyle = (typeof save !== "undefined" && save.luluHair) || "#8B5A2B";
                ctx.beginPath(); ctx.arc(0, -18, 8, Math.PI, Math.PI * 2); ctx.fill();
                ctx.fillStyle = C.skin; ctx.beginPath(); ctx.arc(0, -16, 6.5, 0, Math.PI * 2); ctx.fill();
                ctx.fillStyle = "#1A1A1A";
                ctx.beginPath(); ctx.arc(-2.3, -16, 1, 0, Math.PI * 2); ctx.arc(2.3, -16, 1, 0, Math.PI * 2); ctx.fill();
                // height bars behind
                ctx.strokeStyle = "rgba(0,0,0,0.25)"; ctx.lineWidth = 0.5;
                ctx.beginPath(); ctx.moveTo(-9, -22); ctx.lineTo(9, -22); ctx.moveTo(-9, -12); ctx.lineTo(9, -12); ctx.stroke();
            }
            ctx.fillStyle = "#B71C1C";
            if (wName && wName !== "LULU") {
                var wfs = 7;
                ctx.font = "bold " + wfs + "px 'Segoe UI', Arial, sans-serif";
                while (wfs > 5 && ctx.measureText(wName).width > 66) {
                    wfs -= 0.5; ctx.font = "bold " + wfs + "px 'Segoe UI', Arial, sans-serif";
                }
                ctx.fillText(wName, 0, -2);
            } else {
                ctx.font = "bold 6px 'Segoe UI', Arial, sans-serif";
                ctx.fillText("REWARD: 1 KUGEL", 0, -2);
            }
            ctx.restore();
            return;
        }

        // Board face
        ctx.fillStyle = "#FFF59D";
        roundRect(-37, -35, 74, 38, 2); ctx.fill();
        // Text (wrap into 2 lines)
        ctx.fillStyle = "#D32F2F";
        ctx.font = "bold 8px 'Segoe UI', Arial, sans-serif";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        var words = msg.split(" ");
        var line1 = "", line2 = "";
        for (var i = 0; i < words.length; i++) {
            var test = (line1 ? line1 + " " : "") + words[i];
            if (ctx.measureText(test).width < 70 && !line2) line1 = test;
            else line2 = (line2 ? line2 + " " : "") + words[i];
        }
        if (!line2) {
            ctx.font = "bold 10px 'Segoe UI', Arial, sans-serif";
            ctx.fillText(line1, 0, -16);
        } else {
            ctx.fillText(line1, 0, -22);
            ctx.fillText(line2, 0, -10);
        }
        ctx.restore();
    }

    function drawSasquatch(x, y, phase, walkTime) {
        ctx.save();
        ctx.translate(x, y);
        var legSwing = Math.sin(walkTime * 8) * 4;

        // Shadow
        ctx.fillStyle = "rgba(0,0,0,0.25)";
        ctx.beginPath(); ctx.ellipse(0, 26, 18, 5, 0, 0, Math.PI * 2); ctx.fill();

        // Big brown body
        ctx.fillStyle = "#3E2723";
        ctx.beginPath(); ctx.ellipse(0, 8, 16, 20, 0, 0, Math.PI * 2); ctx.fill();
        // Fur tufts
        ctx.fillStyle = "#5D4037";
        ctx.beginPath();
        ctx.ellipse(-10, 0, 5, 8, -0.2, 0, Math.PI * 2);
        ctx.ellipse(10, 0, 5, 8, 0.2, 0, Math.PI * 2);
        ctx.fill();

        // Legs
        ctx.fillStyle = "#3E2723";
        roundRect(-8, 22 - legSwing, 7, 8 + legSwing, 2); ctx.fill();
        roundRect(1, 22 + legSwing, 7, 8 - legSwing, 2); ctx.fill();
        // Feet
        ctx.fillStyle = "#5D4037";
        roundRect(-10, 28 - legSwing, 10, 4, 2); ctx.fill();
        roundRect(0, 28 + legSwing, 10, 4, 2); ctx.fill();

        // Arms (one waving if phase 1)
        ctx.fillStyle = "#3E2723";
        if (phase === 1) {
            ctx.save();
            ctx.translate(-13, 0);
            ctx.rotate(-0.5 - Math.sin(walkTime * 6) * 0.4);
            roundRect(-4, -2, 8, 18, 3); ctx.fill();
            ctx.restore();
            roundRect(8, 0, 8, 18, 3); ctx.fill();
        } else {
            var armSwing = -legSwing * 0.5;
            roundRect(-15, -2 - armSwing, 8, 18 + Math.abs(armSwing), 3); ctx.fill();
            roundRect(7, -2 + armSwing, 8, 18 + Math.abs(armSwing), 3); ctx.fill();
        }

        // Head (chunky outline + lighter face)
        ctx.fillStyle = "#1A1410";
        ctx.beginPath(); ctx.arc(0, -14, 13, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#4E342E";
        ctx.beginPath(); ctx.arc(0, -14, 12, 0, Math.PI * 2); ctx.fill();
        // Fur tufts on top of head
        ctx.fillStyle = "#3E2723";
        ctx.beginPath();
        ctx.arc(-9, -22, 4, 0, Math.PI * 2);
        ctx.arc(-3, -24, 4, 0, Math.PI * 2);
        ctx.arc(3, -24, 4, 0, Math.PI * 2);
        ctx.arc(9, -22, 4, 0, Math.PI * 2);
        ctx.fill();
        // Lighter muzzle area
        ctx.fillStyle = "#8D6E63";
        ctx.beginPath(); ctx.ellipse(0, -9, 9, 7.5, 0, 0, Math.PI * 2); ctx.fill();
        // Brow ridge (gives personality)
        ctx.fillStyle = "#1A1410";
        ctx.beginPath();
        ctx.ellipse(-5, -17, 4, 1.5, -0.3, 0, Math.PI * 2);
        ctx.ellipse(5, -17, 4, 1.5, 0.3, 0, Math.PI * 2);
        ctx.fill();
        // Bigger friendlier eyes
        ctx.fillStyle = "#FFF9C4";
        ctx.beginPath();
        ctx.arc(-4.5, -14, 3.2, 0, Math.PI * 2);
        ctx.arc(4.5, -14, 3.2, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#000";
        ctx.beginPath();
        ctx.arc(-4.5, -13.5, 1.7, 0, Math.PI * 2);
        ctx.arc(4.5, -13.5, 1.7, 0, Math.PI * 2);
        ctx.fill();
        // Eye highlights
        ctx.fillStyle = "#FFF";
        ctx.beginPath();
        ctx.arc(-3.7, -14, 0.7, 0, Math.PI * 2);
        ctx.arc(5.3, -14, 0.7, 0, Math.PI * 2);
        ctx.fill();
        // Nostrils
        ctx.fillStyle = "#1A1410";
        ctx.beginPath();
        ctx.arc(-2, -9, 0.8, 0, Math.PI * 2);
        ctx.arc(2, -9, 0.8, 0, Math.PI * 2);
        ctx.fill();
        // Mouth
        ctx.strokeStyle = "#000";
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        if (phase === 1) {
            // Surprised "o" mouth when waving
            ctx.arc(0, -5, 2, 0, Math.PI * 2);
        } else {
            ctx.moveTo(-3, -5); ctx.quadraticCurveTo(0, -3, 3, -5);
        }
        ctx.stroke();

        ctx.restore();
    }

    function drawTopBus(x, y) {
        ctx.save();
        ctx.translate(x, y);
        var bw = 24, bh = 54; // half-extents → 48 wide, 108 long
        ctx.fillStyle = "rgba(0,0,0,0.25)";
        ctx.beginPath(); ctx.ellipse(2, 6, bw + 4, bh - 4, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#F9A825"; roundRect(-bw, -bh, bw * 2, bh * 2, 10); ctx.fill();
        ctx.fillStyle = "#FBC02D"; roundRect(-bw + 2, -bh + 2, bw * 2 - 4, bh * 2 - 4, 8); ctx.fill();
        ctx.fillStyle = "#212121"; ctx.fillRect(-bw, -bh + 20, bw * 2, 4); ctx.fillRect(-bw, bh - 24, bw * 2, 4);
        // windshield at the front (bottom, toward player)
        ctx.fillStyle = "#81D4FA"; roundRect(-bw + 5, bh - 20, bw * 2 - 10, 14, 4); ctx.fill();
        // side windows
        ctx.fillStyle = "#4FC3F7";
        for (var wy = -bh + 26; wy < bh - 28; wy += 15) { ctx.fillRect(-bw + 4, wy, 8, 10); ctx.fillRect(bw - 12, wy, 8, 10); }
        drawText("SCHOOL", 0, -bh + 12, "bold 8px Arial", "#212121", null, 0);
        ctx.fillStyle = "#FFFFFF"; ctx.fillRect(-6, -8, 12, 12); // roof hatch
        ctx.fillStyle = "#F44336"; ctx.beginPath(); ctx.arc(-bw + 6, bh - 3, 3, 0, Math.PI * 2); ctx.arc(bw - 6, bh - 3, 3, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#FFEB3B"; ctx.beginPath(); ctx.arc(-bw + 6, -bh + 4, 3, 0, Math.PI * 2); ctx.arc(bw - 6, -bh + 4, 3, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#222";
        roundRect(-bw - 3, -bh + 22, 6, 16, 2); ctx.fill(); roundRect(bw - 3, -bh + 22, 6, 16, 2); ctx.fill();
        roundRect(-bw - 3, bh - 38, 6, 16, 2); ctx.fill(); roundRect(bw - 3, bh - 38, 6, 16, 2); ctx.fill();
        ctx.restore();
    }

    function drawAmbulance(x, y, time) {
        ctx.save();
        ctx.translate(x, y);
        var hw = CAR_W / 2 + 5, hh = CAR_H / 2 + 6;
        ctx.fillStyle = "rgba(0,0,0,0.25)";
        ctx.beginPath(); ctx.ellipse(2, 6, hw + 3, hh - 6, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#CFD8DC"; roundRect(-hw - 2, -hh - 2, hw * 2 + 4, hh * 2 + 4, 10); ctx.fill();
        ctx.fillStyle = "#FFFFFF"; roundRect(-hw, -hh, hw * 2, hh * 2, 8); ctx.fill();
        ctx.fillStyle = "#E53935"; ctx.fillRect(-hw, -3, hw * 2, 8); // red stripe
        ctx.fillStyle = "#4FC3F7"; roundRect(-hw + 8, -hh + 8, hw * 2 - 16, 22, 5); ctx.fill();
        // red cross on the roof
        ctx.fillStyle = "#E53935";
        ctx.fillRect(-3, hh - 30, 6, 18); ctx.fillRect(-9, hh - 24, 18, 6);
        // flashing light bar
        var on = Math.sin(time * 22) > 0;
        ctx.fillStyle = on ? "#F44336" : "#FFCDD2"; roundRect(-hw + 6, -hh - 6, 12, 6, 2); ctx.fill();
        ctx.fillStyle = on ? "#BBDEFB" : "#1E88E5"; roundRect(hw - 18, -hh - 6, 12, 6, 2); ctx.fill();
        if (on) { ctx.fillStyle = "rgba(244,67,54,0.18)"; ctx.beginPath(); ctx.arc(-hw + 12, -hh - 3, 22, 0, Math.PI * 2); ctx.fill(); }
        else { ctx.fillStyle = "rgba(33,150,243,0.18)"; ctx.beginPath(); ctx.arc(hw - 12, -hh - 3, 22, 0, Math.PI * 2); ctx.fill(); }
        ctx.fillStyle = "#222";
        roundRect(-hw - 3, -hh + 12, 7, 16, 3); ctx.fill(); roundRect(hw - 4, -hh + 12, 7, 16, 3); ctx.fill();
        roundRect(-hw - 3, hh - 28, 7, 16, 3); ctx.fill(); roundRect(hw - 4, hh - 28, 7, 16, 3); ctx.fill();
        ctx.restore();
    }

    function drawCopCar(x, y, sirenTime) {
        ctx.save();
        ctx.translate(x, y);
        var hw = CAR_W / 2 + 4, hh = CAR_H / 2 + 4;

        // Shadow
        ctx.fillStyle = "rgba(0,0,0,0.25)";
        ctx.beginPath(); ctx.ellipse(2, 6, hw + 4, hh - 6, 0, 0, Math.PI * 2); ctx.fill();

        // Body (black/white)
        ctx.fillStyle = "#000";
        roundRect(-hw - 2, -hh - 2, hw * 2 + 4, hh * 2 + 4, 10); ctx.fill();
        ctx.fillStyle = "#FAFAFA";
        roundRect(-hw, -hh + hh, hw * 2, hh, 6); ctx.fill();
        ctx.fillStyle = "#212121";
        roundRect(-hw, -hh, hw * 2, hh, 6); ctx.fill();

        // Windshield
        ctx.fillStyle = "#4FC3F7";
        roundRect(-hw + 8, -hh + 8, hw * 2 - 16, 26, 5); ctx.fill();
        ctx.fillStyle = "#81D4FA";
        roundRect(-hw + 10, -hh + 10, hw * 2 - 20, 22, 4); ctx.fill();

        // Sheriff star
        ctx.fillStyle = "#FFD700";
        ctx.font = "bold 14px Arial";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText("★", 0, 10);

        // Sirens (alternating red/blue flashing)
        var flashR = Math.sin(sirenTime * 18) > 0;
        ctx.fillStyle = flashR ? "#F44336" : "#FFCDD2";
        roundRect(-hw + 6, -hh - 6, 12, 6, 2); ctx.fill();
        ctx.fillStyle = flashR ? "#9FA8DA" : "#2196F3";
        roundRect(hw - 18, -hh - 6, 12, 6, 2); ctx.fill();

        // Light beam aura
        if (flashR) {
            ctx.fillStyle = "rgba(244,67,54,0.18)";
            ctx.beginPath(); ctx.arc(-hw + 12, -hh - 3, 24, 0, Math.PI * 2); ctx.fill();
        } else {
            ctx.fillStyle = "rgba(33,150,243,0.18)";
            ctx.beginPath(); ctx.arc(hw - 12, -hh - 3, 24, 0, Math.PI * 2); ctx.fill();
        }

        // Wheels
        ctx.fillStyle = "#222";
        roundRect(-hw - 3, -hh + 10, 7, 16, 3); ctx.fill();
        roundRect(hw - 4, -hh + 10, 7, 16, 3); ctx.fill();
        roundRect(-hw - 3, hh - 26, 7, 16, 3); ctx.fill();
        roundRect(hw - 4, hh - 26, 7, 16, 3); ctx.fill();

        ctx.restore();
    }

    // K9 UNIT — a blacked-out cruiser-SUV with a barking dog in the back, used
    // when a fugitive's heat is high. Boxier + darker than a patrol car.
    function drawK9Car(x, y, sirenTime) {
        ctx.save();
        ctx.translate(x, y);
        var hw = CAR_W / 2 + 6, hh = CAR_H / 2 + 6;
        ctx.fillStyle = "rgba(0,0,0,0.28)"; ctx.beginPath(); ctx.ellipse(2, 8, hw + 4, hh - 4, 0, 0, Math.PI * 2); ctx.fill();
        // boxy black SUV body
        ctx.fillStyle = "#0C0F13"; roundRect(-hw - 2, -hh - 2, hw * 2 + 4, hh * 2 + 4, 8); ctx.fill();
        var bg = ctx.createLinearGradient(-hw, 0, hw, 0);
        bg.addColorStop(0, "#1A1E24"); bg.addColorStop(0.5, "#2C333B"); bg.addColorStop(1, "#1A1E24");
        ctx.fillStyle = bg; roundRect(-hw, -hh, hw * 2, hh * 2, 7); ctx.fill();
        // white "POLICE K9" door panel
        ctx.fillStyle = "#ECEFF1"; roundRect(-hw, -6, hw * 2, 22, 0); ctx.fill();
        drawText("K9", 0, 6, "bold 11px Arial", "#0D1B5E", null, 0);
        // windshield + rear cage window
        ctx.fillStyle = "#37474F"; roundRect(-hw + 7, -hh + 7, hw * 2 - 14, 22, 5); ctx.fill();
        ctx.fillStyle = "#546E7A"; roundRect(-hw + 9, -hh + 9, hw * 2 - 18, 18, 4); ctx.fill();
        // rear cage with a dog silhouette (barking — head bobs)
        ctx.fillStyle = "#11161B"; roundRect(-hw + 8, hh - 30, hw * 2 - 16, 22, 4); ctx.fill();
        ctx.strokeStyle = "#5A6772"; ctx.lineWidth = 1;
        for (var cg = -hw + 12; cg < hw - 10; cg += 6) { ctx.beginPath(); ctx.moveTo(cg, hh - 30); ctx.lineTo(cg, hh - 8); ctx.stroke(); }
        var bob = Math.abs(Math.sin(sirenTime * 6)) * 2;
        ctx.fillStyle = "#5D4037"; ctx.beginPath(); ctx.arc(0, hh - 20 - bob, 5, 0, Math.PI * 2); ctx.fill();   // dog head
        ctx.fillStyle = "#3E2723"; ctx.beginPath(); ctx.moveTo(-5, hh - 24 - bob); ctx.lineTo(-2, hh - 27 - bob); ctx.lineTo(-2, hh - 22 - bob); ctx.closePath(); ctx.fill();  // ear
        ctx.beginPath(); ctx.moveTo(5, hh - 24 - bob); ctx.lineTo(2, hh - 27 - bob); ctx.lineTo(2, hh - 22 - bob); ctx.closePath(); ctx.fill();
        // roof light bar (red/blue strobe)
        var flashR = Math.sin(sirenTime * 18) > 0;
        ctx.fillStyle = "#11161B"; roundRect(-14, -4, 28, 7, 2); ctx.fill();
        ctx.fillStyle = flashR ? "#FF1744" : "#7A1320"; roundRect(-13, -3, 12, 5, 1); ctx.fill();
        ctx.fillStyle = flashR ? "#0D2A6B" : "#2979FF"; roundRect(1, -3, 12, 5, 1); ctx.fill();
        ctx.fillStyle = flashR ? "rgba(255,23,68,0.18)" : "rgba(41,121,255,0.18)";
        ctx.beginPath(); ctx.arc(flashR ? -7 : 7, 0, 22, 0, Math.PI * 2); ctx.fill();
        // chunky tires
        ctx.fillStyle = "#0A0A0A";
        roundRect(-hw - 4, -hh + 12, 8, 18, 3); ctx.fill(); roundRect(hw - 4, -hh + 12, 8, 18, 3); ctx.fill();
        roundRect(-hw - 4, hh - 30, 8, 18, 3); ctx.fill(); roundRect(hw - 4, hh - 30, 8, 18, 3); ctx.fill();
        ctx.restore();
    }

    // A little roadside police motor-pool: paved lot, parked cruisers, a
    // standing officer, and one walking a cuffed perp in. Drawn relative to a
    // scrolling building-like record {x (center), y (top), w, h, side}. Reused
    // as the lot the arrest cruiser pulls into at the station.
    function drawPoliceLot(b) {
        var lw = b.w, lh = b.h, lx = b.x - lw / 2, ly = b.y, t = gameTime;
        ctx.save();
        // drop shadow + asphalt pad
        ctx.fillStyle = "rgba(0,0,0,0.18)"; roundRect(lx + 3, ly + 5, lw, lh, 7); ctx.fill();
        var pg = ctx.createLinearGradient(0, ly, 0, ly + lh);
        pg.addColorStop(0, "#74797E"); pg.addColorStop(1, "#5E6368");
        ctx.fillStyle = pg; roundRect(lx, ly, lw, lh, 7); ctx.fill();
        ctx.strokeStyle = "#3F4448"; ctx.lineWidth = 2; roundRect(lx, ly, lw, lh, 7); ctx.stroke();
        // yellow parking-bay lines
        ctx.strokeStyle = "rgba(255,213,79,0.75)"; ctx.lineWidth = 2;
        for (var py = ly + 20; py < ly + lh - 16; py += 38) {
            ctx.beginPath(); ctx.moveTo(lx + 8, py); ctx.lineTo(lx + lw - 8, py); ctx.stroke();
        }
        // POLICE sign on a post at the entrance
        ctx.fillStyle = "#37474F"; ctx.fillRect(b.x - 1.5, ly - 16, 3, 16);
        ctx.fillStyle = "#1A237E"; roundRect(b.x - 26, ly - 30, 52, 15, 3); ctx.fill();
        drawText("POLICE", b.x, ly - 22, "bold 9px 'Segoe UI', Arial", "#FFD54F", "#000", 2);
        // two parked cruisers (static), scaled to fit the bays
        var sc = Math.min(0.7, (lw - 14) / (CAR_W + 12));
        for (var c = 0; c < 2; c++) {
            ctx.save(); ctx.translate(b.x, ly + 34 + c * 40); ctx.scale(sc, sc); drawCopCar(0, 0, 0); ctx.restore();
        }
        // an officer standing watch (lower-left)…
        drawAngryMan(lx + 16, ly + lh - 12, t, "talk", 1, true);
        // …and an officer walking a cuffed perp toward the door (lower-right)
        var ex = lx + lw - 30, ey = ly + lh - 12;
        ctx.save(); ctx.translate(ex + 13, ey);
        ctx.fillStyle = "#CFD8DC"; roundRect(-6, -16, 12, 16, 3); ctx.fill();             // perp torso
        ctx.strokeStyle = "#78909C"; ctx.lineWidth = 1.4;                                  // prison stripes
        ctx.beginPath(); ctx.moveTo(-6, -12); ctx.lineTo(6, -12); ctx.moveTo(-6, -7); ctx.lineTo(6, -7); ctx.moveTo(-6, -2); ctx.lineTo(6, -2); ctx.stroke();
        ctx.fillStyle = (typeof C !== "undefined" && C.skin) || "#FFD9C0"; ctx.beginPath(); ctx.arc(0, -20, 5, 0, Math.PI * 2); ctx.fill();   // head
        ctx.fillStyle = "#5D4037"; ctx.beginPath(); ctx.arc(0, -22, 5, Math.PI, 0); ctx.fill();   // hair
        ctx.fillStyle = "#B0BEC5"; ctx.fillRect(-3, -6, 6, 3);                              // cuffs
        ctx.restore();
        drawAngryMan(ex, ey, t, "running", 1, true);
        ctx.restore();
    }

    // ── Drawing: Parking scene ───────────────────────────────
    function drawParkingScene(time) {
        var theme = (parkingLevelConfig && parkingLevelConfig.theme) || "day";
        // Sky colors depending on theme
        var skyTop, skyBot, sunOrMoon, sunColor1, sunColor2;
        if (theme === "day") {
            skyTop = "#FFE082"; skyBot = "#FFCC80";
            sunOrMoon = "sun"; sunColor1 = "#FFD54F"; sunColor2 = "#FFB300";
        } else if (theme === "dusk") {
            skyTop = "#FF7043"; skyBot = "#5E35B1";
            sunOrMoon = "sunset"; sunColor1 = "#FF8A65"; sunColor2 = "#D84315";
        } else { // night
            skyTop = "#0D1B40"; skyBot = "#1A237E";
            sunOrMoon = "moon"; sunColor1 = "#ECEFF1"; sunColor2 = "#CFD8DC";
        }
        var skyGrad = ctx.createLinearGradient(0, 0, 0, 80);
        skyGrad.addColorStop(0, skyTop);
        skyGrad.addColorStop(1, skyBot);
        ctx.fillStyle = skyGrad;
        ctx.fillRect(0, 0, W, 80);

        // Stars at night
        if (theme === "night") {
            ctx.fillStyle = "#FFF";
            for (var ss = 0; ss < 30; ss++) {
                var sx = (ss * 37 + 13) % W;
                var sy = (ss * 19 + 7) % 60;
                var twinkle = (Math.sin(time * 2 + ss) > 0.3) ? 1 : 0.4;
                ctx.globalAlpha = twinkle;
                ctx.fillRect(sx, sy, 1.5, 1.5);
            }
            ctx.globalAlpha = 1;
        }

        // Sun / Moon
        ctx.fillStyle = sunColor2;
        ctx.beginPath(); ctx.arc(W - 60, 40, 24, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = sunColor1;
        ctx.beginPath(); ctx.arc(W - 60, 40, 20, 0, Math.PI * 2); ctx.fill();
        if (sunOrMoon === "moon") {
            // Crescent — overlay sky color to carve out a crescent
            ctx.fillStyle = skyTop;
            ctx.beginPath(); ctx.arc(W - 67, 35, 18, 0, Math.PI * 2); ctx.fill();
        }

        // Building silhouette (darker at night/dusk)
        var bldgColors = theme === "night"
            ? ["#1A237E", "#283593", "#0D1F47", "#1A237E", "#283593", "#1A237E"]
            : theme === "dusk"
            ? ["#311B92", "#4527A0", "#1A237E", "#311B92", "#4527A0", "#311B92"]
            : ["#5C6BC0", "#7986CB", "#3F51B5", "#9FA8DA", "#5C6BC0", "#7986CB"];
        var rects = [[20, 30, 60, 50], [85, 20, 80, 60], [170, 35, 70, 45],
                     [245, 25, 60, 55], [310, 30, 90, 50], [405, 40, 65, 40]];
        for (var rb = 0; rb < rects.length; rb++) {
            ctx.fillStyle = bldgColors[rb];
            ctx.fillRect(rects[rb][0], rects[rb][1], rects[rb][2], rects[rb][3]);
            // Chunky black outline
            ctx.strokeStyle = "#1A1A1A";
            ctx.lineWidth = 2.5;
            ctx.strokeRect(rects[rb][0], rects[rb][1], rects[rb][2], rects[rb][3]);
            // Trapezoid roof on top
            ctx.fillStyle = theme === "night" ? "#0D1230" : "#3E2723";
            ctx.beginPath();
            ctx.moveTo(rects[rb][0] - 4, rects[rb][1]);
            ctx.lineTo(rects[rb][0] + rects[rb][2] + 4, rects[rb][1]);
            ctx.lineTo(rects[rb][0] + rects[rb][2] - 2, rects[rb][1] - 7);
            ctx.lineTo(rects[rb][0] + 2, rects[rb][1] - 7);
            ctx.closePath();
            ctx.fill(); ctx.stroke();
        }
        // Windows: gold during day/dusk, blue at night
        ctx.fillStyle = theme === "night" ? "#FFD740" : "#FFEB3B";
        for (var bw = 30; bw < W - 30; bw += 12) {
            for (var bh = 35; bh < 75; bh += 10) {
                if ((bw * 7 + bh * 13) % 11 < (theme === "night" ? 5 : 4)) {
                    ctx.fillRect(bw, bh, 5, 5);
                }
            }
        }

        // Sidewalk
        ctx.fillStyle = "#BDBDBD";
        ctx.fillRect(0, 80, W, 60);
        // Sidewalk cracks
        ctx.strokeStyle = "#9E9E9E";
        ctx.lineWidth = 1;
        for (var sx = 0; sx < W; sx += 60) {
            ctx.beginPath(); ctx.moveTo(sx, 80); ctx.lineTo(sx, 140); ctx.stroke();
        }
        ctx.beginPath(); ctx.moveTo(0, 110); ctx.lineTo(W, 110); ctx.stroke();

        // Curb edge (yellow paint)
        ctx.fillStyle = "#FBC02D";
        ctx.fillRect(0, 138, W, 4);
        ctx.fillStyle = "#212121";
        ctx.fillRect(0, 142, W, 2);

        // Parking strip + main road
        ctx.fillStyle = "#6B7B8D";
        ctx.fillRect(0, 144, W, H - 144);
        // Casual pull-over lots get a subtle ground tint so each one feels fresh.
        if (parkingLotStyle && parkingLotStyle.tint) {
            ctx.fillStyle = parkingLotStyle.tint;
            ctx.fillRect(0, 144, W, H - 144);
        }
        // Worn-asphalt detail — oil stains, tire scuffs, and a patch seam, laid
        // out deterministically per lot (hash of the sign text) so the big grey
        // field between the bays and the road doesn't read as an empty void.
        var lotSeed = 7;
        if (parkingLotStyle && parkingLotStyle.sign) {
            for (var lc = 0; lc < parkingLotStyle.sign.length; lc++) lotSeed = (lotSeed * 31 + parkingLotStyle.sign.charCodeAt(lc)) & 0xffff;
        }
        for (var gd = 0; gd < 7; gd++) {
            var gs = (lotSeed * (gd + 3) * 2654435761) >>> 0;
            var gx2 = 30 + (gs % 1000) / 1000 * (W - 60);
            var gy2 = 250 + ((gs >> 10) % 1000) / 1000 * (H - 470);
            var kind = gs % 3;
            if (kind === 0) {          // oil stain
                ctx.fillStyle = "rgba(30,36,44,0.28)";
                ctx.beginPath(); ctx.ellipse(gx2, gy2, 16 + gs % 14, 8 + (gs >> 4) % 7, (gs % 62) / 10, 0, Math.PI * 2); ctx.fill();
                ctx.fillStyle = "rgba(30,36,44,0.18)";
                ctx.beginPath(); ctx.ellipse(gx2 + 12, gy2 + 4, 6, 3.5, 0, 0, Math.PI * 2); ctx.fill();
            } else if (kind === 1) {   // tire scuff pair
                ctx.strokeStyle = "rgba(40,46,54,0.30)"; ctx.lineWidth = 4;
                ctx.beginPath(); ctx.moveTo(gx2 - 22, gy2 + 8); ctx.quadraticCurveTo(gx2, gy2 - 4, gx2 + 24, gy2 - 2); ctx.stroke();
                ctx.beginPath(); ctx.moveTo(gx2 - 22, gy2 + 20); ctx.quadraticCurveTo(gx2, gy2 + 8, gx2 + 24, gy2 + 10); ctx.stroke();
            } else {                    // lighter repaved patch
                ctx.fillStyle = "rgba(255,255,255,0.05)";
                roundRect(gx2 - 24, gy2 - 10, 48 + gs % 30, 20 + (gs >> 6) % 14, 4); ctx.fill();
            }
        }

        // White parking lines (between cars + at edges of zone)
        ctx.strokeStyle = "#F5F5DC";
        ctx.lineWidth = 3;
        if (parkingZone) {
            ctx.beginPath();
            ctx.moveTo(parkingZone.x, parkingZone.y);
            ctx.lineTo(parkingZone.x, parkingZone.y + parkingZone.h);
            ctx.moveTo(parkingZone.x + parkingZone.w, parkingZone.y);
            ctx.lineTo(parkingZone.x + parkingZone.w, parkingZone.y + parkingZone.h);
            ctx.stroke();
            // Outline (highlight when in zone)
            var inZone = parkingCar && carIsInZone(parkingCar);
            ctx.setLineDash([8, 6]);
            ctx.strokeStyle = inZone ? "#4CAF50" : "#FFEB3B";
            ctx.lineWidth = 3;
            roundRect(parkingZone.x, parkingZone.y, parkingZone.w, parkingZone.h, 4);
            ctx.stroke();
            ctx.setLineDash([]);
        }

        // Road center line (driving lane below)
        ctx.strokeStyle = "#F5F5DC";
        ctx.lineWidth = 2;
        ctx.setLineDash([20, 16]);
        ctx.lineDashOffset = -(time * 30 % 36);
        ctx.beginPath();
        ctx.moveTo(0, H * 0.55); ctx.lineTo(W, H * 0.55);
        ctx.stroke();
        ctx.setLineDash([]);

        // Decorations on sidewalk
        // Lamp post
        ctx.fillStyle = "#37474F";
        ctx.fillRect(70 - 2, 80, 4, 60);
        ctx.beginPath(); ctx.arc(70, 78, 8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#FFEE58";
        ctx.beginPath(); ctx.arc(70, 78, 5, 0, Math.PI * 2); ctx.fill();
        // Lamp glow
        ctx.fillStyle = "rgba(255,238,88,0.3)";
        ctx.beginPath(); ctx.arc(70, 78, 18, 0, Math.PI * 2); ctx.fill();

        // Fire hydrant
        ctx.fillStyle = "#B71C1C";
        roundRect(150, 110, 12, 22, 3); ctx.fill();
        ctx.fillStyle = "#FFEB3B";
        ctx.beginPath(); ctx.arc(156, 113, 3, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#212121";
        ctx.fillRect(145, 132, 22, 3);

        // Mailbox
        ctx.fillStyle = "#1565C0";
        roundRect(330, 102, 24, 18, 3); ctx.fill();
        ctx.fillStyle = "#0D47A1";
        roundRect(338, 96, 8, 12, 2); ctx.fill();
        ctx.fillStyle = "#FFFFFF";
        ctx.font = "bold 8px Arial";
        ctx.textAlign = "center";
        ctx.fillText("USPS", 342, 113);
        // pole
        ctx.fillStyle = "#5D4037";
        ctx.fillRect(340, 120, 4, 18);

        // Parking meter near right
        ctx.fillStyle = "#37474F";
        ctx.fillRect(430, 120, 4, 22);
        ctx.fillStyle = "#90A4AE";
        roundRect(424, 102, 16, 22, 3); ctx.fill();
        ctx.fillStyle = "#000";
        ctx.beginPath(); ctx.arc(432, 110, 5, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#F44336";
        ctx.fillText("EXP", 432, 119);

        // Casual pull-over lots get a little signboard variant (VISITOR / P-2 / …)
        // so the lot reads a touch different each time.
        if (parkingLotStyle && parkingLotStyle.sign) {
            ctx.save();
            // Size the board to the text — "CUSTOMERS ONLY" is much wider than
            // "P-2" and a fixed 48px board clipped the long variants to garbage.
            var sgTxt = "🅿 " + parkingLotStyle.sign;
            ctx.font = "bold 8px Arial";
            var sgW = Math.max(48, ctx.measureText(sgTxt).width + 14);
            ctx.fillStyle = "#37474F"; ctx.fillRect(232, 96, 3, 44);   // post
            ctx.fillStyle = "#1565C0"; roundRect(234 - sgW / 2, 84, sgW, 18, 3); ctx.fill();
            ctx.strokeStyle = "#0D47A1"; ctx.lineWidth = 1.5; roundRect(234 - sgW / 2, 84, sgW, 18, 3); ctx.stroke();
            drawText(sgTxt, 234, 93, "bold 8px Arial", "#FFFFFF", null, 0);
            ctx.restore();
        }
    }

    // ── Drawing: Security camera (with live tracking) ─────────
    function drawSecurityCamera(cam, time) {
        ctx.save();
        ctx.translate(cam.x, cam.y);

        // Pole (thick, dark grey)
        ctx.fillStyle = "#263238";
        ctx.fillRect(-3, 0, 6, cam.poleH);
        ctx.fillStyle = "#37474F";
        ctx.fillRect(-2, 0, 4, cam.poleH);
        // Base on ground
        ctx.fillStyle = "#212121";
        roundRect(-10, cam.poleH - 3, 20, 6, 2); ctx.fill();

        // Camera arm pivot (rotates to track)
        var rot = cam.currentRot;
        ctx.save();
        ctx.rotate(rot);

        // Arm (joint piece)
        ctx.fillStyle = "#37474F";
        ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#455A64";
        roundRect(-3, -5, 22, 10, 3); ctx.fill();

        // Camera body (chunkier)
        ctx.fillStyle = "#212121";
        roundRect(10, -11, 22, 22, 4); ctx.fill();
        ctx.fillStyle = "#37474F";
        roundRect(11, -10, 20, 20, 3); ctx.fill();

        // Top fin
        ctx.fillStyle = "#263238";
        roundRect(14, -14, 14, 4, 2); ctx.fill();

        // Lens (big black with blue inner)
        ctx.fillStyle = "#000";
        ctx.beginPath(); ctx.arc(30, 0, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#1976D2";
        ctx.beginPath(); ctx.arc(30, 0, 5, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#000";
        ctx.beginPath(); ctx.arc(31, -1, 3, 0, Math.PI * 2); ctx.fill();
        // Lens highlight
        ctx.fillStyle = "rgba(255,255,255,0.6)";
        ctx.beginPath(); ctx.arc(29, -2, 1.4, 0, Math.PI * 2); ctx.fill();

        // Recording red dot (blinking)
        var blink = Math.sin(time * 6) > 0;
        if (blink) {
            ctx.fillStyle = "rgba(244,67,54,0.6)";
            ctx.beginPath(); ctx.arc(14, -6, 5, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#F44336";
            ctx.beginPath(); ctx.arc(14, -6, 2.5, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#FFCDD2";
            ctx.beginPath(); ctx.arc(14, -6, 1, 0, Math.PI * 2); ctx.fill();
        } else {
            ctx.fillStyle = "#5D4037";
            ctx.beginPath(); ctx.arc(14, -6, 2, 0, Math.PI * 2); ctx.fill();
        }

        // Tracking laser line - prominent red dashed line
        var lasGrad = ctx.createLinearGradient(30, 0, 320, 0);
        lasGrad.addColorStop(0, "rgba(244,67,54,0.85)");
        lasGrad.addColorStop(1, "rgba(244,67,54,0)");
        ctx.strokeStyle = lasGrad;
        ctx.lineWidth = 2.5;
        ctx.setLineDash([6, 4]);
        ctx.lineDashOffset = -time * 30;
        ctx.beginPath();
        ctx.moveTo(30, 0);
        ctx.lineTo(320, 0);
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.restore();

        // "REC" badge below pole
        ctx.fillStyle = "rgba(0,0,0,0.7)";
        roundRect(-18, cam.poleH + 4, 36, 13, 3); ctx.fill();
        if (blink) {
            ctx.fillStyle = "#F44336";
        } else {
            ctx.fillStyle = "#B71C1C";
        }
        ctx.beginPath(); ctx.arc(-10, cam.poleH + 10, 2.5, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#FFF";
        ctx.font = "bold 9px monospace";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText("REC", 4, cam.poleH + 10);

        ctx.restore();
    }

    // ── Drawing: Damage decals ────────────────────────────────
    function drawDamageDecals(car) {
        if (!car.damage || car.damage.length === 0) return;
        for (var i = 0; i < car.damage.length; i++) {
            var d = car.damage[i];
            ctx.save();
            ctx.fillStyle = "#212121";
            // Dent splotch
            ctx.beginPath();
            ctx.ellipse(d.x, d.y, d.size * 1.2, d.size, d.rot || 0, 0, Math.PI * 2);
            ctx.fill();
            // Inner darker
            ctx.fillStyle = "#000";
            ctx.beginPath();
            ctx.ellipse(d.x, d.y, d.size * 0.7, d.size * 0.5, d.rot || 0, 0, Math.PI * 2);
            ctx.fill();
            // Scratch marks
            ctx.strokeStyle = "#FAFAFA";
            ctx.lineWidth = 0.8;
            for (var s = 0; s < 3; s++) {
                var sa = (d.rot || 0) + s * 0.3 - 0.3;
                ctx.beginPath();
                ctx.moveTo(d.x - Math.cos(sa) * d.size, d.y - Math.sin(sa) * d.size);
                ctx.lineTo(d.x + Math.cos(sa) * d.size, d.y + Math.sin(sa) * d.size);
                ctx.stroke();
            }
            // Glass shards (for major hits)
            if (d.size > 5) {
                ctx.fillStyle = "#B0E0FF";
                for (var g = 0; g < 4; g++) {
                    var ga = sa + g;
                    ctx.beginPath();
                    ctx.moveTo(d.x, d.y);
                    ctx.lineTo(d.x + Math.cos(ga) * 3, d.y + Math.sin(ga) * 3);
                    ctx.lineTo(d.x + Math.cos(ga + 0.5) * 4, d.y + Math.sin(ga + 0.5) * 4);
                    ctx.closePath();
                    ctx.fill();
                }
            }
            ctx.restore();
        }
    }

    // ── Drawing: Lulu's car (parking version with damage + crying) ─
    function drawLuluCarFull(carObj, time, crying) {
        // Driving a special vehicle into the spot → park THAT vehicle. Those art
        // funcs draw fixed-orientation around their origin, so wrap them in the
        // same rotation and scale them to roughly the parking footprint.
        if (carObj.vehicle === "bus" || carObj.vehicle === "ambulance" || carObj.vehicle === "cop") {
            ctx.save();
            ctx.translate(carObj.x, carObj.y);
            ctx.rotate(carObj.rot + Math.PI / 2);
            var vsc = carObj.vehicle === "bus" ? 0.7 : 0.9;
            ctx.scale(vsc, vsc);
            if (carObj.vehicle === "bus") drawTopBus(0, 0);
            else if (carObj.vehicle === "ambulance") drawAmbulance(0, 0, time);
            else drawCopCar(0, 0, time * 3);
            ctx.restore();
            return;
        }
        // A hotwired/hailed civilian ride parks as ITSELF (taxi/pickup/EV/etc.).
        if (carObj.vehicle === "borrowed" && typeof borrowedCar !== "undefined" && borrowedCar) {
            ctx.save();
            ctx.translate(carObj.x, carObj.y);
            ctx.rotate(carObj.rot + Math.PI / 2);
            ctx.scale(0.9, 0.9);
            drawEnemyCar(0, 0, borrowedCar.color || "#E53935", borrowedCar.carType || 0);
            ctx.restore();
            return;
        }
        var skin = SKINS[save.selectedSkin] || SKINS.pink;
        ctx.save();
        ctx.translate(carObj.x, carObj.y);
        ctx.rotate(carObj.rot + Math.PI / 2); // car drawn facing up by default; rotate to current angle
        var hw = CAR_W / 2, hh = CAR_H / 2;

        // Shadow
        ctx.fillStyle = "rgba(0,0,0,0.25)";
        ctx.beginPath();
        ctx.ellipse(3, 6, hw + 4, hh - 6, 0, 0, Math.PI * 2);
        ctx.fill();

        // Wheels
        ctx.fillStyle = C.wheel;
        roundRect(-hw - 4, -hh + 10, 8, 18, 3); ctx.fill();
        roundRect(hw - 4, -hh + 10, 8, 18, 3); ctx.fill();
        roundRect(-hw - 4, hh - 28, 8, 18, 3); ctx.fill();
        roundRect(hw - 4, hh - 28, 8, 18, 3); ctx.fill();

        // Body outline
        ctx.fillStyle = skin.dark;
        roundRect(-hw - 2, -hh - 2, CAR_W + 4, CAR_H + 4, 14); ctx.fill();

        var grad = ctx.createLinearGradient(0, -hh, 0, hh);
        grad.addColorStop(0, skin.light);
        grad.addColorStop(0.5, skin.body);
        grad.addColorStop(1, skin.dark);
        ctx.fillStyle = grad;
        roundRect(-hw, -hh, CAR_W, CAR_H, 12); ctx.fill();
        if (skin.stripe) {
            ctx.fillStyle = skin.stripe;
            roundRect(-4, -hh + 4, 8, CAR_H - 8, 2); ctx.fill();
        }

        // Windshield
        ctx.fillStyle = C.windshieldDark;
        roundRect(-hw + 7, -hh + 8, CAR_W - 14, 26, 6); ctx.fill();
        ctx.fillStyle = C.windshield;
        roundRect(-hw + 8, -hh + 9, CAR_W - 16, 24, 5); ctx.fill();

        // Lulu's face — the SAME shared face as the driving car so she looks
        // identical (was an older, cruder face here before).
        drawLuluFace(-hh + 23, crying);

        // Rear window
        ctx.fillStyle = C.windshieldDark;
        roundRect(-hw + 10, hh - 22, CAR_W - 20, 12, 4); ctx.fill();

        // Kids in back seat (if kidsInCar)
        if (kidsInCar) {
            // Kid 1
            ctx.fillStyle = "#FFC107";
            ctx.beginPath(); ctx.arc(-7, hh - 16, 4.5, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = C.skin;
            ctx.beginPath(); ctx.arc(-7, hh - 15, 3.5, 0, Math.PI * 2); ctx.fill();
            // pigtails
            ctx.fillStyle = "#FFC107";
            ctx.beginPath();
            ctx.ellipse(-11, hh - 16, 2, 3, -0.4, 0, Math.PI * 2);
            ctx.ellipse(-3, hh - 16, 2, 3, 0.4, 0, Math.PI * 2);
            ctx.fill();
            // eyes happy
            ctx.fillStyle = "#000";
            ctx.beginPath();
            ctx.arc(-8.5, hh - 16, 0.7, 0, Math.PI * 2);
            ctx.arc(-5.5, hh - 16, 0.7, 0, Math.PI * 2);
            ctx.fill();
            // smile
            ctx.strokeStyle = "#000";
            ctx.lineWidth = 0.7;
            ctx.beginPath();
            ctx.arc(-7, hh - 14, 1.5, 0.1 * Math.PI, 0.9 * Math.PI);
            ctx.stroke();

            // Kid 2 (with cap)
            ctx.fillStyle = C.skin;
            ctx.beginPath(); ctx.arc(7, hh - 15, 3.5, 0, Math.PI * 2); ctx.fill();
            // baseball cap
            ctx.fillStyle = "#1976D2";
            ctx.beginPath();
            ctx.arc(7, hh - 17, 3.8, Math.PI, Math.PI * 2);
            ctx.fill();
            ctx.fillRect(8, hh - 17, 4, 1.5);
            // eyes
            ctx.fillStyle = "#000";
            ctx.beginPath();
            ctx.arc(5.5, hh - 15, 0.7, 0, Math.PI * 2);
            ctx.arc(8.5, hh - 15, 0.7, 0, Math.PI * 2);
            ctx.fill();
            // big smile
            ctx.strokeStyle = "#000";
            ctx.lineWidth = 0.7;
            ctx.beginPath();
            ctx.arc(7, hh - 13, 1.7, 0.1 * Math.PI, 0.9 * Math.PI);
            ctx.stroke();
            // Ice cream cones
            ctx.fillStyle = "#FFB74D";
            ctx.beginPath();
            ctx.moveTo(-10, hh - 9); ctx.lineTo(-7, hh - 9); ctx.lineTo(-8.5, hh - 6); ctx.closePath();
            ctx.fill();
            ctx.fillStyle = "#F48FB1";
            ctx.beginPath(); ctx.arc(-8.5, hh - 10, 1.8, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = "#FFB74D";
            ctx.beginPath();
            ctx.moveTo(5, hh - 9); ctx.lineTo(8, hh - 9); ctx.lineTo(6.5, hh - 6); ctx.closePath();
            ctx.fill();
            ctx.fillStyle = "#FFFFFF";
            ctx.beginPath(); ctx.arc(6.5, hh - 10, 1.8, 0, Math.PI * 2); ctx.fill();
        }

        // Headlights/taillights
        ctx.fillStyle = "#FFF9C4";
        ctx.beginPath();
        ctx.ellipse(-hw + 10, -hh + 2, 5, 3, 0, 0, Math.PI * 2);
        ctx.ellipse(hw - 10, -hh + 2, 5, 3, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#F44336";
        ctx.beginPath();
        ctx.ellipse(-hw + 10, hh - 4, 4, 3, 0, 0, Math.PI * 2);
        ctx.ellipse(hw - 10, hh - 4, 4, 3, 0, 0, Math.PI * 2);
        ctx.fill();

        // Damage decals (drawn after car body)
        drawDamageDecals(carObj);

        ctx.restore();
    }

    function drawParkedCar(car) {
        ctx.save();
        ctx.translate(car.x, car.y);
        ctx.rotate(car.rot + Math.PI / 2);
        var hw = CAR_W / 2, hh = CAR_H / 2;

        ctx.fillStyle = "rgba(0,0,0,0.18)";
        ctx.beginPath();
        ctx.ellipse(3, 5, hw + 3, hh - 8, 0, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = C.wheel;
        roundRect(-hw - 3, -hh + 8, 7, 16, 3); ctx.fill();
        roundRect(hw - 4, -hh + 8, 7, 16, 3); ctx.fill();
        roundRect(-hw - 3, hh - 24, 7, 16, 3); ctx.fill();
        roundRect(hw - 4, hh - 24, 7, 16, 3); ctx.fill();

        ctx.fillStyle = shadeColor(car.color, -40);
        roundRect(-hw - 2, -hh - 2, CAR_W + 4, CAR_H + 4, 12); ctx.fill();
        var g2 = ctx.createLinearGradient(0, -hh, 0, hh);
        g2.addColorStop(0, shadeColor(car.color, 30));
        g2.addColorStop(1, car.color);
        ctx.fillStyle = g2;
        roundRect(-hw, -hh, CAR_W, CAR_H, 10); ctx.fill();

        ctx.fillStyle = "#78909C";
        roundRect(-hw + 6, hh - 22, CAR_W - 12, 14, 4); ctx.fill();
        roundRect(-hw + 8, -hh + 8, CAR_W - 16, 11, 3); ctx.fill();

        drawDamageDecals(car);
        ctx.restore();
    }

    function carIsInZone(car) {
        if (!parkingZone) return false;
        return car.x > parkingZone.x + 8 &&
               car.x < parkingZone.x + parkingZone.w - 8 &&
               car.y > parkingZone.y + 8 &&
               car.y < parkingZone.y + parkingZone.h - 8;
    }

    // ── Drawing: HUD ─────────────────────────────────────────
    function drawHeart(x, y, filled) {
        ctx.save();
        ctx.translate(x, y);
        ctx.beginPath();
        ctx.moveTo(0, 4);
        ctx.bezierCurveTo(-8, -3, -14, -8, -14, -12);
        ctx.arc(-7, -14, 7, Math.PI, 0);
        ctx.arc(7, -14, 7, Math.PI, 0);
        ctx.bezierCurveTo(14, -8, 8, -3, 0, 4);
        ctx.closePath();
        if (filled) { ctx.fillStyle = C.heart; ctx.fill(); ctx.strokeStyle = "#AD1457"; }
        else { ctx.fillStyle = C.heartEmpty; ctx.fill(); ctx.strokeStyle = "#333"; }
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.restore();
    }

    // ── Drawing: Buttons (UI) ────────────────────────────────
    function drawButton(x, y, w, h, label, opts) {
        opts = opts || {};
        var bg = opts.bg || "#FFC107";
        var bgDark = opts.bgDark || "#FF6F00";
        var textColor = opts.text || "#FFFFFF";
        var disabled = opts.disabled;
        var icon = opts.icon;
        var smallLabel = opts.small;

        if (disabled) { bg = "#9E9E9E"; bgDark = "#616161"; }

        // press-squish feedback (when an id is supplied and recently flashed)
        var sc = opts.id ? getBtnPressScale(opts.id) : 1;
        if (sc !== 1) {
            ctx.save();
            var cx = x + w / 2, cy = y + h / 2;
            ctx.translate(cx, cy); ctx.scale(sc, sc); ctx.translate(-cx, -cy);
        }

        // shadow
        ctx.fillStyle = "rgba(0,0,0,0.25)";
        roundRect(x, y + 4, w, h, 10); ctx.fill();
        // body
        ctx.fillStyle = bgDark;
        roundRect(x, y, w, h, 10); ctx.fill();
        ctx.fillStyle = bg;
        roundRect(x + 2, y + 2, w - 4, h - 6, 8); ctx.fill();
        // label
        drawText(label, x + w / 2, y + h / 2, "bold " + (smallLabel ? "14" : "20") + "px 'Segoe UI', Arial, sans-serif", textColor, "#000", 3);
        if (icon) drawText(icon, x + 14, y + h / 2, "bold 18px Arial", textColor, "#000", 3);

        if (sc !== 1) ctx.restore();
    }

    // Unified back-button helper — same look/size everywhere
    function drawBackButton(x, y) {
        x = (x === undefined) ? 12 : x;
        y = (y === undefined) ? 12 : y;
        drawButton(x, y, 80, 44, "◀ BACK", { bg: "#90A4AE", bgDark: "#455A64", small: true });
        return { x: x, y: y, w: 80, h: 44 };
    }

    // A 🔒 badge + glow ring on a run/slow button that's been double-tapped to
    // lock (cruise control). Shared by the driving HUD and the on-foot HUD.
    function drawSpeedLockBadges() {
        var pairs = [[boostLock, MOBILE_BOOST_RECT], [brakeLock, MOBILE_BRAKE_RECT]];
        for (var i = 0; i < 2; i++) {
            if (!pairs[i][0]) continue;
            var r = pairs[i][1];
            ctx.save();
            ctx.strokeStyle = "rgba(124,252,79,0.9)"; ctx.lineWidth = 3;
            roundRect(r.x - 2, r.y - 2, r.w + 4, r.w + 4, 16); ctx.stroke();
            ctx.fillStyle = "#2E7D32";
            ctx.beginPath(); ctx.arc(r.x + r.w - 6, r.y + 6, 9, 0, Math.PI * 2); ctx.fill();
            drawText("🔒", r.x + r.w - 6, r.y + 7, "11px Arial", "#FFF", null, 0);
            ctx.restore();
        }
    }

    // A clean, centered chili for the pepper-spray button — the 🌶️ emoji renders
    // off-center (its glyph sits high-left in the em box), so we draw our own.
    // A proper pepper-spray CANISTER: red body, white hazard label, black
    // trigger cap + nozzle, and a puff of spray mist. (Replaces the old chili.)
    function drawPepperSprayCan(cx, cy, s) {
        ctx.save(); ctx.translate(cx, cy);
        var bw = s * 0.96, bh = s * 1.74, bodyTop = -bh / 2 + s * 0.2;
        // shadow
        ctx.fillStyle = "rgba(0,0,0,0.22)"; roundRect(-bw / 2 + 1.5, bodyTop + 2, bw, bh - s * 0.2, bw * 0.24); ctx.fill();
        // red canister body
        var g = ctx.createLinearGradient(-bw / 2, 0, bw / 2, 0);
        g.addColorStop(0, "#7F0E0E"); g.addColorStop(0.45, "#EF4636"); g.addColorStop(0.7, "#F4796C"); g.addColorStop(1, "#7F0E0E");
        ctx.fillStyle = g; roundRect(-bw / 2, bodyTop, bw, bh - s * 0.2, bw * 0.24); ctx.fill();
        // white warning label band with a red diamond
        ctx.fillStyle = "#F6F6F6"; roundRect(-bw / 2, -s * 0.06, bw, s * 0.64, 2); ctx.fill();
        ctx.fillStyle = "#D32F2F";
        ctx.beginPath(); ctx.moveTo(0, s * 0.07); ctx.lineTo(s * 0.16, s * 0.26); ctx.lineTo(0, s * 0.45); ctx.lineTo(-s * 0.16, s * 0.26); ctx.closePath(); ctx.fill();
        ctx.fillStyle = "#F6F6F6"; drawText("!", 0, s * 0.27, "bold " + Math.floor(s * 0.34) + "px Arial", "#F6F6F6", null, 0);
        // black trigger cap
        ctx.fillStyle = "#222A2E"; roundRect(-bw * 0.44, bodyTop - s * 0.26, bw * 0.88, s * 0.34, bw * 0.14); ctx.fill();
        // nozzle button + tip
        ctx.fillStyle = "#3C4A52"; roundRect(-bw * 0.30, bodyTop - s * 0.44, bw * 0.36, s * 0.22, 2); ctx.fill();
        ctx.fillStyle = "#222A2E"; roundRect(bw * 0.16, bodyTop - s * 0.30, s * 0.26, s * 0.13, 1); ctx.fill();
        // spray mist puffing up-right from the nozzle
        for (var m = 0; m < 4; m++) {
            var mm = m / 3;
            ctx.globalAlpha = 0.85 - mm * 0.22;
            ctx.fillStyle = mm < 0.5 ? "#FFE082" : "#FFF59D";
            ctx.beginPath(); ctx.arc(bw * 0.5 + mm * s * 0.7, bodyTop - s * 0.2 - mm * s * 0.42, s * (0.09 + mm * 0.11), 0, Math.PI * 2); ctx.fill();
        }
        ctx.globalAlpha = 1;
        ctx.restore();
    }
    // The pepper-spray HUD button (a polished button + the canister icon + a
    // count badge). Shared by the driving and on-foot HUDs.
    function drawPepperButton() {
        drawIconButton(PEPPER_RECT.x, PEPPER_RECT.y, PEPPER_RECT.w, "", { bg: "#FF7043", bgDark: "#BF360C", id: "pepper" });
        drawPepperSprayCan(PEPPER_RECT.x + PEPPER_RECT.w / 2, PEPPER_RECT.y + PEPPER_RECT.w / 2, PEPPER_RECT.w * 0.30);
        // count badge (top-right of the button)
        var bx = PEPPER_RECT.x + PEPPER_RECT.w - 4, by = PEPPER_RECT.y + 4;
        ctx.fillStyle = "#FFFFFF"; ctx.beginPath(); ctx.arc(bx, by, 12, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = "#BF360C"; ctx.lineWidth = 2; ctx.stroke();
        drawText(save.pepperSpray, bx, by + 1, "bold 13px Arial", "#BF360C", null, 0);
    }
    // Polished pull-style HUD button: drop shadow, dark rim, gradient face, a top
    // sheen, and a subtle inner highlight stroke.
    function drawIconButton(x, y, size, icon, opts) {
        opts = opts || {};
        var bg = opts.bg || "#FFC107";
        var bgDark = opts.bgDark || "#FF6F00";
        var r = Math.max(9, size * 0.26);
        var sc = opts.id ? getBtnPressScale(opts.id) : 1;
        if (sc !== 1) {
            ctx.save();
            var cx = x + size / 2, cy = y + size / 2;
            ctx.translate(cx, cy); ctx.scale(sc, sc); ctx.translate(-cx, -cy);
        }
        // drop shadow
        ctx.fillStyle = "rgba(0,0,0,0.30)"; roundRect(x, y + 4, size, size, r); ctx.fill();
        // dark rim / bezel
        ctx.fillStyle = bgDark; roundRect(x, y, size, size, r); ctx.fill();
        // gradient face (lighter top → base → slightly darker bottom)
        var fg = ctx.createLinearGradient(0, y, 0, y + size);
        fg.addColorStop(0, shadeColor(bg, 20)); fg.addColorStop(0.5, bg); fg.addColorStop(1, shadeColor(bg, -12));
        ctx.fillStyle = fg; roundRect(x + 2.5, y + 2, size - 5, size - 5, r - 2); ctx.fill();
        // glossy top sheen
        ctx.fillStyle = "rgba(255,255,255,0.26)"; roundRect(x + 5, y + 4, size - 10, size * 0.36, r - 3); ctx.fill();
        // crisp inner highlight stroke
        ctx.strokeStyle = "rgba(255,255,255,0.30)"; ctx.lineWidth = 1.2; roundRect(x + 2.5, y + 2, size - 5, size - 5, r - 2); ctx.stroke();
        if (icon) drawText(icon, x + size / 2, y + size / 2, "bold " + Math.floor(size * 0.5) + "px Arial", "#FFFFFF", "#000", 3);
        if (sc !== 1) ctx.restore();
    }

    function drawHUD() {
        // Shift the whole HUD below the notch / Dynamic Island (safe-area inset).
        ctx.save();
        ctx.translate(0, SAFE_TOP);
        // Score — left-aligned starting just right of the pause button so the
        // number can't grow under it.
        drawText("SCORE", 64, 14, "bold 13px 'Segoe UI', Arial, sans-serif", "#FFD54F", "#000", 3, "left");
        drawText(formatNum(Math.floor(score)), 64, 36, "bold 26px 'Segoe UI', Arial, sans-serif", C.hud, C.hudShadow, 5, "left");

        // Shared Road rider count (only when connected)
        if (typeof mpStatusChip === "function") { try { mpStatusChip(); } catch (e) {} }
        // Coins (current run) — the counter POPS when a flying coin lands on it.
        var chPop = 1 + Math.max(0, coinHudPulse) * 0.9;
        ctx.save(); ctx.translate(W - 100, 26); ctx.scale(chPop, chPop); drawCoin(0, 0, gameTime); ctx.restore();
        drawText("× " + runCoins, W - 70, 27, "bold 20px 'Segoe UI', Arial, sans-serif", C.coin, C.hudShadow, 4, "left");
        // Collected coins arcing up to the counter (quadratic bezier, ease-in).
        for (var cfd = 0; cfd < coinFlys.length; cfd++) {
            var cf = coinFlys[cfd]; if (cf.t < 0) continue;
            var cp2 = Math.min(1, cf.t / cf.dur); cp2 = cp2 * cp2 * (3 - 2 * cp2);   // smoothstep
            var inv = 1 - cp2;
            var fx = inv * inv * cf.sx + 2 * inv * cp2 * cf.cx + cp2 * cp2 * (W - 100);
            var fy = inv * inv * cf.sy + 2 * inv * cp2 * cf.cy + cp2 * cp2 * 26;
            ctx.save(); ctx.translate(fx, fy); ctx.scale(0.6, 0.6); ctx.globalAlpha = 0.95;
            drawCoin(0, 0, gameTime + cfd); ctx.restore();
        }

        // WANTED file open (skipped the ER, etc.) — a blinking warning so she knows
        // why cops keep giving chase. Only a judge clears it.
        if (typeof isWanted === "function" && isWanted() && !prisonClothes) {
            var wbl = 0.5 + 0.5 * Math.abs(Math.sin(gameTime * 5));
            ctx.globalAlpha = wbl;
            drawText("🚨 WANTED", W - 100, 52, "bold 13px 'Segoe UI', Arial, sans-serif", "#FF5252", "#000", 3, "left");
            ctx.globalAlpha = 1;
        }

        // Steamroller "diesel" gauge while crushing
        if (typeof playerVehicle !== "undefined" && playerVehicle === "dozer" && dozerTimer > 0) {
            var dwp = clamp(dozerTimer / 13, 0, 1);
            drawText("🚜 CRUSH MODE" + (dwp < 0.25 ? " — ⛽ LOW!" : ""), W / 2, 60, "bold 14px 'Segoe UI', Arial, sans-serif", dwp < 0.25 ? "#FF7043" : "#FFD54F", "#000", 3);
            // ⛽ diesel gauge — empties as her time in the steamroller runs out
            ctx.fillStyle = "rgba(0,0,0,0.35)"; roundRect(W / 2 - 60, 74, 120, 7, 3.5); ctx.fill();
            ctx.fillStyle = dwp < 0.25 ? "#FF7043" : "#F9A825"; roundRect(W / 2 - 60, 74, 120 * dwp, 7, 3.5); ctx.fill();
            ctx.fillStyle = "#FFE082"; drawText("⛽", W / 2 - 70, 80, "10px 'Segoe UI', Arial, sans-serif", "#FFE082", "#000", 2);
        }

        // Coin combo badge — appears once the multiplier kicks in (3+ in a row),
        // with a draining window bar. Pops on each fresh pickup.
        if (coinCombo >= 3) {
            var cMult = Math.min(1 + Math.floor((coinCombo - 1) / 3), 5);
            var cHot = cMult >= 4 ? "#FF5252" : cMult >= 3 ? "#FF9800" : "#FFD54F";
            var cPop = 1 + (coinComboFx > 0 ? coinComboFx * 0.7 : 0);
            ctx.save();
            ctx.translate(70, 62);
            ctx.scale(cPop, cPop);
            drawText("🔥 ×" + cMult + " COMBO", 0, 0,
                "bold 14px 'Segoe UI', Arial, sans-serif", cHot, "#000", 3, "left");
            ctx.restore();
            // draining window bar under the badge
            var cwp = clamp(coinComboT / 1.5, 0, 1);
            ctx.fillStyle = "rgba(0,0,0,0.35)"; roundRect(64, 70, 96, 5, 2.5); ctx.fill();
            ctx.fillStyle = cHot; roundRect(64, 70, 96 * cwp, 5, 2.5); ctx.fill();
        }

        // Close-call chain badge — the daredevil score multiplier from shaving
        // past traffic. Sits under the coin combo; heats up as the chain grows.
        if (nearChain >= 2 && nearChainT > 0) {
            var nMult = 1 + 0.25 * Math.min(nearChain, 8);
            var nHot = nearChain >= 6 ? "#FF5252" : nearChain >= 4 ? "#FF9800" : "#80D8FF";
            var nPulse = 1 + 0.06 * Math.sin(gameTime * 9);
            ctx.save();
            ctx.translate(70, 88);
            ctx.scale(nPulse, nPulse);
            drawText("😤 ×" + (Math.round(nMult * 100) / 100) + " CLOSE CALLS", 0, 0,
                "bold 13px 'Segoe UI', Arial, sans-serif", nHot, "#000", 3, "left");
            ctx.restore();
            var nwp = clamp(nearChainT / 6, 0, 1);
            ctx.fillStyle = "rgba(0,0,0,0.35)"; roundRect(64, 96, 96, 5, 2.5); ctx.fill();
            ctx.fillStyle = nHot; roundRect(64, 96, 96 * nwp, 5, 2.5); ctx.fill();
        }

        // 🏆 NEW RECORD banner — pops when the run crosses the old high score.
        if (recordBannerT > 0) {
            var rbIn = clamp((3.0 - recordBannerT) / 0.35, 0, 1);
            var rbScale = easeOutBack(rbIn) * (1 + 0.03 * Math.sin(gameTime * 8));
            var rbAlpha = recordBannerT < 0.5 ? recordBannerT / 0.5 : 1;
            ctx.save();
            ctx.globalAlpha = rbAlpha;
            ctx.translate(W / 2, 120);
            ctx.scale(rbScale, rbScale);
            ctx.fillStyle = "rgba(0,0,0,0.55)";
            roundRect(-128, -24, 256, 48, 14); ctx.fill();
            ctx.strokeStyle = "#FFD700"; ctx.lineWidth = 2.5;
            roundRect(-128, -24, 256, 48, 14); ctx.stroke();
            drawText("🏆 NEW RECORD!", 0, -2, "bold 24px 'Segoe UI', Arial, sans-serif", "#FFD700", "#000", 5);
            drawText("passing " + formatNum(save.highScore), 0, 16, "bold 11px 'Segoe UI', Arial, sans-serif", "#FFE082", "#000", 2);
            ctx.restore();
        }

        // 📖 STORY leg-intro banner — same pop-in style, queued at each story
        // run start ("LEG n/5 — NEXT STOP: …"). Guarded: never present in cruise.
        if (typeof legBannerT !== "undefined" && legBannerT > 0) {
            var lbIn = clamp((2.5 - legBannerT) / 0.35, 0, 1);
            var lbScale = easeOutBack(lbIn) * (1 + 0.03 * Math.sin(gameTime * 8));
            var lbAlpha = legBannerT < 0.5 ? legBannerT / 0.5 : 1;
            ctx.save();
            ctx.globalAlpha = lbAlpha;
            ctx.translate(W / 2, 120);
            ctx.scale(lbScale, lbScale);
            ctx.font = "bold 15px 'Segoe UI', Arial, sans-serif";
            var lbW = Math.max(160, ctx.measureText(legBannerText).width + 40);
            // Stacked lines: title, then this chapter's optional TASK, then the
            // chapter SET's art-direction VIBE. Each widens/heightens the pill;
            // all empty in cruise (banner only shows in story).
            var lbLines = [{ t: legBannerText, f: "bold 15px 'Segoe UI', Arial, sans-serif", c: legBannerColor, ow: 4, h: 22 }];
            var lbTask = (typeof legBannerTask !== "undefined") ? legBannerTask : "";
            if (lbTask) {
                ctx.font = "bold 11px 'Segoe UI', Arial, sans-serif";
                lbW = Math.max(lbW, ctx.measureText(lbTask).width + 34);
                lbLines.push({ t: lbTask, f: "bold 11px 'Segoe UI', Arial, sans-serif", c: "#FFE082", ow: 3, h: 18 });
            }
            var lbVibe = (typeof legBannerVibe !== "undefined") ? legBannerVibe : "";
            if (lbVibe) {
                ctx.font = "italic 10px 'Segoe UI', Arial, sans-serif";
                lbW = Math.max(lbW, ctx.measureText(lbVibe).width + 30);
                lbLines.push({ t: lbVibe, f: "italic 10px 'Segoe UI', Arial, sans-serif", c: "#FFD1E0", ow: 3, h: 15 });
            }
            var lbH = 22;   // top+bottom padding
            for (var lbi = 0; lbi < lbLines.length; lbi++) lbH += lbLines[lbi].h;
            ctx.fillStyle = "rgba(0,0,0,0.6)";
            roundRect(-lbW / 2, -22, lbW, lbH, 13); ctx.fill();
            ctx.strokeStyle = legBannerColor; ctx.lineWidth = 2.5;
            roundRect(-lbW / 2, -22, lbW, lbH, 13); ctx.stroke();
            var lbCy = -22 + 11;   // cursor: top edge + half the padding
            for (var lbj = 0; lbj < lbLines.length; lbj++) {
                var ln = lbLines[lbj];
                drawText(ln.t, 0, lbCy + ln.h / 2, ln.f, ln.c, "#000", ln.ow);
                lbCy += ln.h;
            }
            ctx.restore();
        }

        // Hearts — lives can exceed the starting 3 now. Show up to 6 across
        // (empty slots up to MAX_LIVES so damage still reads clearly), then
        // collapse to a single heart + "×N" so it never runs off-screen.
        if (lives <= 6) {
            var slots = Math.max(MAX_LIVES, lives);
            for (var i = 0; i < slots; i++) {
                drawHeart(W / 2 - (slots - 1) * 14 + i * 28, 30, i < lives);
            }
        } else {
            drawHeart(W / 2 - 16, 30, true);
            drawText("×" + lives, W / 2 + 4, 30, "bold 18px 'Segoe UI', Arial, sans-serif",
                "#FF4081", "#000", 3, "left");
        }

        // Speed bar
        var speedPct = clamp((gameSpeed - BASE_SPEED) / (MAX_SPEED - BASE_SPEED), 0, 1);
        var barW = 60, barH = 6;
        var barX = W - barW - 20, barY = 56;
        ctx.fillStyle = "rgba(0,0,0,0.3)";
        roundRect(barX, barY, barW, barH, 3); ctx.fill();
        var sGrad = ctx.createLinearGradient(barX, 0, barX + barW, 0);
        sGrad.addColorStop(0, "#4CAF50");
        sGrad.addColorStop(0.5, "#FFC107");
        sGrad.addColorStop(1, "#F44336");
        ctx.fillStyle = sGrad;
        roundRect(barX, barY, barW * speedPct, barH, 3); ctx.fill();

        // Distracted mode indicator
        if (distractedMode) {
            drawText("DISTRACTED 2×", W / 2, 60, "bold 12px 'Segoe UI', Arial, sans-serif", "#FF80AB", "#000", 2);
        }

        // Fugitive (escaped-convict) status strip
        if (typeof drawFugitiveHUD === "function") drawFugitiveHUD();

        // Nitro turbo indicator
        if (nitroTimer > 0) {
            drawText("🔥 NITRO", W / 2, 48, "bold 13px 'Segoe UI', Arial, sans-serif", "#FF7043", "#000", 3);
            ctx.fillStyle = "rgba(0,0,0,0.4)"; roundRect(W / 2 - 40, 56, 80, 6, 3); ctx.fill();
            ctx.fillStyle = "#FF7043"; roundRect(W / 2 - 38, 57, 76 * clamp(nitroTimer / 9, 0, 1), 4, 2); ctx.fill();
        }
        // Stolen-lemon warning so she knows WHY the car's misbehaving (stacked
        // below any nitro / courage badge).
        if (carMalfunction) {
            var blink = Math.sin(gameTime * 6) > -0.2;
            var ly = 48 + (nitroTimer > 0 ? 30 : 0) + (courageT > 0 ? 30 : 0);
            drawText(carMalfunction.type === "tire" ? "🛠️ FLAT TIRE — counter-steer!" : "🛠️ BAD ENGINE — sputtering!",
                W / 2, ly, "bold 12px 'Segoe UI', Arial, sans-serif", blink ? "#FF7043" : "#FFB300", "#000", 3);
        }
        // Liquid-courage buff indicator (from the bar) — shield + 2x score
        if (courageT > 0) {
            var cy0 = nitroTimer > 0 ? 78 : 48;
            drawText("🍺 COURAGE ×2", W / 2, cy0, "bold 13px 'Segoe UI', Arial, sans-serif", "#FFD740", "#000", 3);
            ctx.fillStyle = "rgba(0,0,0,0.4)"; roundRect(W / 2 - 40, cy0 + 8, 80, 6, 3); ctx.fill();
            ctx.fillStyle = "#FFD740"; roundRect(W / 2 - 38, cy0 + 9, 76 * clamp(courageT / 20, 0, 1), 4, 2); ctx.fill();
        }

        // THE JOURNEY: compact leg-progress pill (top-center, under the hearts).
        // Self-guards; yields the center strip to any active buff/gauge.
        if (typeof drawJourneyPill === "function") drawJourneyPill();
        // STORY BEATS: the leg-start phone-call card (self-guards on story + playing).
        if (typeof drawStoryCall === "function") drawStoryCall();

        // Passenger buff timer
        if (passengerTimer > 0) {
            var pctP = passengerTimer / 30;
            var pY = distractedMode ? 75 : 60;
            // bg pill
            ctx.fillStyle = "rgba(0,0,0,0.4)";
            roundRect(W / 2 - 70, pY - 9, 140, 18, 9); ctx.fill();
            // fill
            ctx.fillStyle = "#E91E63";
            roundRect(W / 2 - 68, pY - 7, 136 * pctP, 14, 7); ctx.fill();
            drawText("🚗 +" + passengers.length + " · 2× COINS · " + Math.ceil(passengerTimer) + "s",
                W / 2, pY, "bold 11px 'Segoe UI', Arial, sans-serif", "#FFF", "#000", 2);
        }

        // End the SAFE_TOP shift HERE. Everything above is the top text strip,
        // which uses local coords and SHOULD ride below the notch. Everything
        // below (buttons, banners) already bakes SAFE_TOP / SAFE_BOTTOM into its
        // RECTs and absolute coords — keeping it inside the translate shifted it
        // down by an extra SAFE_TOP (pause floated low, the brake button fell off
        // the bottom edge on notched phones, and the visuals no longer matched
        // their touch targets).
        ctx.restore();

        // Pause button (top-left corner)
        drawIconButton(PAUSE_RECT.x, PAUSE_RECT.y, PAUSE_RECT.w, "❚❚", { bg: "#FFFFFF", bgDark: "#BDBDBD", id: "pause" });

        // Mobile boost/brake buttons (only show on touch devices)
        if (isTouchDevice) {
            drawIconButton(MOBILE_BOOST_RECT.x, MOBILE_BOOST_RECT.y, MOBILE_BOOST_RECT.w,
                "▲", { bg: keys.up ? "#FFEB3B" : "#FFC107", bgDark: "#FF6F00" });
            drawIconButton(MOBILE_BRAKE_RECT.x, MOBILE_BRAKE_RECT.y, MOBILE_BRAKE_RECT.w,
                "▼", { bg: keys.down ? "#64B5F6" : "#90CAF9", bgDark: "#1565C0" });
            drawSpeedLockBadges();
        }

        // Missile button (bottom-right) — only shown when you actually have one.
        var mY = MISSILE_RECT.y;
        if (save.missiles > 0) {
            drawIconButton(MISSILE_RECT.x, mY, MISSILE_RECT.w, "🚀", { bg: "#F44336", bgDark: "#B71C1C", id: "missile" });
        }

        // Pepper spray button (above honk) — only when owned.
        if (save.pepperSpray > 0) drawPepperButton();

        // Special-vehicle action button — cop (pull over), ambulance (rescue),
        // or school bus (stop sign).
        if (playerVehicle === "cop" || playerVehicle === "ambulance" || playerVehicle === "bus") {
            var icon = playerVehicle === "bus" ? "🛑" : "🚨";
            var lbl = playerVehicle === "cop" ? "BUST" : playerVehicle === "ambulance" ? "RESCUE" : "STOP";
            var sirRed = Math.sin(gameTime * 8) > 0;
            var abg = playerVehicle === "bus" ? "#F44336" : (sirRed ? "#EF5350" : "#42A5F5");
            var abgD = playerVehicle === "bus" ? "#B71C1C" : (sirRed ? "#B71C1C" : "#0D47A1");
            drawIconButton(COP_RECT.x, COP_RECT.y, COP_RECT.w, icon, { bg: abg, bgDark: abgD, id: "siren" });
            drawText(lbl, COP_RECT.x + COP_RECT.w / 2, COP_RECT.y + COP_RECT.w + 8,
                "bold 10px 'Segoe UI', Arial, sans-serif", "#FFF", "#000", 2);
        }

        // Honk button (above missile, right side)
        drawIconButton(HONK_RECT.x, HONK_RECT.y, HONK_RECT.w, "📣",
            { bg: honkCooldown > 0 ? "#FFEB3B" : "#FFC107", bgDark: "#FF6F00", id: "honk" });

        // Ditch-the-car button — fades in once she's been crawling a moment.
        if (typeof exitBtnShown !== "undefined" && exitBtnShown && EXIT_RECT) {
            var ebp = 0.85 + 0.15 * Math.sin(gameTime * 5);
            ctx.globalAlpha = ebp;
            drawButton(EXIT_RECT.x, EXIT_RECT.y, EXIT_RECT.w, EXIT_RECT.h, "🚶 EXIT CAR", { bg: "#7E57C2", bgDark: "#4527A0", small: true });
            ctx.globalAlpha = 1;
        }
        // Honk-chain badge — shows the current musical streak so the Honk
        // Symphony combo is visible instead of an invisible hidden mechanic.
        if (honkChain > 0) {
            var hcx = HONK_RECT.x + HONK_RECT.w - 4, hcy = HONK_RECT.y - 2;
            var grow = 1 + Math.min(honkChain, 7) * 0.06;
            ctx.save();
            ctx.translate(hcx, hcy);
            ctx.scale(grow, grow);
            ctx.fillStyle = honkChain >= 5 ? "#FF4FA3" : "#7C4DFF";
            ctx.beginPath(); ctx.arc(0, 0, 13, 0, Math.PI * 2); ctx.fill();
            ctx.strokeStyle = "#FFF"; ctx.lineWidth = 2; ctx.stroke();
            drawText("♪" + honkChain, 0, 1, "bold 12px Arial", "#FFF", "#000", 2);
            ctx.restore();
            // thin timeout ring showing how long the chain stays alive
            ctx.strokeStyle = "rgba(255,255,255,0.85)";
            ctx.lineWidth = 2.5;
            ctx.beginPath();
            ctx.arc(hcx, hcy, 16, -Math.PI / 2,
                -Math.PI / 2 + Math.PI * 2 * clamp(honkChainResetTimer / 1.5, 0, 1));
            ctx.stroke();
        }
        // count badge
        if (save.missiles > 0) {
            ctx.fillStyle = "#FFC107";
            ctx.beginPath();
            ctx.arc(W - 22, mY + 5, 13, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = "#FF6F00";
            ctx.lineWidth = 2;
            ctx.stroke();
            drawText(save.missiles, W - 22, mY + 6, "bold 14px Arial", "#000", null, 0);
        }

        // Parking / event message banner
        if (parkingMsgTimer > 0) {
            var alp = clamp(parkingMsgTimer / 2, 0, 1);
            ctx.fillStyle = "rgba(0,0,0," + (0.7 * alp) + ")";
            roundRect(W / 2 - 140, 90, 280, 36, 10); ctx.fill();
            ctx.globalAlpha = alp;
            drawText(parkingMsg, W / 2, 108, "bold 16px 'Segoe UI', Arial, sans-serif", "#FFD700", "#000", 3);
            ctx.globalAlpha = 1;
        }

        // Ima's text message — phone bubble in top-right
        if (imaText) {
            var alpha2 = imaText.t < 0.3 ? imaText.t / 0.3
                       : imaText.t > imaText.dur - 0.5 ? (imaText.dur - imaText.t) / 0.5 : 1;
            var buzz = imaText.t < 0.4 ? Math.sin(imaText.t * 50) * 3 : 0;
            ctx.save();
            ctx.globalAlpha = alpha2;
            // Phone body
            var px = W - 130 + buzz, py = 130;
            ctx.fillStyle = "#212121";
            roundRect(px, py, 110, 92, 8); ctx.fill();
            ctx.fillStyle = "#FFFFFF";
            roundRect(px + 4, py + 4, 102, 84, 5); ctx.fill();
            // Sender header (Ima = pink, Esti = purple/wistful, Tammy = teal)
            var sndr = imaText.sender;
            ctx.fillStyle = sndr === "esti" ? "#9575CD" : sndr === "tammy" ? "#26A69A" : "#FF80AB";
            roundRect(px + 4, py + 4, 102, 18, 5); ctx.fill();
            drawText(sndr === "esti" ? "💔 ESTI" : sndr === "tammy" ? "👩‍⚕️ TAMMY" : "📞 IMA", px + 55, py + 13, "bold 11px Arial", "#FFFFFF", null, 0);
            // Message bubble
            ctx.fillStyle = "#E1F5FE";
            roundRect(px + 8, py + 26, 94, 56, 6); ctx.fill();
            ctx.strokeStyle = "#0288D1";
            ctx.lineWidth = 1.5;
            roundRect(px + 8, py + 26, 94, 56, 6); ctx.stroke();
            // Render multi-line message
            var lines = imaText.msg.split("\n");
            for (var li = 0; li < lines.length; li++) {
                drawText(lines[li], px + 55, py + 38 + li * 12, "11px Arial", "#212121", null, 0);
            }
            ctx.restore();
        }
    }

    // ── State & Globals ──────────────────────────────────────
    var state = "menu";       // boot straight to Lulu's menu (Dina is hidden)
    var prevState = "menu";
    var selectedChar = "lulu"; // "lulu" or "dina"
    var menuSecretTaps = 0, menuSecretT = 0;   // secret tap-combo that reveals the sister picker
    var charHovered = null; // for character-select UI feedback
    var charSelectTime = 0;
    // Dina mode state
    var dina = null;        // {x, y, walkTime, vx, vy, sprintTimer, sprintCool, stumble, holding}
    var mom = null;         // {x, y, walkTime, speed, distance}
    var dinaRunPhase = 0;   // 0 = intro/bus, 1 = running, 2 = home/caught outro
    var dinaRunTimer = 0;
    var dinaRunDistance = 0;   // 0 -> 1 = home
    var dinaSidewalk = [];     // hazards spawned in front of dina
    var dinaSidewalkSpawn = 0;
    var dinaStickers = 0;
    var dinaCoinsRun = 0;
    var dinaEnding = "ran"; // "ran" = beat mom, "walked" = mom caught up
    var schoolBus = null;   // intro animation state
    var schoolGirls = [];   // girls coming off the bus
    var dinaCharacterFace = "happy"; // happy, determined, sleepy
    // Home interior state
    var dinaHome = { x: 240, y: 600, walkTime: 0, facing: "down" };
    var homeMessage = "";
    var homeMessageTimer = 0;
    var homeInteraction = null; // "morgan" | "tablet" | "nap"
    // Morgan plushie mode
    var morganHappy = 0;     // 0-100
    var morganPetSpot = null; // {x, y, t} location to tap
    var morganMood = "calm";
    var morganTimer = 0;
    // Tablet game
    var tabletTransitionTimer = 0;
    var inTabletMode = false; // true means Lulu game is running inside the tablet visual

    // Parking extras (cones, obstacles in parking spot) — declared here to avoid hoisting fragility
    var parkingExtras = [];
    var morganHearts = [];
    var player = { x: W / 2, y: PLAYER_Y, tilt: 0, targetX: W / 2 };
    var score = 0;
    var runCoins = 0;
    var lives = MAX_LIVES;
    var gameSpeed = BASE_SPEED;
    var scrollOffset = 0;
    var gameTime = 0;
    var invincibleTimer = 0;
    var shakeTimer = 0;
    var shakeIntensity = 0;
    var flashTimer = 0;
    var crashFlash = 0;   // white impact flash on the fatal crash (fades fast)
    var slowMoT = 0;      // >0 = brief bullet-time after a big hit
    var hitStopT = 0;     // >0 = a few frames of near-total freeze + zoom punch (impact weight)
    var coinFlys = [];    // little coins arcing from a pickup to the HUD counter
    var coinHudPulse = 0; // HUD coin counter pops when a flying coin lands
    var crashTimer = 0;
    var menuBounce = 0;
    var gameOverAlpha = 0;
    var goScoreShown = 0;      // animated count-up of the final score
    var goConfettiDone = false; // one-shot confetti on a new high score
    var dustTimer = 0;
    var distractedMode = false;

    // Passengers (picked-up pedestrians)
    var passengers = []; // {pedType, hairColor, shirtColor}
    var passengerTimer = 0;

    // Crash animation state
    var crashX = 0, crashY = 0, crashRot = 0, crashRotVel = 0;

    // Angry man crash sequence
    var crashPhase = 0; // 0: explosion, 1: man running, 2: man yelling, 3: man hit, 4: done
    var crashPhaseTimer = 0;
    var angryMan = null;
    var revengeCar = null;
    var crashCause = null;   // {kind:"car"/"animal"/"other", color, carType, animal}
    var crashedCar = null;   // the wrecked enemy car the angry driver climbs out of
    var animalSwarm = [];     // mob of the same animal hurling insults
    var crashCars = [];       // revenge cars that mow down the swarm
    var crashSmokeT = 0;      // smoke emitter timer for the wreck
    var crashCarT = 0;        // spawn cadence for the swarm-mowing revenge cars
    var crashReprieve = false; // this wipeout is secretly a funny second chance
    var reprieveKind = null;   // "arrest" (cop nabs the man) | "chase" (man runs off)
    var playerVehicle = null;  // null = Lulu's car; "bus"/"ambulance"/"cop"/"dozer"/"borrowed"
    var borrowedCar = null;    // {carType, color} when she's driving a hotwired civilian car
    var salonReturnFoot = false; // leaving the salon should drop her back on foot, not driving
    var hitchhiker = null;     // roadside thumber — honk near them to pick up (driving activity)
    var hitchTimer = 0;

    var obstacles = [];
    var coinEntities = [];
    var heartEntities = [];   // rare extra-life pickups
    var fuelCans = [];        // gas-station nitro pickups
    var nitroTimer = 0;       // seconds of turbo remaining
    var courageT = 0;         // "liquid courage" buff from the bar — shield + 2x score while driving
    var carMalfunction = null;// {type:"tire"/"engine", drift, t} — a stolen LEMON drives badly
    var parkingResultBonus = 0, parkingResultStars = 0;   // last park's ACTUAL payout, for the result screen
    var wetTimer = 0;         // brief slow after splashing through a puddle
    var tollBooth = null;     // active toll booth {y, open:[lanes], paid}
    var trainCrossing = null; // active railroad crossing {y, trainX, dir, ...}
    var driveThru = null;     // active drive-thru {y, side, taken}
    var paradeTimer = 0;      // seconds left of a parade/marathon crowd
    var busStop = null;       // parked school bus dropping kids {y, signOut, ...}
    var crossingGuard = null; // crossing guard halting traffic {y, side, kids, ...}
    var convoyTimer = 0;      // field-trip bus convoy spawn window
    var convoyNext = 0;       // spacing between convoy buses
    var iceTruck = null;      // ice-cream truck on the shoulder {y, side, kids, taken}
    var animals = [];
    var missiles = [];
    var heshy = null;         // Heshy-in-the-pool Easter egg cameo {t, dur}

    var spawnClocks = { car: 0, cone: 0, puddle: 0, animal: 0, coin: 0, ped: 0 };

    // Shop UI state
    var shopTab = "skins"; // skins, powerups, special
    var shopDetail = null; // Garage: skin key of the open showroom detail view, or null
    var shopDetailT = 0;   // detail-view open timer (drives the stat-bar fill-in animation)
    var shopGridT = 0;     // garage-grid open timer (drives the card pop-in stagger)
    var lastBoughtMessage = "";
    var lastBoughtTimer = 0;
    var buyPopId = null;   // which shop item's owned-count pill just popped
    var buyPopTimer = 0;   // pop/flash timer for that pill

    // ── Parking mini-game state ──────────────────────────────
    var parkingSigns = [];      // P-sign pickups on the main road
    var parkingSpawnTimer = 25; // first parking sign appears around 25s in
    var parkingCar = null;      // Lulu's car in the parking scene
    var parkedCars = [];        // two stationary parked cars
    var parkingZone = null;     // {x,y,w,h} target spot
    var parkingCameras = [];    // [{x,y,poleH,currentRot,blink}]
    var parkingResult = null;   // "success" | "fail"
    var parkingResultTimer = 0;
    var parkingResultPhase = 0;
    var parkingTransitionTimer = 0;
    var parkingTransitionDuration = 0.9;
    var parkingZoom = 1;
    var parkingFlashTimer = 0;
    var parkingMsg = "";
    var parkingMsgTimer = 0;
    var parkingInZoneTimer = 0; // how long Lulu has been in zone, stationary
    var parkingTimeLeft = 0;    // countdown
    var parkingFailHit = null;  // {who:"parked"|"curb", x,y, side, severity}
    var parkingScore = 0;       // bonus accumulating
    var kidsInCar = false;      // true after success
    // Challenge mode
    var parkingChallengeMode = false;
    var parkingReturnFoot = false;   // entered the parking lot ON FOOT → return to foot
    var parkingFromPullover = false; // reached parking by pulling over while DRIVING → after the
                                     // result screen she steps out + walks off into the foot world
    var parkingWalkout = null;       // {t,dur,x,y,...} the ~1s step-out-of-the-car beat before foot
    var parkingLotStyle = null;      // casual roadside-lot look {tint, sign} — randomized per pull-over
