    function resetGame() {
        player.x = W / 2; player.targetX = W / 2; player.tilt = 0;
        score = 0; runCoins = 0; lives = MAX_LIVES;
        coinCombo = 0; coinComboT = 0; coinComboFx = 0;
        nearChain = 0; nearChainT = 0; recordBannerT = 0; pbWarned = false; pbBroken = false;
        runBanked = false; footQuestAccum = 0; footQuestT = 0;   // weekly-quest run bookkeeping
        // First-ever run → the guided tutorial (decides for itself; skippable).
        if (typeof tutMaybeStart === "function") tutMaybeStart();
        // ── Daily streak: the FIRST run of each day pays out, and consecutive
        //    days stack the bonus (25 × streak, capped at ×7). Miss a day and
        //    the streak starts over. ──
        var dayNum = Math.floor(Date.now() / 86400000);
        if (save.dayNum !== dayNum) {
            save.streak = (save.dayNum === dayNum - 1) ? (save.streak || 0) + 1 : 1;
            save.dayNum = dayNum;
            var streakPay = 25 * Math.min(save.streak, 7);
            save.totalCoins += streakPay; persistSave();
            spawnFloater(W / 2, H * 0.42, "🔥 Day " + save.streak + " streak! +" + streakPay + " 💰", "#FFD700");
            if (save.streak >= 2) spawnFloater(W / 2, H * 0.42 + 30, "come back tomorrow for more!", "#FFE082");
        }
        boostLock = false; brakeLock = false;   // cruise-lock resets each new run
        roadDramas = []; carCrashCooldown = rand(7, 16);
        busStopT = 0; busKidTimer = rand(4, 8); busKids = 0;
        prisonClothes = false; fugitiveT = 0; fugitiveSpot = 0; fugCopT = 0;
        if (typeof fugDisguise !== "undefined") { fugDisguise = null; fugDisguiseT = 0; }
        if (typeof copK9s !== "undefined") { copK9s = []; copMissiles = []; copK9T = 0; copMslT = 0; }
        jail = null; court = null; arrest = null;
        if (save.lockup) { save.lockup = null; persistSave(); }   // a fresh run clears any old sentence
        gameSpeed = BASE_SPEED; scrollOffset = 0; gameTime = 0;
        invincibleTimer = 0; shakeTimer = 0; flashTimer = 0; crashTimer = 0;
        crashFlash = 0; slowMoT = 0; hitStopT = 0; coinFlys = []; coinHudPulse = 0;
        obstacles = []; coinEntities = []; heartEntities = []; animals = []; missiles = []; particles = [];
        fuelCans = []; nitroTimer = 0; courageT = 0; carMalfunction = null; wetTimer = 0; tollBooth = null;
        trainCrossing = null; driveThru = null; paradeTimer = 0; busStop = null;
        crossingGuard = null; convoyTimer = 0; convoyNext = 0; iceTruck = null;
        heshy = null;
        spawnClocks = { car: 0, cone: 0, puddle: 0, animal: 0, coin: 0, ped: 0 };
        initSpawnTimers(); // randomized first-appearance per run (see 01b-spawn-tuning.js)
        passengers = []; passengerTimer = 0;
        crashPhase = 0; crashPhaseTimer = 0; angryMan = null; revengeCar = null;
        crashCause = null; crashedCar = null; animalSwarm = []; crashCars = []; crashSmokeT = 0; crashCarT = 0;
        crashReprieve = false; reprieveKind = null; playerVehicle = null; salonReturnFoot = false;
        if (typeof borrowedCar !== "undefined") borrowedCar = null;
        hitchhiker = null; hitchTimer = rand(25, 55);
        if (typeof footDisguiseLook !== "undefined") footDisguiseLook = null;
        parkingSigns = []; parkingSpawnTimer = 25; parkingReturnFoot = false;
        if (typeof roadsideVeh !== "undefined") { roadsideVeh = []; roadsideCool = 0; }
        iceCreamSigns = []; iceCreamSpawnTimer = 60;
        sasquatch = null; sasquatchTimer = rand(40, 70);
        billboards = []; billboardTimer = 8;
        copEvent = null; copEventTimer = rand(60, 120);
        roadCops = []; copChase = null; copBust = null;
        spontaneousChaseCool = 22; wantedSpot = 0; wantedPatrolT = 0;
        dozers = []; dozerTimer = 0; dozerSpawnCool = 34; flatWrecks = []; dozerNpcCool = 8;
        slowDriveT = 0; parkExit = null; exitBtnShown = false; exitQueued = false;
        // THE JOURNEY: every run restarts the tour at stop 0 (Bubbe, always reachable).
        tripStopIdx = 0; tripLegStart = 0; tripCycle = 0; tripArrival = null;
        tripStopsThisRun = 0; tripPostponeUntil = 0; tripEndedWell = false; tripLastStopName = "";
        if (typeof tripPullInT !== "undefined") { tripPullInT = 0; tripMile50 = false; tripMile85 = false; }
        // STORY TRIP: resume from the last banked checkpoint instead of Bubbe. Cruise
        // leaves the 0s above (it has no journey layer at all). Then queue the
        // "LEG n/5" intro banner for this leg (a no-op in cruise).
        if (typeof runMode !== "undefined" && runMode === "story") {
            // STORY MAP launch: if the map picked a specific chapter, drive THAT leg
            // (then consume the request); otherwise resume from the banked checkpoint.
            if (typeof storyLaunchLeg !== "undefined" && storyLaunchLeg >= 0) {
                tripStopIdx = storyLaunchLeg % TRIP_STOPS.length;
                storyLaunchLeg = -1;
            } else {
                tripStopIdx = (save.storyStop || 0) % TRIP_STOPS.length;
            }
            tripCycle = save.storyCycle || 0;
        }
        if (typeof legBannerT !== "undefined") legBannerT = 0;
        if (typeof queueLegIntro === "function") queueLegIntro();
        // STORY BEATS: fresh run wipes call/event/boon state, then arms leg 0's call
        // + event (armStoryLeg is a no-op in cruise). Boon does NOT persist.
        if (typeof storyCallT !== "undefined") {
            storyCallT = 0; storyCallDelay = 0; storyCallPending = false; storyCallStop = 0; storyCallLine = "";
            storyEvent = null; storyEventDone = false; storyBoonT = 0; tripBoon = null;
        }
        if (typeof armStoryLeg === "function") armStoryLeg();
        if (typeof clearWanted === "function") clearWanted();   // a fresh run starts with a clean record
        // Last-line guard: distracted mode never runs inside a friend room
        // (reverse controls + 2× score would poison shared scores/races).
        if (distractedMode && typeof mpConnected !== "undefined" && mpConnected && mpRoom !== "lobby") {
            distractedMode = false;
        }
        honkCooldown = 0;
        kidsInCar = false;
        imaText = null; imaTextTimer = rand(35, 75);
        sasquatchPassenger = 0;
        honkChain = 0; honkChainResetTimer = 0;
        // Avigail + salon
        avigailWalker = null; avigailSpawnTimer = rand(30, 55);
        avigailInCar = false; pointMult = 1;
        uncleWalker = null; uncleRotil = 0;
        salonSigns = []; salonSpawnTimer = rand(40, 70);
        // Reset Dina + parking state leaks (per QA + Bug Hunter)
        parkingChallengeMode = false;
        parkingFromPullover = false; parkingWalkout = null; parkingLotStyle = null;
        parkingResult = null; parkingFailHit = null;
        parkingExtras = []; parkedCars = []; parkingPedestrian = null;
        parkingCar = null; parkingZone = null; parkingLevelConfig = null;
        parkingCameras = []; parkingMsgTimer = 0;
        morganHearts = []; morganSparkles = []; morganHappy = 0; morganMood = "calm";
        dinaCoinsRun = 0; dinaStickers = 0; dinaSidewalk = [];
        dinaRunTimer = 0; dinaRunDistance = 0; dinaRunPhase = 0;
        shakeIntensity = 0;
        initSeason();
        initZone();
        // STORY chapter SET: initSeason() reset the sky to summer — re-force this
        // leg's directed season now so a fresh run opens in its chapter's mood.
        // (No-op in cruise / a subsequent cruise run has no leak.)
        if (typeof armStorySeason === "function") armStorySeason();
        initDecorations();
    }

    // ── Spawning ─────────────────────────────────────────────
    // Lane LINES (the gaps between lane centers) — used so cars/cones sometimes
    // sit on the dashed line and you can't just park between lanes forever.
    var LANE_LINES = [ROAD_L + LANE_W, ROAD_L + LANE_W * 2];

    // Decide how an enemy car drives. Calm early on; after some distance (and
    // especially at night / in the bar district) some drivers are DRUNK (big
    // weaving swerves, spilling booze) or TEXTING (gentle distracted drift).
    function pickCarBehavior() {
        if (scrollOffset < 4000) return "normal";
        var drunk = 0.06, texting = 0.10;
        if (typeof season !== "undefined" && season === "night") drunk += 0.10;
        if (typeof zone !== "undefined") {
            if (zone === "bars") drunk += 0.30;
            if (zone === "downtown") texting += 0.16;
        }
        var r = Math.random();
        if (r < drunk) return "drunk";
        if (r < drunk + texting) return "texting";
        return "normal";
    }

    // Emergency vehicle for the hospital zone — fast, flashing, and other cars
    // pull aside as it screams down the road.
    function spawnAmbulance() {
        var lane = randInt(0, 2);
        obstacles.push({
            type: "car", behavior: "ambulance",
            x: LANES[lane], y: -120, color: "#FFFFFF", carType: 0,
            hitW: 38, hitH: 70, speedMult: 2.0, lane: lane, swerveT: 0, spillT: 0
        });
        playTone(900, 0.18, "sine", 0.14, 1320);
        setTimeout(function () { playTone(1320, 0.18, "sine", 0.14, 900); }, 200);
        setTimeout(function () { playTone(900, 0.18, "sine", 0.14, 1320); }, 400);
    }

    function spawnFuel() {
        var x = rand(ROAD_L + 24, ROAD_R - 24);
        fuelCans.push({ x: x, y: -30, hitW: 22, hitH: 24, collected: false, bob: rand(0, 6.28) });
    }

    function spawnTrainCrossing() {
        var dir = Math.random() < 0.5 ? 1 : -1;
        // Short train (2-3 cars) so there's always a cleared side to steer into;
        // it sweeps in immediately as the crossing scrolls down.
        // Spawns high so the "R X R" road paint announces it well in advance.
        trainCrossing = {
            y: -420, dir: dir, started: false, gone: false,
            trainX: dir > 0 ? -200 : W + 200, cars: randInt(2, 3), warnPhase: 0
        };
    }
    function spawnDriveThru() {
        var side = Math.random() < 0.5 ? -1 : 1; // which shoulder the window is on
        driveThru = { y: -150, side: side, taken: false };
    }
    function spawnParadeRunner() {
        var side = Math.random() < 0.5 ? -1 : 1;
        obstacles.push({
            type: "ped", x: side < 0 ? ROAD_L - 12 : ROAD_R + 12, y: rand(-30, H * 0.42),
            vx: -side * rand(60, 115), hitW: 18, hitH: 20, speedMult: 0.2, lane: 1,
            pedType: randInt(0, 2), walkTime: 0
        });
    }

    function spawnTollBooth() {
        var sh = [0, 1, 2];
        for (var i = sh.length - 1; i > 0; i--) { var j = randInt(0, i); var t = sh[i]; sh[i] = sh[j]; sh[j] = t; }
        var openCount = Math.random() < 0.5 ? 1 : 2; // 1-2 lanes open
        // Spawns well above the screen so its painted road warnings ("TOLL
        // AHEAD" / "SLOW") scroll into view first — no more sudden gantry.
        tollBooth = { y: -480, open: sh.slice(0, openCount), paid: false };
    }

    // A cop car cruising the road like normal traffic — but it'll give chase if
    // you speed past it (or blow a school-bus stop sign in its view).
    function spawnPatrolCar() {
        var lane = randInt(0, 2);
        var o = {
            type: "car", behavior: "patrol", x: LANES[lane], y: -100,
            color: "#FFFFFF", carType: 0, hitW: 36, hitH: 64,
            speedMult: Math.random() < 0.4 ? rand(1.3, 1.6) : 0.7,
            lane: lane, spot: 0, swerveT: 0, spillT: 0
        };
        obstacles.push(o);
        return o;
    }
    // A K9 unit — a dark cruiser-SUV with a dog aboard, that actively hunts her
    // position. Shows up only when the heat is high (4★+).
    function spawnK9Unit() {
        var lane = randInt(0, 2);
        var o = {
            type: "car", behavior: "patrol", k9: true, aggro: true,
            x: LANES[lane], y: -120, color: "#23272E", carType: 0, hitW: 38, hitH: 70,
            speedMult: 1.5, lane: lane, spot: 0, swerveT: 0, spillT: 0, barkT: rand(1, 2.5)
        };
        obstacles.push(o);
        return o;
    }

    // Water kicked up when Lulu splashes through a puddle.
    function spawnSplash(x, y) {
        for (var i = 0; i < 14; i++) {
            var a = rand(-Math.PI, 0); // upward fan
            particles.push({
                x: x + rand(-14, 14), y: y + 18,
                vx: Math.cos(a) * rand(40, 130), vy: Math.sin(a) * rand(60, 170),
                life: 0.5, maxLife: 0.5, size: rand(2, 4.5),
                color: randPick(["#42A5F5", "#90CAF9", "#BBDEFB", "#E1F5FE"]), gravity: 240
            });
        }
        playTone(280, 0.12, "sine", 0.08, 120);
    }

    function spawnAlcoholDrop(x, y) {
        particles.push({
            x: x + rand(-16, 16), y: y + rand(-6, 18),
            vx: rand(-25, 25), vy: rand(-5, 25), life: 0.9, maxLife: 0.9,
            size: rand(2, 4), color: randPick(["#C8A24B", "#A6792E", "#D4AF5A", "#E8C66A"]),
            gravity: 50
        });
    }

    function spawnObstacle(type) {
        var lane = randInt(0, 2);
        var x = LANES[lane];
        // ~28% of cars/cones straddle a lane line so the lane gaps aren't a
        // permanent safe spot. Everything else gets a little jitter.
        if ((type === "car" || type === "cone") && Math.random() < 0.28) {
            x = randPick(LANE_LINES) + rand(-8, 8);
        } else {
            x += rand(-10, 10);
        }
        var y = -90;
        for (var i = 0; i < obstacles.length; i++) {
            if (Math.abs(obstacles[i].y - y) < 120 && Math.abs(obstacles[i].x - x) < LANE_W) return;
        }
        if (type === "car") {
            var beh = pickCarBehavior();
            // Regular cars only ever drive SLOWER than you — you overtake them
            // (same direction). Only DRUNK drivers can barrel toward you from the
            // opposite direction (fast). Cops/ambulances set their own speeds.
            var sm = rand(0.45, 0.72);
            if (beh === "drunk" && Math.random() < 0.5) sm = rand(1.4, 1.7);
            var ct = randCarType(), hb = carHitbox(ct);
            var carObj = {
                type: "car", x: x, y: y,
                color: randPick(C.enemyCols),
                carType: ct,
                hitW: hb.hw, hitH: hb.hh,
                speedMult: sm,
                lane: lane,
                behavior: beh,
                swerveT: rand(0, 6.28), spillT: rand(0.2, 0.6)
            };
            // Rare traffic MALFUNCTION (~3%) — normal cars only, and at most ONE
            // afflicted car on screen at a time (skip the roll if one's already out).
            if (beh === "normal" && Math.random() < 0.03) {
                var malOut = false;
                for (var mq = 0; mq < obstacles.length; mq++) { if (obstacles[mq].mal) { malOut = true; break; } }
                if (!malOut) {
                    carObj.mal = randPick(["breakdown", "flat", "rage"]);
                    carObj.malT = 0;
                }
            }
            obstacles.push(carObj);
        } else if (type === "cone") {
            obstacles.push({
                type: "cone", x: x + rand(-15, 15), y: y,
                hitW: 14, hitH: 14, speedMult: 1, lane: lane
            });
        } else if (type === "puddle") {
            obstacles.push({
                type: "puddle", x: x, y: y,
                hitW: 30, hitH: 12, speedMult: 1, lane: lane
            });
        } else if (type === "pool") {
            // Heshy's pool — no longer plopped in the middle of TRAFFIC: it sits
            // in a little front yard off the shoulder, and just cruising past it
            // (any lane) summons Heshy + grants the shield. Same treat, believable
            // address.
            var poolLeft = Math.random() < 0.5;
            obstacles.push({
                type: "pool",
                x: poolLeft ? rand(34, Math.max(38, ROAD_L - 28)) : rand(ROAD_R + 28, W - 34),
                y: y, hitW: 34, hitH: 18, speedMult: 1, lane: lane, yard: true
            });
        } else if (type === "ped") {
            obstacles.push({
                type: "ped", x: x, y: y,
                hitW: 18, hitH: 20, speedMult: 0.5, lane: lane,
                pedType: randInt(0, 2),
                worker: (typeof zone !== "undefined" && zone === "construction"),
                drunk: (typeof zone !== "undefined" && zone === "bars"),
                cop: (typeof zone !== "undefined" && zone === "police"),
                // Small staggered initial delay so a crowd doesn't all shout on the
                // same frame, but the first line still lands within ~1s of view.
                catcallT: rand(0.2, 1.0),
                walkTime: 0
            });
        }
    }

